%\end{equation}


\subsection{Approximation by piecewise linear functions}



We recall the classical approximation result in Sobolev spaces \cite[Th. 4.4.20]{MR2373954}: For any polyhedral domain $\Omega\in \rr^N$,   $N<2p$, $\mathcal{T}_h$ as above, $1<p\leq \infty$ or $n\leq 2$ if $p=1$ (see  \cite[Th. 4.4.4]{MR2373954} for the complete set of restrictions), and $s\in \{0,1\}$, the global piecewise linear interpolant $I^h$ satisfies  
 \begin{equation}
\label{fem.error.sobolev}
  \Big(\sum_{T\in \mathcal{T}_h }\| u-I^h u\|^p_{W^{s,p}(T)} \Big)^{1/p}\leq Ch^{2-s}\|u\|_{W^{2,p}(\Omega)}, \ \forall u\in W^{2,p}(\Omega).
\end{equation}
  The above restrictions are necessarily when one needs to have an estimate for all functions in $W^{2,p}(\Omega)$.   When restrict to the class of functions that are smooth, for example $C^2(\overline{\Omega})$ the above restrictions on the dimension can pe relaxed. The restriction $N<2p$ is exactly the one that guaranteess that $W^{2,p}(\rr^N)\subset C^0(\Omega)$, the class where the global linear interpolator $I^h$ is defined. 

\begin{lemma}\label{est.c2}Let $\mathcal{T}_h$ a regular mesh on a 
	polyhedral domain $\Omega\in \rr^N$,    $1<p\leq \infty$, $s\in \{0,1\}$. There exists a positive constant $C=C(N,p,s,\sigma)$ such that for all $|\alpha|$=s and $1\leq p<\infty$:
	\begin{equation}
\label{est.fem.c2}
    \Big(\sum_{T\in \mathcal{T}_h }\| D^\alpha(u-I^h u)\|^p_{L^{p}(T)} \Big)^{1/p}\leq Ch^{2-s}\Big( \sum_{T\in \mathcal{T}_h} |T| \|D^2 u\|^p_{L^\infty(T)}\Big)^{1/p}, \ \forall u\in C^{2}(\overline{\Omega}), 
\end{equation}
and
	\begin{equation}
\label{est.fem.c2.infty}
    \max_{T\in \mathcal{T}_h}\| D^\alpha(u-I^h u)\|_{L^{\infty}(T)}\leq Ch^{2-s}\max_{T\in \mathcal{T}_h}   \|D^2 u\|_{L^\infty(T)}, \ \forall u\in C^{2}(\overline{\Omega}).
\end{equation}
%Moreover, for any $T\in \mathcal{T}_h$
%\begin{equation}
%\label{est.fem.c3.loc}
%  \|D^\alpha I_hu\|_{L^p(T)}\lesssim 
%\begin{cases}
%	\| u\|_{W^{1,p}(T)},& p>N,\\ 
%	h_T^{-|\alpha|+\frac Np}\|u\|_{L^\infty(T)}, &p\geq 1.
%\end{cases}
%\end{equation}
\end{lemma}

The proof is a slightly modification of the one in \cite[Th.~4.4.4, Chapter 4]{MR2373954}. The proof can be extended to more general finite elements and $u\in C^m(\overline{\Omega})$ but this is out of the scope of this paper. For a proof see \cite{ignat2025}.

In fact the above estimates are sharp in the case of functions that are uniform convex in one direction.  


\begin{lemma}\label{lower.bound.triangle}For any $p\in (1,\infty)$ there exists a positive constant $C(p)$ such that for any $T\in \mathcal{T}_h$ and any
 $u\in C^2(T)$  
	\[
	 \min_{A\in \rr^N} \int_T |Du-A|^pdx \geq C(p)\rho_T^{N+p} \max _{\xi\in \mathbf{S}^{N-1}}\min _{x\in \overline{\Omega}}|\xi^T D^2u(x)\xi|^p.
	\]
	The same holds under the assumption that the function is uniformly convex in one direction, i.e. $\inf_{T}|\partial^2_{x_k}u(x)|>0$ for some $x_k$.
	\end{lemma}

\subsection{Finite element eigenvalue approximation}\label{classical.approximation} Let us now recall the classical theory for eigenvalue approximation, \cite{MR1115240}. Here we present it in the  simplest case.  Following the notations  in \cite[Section 8, p.~697]{MR1115240}, let $V$ a real Hilbert space and $a(\cdot, \cdot)$ be a symmetric continuous and coercive bilinear form on $V $. Let $H$ be another Hilbert space such that $V\subset H$ with compact embedding, $b$ a symmetric continuous bilinear form on $H$, such that $b(u,u)>0$, for all $u\in V$, $u\neq 0$. Let $V_h\subset V$ be a family of finite-dimensional spaces of $V$. 

Let $\lambda_1$ be the first eigenvalue of \textit{the form $a$ relative to the form $b$}, i.e. the smallest $\lambda_1$ so that there exists a non-trivial $u_1\in  V$ such that
\[
a(u_1,v)=\lambda_1b(u,v), \forall \ v\in V.
\]
In a similar way one define $\lambda_{1h}$ in the space $V_{1h}$: there exists $u_{1h}\in V_h$ such that 
\[
a(u_1,v)=\lambda_{1h}b(u,v), \forall \ v_h\in V_h.
\]
A fundamental result in the theory of eigenvalue approximation is the following, originally established in \cite[Prop.~6.30, p.~315]{MR3405533}; see also \cite[p.~700]{MR1115240} for a more direct statement:
\begin{equation}
\label{two-side.estimate}
  C_1\eps_h^2 \leq \lambda_{1h}-\lambda_1\leq C_2\eps_h^2
\end{equation}
where
\[
\eps_h=d(u_1,V_h)=\inf_{v_h\in V_h } \|u_1-v_h\|_{V}. 
\]
The upper bound together with the trivial estimate $0\leq \lambda_{1h}-\lambda_1$,  can be also found in \cite[Th. 6.4-2]{raviart}.

This analysis will be useful in the proofs of Theorem~\ref{main.2} and Theorem~\ref{main.3}, which are effectively related to eigenvalue problems. However, it does not apply to Theorem~\ref{main}, which falls outside this framework and requires an independent analysis.





\section{Proof of Theorem \ref{main} }\label{hardy}
Let us consider $\Omega$ a convex smooth domain such that 
$0\in \Omega \subset \overline{\Omega}\subset B_R$ for some $R>0$.  Without loss of generality assume that $R=1$. 
We approximate the domain $\Omega$ by a polygonal domain $\Omega_h\subset \Omega$ as in \cite{MR2754218}. We introduce the finite element subspace $V_h\subset H^1(\Omega_h)\cap C(\overline \Omega_h)$  extended by zero to $\Omega\setminus \Omega_h$. 

The proof of Theorem \ref{main} \eqref{est.hardy.1} treats separately the lower and upper bound. 

The following Hardy inequality with a logarithmic reminder term \cite[Th.~2.5.2, p.~25]{peral} will play a key role: There exists a positive constant $C=C(N,\Omega)$ such that for all $\phi\in C_c^\infty(\Omega)$ it holds
\begin{equation}
\label{hardy.log}
  \int_\Omega |\nabla \phi|^2 dx- \Lambda_N\int_{\Omega}\frac{\phi^2}{|x|^2}dx\geq C \int_{\Omega} |\nabla \phi|^2 \Big(\log\frac 1 {|x|} \Big)^{-2}dx.
\end{equation}
By density it also holds for any $\phi\in H_0^1(\Omega)$. We also recall that   (see \cite[(2.5.7), p.~25-26]{peral}) 
\begin{equation}
	\label{peral1.4}
\inf_{\phi\in C_c^\infty(\Omega), \phi\not= 0} \frac{  \int_\Omega |\nabla \phi|^2 dx- \Lambda_N\int_{\Omega}\frac{\phi^2}{|x|^2}dx}{ \int_{\Omega} | \phi|^2 |x|^{-2} \big(\log\frac 1 {|x|} \big)^{-2}dx}=\frac 14.
\end{equation}
In dimension $N\geq 3$, the infimum above, $1/4$, can be achieved along a minimizing sequence,  by taking regularizations $u_\eps=\eta_\eps \tilde u_2$ (see  Section \ref{upperbound} for more details) of 
\begin{equation}
\label{tildee2}
  \tilde u_2(x)= \tilde u_2(|x|),\; \tilde u_2(r)=|r|^{-\frac{N-2}2} \Big(\log \frac 1{|r|}\Big)^{1/2},
\end{equation}
which is the distributional solution of 
\[
-\Delta w - \Lambda_N \frac w{|x|^2}=\frac 14 \frac {w}{|x|^2} \Big(\log \frac 1{|x|}\Big)^{-2}.
\]
This regularization consists, roughly speaking, in truncating the function  $\tilde u_2$ outside a suitably chosen ball that contains the singularity a $x=0$.

  It is worth to mention that functions $u(x)=|x|^{-(N-2)/2}v(x)$ where $v(x)\simeq (\log (1/x))^\alpha$ as $x\rightarrow  0$ belong to space ${\mathcal{H}}$ if $\alpha\in [0,1/2)$ but fail to be in ${\mathcal{H}}$ for $\alpha\geq 1/2$, see \cite{MR2960851}.


Since $u_\eps$ has the suport outside the ball of radius $
\eps^2$  we  have
\[
\frac{  \int_\Omega |\nabla u_\eps|^2 dx- \Lambda_N\int_{\Omega}{u_\eps^2}{|x|^{-2}}dx}{ \int_{\Omega} | u_\eps|^2 |x|^{-2} }\simeq \frac 14\frac{ \int_{\Omega} | u_\eps|^2 |x|^{-2} \Big(\log\frac 1 {|x|} \Big)^{-2}dx}{\int_{\Omega} | u_\eps|^2 |x|^{-2} }\lesssim |\log \eps|^{-2}.
\]
The family $u_\eps $  may be used as a minimizing sequence for  $\Lambda_N$, with a controlled error of order $|\log \eps|^{-2}$. The proof of Theorem \ref{main} proceeds by a careful finite element approximation of this minimising sequence.

\subsection{The lower bound.} Although it is briefly presented in \cite{della2023finite}, we include a sketch here for completeness.

 Let $v_h\in  V_h$ the minimizer corresponding to $\Lambda_h$:
\[
\Lambda_h=\frac{\int _\Omega |\nabla v_h|^2dx}{\int _\Omega v_h^2 |x|^{-2}dx}. 
\]
It follows that
\begin{align*}
\Lambda_h-\Lambda_N= \frac{\int _\Omega |\nabla v_h|^2dx- \Lambda_N\int _\Omega v_h^2 |x|^{-2}dx }{\int _\Omega v_h^2 |x|^{-2}dx}\geq C(N,\Omega)  \frac{\int _\Omega |\nabla v_h|^2 |\log |x||^{-2}dx}{\int _\Omega v_h^2 |x|^{-2}dx}.
\end{align*}
Using that $\nabla v_h$ is constant in each triangle and  Lemma \ref{logth} in the Appendix below we get
\begin{align*}
\label{}
  \int _\Omega |\nabla v_h|^2 |\log |x||^{-2}dx&=\sum_{T\in \th} \int_{T} |\nabla v_h|^2 |\log |x||^{-2}dx=\sum_{T\in \th} |\nabla v_h|^2\int_{T}  |\log |x||^{-2}dx\\
  &\gtrsim \frac{1}{|\log h|^2}\sum_{T\in \th} |T| |\nabla v_h|^2  dx=
 \frac{1}{|\log h|^2}\int_{\Omega}|\nabla v_h|^2\\
 &=\frac{\Lambda_{h}}{|\log h|^2}\int _\Omega v_h^2 |x|^{-2}dx.
\end{align*}
This shows that $\Lambda_h-\Lambda_N\gtrsim\Lambda_h|\log h|^{-2}\geq \Lambda_N|\log h|^{-2}$.  

\subsection{The upper bound}\label{upperbound}  It is sufficient to prove the upper bound 
\[
\Lambda_{h} -\Lambda_N\lesssim \frac 1{|\log h|^2},
\]
in the case when $\Omega$ is a ball centered at origin $B$. Indeed, given that the constant $\Lambda_N$ is independent of the bounded domain under consideration, the upper holds in the general case by comparison.

To simplify the presentation, and without loss of generality, we consider the case when $\Omega=B_{1}$ the unit ball. 

As mentioned above, the main idea on the upper bound is to use an approximating sequence $u_\eps$ of 
\[\tilde u_2(r)=r^{-N/2+1}\left(\log \frac 1r\right)^\alpha\]
 and project it on the space $ V_h$.  In the following we  make this construction more precise. 

 Along the proof we will also employ the function
 \[  u_2(r)=r^{-N/2+1}.\]

We consider the following cut-off function inspired by \cite[proof of Corol. VIII.6.4]{MR3823299} and \cite{MR3528527}:
\[
\eta_\eps (x)=\begin{cases}
	0,& |x|<\eps^2, \\
	\xi (\frac {\log (|x|/\eps^2)}{\log (1/\eps)}), & |x|\in (\eps^2,\eps),\\
	1, & |x|>\eps,
\end{cases}
\]
where $\xi:[0,1]\rightarrow [0,1]$ is a smooth function such that for some $\mu\in (0,1)$,
 $\xi=0$ on $[0,\mu]$ and $\xi=1$ on $[1-\mu,1]$. 


The function $\eta_\eps$ satisfies the following properties:
 \begin{enumerate}
 \item \label{p0} $\eta_\eps(r)=0$ on $0<r<\eps^{2-\mu}$,  
 	\item \label{p1} $|\eta'_\eps(r)|\leq \frac{\|\xi \|_\infty}{r |\log \eps|}\lesssim \frac{1}{r|\log \eps|}$, $\eps^2\leq r\leq \eps$, 
 	\item \label{p2} $|\eta''(r)|\leq \frac{\|\xi''\|_\infty}{r^2|\log \eps|^2}+\frac{\|\xi'\|_\infty}{r^2|\log \eps|}\lesssim \frac{1}{r^2 |\log \eps|}$, $\eps^2<r<\eps$.
 \end{enumerate}
 As a consequence we get
 \begin{enumerate}
 	\item \label{p3}  $|\nabla \eta_\eps(x)|\leq \frac 1{|x||\log \eps|}$ if $\eps^2<|x|<\eps$ and vanishes otherwise,
 	\item \label{p5} $|D^2\eta_\eps (x)|\lesssim \frac 1{|x|^2 |\log \eps|}$, if $\eps^2<|x|<\eps$ and vanishes otherwise.
 \end{enumerate}
With this function $\eta_\eps$ we introduce 
\[
u_\eps(x)= \tilde u_2(|x|) \eta_\eps(|x|)\psi(|x|)\in C_c^\infty(\Omega),
\]
where $\psi\in C_c^\infty (\rr)$ such that $\psi \equiv 1$ for $|r|\leq 1/4$ and $\psi\equiv 0$ for $|r|>1/2$.

The following lemma provides quantitative estimates for this sequence, viewed as a minimizing sequence for the Hardy constant.

\begin{lemma}\label{est.u.eps}Let $\alpha\geq 0$. The family of functions $u_\eps$ satisfies the following estimates
 \begin{equation}
\label{estAeps}
  A_\eps= \int_\Omega |\nabla u_\eps|^2dx-\Lambda_N\int_\Omega \frac{u_\eps^2}{|x|^2}dx\lesssim 
  \begin{cases}
  |\log \eps|^{2\alpha-1}, &\alpha > 1/2,\\[10pt]
\log |\log \eps|,& \alpha=1/2,\\[10pt]
1,& \alpha\in [0,1/2),
 \end{cases}
 \end{equation}
	 \begin{equation}
\label{estBeps}
  B_\eps=\int _{\Omega} \frac{u_\eps^2}{|x|^2}dx\simeq |\log \eps|^{2\alpha+1}, 
  \end{equation}
 and  
\begin{equation}
\label{est.H2u.eps}
  \|u_\eps\|^2_{H^2(\Omega)}\lesssim   \frac{|\log \eps|^{2\alpha}}{\eps^{4-2\mu}}.
\end{equation}
\end{lemma}

\begin{remark}
	As a consequence we get that the quotient $A_\eps/B_\eps$ satisfies
	\begin{equation}
\label{a/b}
\frac {A_\eps}{B_\eps}\lesssim 
\begin{cases}
	\frac 1{|\log \eps|^2},& \alpha>\frac 12,\\[10pt]
	\frac{\log |\log \eps}{|\log \eps|^2},& \alpha=\frac 12,\\[10pt]
	\frac{1}{|\log \eps|^{2\alpha+1}}, & \alpha\in [0,\frac 12).
\end{cases}  
\end{equation}

\end{remark}



 \begin{proof}  Using that $u_\eps(x)=\tilde u_2(|x|) \eta_\eps(r)\psi(r)$,  
 we obtain
\[
B_\eps\leq \int_{\eps^2}^{1/2} r^{N-3}|\tilde u_2(r)|^2 \eta^2_\eps(r)dr\lesssim \int_{\eps^2}^{1/2} \frac{|\log r|^{2\alpha}}r  dr\lesssim |\log \eps|^{2\alpha+1}
\]
and
\[
B_\eps\gtrsim \int_{\eps}^{1/4} \frac{|\log r|^{2\alpha}}r dr\gtrsim |\log \eps|^{2\alpha+1},
\]
and then \eqref{estBeps}. 

Estimate \eqref{estAeps} is more delicate. 

Let us recall that for any $u\in \mathcal{H}$, 
\[
\|u\|_{H}^2=\int_{\Omega} |x|^{-(N-2)} \left|\nabla \left(\frac {u}{u_2}\right)\right|^2dx=\int_{\Omega}|\nabla u|^2dx-\int_{\Omega}\Lambda_N\frac{u^2}{|x|^2}dx.
\]
For
$u_\eps$ it holds  \[
A_\eps =\int _{\Omega} \Big| \nabla u_\eps-u_\eps \frac{\nabla u_2}{u_2} \Big|^2dx=  \int_\Omega |u_2\nabla \theta_\eps|^2dx,
\]
where \begin{equation}\theta_\eps(r)=\left(\log \frac 1r\right)^{\alpha}\eta_\eps(r)\psi(r).\end{equation}

Note that 
\[\nabla \theta_\eps=\Big (\log (\frac 1{|x|})^{\alpha}\nabla \eta_\eps - \alpha(\log \frac 1 {|x|})^{\alpha-1}\frac {x}{2|x|^2}\eta_\eps\Big)\psi+ (\log (\frac 1{|x|})^\alpha)\nabla \psi,
\]
 and, according to the properties of $\psi$ and $\eta_\eps$, 
\begin{align*}
   \int_{\Omega}|u_2\nabla \theta_\eps|^2dx& \lesssim  \int_{|x|<1/2}\left(u_2^2 |\nabla \eta_\eps|^2 |\log |x||^{2\alpha}+u_2^2\eta_\eps^2 \frac{|\log |x||^{2\alpha-2}} {|x|^2 }\right)dx+\int _{1/4<|x|<1/2}|\log |x||^{2\alpha}\eta_\eps^2dx \\
   &\lesssim\int_{\eps^2}^{\eps } r|\log r|^{2\alpha}\frac{dr}{r^2 |\log \eps|^2} +\alpha^2 \int_{\eps^2}^{r_0} \frac{|\log r|^{2\alpha-2}dr}{r} +\int_{1/4}^{1/2} \frac{|\log r|^{2\alpha}dr}{r}\\
   &\lesssim \begin{cases}
|\log \eps|^{2\alpha-1}, &\alpha > 1/2,\\
1+ \log |\log \eps|,& \alpha=1/2,\\
1+|\log \eps|^{2\alpha-1},& \alpha\in [0,1/2).
 \end{cases}
\end{align*}
This completes the proof of \eqref{estAeps}.


Let us now estimate   the $H^2(\Omega)$ norm of $u_\eps$. For simplicity assume that $\psi \equiv 1$ since the main contribution comes from the singularity near the origin. As above we have
\[
\|u_\eps\|^2_{L^2}=\int_{\eps^2}^{1} r^{N-1}|\tilde u_2(r)|^2 \eta^2_\eps(r)dr\lesssim \int_{\eps^2}^{1} r {|\log r|^{2\alpha}}  dr\lesssim 1.
\]
Using the expression of $u_\eps$ and the properties of $\eta_\eps$ we have
\begin{align*}
\label{}
  |u_\eps'(r)|&\lesssim r^{-N/2}|\log r|^{\alpha}\eta_\eps(r)+r^{-N/2}|\log r|^{\alpha-1}\eta_\eps(r)+r^{-N/2+1}|\log r|^{\alpha} \eta'_\eps(r)\\
  &\lesssim r^{-N/2}|\log r|^{\alpha}\eta_\eps(r)+r^{-N/2+1}|\log r|^{\alpha} \eta'_\eps(r)\\
  &\lesssim r^{-N/2}|\log r|^{\alpha}+r^{-N/2}\frac{|\log r|^{\alpha}}{|\log \eps|}\lesssim r^{-N/2}|\log r|^{\alpha}.
\end{align*}
It implies that
\begin{align*}
  \|\nabla u_\eps\|_{L^2(\Omega)}^2&=\int_{\eps^{2-\mu}}^1 r^{N-1}|u_\eps'(r)|^2dr\lesssim 
\int_{\eps^{2-\mu}}^1 r^{-1}|\log r|^{2\alpha}dr\lesssim |\log \eps|^{2\alpha+1}.
\end{align*}
The second order derivatives of $u_\eps $ satisfies
\begin{align*}
    |D^2u^\eps(x)| \sim |u_\eps''(r)| \lesssim  & \quad  \eta_\eps(r)r^{-N/2-1}\Big(|\log r|^{\alpha}+|\log r|^{\alpha-1}+|\log r|^{\alpha-2} \Big)  \\
  &+\eta_\eps'(r)r^{-N/2}\Big(|\log r|^{\alpha}+|\log r|^{\alpha-1} \Big)\\
  &+\eta_\eps''(r)r^{-N/2+1}|\log r|^{\alpha}\\
  \lesssim  &\quad  \eta_\eps(r)r^{-N/2-1}|\log r|^{\alpha}+\eta_\eps'(r)r^{-N/2} |\log r|^{\alpha}+\eta_\eps''(r)r^{-N/2+1}|\log r|^{\alpha}.
\end{align*}


This implies that
\begin{align*}
\int_\Omega |\partial_{ij}u_\eps|^2dx&\lesssim \int_{\eps^{2-\mu}}^1r^{N-1}\Big(|u_\eps''(r)|^2+\frac{|u_\eps'(r)|^2}{r^2}\Big )dr\\
&\lesssim \int_{\eps^{2-\mu}}^1 \Big(\eta_\eps^2(r)r^{-3}|\log r|^{2\alpha}+|\eta_\eps'(r)|^2r^{-1}|\log r|^{2\alpha}+|\eta_\eps''|^2r |\log r|^{2\alpha}\Big)dr\\
&\lesssim  \int_{\eps^{2-\mu}}^1  r^{-3}|\log r|^{2\alpha}dr+  \int_{\eps^{2-\mu}}^{\eps } r^{-1}|\log r|^{2\alpha}\frac{dr}{r^2|\log \eps|^2}+  \int_{\eps^{2-\mu}}^{\eps } r |\log r|^{2\alpha}\frac{dr}{r^4|\log \eps|^2}\\
&\lesssim \frac{|\log \eps|^{2\alpha}}{\eps^{4-2\mu}}+\frac{|\log \eps|^{2\alpha-2}}{\eps^{4-2\mu}}\lesssim \frac{|\log \eps|^{2\alpha}}{\eps^{4-2\mu}}.
\end{align*}
The proof of the Lemma is now complete. 
\end{proof}

Let us now prove the desired upper bound in Theorem \ref{main}. For simplicity we treat the case  {$N=3$}. The general case $N\ge 4$ can be dealt with as in \cite{ignat2025} by using Lemma \ref{lower.bound.triangle}. 

We consider \[\tilde u_2(r)=r^{-N/2+1}\left(\log \frac 1r\right)^\alpha, \alpha>\frac 12,\]
and the corresponding $u_\eps$ constructed previously 
\[
u_\eps(x)= \tilde u_2(|x|) \eta_\eps(|x|)\psi(|x|).
\]
 Let us denote $\Pi_hu_\eps$ the projection of $u_\eps$ on the space $V_h$. In view of the classical estimate \eqref{fem.error.sobolev} it satisfies
\[
\|\nabla (\Pi_h u_\eps -u_\eps)\|_{L^2(B)}\lesssim h \|u_\eps \|_{H^2(B)}. 
\]
Since $\Pi_h $ is the projection on $V_h$ it follows that
\[
\int_{B}|\nabla (\Pi_h u_\eps)|^2dx=\int _B |\nabla u_\eps |^2dx-\int_{B}|\nabla (u_\eps -\Pi_h u_\eps)|^2dx.
\]




Also
\begin{align*}
\int_{B}\frac{|\Pi_h u_\eps|^2}{|x|^2}dx&\geq \int_{B}\frac{u_\eps^2}{|x|^2}dx-\frac 14 \int_{B}\frac{|u_\eps-\Pi_hu_\eps|^2}{|x|^2}dx\\
&\geq  \int_{B}\frac{u_\eps^2}{|x|^2}dx-\frac{1}{4\Lambda_N}\int_{B}|\nabla (u_\eps -\Pi_h u_\eps)|^2dx.
\end{align*}
Let us denote
\[
R_{\eps,h}=\frac{\int_{B}|\nabla (u_\eps -\Pi_h u_\eps)|^2dx}{\int_{B} u_\eps^2 |x|^{-2}dx},\quad Q_\eps=\frac{\int _B |\nabla u_\eps |^2dx}{\int_{B} u_\eps^2 |x|^{-2}dx}.
\]
We know from Lemma \ref{est.u.eps} that \
\[
Q_\eps =\frac{A_\eps}{B_\eps}=\Lambda_N+O(|\log \eps|^{-2})
\] and
\[
R_{\eps,h}\lesssim \frac{h^2 \|u_\eps\|^2_{H^2(B)}}{|\log \eps|^{2\alpha+1}}\lesssim \frac{h^2  }{|\log \eps|^{2\alpha+1}} \frac{|\log \eps|^{2\alpha}}{\eps^{4-2\mu}}=
\frac{h^2}{\eps^{4-2\mu} |\log \eps|}.
\]
Under the assumption that $R_{\eps,h}$ is small enough we get
\begin{align*}
S_{1h}&=\min _{v\in V_h}\frac{\int_\Omega |\nabla v|^2dx}{\int_\Omega v^2|x|^{-2}dx} \leq \frac{\int_{B}|\nabla (\Pi_h u_\eps)|^2dx}{\int_{B}{|\Pi_h u_\eps|^2}|x|^{-2}dx}\leq 
\frac{\int _B |\nabla u_\eps |^2dx+\int_{B}|\nabla (u_\eps -\Pi_h u_\eps)|^2dx}{\int_{B}u_\eps^2|x|^{-2}dx-\frac{\Lambda_N}4\int_{B}|\nabla (u_\eps -\Pi_h u_\eps)|^2dx}   \\
&=\frac{Q_\eps +R_{\eps,h}}{1-\frac{\Lambda_N}4 R_{\eps,h}}\leq (Q_\eps +R_{\eps,h})(1+2R_{\eps,h})\leq Q_\eps + O(R_{\eps,h})\\
&\leq \Lambda_N+O\Big (\frac 1{|\log \eps|^2}\Big)+O(\frac{h^2}{\eps^{4-2\mu} |\log \eps|}).
\end{align*}
Taking \begin{equation}\eps^2\simeq h\end{equation} we have that \begin{equation} R_{\eps h}=O(\frac{h^
\mu}{|\log h|}), \quad \mu\in (0,1), \end{equation}
and we
 get the desired estimate
\[
\Lambda_{h} \leq \Lambda+O(\frac 1{|\log h|^2}).
\]

\section{Proof of Theorem \ref{main.2}}
Classical arguments on the finite element approximation of eigenvalues show that
\begin{equation}
\mu_1(\Omega)-\mu_{1h} \sim \inf _{v_h\in V_h} \| \phi_1 -v_h\|_{\mathcal{H}}^2
\end{equation}
where $\phi_1$ is the corresponding first eigenfunction associated to $\mu_1(\Omega)$. In the case where $\Omega$ is the unit ball we have
\begin{equation} \phi_1(x)=\phi_1(|x|)=|x|^{-(N-2)/2}J_0(z_{0,1}|x|).
\end{equation} 
When $\Omega$  is a smooth domain containing the origin, one can show, using a cut-off argument, that $\phi_1$ exhibits the same type of singularity near the origin as in the case of the unit ball.

It remains to quantify the above distance in the particular case of the unit ball. 

Let us first prove the upper bound. A similar computations as in Lemma \ref{est.u.eps} with $\alpha=0$ gives us \begin{align*}
  \inf _{v_h\in V_h} \| \phi_1 -v_h\|^2_\mathcal{H}&\lesssim  
  \|\phi_1-\phi_{1,\eps}\|^2_{\mathcal{H}} +\|\phi_{1,\eps }- I^h \phi_{1,\eps }\|^2_{\mathcal{H}}\\
  &\lesssim \frac {1}{|\log \eps|}+ \|\nabla (\phi_{1,\eps }- I^h \phi_{1,\eps })\|_{L^2(\Omega)}^2\\
  &\lesssim \frac {1}{|\log \eps|}+ \frac{h^2}{\eps^{4-2\mu}}.
\end{align*}
Taking $\eps^2\simeq h$ we obtain the desired upper bound. 

Let us now prove that for any $v_h\in V_h$
\[
 \| \phi_1 -v_h\|^2_{\mathcal{H}}\gtrsim \frac 1{|\log h|}.
\]
Using the Hardy inequality with logarithmic correction in Lemma \ref{hardy.log.2} we obtain 
\begin{align*}
\label{}
   \| \phi_1 -v_h\|^2_{\mathcal{H}}\gtrsim \int_{\Omega}\frac{|\nabla \phi_1-\nabla v_h|^2dx}{|\log(1/|x|)|^2}=\sum_{T\in \mathcal{T}_h} \int_T \frac{|\nabla \phi_1-\nabla v_h|^2dx}{|\log(1/|x|)|^2}.
\end{align*}
It is interesting to notice that for all the triangles situated outside the ball of radius $h$ the contribution if of order $1/{|\log h|^2}$. The main contribution comes from the triangle $T_0$  containing the origin or the finitely many triangles for which the origin lies on their boundaries.

 To simplify the presentation, let us consider the  case in which the origin is the in center of $T_0$,
and  a ball of radius $\rho_{T_0}\simeq h$ centered at $x=0$ is contained in $T_0$. Otherwise we can perform a similar computation choosing a conical subset. 

In this case, this main contribution is given by
\[
I_h= \int_{|x|\leq h} \frac{|\nabla \phi_1-\nabla v_h|^2dx}{|\log(1/|x|)|^2}\geq \inf _{A\in \rr^N} \int_{|x|\leq h} \frac{|\nabla \phi_1-A|^2dx}{|\log(1/|x|)|^2}.
\] 
Since 
\[
\nabla \phi_1(x)=\phi_1'(|x|)\frac x{|x|}
\]
 we obtain that
 \[
 |\nabla \phi_1-A|\geq ||\phi'_1(r)|-|A|| 
 \]
 and we have to prove that for any $A\geq 0$
 \[
 f(A)=A^2 \int _0^h \frac {r^{N-1}dr}{|\log(1/|x|)|^2}-2A  \int _0^h \frac {r^{N-1}|\phi'(r)|dr}{|\log(1/|x|)|^2}+ \int _0^h \frac {r^{N-1}|\phi'(r)|^2dr}{|\log(1/|x|)|^2}\gtrsim \frac 1{|\log h|},
 \]
 where $\phi_1(r)=r^{-(N-1)/2}J_0(z_{01}r)$. 

 Denoting $f(A)=A^2a_h -2Ab_h+c_h$ we know that the minimum is taken for $A=b_h/a_h$ and 
 \[
 \min _{A\in \rr } f(A) =f(\frac {b_h}{a_h})=c_h-\frac{b_h^2}{a_h}.
  \]
 We use that for any the following expansion as $h\rightarrow 0$, valid for $\alpha\geq -1$:
 \[
 \int_0^h \frac{r^\alpha}{|\log r|^2}\simeq 
 \begin{cases}
 	\frac{h^{\alpha+1}}{|\log h|^2},& \alpha>-1,\\
 		\frac{1}{|\log h|},& \alpha=-1.
 \end{cases} 
 \]
 Since $\phi_1'(r)\simeq r^{-N/2}$ as $r\rightarrow 0$ we obtain that $$c_h\simeq |\log h|^{-1}, \quad a_h\simeq r^{N/2}|\log h|^{-2}, \quad b_h\simeq r^{N/2}|\log h|^{-2}.$$
 Then 
 \[
  \min _{A\in \rr } f(A)\simeq \frac 1{|\log h|}.
 \]

 \section{Proof of Theorem \ref{main.3}} We consider the case where the domain $\Omega$ is the unit ball since the singularity analysis near the origin is the same for all domains containing $x=0$.

In the present case,  the norm introduced by the bilinear form is equivalent to the $H^1_0(B)$-one.  Thus, it is sufficient to provide sharp upper bounds on \[
 d(\phi_1, V_h)\simeq \inf_{v_h\in V_h} \|\nabla \phi_1 -\nabla v_h \|_{H^1_0(B_1)},
 \]
 where $\phi_1$ is the first eigenfunction.


  Let us set \[
 m=\sqrt{\Lambda_N-\Lambda}\in \Big(0,\frac{N-2}2\Big].\]  Recall  that  
  in the case of the ball the first eigenfunction can be explicitly computed  (see \cite{MR1760280}), $\phi_1(x)=\phi_1(|x|)$,
 \[
 \phi_1(r)=r^{-N/2+1} J_{m}(j_{m,1}r)\simeq r^{-N/2+1+m}, r\simeq 0,
 \]
 where $J_m$ is the Bessel function of order $m$ and $j_{m,1}$ is its  first zero.  

 This eigenfunction $\phi_1$ belongs to $H^{1+s}(B_1)$ for all $0<s<m$ if $m< (N-2)/2$ and it is $C^\infty(B_1)$ if $m=(N-2)/2$. 

% We emphasize that prove that 
% \begin{equation}\label{est.eps}
%  \inf_{v_h\in V_h} \|\nabla \phi_1 -\nabla v_h \|_{H^1_0(B_1)}\simeq h^{\sqrt{\Lambda_N-\Lambda}}
%\end{equation}
%it is not sufficient to use the classical error estimates for the finite elements 
%\[
%\|\nabla \phi_1 -\nabla v_h \|_{H^1_0(B_1)}\lesssim  h^{s}\|\phi_1\|_{H^{s+1}(B_1)}
%\]
%because this will provide us a sub-optimal order of convergence. 

Let us prove the upper bound. We take a function $v_h$ that vanishes in the triangle $T_0$ containing the origin.  We split in two parts:
\[
\|\nabla \phi_1 -\nabla v_h \|_{L^2(B_1)}^2\leq \int_{|x|\lesssim h}|\nabla \phi_1|^2dx +h^2 \int_{|x|\gtrsim h} |D^2\phi_1|^2dx:=I_1+I_2.
\]
When $m<\frac N2-1$ we have 
\[
I_1\leq \int_0^h r^{N-1}r^{2(-N/2+m)}dr\simeq h^{2m}
\] 
while for $m=\frac N2 -1$ we have $I_1\simeq h^N$ since $
\phi_1$ is $C^\infty$ in this case.  


For the second term we first consider the case $N\geq 5$. When $m=\frac{N-2}2$ clearly we have $I_2\lesssim h^2$.  For $0<m<\frac{N-2}2$ a similar argument as for $I_1$ yields
\[
I_2\lesssim h^2\int_h^1 r^{N-1}r^{2(-N/2-1+m)}dr=h^2\int_h^1 r^{2m-3}dr  \lesssim   \begin{cases}
h^{2m},& 0<m<1,\\
h^2|\log h|, & m=1,\\
h^2, &m\in (1, \frac{N-2}2). 
  \end{cases}
\]
Putting together the result for $I_1$ and $I_2$ leads to the desired result.

When $N=4$ we obtain, in a similar way, that $I_2\leq h^2$ for $m=\frac{N-2}2=1$ and \[
I_2\leq h^2\int_h^1 r^{2m-3}dr\simeq h^{2m}, \ 0<m<1.
\]

In dimension $N=3$ we get $I_2\leq h^2$ when $m=\frac 12=\frac{N-2}2$ and 
 \[
 I_2\leq h^2 \int_{|x|\gtrsim h} |D^2\phi_1|^2dx
\leq h^2\int_h^1 r^{2m-3}dr \simeq h^{2m}, \ 0<m<1/2.
\]

To obtain the lower bound in \eqref{est.hardy.3} we divide the integral in two parts, the first one as in the proof of Theorem \ref{main.2} and 
the second one integrating outside the ball of radius $h$:
\[
 \|\nabla \phi_1 -\nabla v_h \|_{L^2(B_1)}^2=\int_{|x|<h}|\nabla \phi_1 -\nabla v_h|^2dx+\int_{h<|x|<1}|\nabla \phi_1 -\nabla v_h|^2dx=I_1+I_2.
\]
Let us consider the case $N\geq 5$ since the others are similar.  For $I_1$ the same arguments as in the proof of Theorem \ref{main.2}
 give us that $I_1\gtrsim h^{2m}$ for $0<m<\frac{N-2}2$ or $I_1\gtrsim h^{2N}$ if $m=\frac{N-2}2$. 
Using Lemma \ref{lower.bound.triangle} as in \cite{ignat2025} we get 
 \[
 I_2\gtrsim  \begin{cases}
h^{2m},& 0<m<1,\\
h^2|\log h|, & m=1,\\
h^2, &m>1. 
  \end{cases}
 \]
 The proof is now complete.



\section{Conclusions and Open Problems}

In this work, we have analyzed the finite element approximation of the best Hardy constant in bounded domains containing the origin for dimensions $N \geq 3$. Despite the absence of minimizers for the Hardy inequality in the standard Sobolev space $H^1_0(\Omega)$, we have rigorously established that the first eigenvalue of the corresponding discrete eigenvalue problem converges to the continuous Hardy constant as the mesh size $h \to 0$.

Our main result provides an explicit convergence rate of order $1/|\log h|^2$, independent of the spatial dimension, and reflects the singular nature of the underlying functional inequality. The analysis demonstrates how the finite element method is capable of capturing the concentration phenomena inherent in the minimization sequences that saturate the Hardy inequality.

Wee have also analysed similar approximation issues for two closely related eigenvalue problems.

Several open problems naturally arise from this study:
\begin{itemize}
\item{\it The $2$-dimensional case:} As mentioned in the introduction, the two-dimensional case is critical and requires an inverse-square logarithmic correction to the Hardy inequality, as shown in \cite{MR1938711}. This case would therefore require a more detailed analysis.

\item {\it Other Hardy inequalities:} The literature on Hardy inequalities is extensive; we refer the reader to the monograph \cite{peral} for a comprehensive overview. The finite element approximation techniques developed in this paper could, in principle, be systematically applied to the many existing variants of the Hardy inequality. 
\item {\it Weighted spectral problems:} Using that 
 \[  \mu_1(\Omega)=\min _{u\in \mathcal{H}}\frac{\|u\|^2_{ \mathcal{H}} }{\|u\|^2_{L^2(\Omega)}}=
\min _{v\in W^{1,2}_{0}(|x|^{-(N-2)}dx,\Omega)} \frac{\int _\Omega  |x|^{-(N-2)} |\nabla v|^2dx}{\int_ \Omega |x|^{-(N-2)} v^2dx}
\]
one can consider introducing the finite element approximation in this weighted setting 
 \[\tilde \mu_{1h}(\Omega)=
\min _{v\in V_h} \frac{\int _\Omega  |x|^{-(N-2)} |\nabla v|^2dx}{\int_ \Omega |x|^{-(N-2)} v^2dx}
\]
and analyze the approximation rates.


	\item {\it Higher-Order Finite Elements:}
It would be of interest to investigate whether similar convergence rates can be established for higher-order finite element spaces and other finite-element variants, like discontinuous Galerkin approximations.
	\item	 {\it  Adaptive Mesh Refinement:}
Given the concentration of minimizing sequences near the singularity at the origin, adaptive mesh refinement strategies could improve the numerical approximation. Theoretical analysis of such adaptive methods in this singular context remains an open challenge.
	\item	 {\it Extension to Non-Radial Settings and General Domains:}
While our analysis is presented for general bounded domains containing the origin, extensions to more complex geometries or domains with additional singularities could reveal new phenomena. The same can be said in the context of multi-polar Hardy inequalities (see \cite{cazacu2013improved} for the analysis in the continuous setting).
	\item	{\it Other Singular Inequalities:}
A natural direction for future work is to study the finite element approximation of best constants in other critical inequalities, such as Rellich or Hardy-Sobolev inequalities, where similar non-attainability issues arise. Similar issues also arise in the fractional setting, see \cite{de2024fractional}.

\end{itemize}
We hope that this contribution stimulates further research on the numerical analysis of critical inequalities and the development of numerical methods tailored for singular variational problems.

