    \item[\textbf{\makebox[12pt]{$\hspace{0pt}(\leftrightarrow$)}}] \hspace{2pt}between QUBO-Relaxed with 10 initializations and 50 initializations 
    \item[\textbf{($\downarrow$)}] worse than QUBO-Relaxed with 10 initializations
\end{itemize} 
