\subsection{Discrimination Prompt Words Selecting Algorithm}

\begin{algorithm}
\caption{Find Similar Counterexamples by Discrimination Tree}
\label{alg:ce_search}
\begin{algorithmic}
\Procedure{HistoryOracle}{C,q}
    \If{$q\in C_{EQ}$}
        \State \textbf{return} $C_{EQ}[q]$
    \Else
        \State \textbf{return} False
    \EndIf
\EndProcedure
\State Represent \textit{HistoryOracle} by $O_{\mathcal{H}}$
\Procedure{Discrimination Based Word Search}{q}
\State Construct the hypothesis $\mathcal{H}$ via any active learner by $O_{\mathcal{H}}$
\State Build the discrimination tree $DT$ based on $\mathcal{H}$
\State Find the lowest common ancestor $d$ of $\mathcal{H}[q]$ and another child $s$ of $d$.
\State Use \textit{Levenshtein Distance} $L$ to estimate the similarity between two words.
\State Initialize $ l_q\leftarrow \inf, l_s\leftarrow \inf$.
\State Let $L$ represent Levenshtein Distance.
\For{each query $q_i$ in the $C$}
    \If{$\mathcal{H}[q_i]=\mathcal{H}[q]$ and $L(q_i, q) < l_q$}
        \State $l_q\leftarrow L(q_i, q)$
        \State $w_q\leftarrow q_i$
    \ElsIf{$\mathcal{H}[q_i]=\mathcal{H}[s]$ and $L(q_i, q) < l_s$}
        \State $l_s\leftarrow L(q_i, q)$
        \State $w_s\leftarrow q_i$
    \EndIf
\EndFor 
\State \textbf{return} $w_q, w_s$
\EndProcedure
\end{algorithmic}
\end{algorithm}





