        \section{Preliminaries}\label{sec:preliminaries}

                %

\subparagraph*{Functions and Sets}
For $n \in \mathbb{N}$, we write $[n]:= \{1, \dots, n\}$. Given a set $S$
we write $2^S$ to denote the power set of $S$. Whenever writing $\overline{a}$ to denote
a $k$-tuple, we write $a_i$ to denote the tuple's $i$-th component;
i.e., $\overline{a}=(a_1,\dots, a_k)$. Moreover, we write $\tilde{a} := \{a_1, \dots, a_k\}$. For a function $f \colon X \to Y$ and $X' \subset X$ we write $f\restriction_{X'}$ to denote the restriction of $f$ to $X'$. We extend this operations to sets of functions in the obvious way. Given disjoint sets $X, X'$ and two functions $f \colon X \to Y, g\colon X' \to Y'$ we define $f \times g \colon X \cup X' \to Y \cup Y'$ as follows
\[
(f \times g) (x) = \begin{cases}
f(x) & x \in X \\
g(x) & x \in X'.
%
%
\end{cases}
\]
We will often combine two sets of functions pairwise in this way. Formally, for a set $S$ of functions with domain $X$ and a set $T$ of functions with domain $X'$ we define $S \times T = \{f \times g \, \mid \, f \in S,\, g \in T\}$. We also use $\times$ to denote Cartesian product in the normal sense; we can overcome this seeming mismatch by viewing a function $f \colon X \to D$ as a tuple with coordinates in bijection with $X$ such that the $x$-th coordinate is $f(x)$.

\subparagraph*{Graphs and Hypergraphs}
A \emph{hypergraph} $\graphH = (\vertexH, \edgeH)$ is a pair, consisting of a finite set of vertices $\vertexH$ and a finite set of edges $\edgeH \subseteq 2^{\vertexH}$. If $|e| = 2$, for every $e \in \edgeH$, we say that $\graphH$ is a \emph{graph}. Note that via this definition we are implicitly assuming that all graphs are undirected and \emph{simple}, i.e., that they do not contain self-loops. We write $\graphK_k$ for
the complete graph on $k$ vertices, which we also call the \emph{$k$-clique}. 

Given a hypergraph $\graphH = (\vertexH, \edgeH)$ and a subset $X \subseteq \vertexH$,
%
 an \emph{edge cover} of $X$ is a set $S \subseteq \edgeH$ such that for all $ v\in X$ there is some $e \in S$ with $v \in e$. A \emph{fractional edge cover} for $X$, is the natural fractional relaxation of an edge cover for $X$, i.e. a function $s \colon \edgeH \to [0,1]$, such that for every $v \in X$, we have that
$\sum_{e \ni v} s(e) \ge 1$. We write $\weight(s):= \sum_{e \in \edgeH} s(e)$. Then $\fec(X)$\confORfull{ }{---the 
\emph{fractional edge cover number of $X$ in $\graphH$}---}is defined to be minimum of $\weight(s)$ over all 
fractional edge covers of $X$. 

%

Note that $\fec$ can be viewed as a function from $2^{\vertexH} \to [0,1]$. More generally, let $\mathbf{S}(\graphH)$ be the set of all functions $f \colon 2^{\vertexH} \to [0,1]$ with $f(\emptyset) = 0$ that satisfy the following properties:
\begin{enumerate}
\item $f(S) \le f(T)$ for all $S \subseteq T \subseteq \vertexH$,
\item $f(e) \le 1$ for every $e \in \edgeH$, and 
\item $f(S) + f(T) \ge f(S \cap T) + f(S \cup T)$ for every $U, V \subseteq \vertexH$. 
\end{enumerate}
%
Observe that $\fec \in \mathbf{S}(\graphH)$.

\subparagraph*{Width Measures}
A \emph{tree decomposition} of a hypergraph $\graphH$ is a pair
$(\treeT,\beta)$ where $\treeT$ is a tree and $\beta\colon \vertexT \to 2^{\vertexG}$ associates to every node $t\in \vertexT$ a bag $\beta(t)$ such
that:
\begin{enumerate}
\item for every $v\in \vertexH$ the set $\{t \in \vertexT \mid v\in
  \beta(t)\}$ is a non-empty connected subset of $\vertexT$ and
\item for every $e \in \edgeH$ there is some $t\in \vertexT$ such that $ e \subseteq
  \beta(t)$.
\end{enumerate}
%
We write $\classT(\graphH)$ for the set of tree decompositions of $\graphH$. The width of a tree decomposition is $\max_{t\in \vertexT}|\beta(t)|-1$
and the \emph{treewidth} of $\graphH$ is the minimum width of all $(\treeT,\beta) \in \classT(\graphH)$.


Treewidth is an incredibly influential concept and has inspired many more sophisticated notions of width, see~\cite{DBLP:journals/cj/HlinenyOSG08} for a survey. In this paper we deal with two such measures: fractional hypertree width and submodular width. The \emph{fractional hypertree width} of a tree decomposition $(\treeT,\beta)$ is defined to be the maximum value of $\fec(\beta(t))$ over all $t \in \vertexT$. The fractional hypertree width of a hypergraph $\graphH$ is the minimum fractional hypertree width over all tree decomposition of $\graphH$, in symbols
\[
\fhtw(\graphH) := \min_{(\treeT,\beta) \in \classT(\graphH)} \, \max_{t \in \vertexT} \fec(\beta(t)).
\]
%
So if $\graphH$ has low fractional hypertree width then there is a
tree decomposition where every bag has small fractional edge cover
number.
%
%
%
%
The submodular width is more demanding; if $\graphH$ has low
submodular width then for \emph{every} $ f \in \mathbf{S}(\graphH)$
 there is a
tree decomposition where every bag evaluates to a small number
under $f$.
To be
precise the submodular width of $\graphH$ is defined to be
\[
\subw(\graphH) := \sup_{f \in \mathbf{S}(\graphH)} \min_{(\treeT,\beta) \in \classT(\graphH)} \, \max_{t \in \vertexT} f(\beta(t)).
\]
%
From the definitions, it is easy to see that $\tw(\graphH) \le \fhtw(\graphH) \le \subw(\graphH)$. \confORfull{}{Note that we will not work directly with the definitions of width measures but instead use known characterisations of what it means to have high width to prove lower bounds.}


\subparagraph*{Structures and Homomorphisms}

A (relational) signature $\sigma$ is a set of relation symbols $R$, each  equipped with an arity $r =r(R)$. A (finite, relational) $\sigma$-structure $\strucA$
consists of a finite universe $A$ and  relations
$R^{\strucA}\subseteq A^r$ for every $r$-ary relation
symbol $R\in \sigma$. The size of $\strucA$ is defined to be $\|\strucA\|:=
\sum_{R \in \sigma} |R^{\strucA}|$ and the \emph{arity} is the maximum arity of all relations in $\sigma$.


 The \emph{Gaifman graph} of
$\strucA$ is the graph with vertex set $A$ and edges $\{u,v\}$ for any
distinct $u,v$ that occur together in a tuple of a relation in
$\strucA$. We say $\strucA$ is \emph{connected} if its Gaifman graph is connected and assume henceforth that all structures in this paper are connected. The \emph{hypergraph} of a $\sigma$-structure $\strucA$ is a hypergraph with vertex set $A$, such that $e \subseteq A$ is an edge iff there is a tuple $\overline{e} \in R^{\strucA}$ for some $R \in \sigma$, such that $\tilde{e} = e$.

For $x \in \{\textrm{tree, fractional hypertree, submodular}\}$, the \emph{$x$-width} of a structure is the $x$-width of its
hypergraph. For a set of structures $\mathsf{A}$, we write $\tw(\classA) := \sup_{\strucA \in \classA} \tw(\strucA)$, which may be infinite. If $\tw(\classA)$ is finite we say that $\classA$ has \emph{bounded treewidth}, otherwise we say it has unbounded treewidth. We define the analogous notions for fractional hypertree and submodular width. It is known that there are exists a class of structures with bounded fractional hypertree width but unbounded treewidth \cite{DBLP:journals/talg/GroheM14} and a class of structures with bounded submodular width but unbounded fractional hypertree width \cite{DBLP:journals/mst/Marx11}. Finally, if there is some integer $r$ such that every structure in $\classA$ has arity at most $r$, we say that $r$ has \emph{bounded arity}. In this case $\classA$ has bounded treewidth iff $\classA$ has bounded fractional hypertree width iff $\classA$ has bounded submodular width. 

\confORfull{Finally, a}{Finally, given two $\sigma$-structures $\strucA, \strucB$ a} \emph{homomorphism from $\strucA$ to $\strucB$} is a function $h \colon A \to B$ that preserves all relations, i.e., for every $r$-ary $R \in \sigma$ and $\bar{a} =(a_1, \dots, a_r) \in R^{\strucA}$ it holds that $h(\bar{a}) := (h(a_1), \dots, h(a_r)) \in R^{\strucB}$. We write $\Hom(\strucA, \strucB)$ for the set of all homomorphisms from $\strucA$ to $\strucB$. 




