        \section{Lower Bounds for \texorpdfstring{$\{\cup, \times\}$-}{Union-Product }Circuits via Rectangle Covers} \label{s:rect}

        %

In this section, we introduce a by now standard framework---pioneered in \cite{DBLP:conf/ijcai/BovaCMS16}---for proving lower bounds on $\{\cup,\times\}$-circuits  and their subclasses: analysing rectangle covers. This enables us to reduce reasoning about complicated objects ($\{\cup,\times\}$-circuits) to  simple ones (combinatorial rectangles). For this we need the following definition.

\begin{definition}[Rectangle]
Let $X$ be a finite set, $(Y,Z)$ a partition of $X$ and $\mathcal{R}$ a set of functions with domain $X$. Then $\mathcal{R}$ is an \emph{$(X,Y)$-rectangle} iff $\mathcal{R} = \mathcal{R}\restriction_Y \times \mathcal{R}\restriction_Z$.
\end{definition}

\begin{example}
Let $X= \{y,z\}$, $Y =\{y\}$ and $Z = \{z\}$. Further let $\mathcal{R} = \{f, g \}$, where $f(x) = f(y) = 0$ and $g(x) = g(y) = 1$. Then $\mathcal{R}$ is \emph{not} a $(Y,Z)$-rectangle. To see this note that $ \mathcal{R}\restriction_Y \times \mathcal{R}\restriction_Z$ contains the map $\{x \mapsto 0, y \mapsto 1\}$. On the other hand the set of functions $\{f \, \mid \, f : \{y,z\} \to \{0,1\}\}$ is a $(Y,Z)$-rectangle. 
\end{example}

\noindent Note that trivially every set of functions with domain $X$ is a $(X, \emptyset)$-rectangle. To get a non-trivial notion we introduce the notion of a \emph{balanced} partition; that is a partition $(Y,Z)$ of $X$ such that $\min(|Y|, |Z|) \ge |X|/3$. We then say a set $\mathcal{R}$ is a \emph{balanced} rectangle, if it is a $(Y,Z)$-rectangle for some balanced partition $(Y,Z)$. We say that a set of balanced rectangles $\{\mathcal{R}_i\}_{i \in \mathcal{I}}$ is a \emph{balanced rectangle cover} for $\Hom(\strucA, \strucB)$ if $\bigcup_{i \in \mathcal{I}} \mathcal{R}_i = \Hom(\strucA, \strucB)$. The following lemma shows that if there is a small $\{\cup,\times\}$-circuit computing $\Hom(\strucA, \strucB)$, then there is a small balanced rectangle cover for $\Hom(\strucA, \strucB)$. 

\begin{lemma}[{\cite{DBLP:conf/ijcai/BovaCMS16, DBLP:conf/stacs/BerkholzMW24}}] \label{lem: basic_rect}
Let $\strucA, \strucB$ be structures and let $\C$ be a $\{\cup,\times\}$-circuit of size $s$ computing $\Hom(\strucA, \strucB)$. Then there is a balanced rectangle cover of $\Hom(\strucA, \strucB)$ of size $s$. 
%
%
\end{lemma}

\noindent Therefore, to prove lower bounds on $\{\cup,\times\}$-circuits it suffices to prove lower bounds on the size of balanced rectangle covers. This result was proven for Boolean functions in \cite[Theorem 6]{DBLP:conf/ijcai/BovaCMS16} and extended to general sets of functions in \cite[Lemma 26]{berkholz2023characterization}. 

In fact, we need a slight generalisation of Lemma~\ref{lem: basic_rect} that allows us to balance rectangles with respect to some weighting function $f : 2^{A} \to \mathbb{R}^{+}$ defined on subsets of $\strucA$. To be precise, we say that a partition $(X,Y)$ of $A$ is $f$-balanced if $\min(f(X), f(Y)) \ge f(A)/3$. We define the notions of an $f$-balanced rectangle and an $f$-balanced cover in the obvious way. To ensure the proof goes through we need an $f$ which is sufficiently small on singletons and which is \emph{subadditive on disjoint subsets}. That is on disjoint sets $S,T \subseteq A$, it holds that $f(S \cup T) \le f(S) + f(T)$. \confORfull{See Appendix~\ref{a:weighted} for a proof.}{}

\begin{lemma} \label{lem:weightedrect}
Let $\strucA, \strucB$ be structures, $\C$ be a $\{\cup,\times\}$-circuit  computing $\Hom(\strucA, \strucB)$ and $f: 2^{A} \to \mathbb{R}^{+}$ be a function which is subadditive on disjoint subsets and satisfying $f(\{a\}) \le 2f(A)/3$ for all $a \in A$. Then there is a $f$-balanced rectangle cover of $\Hom(\strucA, \strucB)$ of size $|\C|$. 
%
\end{lemma}


\confORfull{}{%
\begin{proof}[Proof (sketch)]
Every gate $g$ in a $\{\cup,\times\}$-circuit corresponds to a $(\var(g), A \setminus \var(g))$ rectangle, so if we delete the gate from the circuit we remove the corresponding rectangle from the output. Therefore, by iteratively deleting gates we get a rectangle cover and since the number of iterations is at most the number of gates in the original circuit the size bound on the cover follows; again see the proof of \cite[Lemma 26]{berkholz2023characterization}. It remains to show that at each stage we can find a gate to eliminate with an appropriate partition; i.e.\! one that is $f$-balanced. In fact, it is enough to find a gate $\hat{g}$ such that $f(A)/3 \le f(\var(\hat{g})) \le 2f(A)/3$. To see this note that since $f$ is subadditive on disjoint subsets, $f(A \setminus \var(\hat{g})) \ge f(A) - f(\var(\hat{g})) \ge f(A)/3$. We find $\hat{g}$ via a top-down descent in the circuit using the fact that $f$ is subadditive on disjoint subsets. 

In detail, we start at the unique sink $s$ of the circuit, noting that $f(\var(s)) = f(A)$. We maintain the invariant that for every node in our descent $g$, $f(\var(g)) \ge f(A)/3$. Suppose at some point we are at a node $g$. Then by assumption $f(\var(g)) \ge f(A)/3$. If also $f(\var(g)) \le 2f(A)/3$ we set $\hat{g} = g$ and are done. Otherwise, since $f(\var(g)) > 2f(A)/3$, we know that $g$ is not an input gate, so $g$ has two children $g_1, g_2$. If $g$ is a $\cup$-gate, by smoothness we have $f(\var(g_1)) = f(\var(g)) = f(\var(g_2))$, so we choose one of these children arbitrarily and continue the descent from there. Otherwise, $g$ is a $\times$-gate so by decomposability $\var(g_1)$ and $\var(g_2)$ are disjoint. Therefore, by the sub-additivity of $f$ on disjoint subsets we have $f(\var(g)) \le f(\var(g_1)) + f(\var(g_2))$. In particular, there is some child $u$ of $g$ satisfying $f(\var(u)) \ge f(\var(g))/2 \ge f(A)/3$; so we can continue the descent from $u$.
\end{proof} %
}

\noindent To use Lemma~\ref{lem:weightedrect} to prove lower bounds we will define for each $\strucA$ a structure $\strucB$ such that $\Hom(\strucA, \strucB)$ is large but the size of each $f$-balanced rectangle is small, for some appropriate function $f$. In the next section, we will see a simple example of this where $f(S) := |S \cap W|$, where $W$ is the `highly connected set' in $\strucA$. To upper bound the size of rectangles we use the following simple observation about sets of functions. 

\begin{observation} \label{ob:projectub}
Let $\mathcal{R}$ be a set of functions with domain $X$. Then 
$|\mathcal{R}| \le \prod_{x \in X} |\mathcal{R}\restriction_{\{x\}}|.$
\end{observation}






