        \section{Tight Lower Bounds for the Bounded Arity Case} \label{s:tw}

        %
In this section we prove Theorem~\ref{thm: tw_struc}. We first show the result for graphs and then deploy results from \cite{DBLP:conf/icalp/BerkholzV23} to lift it to relational structures of bounded arity. To be precise, the main part of this section aims at showing the following. 

\begin{theorem} \label{thm:graph_lb}
Let  $\graphG$ be a graph. Then there exists arbitrarily large graphs $\graphH$ with $n_{\graphH}$ vertices and at least $n_{\graphH}^2/8$ edges such that any $\{\cup,\times\}$-circuit computing $\Hom(\graphG, \graphH)$ has size $\Omega(n_{\graphH}^{\frac{\tw(\graphG)}{9} - (1 + \delta)})$, for arbitrarily small $\delta>0$. 
\end{theorem}

\noindent To prove this result we use that every graph with high treewidth contains a set with no small balanced seperator.

\begin{definition}[Balanced Separator] \label{def:bal_sep}
 Let $\graphG = (\vertexG,\edgeG)$ be a graph and $W \subseteq \vertexG$ be a non-empty set of vertices. Then we say that $S \subseteq \vertexG$ is a balanced separator with respect to $W$, if $|W \cap C| \le |W|/2$ for every connected component $C$ of $\vertexG - S$. Further, a balanced separator $S$ with respect to $W$ is a $k$-balanced separator with respect to $W$ if $|S| \le k$.
\end{definition}

\begin{lemma}[\cite{reed1997tree, robertson1995graph}] \label{lem: con}
Let $k \in \mathbb{N}$ and let $\graphG$ be a graph with $\tw(\graphG) > 3k$. Then there is some $W \subseteq \vertexG$ with $|W| = 2k+1$ having no balanced $k$-separator. 
\end{lemma}

\noindent This lemma is also used in \cite{DBLP:journals/toc/Marx10} by Marx to prove conditional lower bounds via fairly elaborate reductions. Our setting is different and we are able to deploy Lemma~\ref{lem: con} more directly. We follow a similar proof strategy to in \cite{DBLP:conf/icalp/BerkholzV23}. However, we have a somewhat simpler argument since we argue about rectangle covers rather than directly about the circuit. Our bad instances are the graphs given to us by the following lemma.

\begin{lemma}[{\cite[Lemma 8]{DBLP:conf/icalp/BerkholzV23}}] \label{lem: bad_graph}
For every $\ell \in \mathbb{N}$, there exists some $c_\ell \in \mathbb{R}^{+}$ such that for every sufficiently large integer $n_{\graphH}$ there is a
  graph $\graphH = \graphH(n_{\graphH},\ell)$ with $n_{\graphH}$ vertices, such that
%
  \begin{enumerate}
  \item $\graphH$ has at least $\frac18 n_{\graphH}^2$ edges, \label{label:manyedges}
  \item $\graphH$ contains no complete bipartite
      subgraph $\graphK_{a,a}$ for $a \geq3\log(n_{\graphH})$, and \label{label:nobipart}
  \item the number of $\ell$-cliques in $\graphH$ is at least $c_\ell \cdot n_{\graphH}^{\ell}$. \label{label:manycliques}
    \end{enumerate}
  \end{lemma} 

\noindent So fix some graph $\graphG = (\vertexG,\edgeG)$ with $\tw(\graphG) = w$, $|\vertexG| = n_{\graphG}$ and let $\graphH = \graphH(n_{\graphH},n_{\graphG})$ be as in Lemma~\ref{lem: bad_graph}. Our aim is to show that any $\{\cup,\times\}$-circuit computing $\Hom(\graphG, \graphH)$ has size $n_{\graphH}^{\Omega(w)}$. The idea is to show that any balanced rectangle $\mathcal{R} \subseteq \Hom(\graphG, \graphH)$ with  partition $(X,Y)$ must be small. We do this by using the existence of a highly connected set $W$ given to us by Lemma~\ref{lem: con}. However, it could be that $W \subseteq X$ in which case it is hard to see how to proceed. 

To get around this problem we use Lemma~\ref{lem:weightedrect}. The point is that instead of balancing our rectangles with respect to all variables we only balance them with respect to $W$. We say a partition $(X,Y)$ of $\vertexG$ is $W$-balanced if $\min(|X \cap W|, |Y \cap W|) \ge |W|/3$. In turn, a rectangle is $W$-balanced if its underlying partition is $W$-balanced. By Lemma~\ref{lem:weightedrect}, it follows that to prove Theorem~\ref{thm:graph_lb} we have to show that any $W$-balanced rectangle $\mathcal{R} \subseteq \Hom(\graphG, \graphH)$ is small. The key is that there is a large matching between the two sides of any $W$-balanced partition.

\begin{lemma} \label{lem: matching}
Let $k \in \mathbb{N}$, $\graphG = (\vertexG, \edgeG)$ be a graph and $W$ be a set of $2k+1$ vertices of $G$ with no balanced $k$-separator. Suppose $(X,Y)$ is a $W$-balanced partition of $\vertexG$. Then there is a matching $\M \subseteq \edgeG[X,Y]$ of size $\lfloor k/3 \rfloor$, i.e.\! $|\M| = \lfloor k/3 \rfloor$ and every $v \in \vertexG$ is an endpoint of at most one edge in $\M$. 
\end{lemma} 

\begin{proof}
Since $(X,Y)$ is $W$-balanced we may assume w.l.o.g.\!  that 
\[ 
\frac{2k+1}{3} \le |X \cap W| \le k < |Y \cap W| \le \frac{4k+2}{3}.
\]
Further suppose, for a contradiction, that there exists a set $S' \subseteq \vertexG$ of size $\lfloor 2k/3 \rfloor$ such that removing $S'$ from $G$ disconnects $X$ from $Y$. Then pick arbitrarily a set $T$ of $\lceil k/3 \rceil$ elements of $(Y \cap W) \setminus S'$ and add these to $S'$ to form a set $S$. Then $|S| = k $. We claim that $S$ is a balanced separator with respect to $W$. 

To see this let $C$ be a connected component of $G \setminus S$. Then either $C \subseteq X$ or $C \subseteq Y \setminus T$, by the assumption on $S'$. If $C \subseteq X$ then $|C \cap W| \le |X \cap W| \le k$. On the other hand if $C \subseteq Y \setminus T$ then
%
\[
|C \cap W| \le  |(Y \setminus T) \cap W)| = |Y \cap W| - |T| \le \frac{4k +2}{3} - \frac{k}{3} = k + \frac{2}{3}
\] 
%
\noindent Since $|C \cap W|$ is an integer it follows that $|C \cap W| \le k$. Therefore, $S$ is indeed a $k$-balanced separator, a contradiction. So there is no such set $S'$

To construct $\M$ we first choose any edge between $X$ and $Y$ and delete the two endpoints. We then choose an edge between $X$ and $Y$ in this new graph and repeat until $X$ and $Y$ become disconnected. By the above this leads to a matching of size at least $\lfloor k/3 \rfloor$.
\end{proof}

\noindent By exploiting this matching it is now not too hard to show that every $W$-balanced rectangle is small; the key is that one endpoint of every edge in the matching must have small image. 

\begin{lemma} \label{lem: big_rect}
Let 
%
$\graphG = (\vertexG, \edgeG)$ be an $n_{\graphG}$-vertex graph and $W \subseteq \vertexG$ be a set of vertices of size $2k+1$ with no $k$-balanced separator. Further, let $\graphH = \graphH(n_{\graphH},n_{\graphG})$ be 
the graph given by Lemma~\ref{lem: bad_graph}, for some sufficiently big 
$n_{\graphH}$ and $\mathcal{R} \subseteq \Hom(\graphG, \graphH)$ be a $W$-balanced rectangle. Then 
%
\[
 |\mathcal{R}| \le n_{\graphH}^{n_{\graphG} - \lfloor \frac{k}{3} \rfloor } \cdot [3\log(n_{\graphH})]^{\lfloor \frac{k}{3} \rfloor}. 
 \] 
\end{lemma}

\begin{proof}
Let $(X,Y)$ be the underlying partition of $\mathcal{R}$. By Lemma~\ref{lem: matching}, there is a matching $\M \subseteq \edgeG[X,Y]$ of size $\lfloor k/3 \rfloor$. Let $\{x,y\} \in \M$ with $x\in X, y \in Y$. Further define,
\confORfull{\begin{equation*}
    \begin{aligned}
        P_x &:= \{u \in \vertexH \mid h(x) = u, \text{ for some } h \in \mathcal{R} \}, \quad
        P_y := \{u \in \vertexH \mid h(y) = u, \text{ for some } h \in \mathcal{R} \}.
    \end{aligned}
\end{equation*}
}
{\begin{align*}
P_x &:= \{u \in \vertexH \, \mid \, h(x) = u, \textit{ for some } h \in \mathcal{R} \} \\
P_y &:= \{v \in \vertexH \, \mid \, h(y) = v, \textit{ for some } h \in \mathcal{R} \}.
\end{align*}}
Then for every $u \in P_x$ and $v \in P_y$, there is an edge in $\graphH$ between $u$ and $v$. To see this let $h, g \in \mathcal{R}$ with $h(x) = u$ and $g(y) = v$. Then $h\restriction_{X} \times \, g\restriction_{Y} \, \in \mathcal{R} \subseteq \Hom(\graphG, \graphH)$ since $\mathcal{R}$ is an $(X,Y)$-rectangle. Therefore, since $\{x,y\} \in \edgeG$, we have that $\{h(x), g(y)\} = \{u, v\} \in \edgeH$. It follows that either $|P_x| \le 3\log(n_{\graphH})$ or $|P_y| \le 3\log(n_{\graphH})$, since $\graphH$ contains no $\graphK_{3\log(n_{\graphH}), 3\log(n_{\graphH})}$ subgraph by Lemma~\ref{lem: bad_graph}(\ref{label:nobipart}). Moreover, by definition $|P_{x}| = |\mathcal{R}\restriction_{\{x\}}|$ and $|P_{y}| = |\mathcal{R}\restriction_{\{y\}}|$.

Since the above holds for every $\{x,y\} \in \M$ it follows that there are at least $\lfloor k/3 \rfloor$ vertices $v \in \vertexG$ such that  $|\mathcal{R}\restriction_{\{v\}}| \le 3\log(n_{\graphH})$. The result follows by Observation~\ref{ob:projectub}.
\end{proof}

