\begin{lemma}[{\cite[Lemmas~14-16]{DBLP:conf/icalp/BerkholzV23}}] \label{lem:reduct}
Let $a, r \in \mathbb{N}$ and let $\strucA$ be a $\sigma$-structure with arity at most $r$. Let $\graphG$ be the Gaifman graph of $\strucA$ and suppose that there exists a graph $\graphH$ such that any $\{\cup,\times\}$-circuit computing $\Hom(\graphG, \graphH)$ has size at least $\|\graphH\|^{a}$. Then there is a $\sigma$-structure $\strucB$ with $\|\strucB\| \ge \|\graphH\|$ and a function $g$ such that any $\{\cup,\times\}$-circuit computing $\Hom(\strucA, \strucB)$ has size at least $g(\|\strucA\|) \cdot \|\strucB\|^{2a/r}$.
\end{lemma} 

%
%

\begin{proof}[Proof of Theorem~\ref{thm: tw_struc}]
Let $\graphG$ be the Gaifman graph of $\strucA$  and let $N'$ be an integer. Then since the treewidth of $\graphG$ is the same as the treewidth of $\strucA$ we may apply Theorem~\ref{thm:graph_lb}, to obtain a graph $\graphH$ with $n_{\graphH} \ge N'$ many vertices and at least $n_{\graphH}^2/8$ many edges such that any $\{\cup,\times\}$-circuit computing $\Hom(\graphG, \graphH)$ has size $\Omega(n_{\graphH}^{\frac{w}{9}-2}) = \|\graphH\|^{\Omega(w)}$. Therefore, by Lemma~\ref{lem:reduct}, there is a $\sigma$-structure $\strucB$ with $\|\strucB\| \ge \|\graphH\| \ge N'$ such that any $\{\cup,\times\}$-circuit for $\Hom(\strucA, \strucB)$ has size $\|\strucB\|^{\Omega(w)}$, since $r$ is a constant and by choosing $n_{\graphH}$ (and therefore $\|\strucB\|$) to be sufficiently big.
\end{proof}

\noindent Note that some form of dependence on the arity is necessary since there are classes of structures $\classA$ of unbounded treewidth such that solving $\{\cup,\times\}$-$\CSP(\classA, \classall)$ is in polynomial time, e.g. classes of unbounded treewidth but bounded fractional hypertree width. Such classes must have unbounded arity; we next turn to this setting.


