\[ 
\sigma^{\textrm{sp}} := \{R_{\bar{t}} \, \mid \, R \in \sigma \setminus \sigma_{\!A}, \, \bar{t} \in R^{\strucA} \}.
 \]
Further, let $\strucA^{\textrm{sp}}$ be the $\sigma^{\textrm{sp}} $-structure such that for every $R \in \sigma \setminus \sigma_{\!A}$ and every $\bar{t} \in R^{\strucA}$ we have that $R_{\bar{t}}^{\strucA^{\textrm{sp}}} = \{\bar{t}\}$. 

\begin{lemma} \label{lem:individual_to_sparse}
Let $\strucA$ be an individualised $\sigma$-structure and let $\strucB$ be a $\sigma$-structure such that  $\{P_a^{\strucB} \, \mid \, a \in A\}$ is a partition of the universe. Let $\hat{\strucB}$ be the $\sigma^{\textrm{sp}}$-structure with 
\[
R_{(t_1, \dots, t_r)}^{\hat{\strucB}} := \{(x_1, \dots, x_r) \in R^{\strucB} \, \mid \, x_i \in P_{t_i}^{\strucB} \textit{ for all } i \in [r] \},
\]
%
for all $R_{(t_1, \dots, t_r)} \in \sigma^{\textrm{sp}}$. Then 
$\Hom(\strucA, \strucB) = \Hom(\strucA^{\textrm{sp}}, \hat{\strucB})$.
\end{lemma}

\begin{proof}
First let $h \in \Hom(\strucA, \strucB)$ and consider a 
relation $R_{(t_1, \dots, t_r)} \in \sigma^{\textrm{sp}}$. Then the 
unique tuple in this relation in $\strucA^{\textrm{sp}}$ is $(t_1, 
\dots, t_r)$ which by construction is also in $R^{\strucA}$. Since $h 
\in \Hom(\strucA, \strucB)$ it follows that $(h(t_1), \dots, h(t_r)) 
\in R^{\strucB}$ and that $h(t_i) \in P_{t_i}^{\strucB}$ for all $i 
\in [r]$. Therefore, $(h(t_1), \dots, h(t_r)) \in R_{(t_1, \dots, 
t_r)}^{\strucB^{\textrm{sp}}}$. It follows that $h \in \Hom(\strucA^{\textrm{sp}}, 
\hat{\strucB})$. 

Conversely, let  $h \in \Hom(\strucA^{\textrm{sp}}, \hat{\strucB})$ and 
let $(t_1, \dots, t_r) \in R^{\strucA} $ for some $R \in \sigma \setminus \sigma_{\!A}$. 
Then by construction $(t_1, \dots, t_r) \in R^{\strucA}_{(t_1, \dots, 
t_r)}$. Therefore, since $h \in \Hom(\strucA^{\textrm{sp}}, \strucB^{\textrm{sp}}	)
$, $(h(t_1), \dots, h(t_r)) \in R^{\strucB}_{(t_1, \dots, t_r)}$ and 
so in particular in $R^{\strucB}$. Therefore, $h$, respects every relation in $\sigma \setminus \sigma_{\!A}$.  Moreover, $h(t_i) \in P_{t_i}^{\strucB}$ for all $i \in [r]$, again by the definition of $R^{\strucB}_{(t_1, \dots, t_r)}$. The result follows, recalling that $\strucA$ and $\strucB$ are connected by assumption.
\end{proof}

\noindent We next make explicit how this helps our proof of Theorem~\ref{thm: sub_lb}. To simplify the statement we need two definitions. So let $\strucA, \strucB$ be $\sigma$-structures. Then we say that $\strucB$ is \emph{coordinate respecting (relative to $\strucA$)} if for every $h, h' \in \Hom(\strucA, \strucB)$ and every distinct $a, a' \in A$ it holds that $h(a) \neq h(a')$. In this case we define 
\[ 
\dom_{\strucB}(a) = \{b\in B \, \mid \, h(a) = b \textit{ for some } h \in \Hom(\strucA, \strucB)\}.
\]
Note that $\dom_{\strucB}(a) \cap \dom_{\strucB}(a')$ is empty for all $a \neq a'$. Since $\strucB$ is normally clear from the context we often write $\dom(a)$ for $\dom_{\strucB}(a)$.

Moreover, we say that $\strucB$ is \emph{reduced (relative  to $\strucA$)} if it contains no isolated vertices and its relations contain no tuples which are irrelevant to $\Hom(\strucA, \strucB)$. Formally, this means that for every $R \in \sigma$ and $\bar{b} \in R^{\strucB}$ there exists $\bar{a} \in R^{\strucA}$ and $h \in \Hom(\strucA, \strucB)$ with $h(\bar{a}) = \bar{b}$. If $(R, \bar{b})$ violates this property, then we may remove $\bar{b}$ from $R^{\strucB}$ without affecting $\Hom(\strucA, \strucB)$. Using this given an arbitrary $\sigma$-structure $\strucB$, we can always find a reduced structure $\strucB'$ such that $\Hom(\strucA, \strucB) = \Hom(\strucA, \strucB')$.  

The following lemma implies that it suffices to prove lower bounds for $\strucA$ where each relation contains exactly one tuple so long as $\strucB$---the bad instance---is coordinate respecting for $\strucA$.

\begin{lemma} \label{lem:one_tuple}
Let $\strucA$ be a $\sigma$-structure and let $\strucC$ be a $\sigma^{\textrm{sp}}$-structure which is coordinate respecting relative  to $(\strucA^{\textrm{id}})^{\textrm{sp}}$. Then there exists a $\sigma$-structure $\strucB$ with $\|\strucB\| = \|\strucC\|$ such that if there is a $\{\cup,\times\}$-circuit computing $\Hom(\strucA, \strucB)$ of size $s$ then there is a $\{\cup,\times\}$-circuit computing $\Hom((\strucA^{\textrm{id}})^{\textrm{sp}}, \strucC)$ of size $s$.
\end{lemma}

\begin{proof}
We proceed in two stages first using Lemma~\ref{lem:individual_to_sparse} and then using Lemma~\ref{lem:any_to_individual}. We assume without loss of generality that $\strucC$ is reduced relative  to $(\strucA^{\textrm{id}})^{\textrm{sp}}$.

For the first part we need to define an appropriate structure $\strucD$ over the signature $\sigma \cup \sigma_{\!A}$, where recall $\sigma_{\!A}:= \{P_a \, \mid \, a \in A\}$, where each $P_a$ is a distinct unary relation symbol. $\strucD$ has the same universe as $\strucC$. Then for $a \in A$, $R \in \sigma$ we define:
\begin{align*}
P_a^{\strucD} :=& \dom_{\strucC}(a) \\
R^{\strucD} :=& \bigcup_{\bar{t} \in R^{\strucA}} R_{\bar{t}}^{\strucC}
\end{align*}
%
This completes the description of $\strucD$. Since $\strucC$ is coordinate respecting it follows that the relations $\{P_a \, \mid \, a \in A\}$ partition the universe of $\strucD$.  Moreover, by construction $\strucC = \hat{\strucD}$, in the notation of Lemma~\ref{lem:individual_to_sparse}. Therefore, by Lemma~\ref{lem:individual_to_sparse}, we obtain that $\Hom(\strucA^{\textrm{id}}, \strucD) = \Hom((\strucA^{\textrm{id}})^{\textrm{sp}}, \strucC)$. 

For the second step, let $\strucB$ be the $\sigma$-reduct of $\strucD$. Then applying Lemma~\ref{lem:any_to_individual}, if there is a $\{\cup,\times\}$-circuit of size $s$ computing $\Hom(\strucA, \strucB)$ then there is a $\{\cup,\times\}$-circuit of size $s$ computing $\Hom(\strucA^{\textrm{id}}, \strucD) = \Hom((\strucA^{\textrm{id}})^{\textrm{sp}}, \strucC)$.  The result follows noting $\|\strucB\| = \|\strucC\|$.
\end{proof}

\noindent We end this subsection by making two further simplifications designed to circumvent a technical annoyance. Namely, that in our proofs we often want to go between sets and tuples. Of course, for every tuple $\bar{a} = (a_1, \dots, a_r)$ there is a naturally corresponding set $\tilde{a} := \{a_1, \dots, a_r\}$. But in the other direct given a set there are many possible corresponding tuples, and it can be messy to specify which we mean in our proofs.

We first need some definitions. So let $\strucA, \strucB$ be $\sigma$-structures. If for every $R \in \sigma$ and $\bar{a} \in R^{\strucA}$, $a_i \neq a_j$ for $i\neq j$ we say that $\strucA$ has \emph{no repeated coordinates}. Moreover, let $\leq$ be a total order on $A$, the universe of $\strucA$. Then define $\strucA^{\leq}$ to be the structure with universe $A$ and with relations exactly as in $\strucA$ except with the tuples reordered to respect $\leq$. To be precise if $(t_1, \dots, t_r) \in R^{\strucA}$ and $t_{i_1} \leq t_{i_2} \dots \leq t_{i_r}$, with each $t_{i_{\ell}} \in \{t_1, \dots, t_r\}$, then $(t_{i_1}, t_{i_2}, \dots, t_{i_r}) \in R^{\strucA^{\leq}}$. Now let $\strucB$ be a coordinate respecting $\sigma$-structure. Then $\leq$ induces a partial order $\leq_B$ on $B$ as follows. For $b_1, b_2 \in B$, $b_1 \leq_B b_2$ iff $b_1 = b_2$ or there are distinct $a_1, a_2 \in A$ with $b_1 \in \dom(a_1)$, $b_2 \in \dom(a_2)$ and $a_1 \leq a_2$. This allows us to define $\strucB^{\leq}$; this has the same universe as $\strucB$ and with relations exactly as in $\strucB$ except with the tuples reordered according to $\leq_{B}$. Note that $\leq_B$ induces a unique order on every tuple in every relation since $\strucB$ is coordinate respecting. We call $\strucA$ \emph{order respecting} if $\strucA = \strucA^{\leq}$ for some total order $\leq$ on $A$. In this case we say that $\strucB$ is order respecting relative  to $\strucA$ if $\strucB = \strucB^{\leq}$. The following two easy observations finish our simplification process.

\begin{observation} \label{ob:order}
Let $\strucA, \strucB$ be structures where in $\strucA$ every relation contains exactly one tuple and $\strucB$ is coordinate respecting relative  to $\strucA$. Then $\Hom(\strucA, \strucB) = \Hom(\strucA^{\leq}, \strucB^{\leq})$.  
\end{observation}

\begin{observation} \label{ob:repeat}
Let $\strucA, \strucB$ be structures where in $\strucA$ every relation contains exactly one tuple and $\strucB$ is coordinate respecting relative  to $\strucA$. Then there exists structures $\strucA'$, $\strucB'$ such that $\strucA'$ has no repeated coordinates and satisfies $\|\strucA\| = \|\strucA'\|$; $\strucB'$ satisfies $\|\strucB\| = \|\strucB'\|$; and $\Hom(\strucA, \strucB) = \Hom(\strucA', \strucB')$.  
\end{observation} 

\noindent Then by Lemma~\ref{lem:one_tuple} and Observations~\ref{ob:order} and \ref{ob:repeat} in order to prove Theorem~\ref{thm: sub_lb} it suffices to prove the following result. 

\begin{theorem} \label{thm:sub_lb_reduced}
Let $\strucA$ be an order respecting structure with no repeated coordinates such that every relation in $\strucA$ contains exactly one tuple. Then there exists arbitrarily large relational structures $\strucB$ which are coordinate  and ordered respecting relative  to $\strucA$ and such that any $\{\cup,\times\}$-circuit computing $\Hom(\strucA, \strucB)$ has size $\|\strucB\|^{\Omega(\subw(\strucA)^{1/4})}$. 
\end{theorem}

\noindent Before proving Theorem~\ref{thm:sub_lb_reduced}, we show how the simplifications above allow us to go from sets to tuples. Given that $\strucA$ respects an order and  has no repeated coordinates,  for any
$S \subseteq A$, we define $\overrightarrow{S}$ to be the 
unique tuple respecting the order $\leq$ whose coordinates are the elements of $S$. Moreover, if $\strucB$ is order respecting relative to $\strucA$, then we can similarly deploy this notation 
for any subset of $B$ which is `colourful', in the sense that 
no two of its elements appear in the same $\dom(a)$ set. }

\subsubsection{Defining the Bad Instances}

Towards proving Theorem~\ref{thm:sub_lb_reduced}, let $\strucA$ be an order respecting structure with no repeated coordinates such that every relation in $\strucA$ contains exactly one tuple. Further suppose $\subw(\strucA) = w$ so that, by Theorem~\ref{thm: sub_con}, there exists some $W \subseteq \vertexH$ which can be partitioned into $(K_1, \dots, K_k)$ for some $k = \Omega(\sqrt{w})$, where each $K_i$ is a clique such that there is a uniform concurrent flow $F = \bigcup F_{i,j}$ of value $\varepsilon = \Omega(k^{-3/2})$ on $(K_1, \dots, K_k)$. The aim of this subsection is to define appropriate bad instances $\strucB$. Analogously to in the treewidth case we will use random instances. However, we need to carefully control how each vertex contributes to the number of homomorphisms from $\strucA$. In fact a crucial idea is to use the flow $F$ to do this. Essentially we use $F$ to define a instance $\strucB$ in the spirit of that used in the upper bound of the `AGM bound' \cite[Lemma 4]{DBLP:conf/focs/AtseriasGM08}. Then we sprinkle in some randomness to ensure hardness. 

Concretely, let $N$ be a sufficiently big integer, $\graphH = (\vertexH, \edgeH)$ be the hypergraph of $\strucA$ and for $v \in \vertexH$, let $\mathcal{P}_v$ be the set of 
paths in $\graphH$ that contain the vertex $v$. Define a map $\mu 
\colon \vertexH \to [0,1]$ by $\mu(v) := \frac{1}{2}\sum_{P \in 
\mathcal{P}_{v}} F(P)$. Then 
for each $v \in \vertexH$ we define disjoint sets of elements $
\dom(v)$ such that $|\!\dom(v)| = N^{\mu(v)}$. We define the 
\emph{random structure $\strucB$ induced by $F$ with relations bounded by $N$} as follows. For each 
relation $R \in \sigma$, let $\bar{v} = (v_1, \dots, v_r)$ be the unique tuple 
in $R^{\strucA}$. Then $R^{\strucB}$ is a random subset of $
\bigtimes_{i=1}^r \dom(v_i)$, where each tuple is included 
independently with probability a half. Note that,
%
\[
|R^{\strucB}| \le \prod_{i=1}^r|\!\dom(v_i)| = N^{\alpha}, \quad \text{where } \alpha := \sum_{i=1}^r \mu(v_i).
\]

Moreover, $\tilde{v}$ is an edge of $\graphH$ by definition. Since $F$ is a flow we obtain that 
\[
\sum_{v \in e} \mu(v) = \frac{1}{2}\sum_{v \in e} \sum_{P \in \mathcal{P}_{v}} F(P) \le  \sum_{\substack{P \in \mathcal{P}, P \cap e \neq \emptyset}} F(P) \le 1.
\] 
Here we assume w.l.o.g.\! that each path appearing in $F$ is minimal and therefore intersects each edge at most twice. Using this (non-standard) model of a random structure we can obtain an analogue to Lemma~\ref{lem: bad_graph}. There we showed that our bad instances did not contain any complete bipartite subgraphs. The natural suggestion would be to look at the Gaifmann graph of $\strucB$ and show that it (with high probability) has no large complete bipartite subgraphs. However, the Gaifmann graph of $\strucB$ is very dense so this does not work. Instead the following definition gives us the analogous `badness' property in the relational setting. 

\begin{definition} \label{def:scattered}
Let $N$ be a positive integer, $\strucB$ a $\sigma$-structure and $R \in \sigma$ with $R^{\strucB} \subseteq\bigtimes_{i \in [r]} \dom(v_i)$ for some $\bar{v}$ an $r$-tuple of vertices of $\graphH$. Then we say that $R$ is \emph{$N$-scattered} if for every $(U,V)$, a partition of $\tilde{v}$, the following holds. For every $S \subseteq \bigtimes_{v \in U} \dom(v)$ and $T \subseteq \bigtimes_{v \in V} \dom(v)$, such that 
\[
\left\{\overrightarrow{\left(\tilde{s} \cup \tilde{t} \right)} \, \mid \, s \in S, \, t \in T \right\} \subseteq R^{\strucB} 
\]
either $|S| \le 3\log(N)$ or $|T| \le 3\log(N)$. 
\end{definition}

\noindent The following lemma shows that the bad instances we need exist\confORfull{; it is proved by a simple probabilistic argument, see Appendix~\ref{ass:rest}.}{.} 

\begin{lemma} \label{lem: bad_hypergraph}
There exists some $c = c(\|A\|)$, such that for every sufficiently large integer $N$ there exists a $\sigma$-structure $\strucB = \strucB(N)$ which is coordinate and ordered respecting relative to $\strucA$, has universe $\bigcup_{v \in \vertexH} \dom(v)$, and size $\|\strucB\| \le \|A\| \cdot N$ satisfying the following properties:
\begin{enumerate}
\item $|\!\Hom(\strucA, \strucB)| \ge cN^{t}$, where $t := \sum_{v \in \vertexH} \mu(v)$ and \label{big_instance}
\item for every $R \in \sigma, R^{\strucB}$ is $N$-scattered. \label{nonuni}
\end{enumerate}
\end{lemma}

\confORfull{}{%
\begin{proof}
We proceed by showing that the probability that $\strucB$, the random structure induced by $F$ with relations bounded by $N$, satisfies the lemma is greater than zero. We begin with the following claim; actually although the setting is different the core probability calculation is the same as in the proof of Lemma~\ref{lem: bad_graph} given in \cite[Lemma 8]{DBLP:conf/icalp/BerkholzV23}.
\begin{claim}
Let $N>0$, $R \in \sigma$ and $\strucB$ be the random structure  Then the probability that $R$ is $N$-scattered tends to one as $N \to \infty$. 
\end{claim}

\begin{claimproof}
Suppose that $R^{\strucA} = \{\bar{v}\}$ and let $(U,V)$ be a partition of $\tilde{v}$. Then the number of pairs $(S,T)$ such that $S\subseteq \bigtimes_{v \in U} \dom(v)$, $T \subseteq \bigtimes_{v \in V} \dom(v)$ and $|S| = |T| = 3\log(N):= a$ is at most $\binom{N}{a}^{\! 2}$. Let $P$ be the probability that there exists such a pair with
\[\left \{\overrightarrow{\left(\tilde{s} \cup \tilde{t} \right)} \, \mid \, s \in S, \, t \in T \right \} \subseteq R^{\strucB}. \] 
%
By the union bound and the definition of $\strucB$ we obtain
\[
P \le \binom{N}{a}^{\! \! 2} 2^{-a^2} \le N^{2a}2^{-a^2} = 2^{2a\log(N)-a^2} = 2^{-3\log^2(N)}.
\]
Moreover, the number of partitions of $\tilde{v}$ is only a function of $r$ which in particular is at most $|\vertexH|$. Since this number is independent of $N$ the claim follows. 
\end{claimproof}

\noindent As $|\sigma| = \|A\|$ is independent of $N$ the probability that (\ref{nonuni}) holds for $\strucB$ tends to one as $N \to \infty$. Further, $\|\strucB\| \le |\sigma| \cdot N = \|A\| \cdot N$ and $\strucB$ is coordinate and order respecting relative to $\strucA$.

It remains to analyse  the probability that (\ref{big_instance}) holds in $\strucB$. So let $X = |\!\Hom(\strucA, \strucB)|$.  Consider a map $h: \vertexH \to B$, where $B$ is the universe of $\strucB$, such that $h(v) \in \dom(v)$ for all $v \in \vertexH$. Then the probability that $h \in \Hom(\strucA, \strucB)$ is exactly the probability that for every $R \in \sigma$ with $R^{\strucA} = \left\{\bar{t} \right\}$, $h(\bar{t}) \in R^{\strucB}$. This occurs with probability $2^{-|\sigma|} = 2^{-\|A\|}:= \delta$. Since, the total number of such maps $h$ is equal to $\prod_{v \in \vertexH} |\!\dom(v)| = N^{t}$, we obtain that $\mathbb{E}[X] = \delta N^t$. Let $P$ be the probability that $X \le \mathbb{E}[X]/8$, then $P = 2^{\Omega(-\|A\|)}$. This follows since
\[
\delta N^t = \mathbb{E}[X] \le (1-p) \cdot \frac{\mathbb{E}[x]}{8} + p \cdot N^t.
\]
Then by rearranging we get the bound on $P$. This completes the proof since $P$ is positive and independent of $N$. 
\end{proof} %
}

\subsubsection{Analysis} 

\noindent To argue about these instances we, similarly to in the treewidth case, reason about combinatorial rectangles with partitions balanced relative  to the highly connected nature of $\strucA$. To do this we use Lemma~\ref{lem:weightedrect}, for some \confORfull{appropriate $f$}{appropriately chosen $f$}. The natural choice seems to be to set $f = \mu$\confORfull{.}{, recalling that we extend functions defined on $\vertexH$ to functions defined on $2^{\vertexH}$ in the natural way.} However, for technical reasons we instead use a closely related function $\alpha$ which is defined by
%
\[
\alpha(v) := \begin{cases}
0 & v \not \in W \\
\frac{1}{2}\sum_{j \in [k]\setminus \{i\}} \sum_{\substack{P \in \mathcal{P}_v}} F_{i,j}(P) & v \in K_i
\end{cases}
\]

\noindent The idea is that firstly, we only take vertices of $W$ into account for our balancing since this is the part of $\graphH$ we know is `highly connected' and secondly that we weight each vertex $v \in W$ according to the sum of the weights of paths in $F$ for which $v$ is an endpoint. Trivially, $\alpha(v) \le \mu(v)$ for every $v \in V$. We next observe that every $K_i$ has equal weight under $\alpha$.

\begin{observation} \label{ob: clique_weight}
For every $i \in [k]$, $\alpha(K_i) := \delta = \varepsilon/2 \cdot (k-1).$ Moreover, $\alpha(W) = k \cdot \delta$.  
\end{observation}

\noindent So let $(X,Y)$ be an $\alpha$-balanced partition. This means that globally the weight of $W$ under $\alpha$ is (up to a constant factor) evenly split between $X$ and $Y$. However, this is not necessarily the case for each $K_i$.\confORfull{}{ It could, for instance, happen that every $K_i$ is either a subset of $X$ or a subset of $Y$.} We first analyse the case where there are many values of $i$ such that the weight of $K_i$ under $\alpha$ is roughly evenly split between $X$ and $Y$. To formalise this we say that $K_i$ is \emph{$\alpha$-balanced} for $(X,Y)$ if 
\[ 
\min( \alpha(K_i \cap X), \alpha(K_i \cap Y)) \ge \frac{\alpha(K_i)}{10}  =  \frac{\delta}{10}.
\] 
%
\confORfull{}{Note that the multiplicative constant $1/10$ differs from the $1/3$ that appears in the definition of an $\alpha$-balanced partition; this is unfortunately a technical necessity.} It turns out that if a lot of the $K_i$ are balanced then we can argue very similarly to in the proof of Theorem~\ref{thm: tw_struc}\confORfull{, see Appendix~\ref{ass:rest} for details.}{.}


\begin{lemma} \label{lem: easy_part}
%
Let $(X,Y)$ be an $\alpha$-balanced partition of $\vertexH$ and let $\lambda > 0$\confORfull{}{ be a constant}. Suppose that $K_i$ is $\alpha$-balanced for at least $\lambda \cdot k$ values of $i$. Then there is a constant $c = c(\lambda) >0$, such that every $\mathcal{R} \subseteq \Hom(\strucA, \strucB)$ with underlying partition $(X,Y)$ has size at most $N^{t - c \sqrt{k}}$.
\end{lemma}

\confORfull{}{%
\begin{proof}
Pick any $K_i$ which is $\alpha$-balanced for $(X,Y)$. Then we know there is some edge $e \in \edgeH$ with $K_i \subseteq e$. Therefore, there is some $R \in \sigma$, with $R^{\strucA} = \{\overrightarrow{e}\}$. Recall, that every member of $\mathcal{R}$ is a mapping $h: \vertexH \to B$. Let,
\begin{align*}
U_i &:= \{h(e \cap X) \, \mid \, h \in \mathcal{R} \} \textit{ and}  \\
V_i &:= \{h(e \cap Y) \, \mid \, h \in \mathcal{R} \}.
\end{align*}

\begin{claim}\label{claim:rect}
 Let $u \in U_i$ and $v \in V_i$. Then $\overrightarrow{u \cup v} \in R^{\strucB}$. 
\end{claim}

\begin{claimproof}
 By the definition of $U_i$ and $V_i$ there exists $h_u, h_v \in \mathcal{R} \subseteq \Hom(\strucA, \strucB)$  such that $h_u(e \cap X) = u$ and $h_v(e \cap Y) = v$. Moreover, since $
\mathcal{R}$ is a rectangle $h:= h_u\restriction_X \times h_v\restriction_Y \in \mathcal{R}$. Since $h$ is a homomorphism from $\strucA$ to $\strucB$, $h(\overrightarrow{e}) \in R^{\strucB}$. But $h(\overrightarrow{e})  = \overrightarrow{u \cup v}$, since $h(e) = u \cup v$ by construction. The claim follows.
\end{claimproof}

\noindent 
%
On the other hand, by Lemma~\ref{lem: bad_hypergraph}(\ref{nonuni}), $R^{\strucB}$ is $N$-scattered. It follows that either $|U_i| \le 3\log(N)$ or $|V_i| \le 3\log(N)$. Let $\mathcal{I}$ be the set of $i \in [k]$ such that $K_i$ is balanced for $(X,Y)$. By assumption $|\mathcal{I}| \ge \lambda \cdot k$. For every such $i$, let $e_i$ be an edge of $\graphH$ such that $K_i \subseteq e_i$ and then define  
\[
s_i := \begin{cases}
e_i \cap X & \textit{ if } |U_i| \le |V_i| \\
e_i \cap Y & \textit{ otherwise.} 
\end{cases}
\]
 Let $S := \bigcup_{i \in \mathcal{I}} s_i $. It follows that 
\begin{align*}
\mu(S) \ge \alpha(S) &\ge \sum_{i \in \mathcal{I}} \min[\alpha(K_i \cap X, K_i \cap Y)] \\
 &\ge  \lambda \cdot k \cdot \frac{\delta}{10} \ge \hat{c} \cdot \sqrt{k},
\end{align*} 
for some constant $\hat{c}>0$, depending on $\lambda$, since $\delta = \Omega(k^{-1/2})$.
%

Moreover, by definition the restriction of $\mathcal{R}$ to $\{s_i\}$ has size at most $3\log(N)$ for every $i \in \mathcal{I}$. Therefore, since $|\!\Hom(\strucA, \strucB)| = \Theta(N^t)$ and as we take $N$ to be sufficiently large, the result follows by applying Observation~\ref{ob:projectub}.
%
%
%
%
%
\end{proof} %
}

\noindent To finish the proof we have to deal with the case where almost every $K_i$ is not $\alpha$-balanced relative to $(X,Y)$. The key is to argue that then there are many paths in $F$ which cross from $X$ into $Y$ (or vice-versa). This is the core of the argument as it is where the flow is deployed. \confORfull{Note that in the extreme case where every $K_i$ is either a subset of $X$ or a subset of $Y$ the argument is simple. For suppose $K_i \subseteq X$ and $K_j \subseteq Y$, then in particular every path with non-zero weight under $F_{i,j}$ must at some point cross from $X$ into $Y$. Moreover, since $\alpha(K_i) = \delta$ for every $i$ and since the partition $(X,Y)$ is $\alpha$-balanced we know that the number of $K_i$ contained in $X$ differs only by a constant factor from the number of $K_i$ contained in $Y$. Therefore, the total weight of the paths crossing from $X$ into $Y$ is $\Theta(k \cdot \delta) = \Theta(k^{1/2})$; the result then follows by a similar calculation to in Lemma~\ref{lem: easy_part}. The general case is similar we just have to be a little more careful; the key insight is that  weight of paths intersecting both $X$ and $Y$ is large; we give the details in Appendix~\ref{ass:rest}.}{} 

\confORfull{}{Before going into the proof first note that in the extreme case where every $K_i$ is either a subset of $X$ or a subset of $Y$ the argument is simple. For suppose $K_i \subseteq X$ and $K_j \subseteq Y$, then in particular every path with non-zero weight under $F_{i,j}$ must at some point cross from $X$ into $Y$. Moreover, since $\alpha(K_i) = \delta$ for every $i$ and since the partition $(X,Y)$ is $\alpha$-balanced we know that the number of $K_i$ contained in $X$ differs only by a constant factor from the number of $K_i$ contained in $Y$. Therefore, the total weight of the paths crossing from $X$ into $Y$ is $\Theta(k \cdot \delta) = \Theta(k^{1/2})$; the result then follows by a similar calculation to in Lemma~\ref{lem: easy_part}. In the more general case, where $K_i$ can intersect both $X$ and $Y$, a similar argument works. Firstly, by Lemma~\ref{lem: easy_part}, we may assume that the weight of many $K_i$ is overwhelmingly concentrated either in $X$ and in $Y$. Then we just have to argue that---as in the proof sketch above---the weight of paths intersecting both partitions is large.}

\begin{lemma} \label{lem:hardpart}
Let $\lambda > 0$ be sufficiently small and $(X,Y)$ be an $\alpha$-balanced partition of $\vertexH$, such that the number of $\alpha$-balanced $K_i$ is less than $\lambda \cdot k$. Then there is a constant $d = d(\lambda)>0$ such that every $\mathcal{R} \subseteq \Hom(\strucA, \strucB)$ with underlying partition $(X,Y)$ has size $N^{t - d\sqrt{k}}$.
\end{lemma}

\confORfull{}{%
\begin{proof}
For $Z \in \{X,Y\}$, let $\mathcal{K}_Z$ be the set of $i$ such that $\alpha(K_i \cap Z) < \delta/10 $. Then by assumption 
\[
|\mathcal{K}_X \cup \mathcal{K}_Y| \ge k - \lambda \cdot k.
\]
We first give a lower bound for $|\mathcal{K}_X|\cdot |\mathcal{K}_Y|$. Observe that
\[
\frac{2k\delta}{3} = \frac{2\alpha(W)}{3} \ge \alpha(Y \cap W) \ge |\mathcal{K}_X| \cdot \frac{9 \delta}{10},
\]
where the equality uses Observation~\ref{ob: clique_weight}, the first inequality that $(X,Y)$ is $\alpha$-balanced and the second that for every $i \in \mathcal{K}_X$, $\alpha(K_i \cap Y) = \alpha(K_i) - \alpha(K_i \cap X) \ge \delta - \delta/10 = 9\delta/10$. Rearranging, we obtain that $|\mathcal{K}_X| \le  20k/27$. Analogously, we know that $|\mathcal{K}_Y| \le 20k/27$.
%
%
%
We also know that $|\mathcal{K}_X| + |\mathcal{K}_Y| \ge k - \lambda \cdot k$, so to give a lower bound for $|\mathcal{K}_X|\cdot |\mathcal{K}_Y|$ it suffices to find the minimum of the function 
\begin{align*}
&x \to x(k - \lambda \cdot k -x)  & x \in \left[\frac{7k}{27} - \lambda \cdot k, \frac{20k}{27}\right].
\end{align*} 
%
This occurs for the extremal values of $x$, which gives us that
\[
|\mathcal{K}_X|\cdot |\mathcal{K}_Y| \ge \frac{20k}{27} \cdot \left(\frac{7k}{27} - \lambda \cdot k\right) \ge 0.19k^2,
\]
where the last inequality follows by choosing $\lambda$ sufficiently small.

Let $F'$ be the union of $F_{i,j}$, such that $i \in K_X$  and $j \in K_Y$. First, observe that the value of $F'$ is $|\mathcal{K}_X||\mathcal{K}_Y| \cdot \varepsilon$. Let $F'_g$ be the subflow of $F'$ containing exactly those paths from $F'$ which intersect both $X$ and $Y$. We aim to show this also has large value. To see this we upper bound the value of $F'_b := F' \setminus F'_g$.

So let $P \in F'_b$, then $P$ is fully contained in $Z$, for some $Z \in \{X,Y\}$. Then one endpoint $P$ lies in $K_i$ for some $i \in \mathcal{K}_Z$; we denote this endpoint by $s(P)$. Then note that 
\[
\sum_{P \in F'_b} F(P) = 2 \sum_{P \in F'_b} \alpha(s(P)) < 2 (|\mathcal{K}_X|+|\mathcal{K}_Y|) \cdot \frac{\delta}{10} \le \frac{k \cdot \delta}{5} \le \frac{k^2 \cdot \varepsilon}{10},
\]
where the last inequality follows since $\delta:= \varepsilon/2 \cdot (k-1)$.  It follows that the value of $F'_g$ is at least
\[
|\mathcal{K}_X||\mathcal{K}_Y| \cdot \varepsilon - \frac{k^2 \cdot \varepsilon}{10} \ge 0.19k^2 \cdot \varepsilon - \frac{k^2 \cdot \varepsilon}{10}  =  \Omega(k^{1/2}),
\]
where the asymptomatic bound follows since $\varepsilon =\Omega(k^{-3/2})$.

Let $P \in F'_g$. Then we know that at some point $P$ crosses from $X$ to $Y$, i.e. there exist successive vertices  $x_P, y_P$ in $P$ such that $x_P \in X$ and $y_P \in Y$. Therefore, there is some edge $e_P \in \edgeH$ such that $e_P \supseteq \{x,y\}$. It is easy to see by a similar argument to Lemma~\ref{lem: easy_part} that either the restriction of $\mathcal{R}$ to $e_P \cap X$ has size at most $3\log(N)$ or the restriction of $\mathcal{R}$ to $e_P \cap Y$ has size at most $3\log(N)$. Moreover, 
\[ \mu(e_P \cap X) \ge \mu(x_P) \ge F'_g(P).   \]
%
Similarly $\mu(e_P \cap Y) \ge F'_g(P)$. So let $s_P$ equal $e_P \cap X $  if the size of the restriction of $\mathcal{R}$ to $e_P \cap X$ is less than the size of the projection of $\mathcal{R}$ to $e_P \cap Y$ and otherwise let $S_P$ equal $e_P \cap X$. Then $\mu(\cup_{P \in F'_g} s_P)$ is at least the value of $F'_g$ which is $\Omega(k^{1/2})$. The result follows by deploying Observation~\ref{ob:projectub}.
\end{proof} %
}

\noindent Theorem~\ref{thm:sub_lb_reduced}---and therefore also Theorem~\ref{thm: sub_lb}---is immediate.

\begin{proof}[Proof of Theorem~\ref{thm:sub_lb_reduced}]
Take $\strucB$ from Lemma~\ref{lem: bad_hypergraph}. Then $|\!\Hom(\strucA, \strucB)| \ge cN^t$, where $N$, $c$ and $t$ are defined as in the lemma. On the other hand, by Lemmas~\ref{lem: easy_part} and \ref{lem:hardpart} we know that every $\alpha$-balanced rectangle $\mathcal{R}$ with $\mathcal{R} \subseteq \Hom(\strucA, \strucB)$ has size at most $N^{t- \varepsilon\sqrt{k}}$, for some positive constant $\varepsilon$ and some $k = \Omega(\sqrt{w})$; the result follows by Lemma~\ref{lem:weightedrect}.
\end{proof}




