\State $K_s$ $\gets$ generateTriangularWaveform$(t\_stop, K_s\_max)$
\Statex \textcolor{blue}{// Begin simulation loop}
\While{$t < t\_stop$}
    \Statex \quad \textcolor{blue}{// For each oscillator, compute interaction terms}
    \For{$i = 0$ \textbf{to} $n-1$}
        \State $\partial_i \gets 0$ \textcolor{blue}{// Initialize partial derivative}
