        \EndFor
    \EndFor
    \Statex \quad \textcolor{blue}{// Update all oscillator phases using Forward Euler method}
    \For{$i = 0$ \textbf{to} $n-1$}
        \State $derivative \gets K \cdot \partial_i + K_s[t] \cdot \sin(2\pi N \phi_i)$
        \State $noise \gets K_n \cdot \mathcal{N}(0,1) \cdot \sqrt{h}$ \textcolor{blue}{// Gaussian noise term}
