For ease of notation, for a subset $S$ of vertices in $R$, we use $\mcap(S) = \sum_{v \in S} \mcap_v$ to denote the total capacity of $S$, and use $\neigh(S) = \bigcup_{v \in S} \neigh_v$ to denote the neighbor set of $S$.
\cref{lem:alloc-bound} implies the two lower bounds on $\mweight$. First, since each vertex in $\bigcup_{j<2\tau} \lset_j$ almost fill up their capacities, we have

\begin{equation} \label{eqn:weight-bound-1} \textstyle
    \mweight \geq \frac{1}{1+3\epsilon} \sum_{j=0}^{2\tau-1} \mcap(\lset_j).
\end{equation}
Second, since all vertices in $\bigcup_{j > 0} \lset_j$ has bounded over-allocation, when line 6 of \cref{alg:local} was executed, the ratio of $\frac{\mcap_v}{\alloc_v}$ was at least $\frac{1}{1 + 3\epsilon}$.
Hence, we have

\begin{equation} \label{eqn:weight-bound-2} \textstyle
    \mweight \geq \frac{1}{1+3\epsilon} \sum_{j=1}^{2\tau} \sum_{v \in \lset_j} \alloc_v.
\end{equation}

Let $OPT$ be the weight of an optimal fractional allocation. The following lemma gives an upper bound on $OPT$.

\begin{lemma} \label{lem:goal} Assume that we run \cref{alg:local} for $\tau \geq 1$ rounds. Then, after all rounds have completed, we have
\begin{equation} \label{eqn:goal} \textstyle
     OPT \leq (1 + 3\epsilon) \mweight + |\neigh(\lset_{2\tau})|.
\end{equation}
\end{lemma} 
\begin{proof}
In \cite[Claim 1]{AZM18}, it has been shown that
\begin{equation*} \textstyle
    \mbox{for all } 0 \leq \ell \leq 2\tau \mbox{, we have } OPT \leq \sum_{j=0}^{\ell} \mcap(\lset_j) + |\neigh (\bigcup_{j=\ell+1}^{2\tau} \lset_{j})|.
\end{equation*}
That is, the optimal fractional allocation is at most the total capacity of $\bigcup_{j \leq \ell} \lset_j$ plus the total number of neighbors of $\bigcup_{j > \ell} \lset_j$.
By setting $\ell = 2\tau - 1$, we obtain
\begin{equation*} \textstyle
    OPT \leq \sum_{j=0}^{2\tau-1} \mcap(\lset_j) + |\neigh(\lset_{2\tau})|.
\end{equation*}
By \cref{eqn:weight-bound-1}, the term $\sum_{j=0}^{2\tau-1} \mcap(\lset_j)$ can be replaced by $(1 + 3\epsilon) \mweight$, which yields the desired inequality.
\end{proof}

\begin{remark}
Before proceeding, we remark on how the arboricity naturally arises in our analysis as follows.
By \cref{lem:goal}, if the current fractional solution is as large as $(1 - O(\eps)) |\neigh(\lset_{2\tau})|$, then the solution is a $(2 + O(\eps))$ approximation.
The only reason that $\mweight$ does not reach $(1 - O(\eps)) |\neigh(\lset_{2\tau})|$ is when most fractions from $\neigh(\lset_{2\tau})$ are allocated to $\lset_0$, because $\lset_0$ is the only set of vertices having unbounded over-allocation.
Intuitively, this implies that the subgraph induced by $\neigh(\lset_{2\tau}) \cup \lset_0$ is dense because the vertices in $\lset_0$ have low priority values compared to the vertices in $\lset_{2\tau}$.
For a large enough $\tau$, such a dense subgraph cannot exist in a low-arboricity graph, implying a contradiction.
\end{remark}

