We are ready to prove the approximation factor of \cref{alg:local}.

\begin{theorem} \label{thm:apx-factor} Assume that we run \cref{alg:local} for $\tau \geq \loglambda$ rounds. Then, $OPT \leq (2 + 10\epsilon)\cdot \mweight$.
\end{theorem}
\begin{proof} Let $N'$ denote $\neigh(\lset_{2\tau})$. By \cref{eqn:goal}, if we can show that $|N'| \leq (1 + 7\epsilon) \cdot \mweight$, then $OPT \leq (2 + 10\epsilon)\mweight$ and thus \cref{alg:local} is a $(2 + 10\epsilon)$-approximation algorithm. To prove that $|N'| \leq (1 + 7\epsilon) \mweight$, we consider two cases:

\begin{itemize}
    \item[] \textbf{Case 1:} $|N'| \leq |\lset_0|$. By \cref{eqn:weight-bound-1}, we have
    \begin{equation*}
        \mweight \geq \frac{1}{1+3\epsilon} \mcap(\lset_0) \geq \frac{1}{1+3\epsilon} |\lset_0| \geq \frac{1}{1+3\epsilon}|N'|.
    \end{equation*}
    Hence, $|N'| \leq (1 + 7\epsilon) \mweight$ holds for this case.

    \item[] \textbf{Case 2:} $|N'| > |\lset_0|$. We first show that $\sum_{j=1}^{2\tau} \sum_{v \in \lset_j} \alloc_v \geq (1 - \frac{\epsilon}{2}) |N'|$.
    Consider a vertex $u \in L$ and a vertex $v \in \lset_0$.
    Since $N'$ is the neighbor set of $\lset_{2\tau}$, there is a vertex $v' \in \lset_{2\tau}$ that is a neighbor of $u$.
    In the end of round $\tau$, $\beta_{v'}$ is larger than $\beta_{v}$ by a factor of $(1 + \epsilon)^{2\tau}$.
    Thus, in the beginning of round $\tau$, $\beta_{v'}$ is larger than $\beta_v$ by at least a factor of $(1 + \epsilon)^{2\tau-2}$.
    Recall that $x_{u,v}$ and $x_{u,v'}$ are calculated proportional to the priority values of $v$ and $v'$ in the beginning of round $\tau$.
    Thus, $\vx_{u,v} \leq \vx_{u,v'} / (1+\epsilon)^{2\tau - 2}$.
    Since $\tau = \loglambda$, we have $\vx_{u,v} \leq \frac{\epsilon}{4\lambda}\cdot\vx_{u,v'} \leq \frac{\epsilon}{4\lambda}$.
    That is, every edge $(u, v)$ with $u \in N'$ and $v \in \lset_0$ allocates at most an amount of $\frac{\epsilon}{4\lambda}$ to $\lset_0$.
    Consider the subgraph $G'$ of $G$ induced by $N' \cup \lset_0$.
    Since the arboricity of $G$ is bounded by $\lambda$ and $|N'| > |\lset_0|$, the number of edges in $G'$ is at most $\lambda \cdot (|N'| + |\lset_0|) < 2 \lambda |N'|$.
    Therefore, the total allocation from $N'$ to $\lset_0$, $\sum_{u \in N'} \sum_{v \in \lset_0} \vx_{u,v}$, is at most $2 \lambda |N'| \cdot \frac{\epsilon}{4\lambda} = \frac{\epsilon}{2} |N'|$.
    That is, the total allocation from $N'$ to vertices not in $\lset_0$ is at least $(1 - \frac{\epsilon}{2})|N'|$.
    This implies that $\sum_{j=1}^{2\tau} \sum_{v \in \lset_j} \alloc_v \geq (1 - \frac{\epsilon}{2}) |N'|$.

    By \cref{eqn:weight-bound-2}, $\mweight$ is at least $\frac{1}{1+3\epsilon} \sum_{j=1}^{2\tau} \sum_{v \in \lset_j} \alloc_v$. Therefore, we obtain

    \begin{equation*}
        \mweight \geq \frac{1}{1+3\epsilon} \sum_{j=1}^{2\tau} \sum_{v \in \lset_j} \alloc_v \geq \frac{1}{1+3\epsilon} (1 - \frac{\epsilon}{2}) |N'| \geq \frac{1}{1 + 7\epsilon} |N'|,
    \end{equation*}
    where the last inequality holds for $\epsilon \leq 1$. Hence, $|N'| \leq (1 + 7\epsilon) \mweight$ also holds for this case.
\end{itemize}

Since we have $|N'| \leq (1 + 7\epsilon) \mweight$ in both cases, the theorem holds.
\end{proof}

\noindent Note that \cref{thm:LOCAL-allocation} is a direct consequence of \cref{thm:apx-factor}.

We conclude this section by the following remark. The proof of \cref{thm:apx-factor} also implies that after $\loglambda$ rounds, at least one of the following conditions must hold: either $\neigh(\lset_{2\tau}) \leq |\lset_0|$, or $\sum_{j=1}^{2\tau} \sum_{v \in \lset_j} \alloc_v \geq (1 - \frac{\epsilon}{2}) |N'|$; moreover, if one of the conditions hold at the end of the last round, the output is a $(2 + 10\epsilon)$-approximation. This implies a variation of \cref{alg:local} that does not assume the knowledge of $\lambda$: Instead of running the for-loop in lines 1-4 for $\loglambda$ rounds, we terminate the loop when one of the above conditions hold. By the discussion above, the variation is a $(2 + 10\epsilon)$-approximation algorithm that performs $\tau \leq \loglambda$ rounds of computation. The new termination condition for the loop can be checked in $O(1)$ MPC rounds. However, it is not clear how to check it in $O(1)$ LOCAL rounds.

\section{MPC algorithm}
\label{sec:mpc}

\begin{algorithm}
\begin{algorithmic}[1]
\Statex \textbf{Input:} $G = (L \cup R, E)$, capacity constraints $\{\mcap_v\}_{v \in R}$, number of rounds $\tau \geq 1$, approximation parameter $\epsilon > 0$.
\Statex \textbf{Output:} A $2+\epsilon$ approximate fractional allocation of $G$
\Statex \textbf{Parameters:} $B = B_{\epsilon/48}$ \text{ as per } \cref{eqn:bvalue}, and $t = (1+\epsilon)^{2B} \cdot \epsilon^{-5} \cdot \log n$
\Statex \textbf{Initialization:} Set $\beta_v \gets 1$ for every $v \in R$ and $\beta_u = \sum_{v\in \neigh_u} \beta_v$ for all $u \in L$

\For{ phases $p = 0, 1, \dots \tau/B-1$}
    \State for each $w\in V(G)$:
    \Statex \hspace{1cm} Partition $\neigh_w$ into $4\tau+1$ groups $\lset_{-2\tau},\dots \lset_{2\tau}$ as follows, 
    \Statex \hspace{3.5cm} $$\lset_x \gets \Big\{u \in \neigh_w \mid \beta_u \in ((1+\epsilon)^{x-1}, (1+\epsilon)^x] \Big\} \text{ for each } x = -2\tau, \cdots ,2\tau$$ \label{line:block-splitting}

    \State for each vertex $w \in V(G)$, integer $r \in [0, B)$, integer $x \in [-2\tau, 2\tau]$:
    \Statex \hspace{1cm} $E_{r, v, x} \gets $ Sample $t$ edges from $\neigh_v \bigcap \lset_x$ u.a.r.
    \Statex \hspace{0.25cm} $H_r:=$ Graph induced by edges in $\cup E_{r, v, x}$ over all $v, x$.
    \Statex \hspace{0.25cm} $H_{r, v}:=$ Ball of radius $B$ around $v$ in $H_r$.
    \Statex \hspace{0.25cm} $\neigh_{r, v}:=$ neighborhood of $v$ in $H_r$. \label{line:sampling}

    \For { rounds $r = pB+1, pB+2, \dots (p+1)B$} \label{line:local-sim-begin}
        \Statex \hspace{1cm} \textbf{for} each $u \in L$:
            \State \hspace{0.25cm} Set $\beta_{u} \gets \frac{|\neigh_u|}{|\neigh_{r, u}|} \sum\limits_{v \in \neigh_{r, u}} \beta_{v}$ \label{line:est1}
        \Statex \hspace{1cm} \textbf{for} each $v \in R$:
            \State \hspace{0.25cm} Set $\halloc_v \gets \frac{|\neigh_v|}{|\neigh_{r, v}|} \sum \limits_{u \in \neigh_{r, v}} \frac{\beta_v}{\beta_u}$ and update  $\beta_v$ as follows, \label{line:est2}

            \State \hspace{0.25cm} $$ \beta_v \gets \begin{cases} 
            \beta_v (1 + \epsilon) \ \ \ \text{if } \halloc_v \leq \mcap_v / (1 + \epsilon) \\
            \beta_v / (1 + \epsilon) \ \ \text{if } \halloc_v \geq \mcap_v (1 + \epsilon) \\
            \beta_v \ \ \ \ \ \ \ \ \ \ \ \ \text{otherwise}      
            \end{cases} $$
    \EndFor
    \label{line:local-sim-end}
    \State Each $v \in R$ calculates $\vx_{u, v} = \min(1, \frac{\mcap_v}{\halloc_v}) \cdot \sum\limits_{u \in \neigh_v} \frac{\beta_v}{\beta_u} $, the desired fractional allocation.
    \label{line:last-step}
\EndFor
\end{algorithmic}
\caption{A fractional allocation algorithm for bipartite graphs}
\label{alg:matching}
\end{algorithm}

In this section we outline how \cref{alg:local} can be efficiently implemented in sublinear MPC within $\tilde{O}(\sqrt{\log \lambda})$ rounds. Towards this goal, we present \cref{alg:matching}, a LOCAL algorithm with small \textit{locality volume}. The locality volume is the size of the subgraph around each vertex $v$ that is sufficient to obtain the output of $v$.  
More precisely, for every vertex $v \in V(G)$ and $\Theta(\sqrt{\log \lambda})$ rounds of \cref{alg:matching}, the output of $v$ is influenced by at most $O(\lambda \cdot \text{poly}(\log n))$ vertices. Mirroring the sparsification technique in \cite{GU19}, yields us our result. \cref{alg:local} gives a $2 + \epsilon$ approximation. Applying the framework of \cite{ghaffari2022massively}, we can boost this ratio to $1 + \epsilon$. A modification in the reduction is needed since the framework of \cite{ghaffari2022massively} is for the more general $b$-matching problem. We discuss details in \cref{sec:framework}.

\begin{theorem} \label{thm:fast-mpc}
    There is an $O_{\epsilon}(\sqrt{\log \lambda} \cdot \log \log \lambda)$-round MPC algorithm using $n^{\alpha}$ local memory (for any constant $\alpha \in (0, 1)$) and $\tilde{O}(\lambda n)$
global memory that with high probability computes an $2+\epsilon$ approximate allocation of any graph with arboricity $\lambda$. Using the framework of \cite{ghaffari2022massively}, the approximation can be further reduced to $1+\epsilon$ with the same asymptotic round complexity.
\end{theorem}

In \cref{alg:local}, in each round a vertex $v$ communicates with \textit{all} of its neighbors. The locality volume for $B$ rounds is thus, $\Delta^B$ in the worst case. The communication is done for exactly two purposes: to determine the value of either (i) $\sum\limits_{v \in \neigh_u} \beta_u$ for all $u \in L$ or (ii) $\sum\limits_{u \in \neigh_v} \beta^{-1}_u$ for all $v \in R$. 

For a node $v \in R$, $\beta_v$ has the same connotation as \cref{alg:local}. The values $\beta_v$ provide an implicit distribution of how weights should be assigned to the edges incident on it. For a node $u \in L$ we define $\beta_u = \sum\limits_{v \in \neigh_{u}} \beta_v$. This definition helps us treat the aggregations needed for Line 2 and Line 3 of \cref{alg:local} in a similar way. Note that to implement Line 2 we require $\sum\limits_{v \in \neigh_u} \beta_v$ for every vertex $u \in L$. As per our definition, Line 3 can be written as $\beta_v \cdot \sum\limits_{u \in \neigh_v} \beta^{-1}_{u}$, i.e., essentially $v$ requires only $\sum\limits_{u \in \neigh_v} \beta^{-1}_u$, which is symmetric to the previous aggregation.
Observe that $1 + O(\epsilon)$ multiplicative approximations of the $\beta$ values are sufficient to obtain $1 + O(\epsilon)$ approximations of both aggregates.


% Note that both are neighborhood aggregations and that $1+O(\epsilon)$ approximations of $\beta_w$ is sufficient to obtain approximations of these aggregates. 
Finally at the end of a single round, if these aggregations exceed a certain threshold, the $\beta$ values are decreased by a $1+\epsilon$ factor. Similarly, if they fall below a certain threshold, the $\beta$ values are increased by a $1+\epsilon$ factor.

Our main observation is that even if these thresholds are slightly ``loose'', the algorithm is still correct. We prove this observation in \cref{sec:mpc:correctness}. A consequence of this is that estimating the exact aggregations computed by \cref{alg:local} in Lines 2 and 3 is sufficient.

To obtain approximations with an efficient number of samples, we use the fact that the $\beta$ values (see \cref{alg-local:agg1}) cannot change drastically within a single round. In particular, after $B$ rounds the values change by at most $(1+\epsilon)^B$. The following lemma helps in this regard.

\begin{lemma}\label{lem:sampling}
    Consider any sequence $X$ of $n$ elements $x_1, x_2, \dots x_n$ with $S_x = \sum\limits_{i=1}^n x_i$ and such that each $x_i$ lies in the interval $[V / t, V \cdot t]$ for some positive real $V$, and let $\epsilon \in (0, 1]$.
    For $s \geq 20 \cdot t^2 \log n / \epsilon^4$, let $y_1, y_2, \dots y_s$ be a sequence of uniformly random independent samples from $X$.
    % \kuba{Added 'independent'} 
    Denote the rescaled sum of the samples as $S_y = \frac{n}{s} \cdot \sum\limits_{i=1}^s y_i$. Then,
    \begin{equation*}
        \mathrm{Pr}\Bigg[|S_y - S_x| \leq 4\epsilon S_x\Bigg] \geq 1 - n^{-10} \cdot \log_{1+\epsilon} t
    \end{equation*}
\end{lemma}

\begin{proof}
    We have $S_x \geq n V / t$. Let us split the interval $[V / t, V \cdot t]$ into groups $\lset_i = ((1+\epsilon)^{r-1}, (1 + \epsilon)^r]$ for $i$ ranging from $-\lceil \log_{1+\epsilon} t \rceil$ to $\lceil \log_{1+\epsilon} t \rceil$. Let $M_i$ be the set of elements $j$ whose value $x_j$ lies in $\lset_i$.

    We partition the contribution of the elements $x_i$ into two parts, depending on the size of $|M_i|$. Let $S_x = S_{x,\mathsf{small}} + S_{x,\mathsf{large}}$ where, $S_{x,\mathsf{small}}$ is the sum of all $x_j$ such that $j$ lies in a group $M_i$ of size at most $10 n \log n / (s \epsilon^2)$. $S_{x,\mathsf{large}}$ is the sum of the remaining elements.

    \begin{enumerate}
        \item[] \textbf{Case 1:} ($S_{x,\mathsf{small}} \leq S_x \epsilon$). In this case, the total contribution of such groups can be bound as follows,
        \begin{equation*}
            S_{x,\mathsf{small}} \leq \frac{20 n V t \log n}{s \epsilon^3} = \frac{n V}{t} \cdot \frac{20t^2 \log n}{s \epsilon^3} \leq S_x \cdot \epsilon
        \end{equation*}

        For the leftmost inequality, we assumed that every group has the maximum size \\ ($10 n \log n / (s \epsilon^2)$) and maximum value. The maximum value is bounded as follows, the value of the largest group is at most $Vt$. Therefore the total contribution over all groups is at most the infinite geometric sum with first term as $\frac{10 n V t \log n}{s \epsilon^2}$ and common ratio $1+\epsilon$, which is bounded by $\frac{20 n V t \log n}{s \epsilon^3}$. 
        For the last inequality, we used the assumption that $s \geq 20 t^2 \log n / \epsilon^4$.

        \item[] \textbf{Case 2:} ($|S_y - S_{x,\mathsf{large}}| \leq 3 \epsilon S_{x,\mathsf{large}}$). In this case, for each $x_j$ contributing to the sum, at least $10 n \log n / (s \epsilon^2)$ values close to it exist (i.e., they lie in the same set $M_i$ for some $i$). For each such group $M_i$, the expected number of samples $y_k$ chosen from $M_i$ is $10 \log n / \epsilon^2$. By Chernoff bounds, the number of samples is off by a factor of $1+2\epsilon$ of the expected value by a probability of at most $2 e^{-40 \log n/3} \leq n^{-10}$.

        The sum of the values of these samples incurs at most another $1+\epsilon$ factor, since the gap between the largest and smallest value in a group is $1+\epsilon$. The overall approximation ratio is $1 + 3\epsilon$ for this case.
    \end{enumerate}
    Assuming we lose all the elements in Case 1, we still have at least $(1-\epsilon) S_x$ left in Case 2. In Case 2, we do not deviate from the actual value by more than $3\epsilon S_x$. Overall, $S_y$ deviates from $S_x$ by at most $4\epsilon S_x$. Using the union bound over all intervals in Case 2 gives us the desired probability.
\end{proof}

Guided by \cref{lem:sampling}, if we want to compress $B$ rounds of \cref{alg:local} to MPC (being content with $1+O(\epsilon)$ approximations), then we can plugin $t = (1+\epsilon)^{B}$ in \cref{lem:sampling} and obtain $s$, the number of samples needed per group. The total degree per vertex is at most $d = 20(1+\epsilon)^{2B} \cdot \log^2 n \cdot \epsilon^{-5}$.

Now the $B$-radius neighborhood of the relevant vertices around each vertex has volume at most $d^B$. We choose $B$ so that (i) the neighborhood can be stored within a single machine and (ii) the size is at most $\lambda$. (i) ensures that we can simulate $B$ rounds for $v$ in a single machine and (ii) ensures that the total memory is $\tilde{O}(\lambda n + m)$. We require $d^B \leq \min\{\lambda, n^\alpha\}$:
\begin{equation*}
    2B^2 \log(1+\epsilon) + 5 B \log(\epsilon^{-1}) + 2B \log \log n + 5B \leq \min\{\log \lambda, \alpha \cdot \log n \}  
\end{equation*}
Since we are concerned only with asymptotics, we obtain a simple candidate for $B$ by bounding each term on the left by $\min(\log \lambda, \alpha \log n) / 4$. Assuming $\epsilon$ is a constant, and $n$ is large enough, the first term is dominant. Thus, we can set $B = B_{\epsilon}$ to guarantee that aggregations are computed within a $1+4\epsilon$ factor. 
\begin{equation}\label{eqn:bvalue}
B_{\epsilon} = \min \Bigg\{ \frac{\sqrt{\alpha \log n}}{\sqrt{8 \epsilon}}, \frac{\sqrt{\log \lambda}}{\sqrt{8 \epsilon}} \Bigg\}
\end{equation}

For ease of analysis in the correctness proof, we set $B=B_{\epsilon/48}$, giving us the following lemma.

\begin{lemma} \label{lem:approx}
    Consider \cref{alg:matching}. We define the following parameters, 
    \begin{equation*} \begin{split}
    \overline{\beta_u} = \sum\limits_{v \in \neigh_u} \beta_v, \ \ \ 
    \alloc_v = \sum\limits_{u \in \neigh_v} \overline{\beta_u}
    \end{split} \end{equation*}
    We have $|\overline{\beta_u} - \beta_u| \leq \epsilon/12 \cdot \overline{\beta_u}$ and $|\alloc_v - \halloc_v| \leq \epsilon/4 \cdot \alloc_v$ with probability at least $1 - n^{-5}$ over all rounds and vertices.
\end{lemma}

\begin{proof}
    For $\overline{\beta_u}$ we use \cref{lem:sampling} with $t = (1 + \epsilon)^B$. Observe that $B$ value is set so that the error term in \cref{lem:sampling} is $\epsilon / 48$. The approximation ratio is $1 + \epsilon/12$. Since the choice of $B$ in \cref{eqn:bvalue} is $o(n)$ even when $\epsilon < 1/n$, the probability guarantee is at least $1 - n^{-9}$. 

    For the second expression, we have the same situation. Applying union bound over all vertices and rounds we get a conservative failure probability of $n^{-5}$ overall. For the approximation ratio, the $1 + \epsilon/12$ is cascaded twice, leading to overall $(1 +  \epsilon/12)^2 \leq 1 + \epsilon / 4$.
\end{proof}
From \cref{lem:approx}, we can infer that the $B$ round simulation is identical to a run of the algorithm described in \cref{sec:mpc:correctness} with the value of $k$ chosen appropriately. Our round complexity is $\tau \log B / B$ where $\tau$ is given in \cref{alg:local} and $B$ is as per \cref{eqn:bvalue}, which completes the proof of \cref{thm:fast-mpc}.

We did not cover MPC simulations of certain lines in \cref{alg:matching} such as the graph exponentiation to compute the subgraphs $H_{r, v}$ for each $v$ and the random sampling from the groups. These can be implemented from standard primitives such as graph exponentiation and sorting, which are by now standard in the MPC literature.

Finally, our algorithms as stated assume knowledge of $\lambda$. To remove this assumption, we can make use of the fact that the proof of correctness of \cref{alg:local} provides a termination condition. To perform this test, we are required to compute the fractions assigned to edges incident to a subset of vertices. Again using known primitives in MPC, we can perform this computation in $O(1)$ rounds. We therefore can repeat the algorithm by guessing the value of $\sqrt{\log \lambda}$ and doubling the estimate when the termination test fails.

