\section{Correctness of the MPC algorithm}
\label{sec:mpc:correctness}

\begin{algorithm}
\begin{algorithmic}[1]
\Statex \textbf{Input:} $G = (L \cup R, E)$, capacity constraints $\{\mcap_v\}_{v \in R}$, number of rounds $\tau \geq 1$, approximation parameter $\epsilon \in (0, \frac{1}{4}]$.
\Statex \textbf{Parameters:} positive real numbers $\{k_{v,r}\}_{v \in R, 1 \leq r \leq \tau}$.
\Statex \textbf{Output:} a fractional allocation $\{\vx'_{u,v}\}_{(u,v) \in E}$
\Statex \textbf{Initialization:} Set $\beta_v \gets 1$ for every $v \in R$

\For{rounds $r = 1, 2, \dots \tau$}
    \State for each vertex $u \in L$: %\label{alg-local:agg1}
    \Statex \hspace{1cm} Set $\vx_{u, v} = \frac{\beta_v}{\sum_{v' \in \neigh_u} \beta_{v'}}$ for each $v \in \neigh_u$ 
    \State for each vertex $v \in R$: %\label{alg-local:agg2}
    \Statex \hspace{1cm} Set $\alloc_v \gets \sum\limits_{u \in \neigh_v} \vx_{u, v}$
    \State for each vertex $v \in R$, update  $\beta_v$ as follows, %\label{alg-local:thresh-checker}

    \Statex  $$ \beta_v \gets \begin{cases} 
        \beta_v (1 + \epsilon) \ \ \ \text{if } \alloc_v \leq \mcap_v / (1 + k_{v, r}\epsilon) \\
        \beta_v / (1 + \epsilon) \ \ \text{if } \alloc_v \geq \mcap_v (1 + k_{v, r} \epsilon) \\
        \beta_v \ \ \ \ \ \ \ \ \ \ \ \ \text{otherwise}      
    \end{cases} $$    
\EndFor

\For {each vertex $v \in R$}
    \State For all $u \in \neigh_v$, set $\vx'_{u,v} \gets \begin{cases} 
        \frac{\mcap_v}{\alloc_v}\vx_{u,v} \ \ \ \text{if } \alloc_v > \mcap_v \\
        \vx_{u,v} \ \ \ \ \ \ \ \ \ \ \ \ \text{otherwise}      
    \end{cases}$
\EndFor
\end{algorithmic}
\caption{An adapted version of \cref{alg:local}.}
\label{alg:det-thresh}
\end{algorithm}

To prove the correctness of the MPC algorithm (\cref{alg:matching}), we consider an adaptation of our LOCAL algorithm (\cref{alg:local}).
The adaptation is given in \cref{alg:det-thresh}.
\cref{alg:local,alg:det-thresh} only have two differences:
First, \cref{alg:det-thresh} requires an additional set of parameters $\{k_{v,r}\}_{v \in R, 1 \leq r \leq \tau}$.
Second, \cref{alg:det-thresh} applies a different update rule in line 4, in which the thresholds for updating $\beta_v$ are replaced with $\mcap_v / (1 + k_{v,r}\epsilon)$ and $\mcap_v(1 + k_{v,r}\epsilon)$.
This adapted update rule is more flexible because the thresholds can be controled by adjusting the parameters.
Note that \cref{alg:local} is a special case where all parameters $k_{v,r}$ are fixed as 1.

Consider an input instance $(G, \{\mcap_v\}_{v \in R}, \tau, \epsilon)$ of \cref{alg:matching}.
The correctness proof for \cref{alg:matching} consists of three parts.

\begin{itemize}
    \item In the first part, we argue that \cref{alg:matching} is equivalent to \cref{alg:det-thresh} with a specific set of parameters.
More precisely, we show that given a fixed execution of \cref{alg:matching} (on the input instance $(G, \{\mcap_v\}_{v \in R}, \tau, \epsilon)$),
with high probability, there exists a set of parameters $\{k_{v,r}\}_{v \in R, 1 \leq r \leq \tau}$ such that the outputs of \cref{alg:matching,alg:det-thresh} are the same; in addition, the constructed parameters satisfy $\frac{1}{4} \leq k_{v,r} \leq 4$ for all $v \in R$ and $1 \leq r \leq \tau$.
    \item In the second part, we show that \cref{alg:det-thresh} has an approximation factor of $(2 + (2k + 8)\epsilon)$ if the input and parameters satisfy $\frac{1}{k} \leq k_{v,r} \leq k$ for some small number $k$, $\epsilon \leq \frac{1}{k}$, and $\tau \geq \loglambda$. By combining the results of the first and second parts, we know that \cref{alg:matching} has an approximation factor of $2 + 16 \epsilon$ if $\tau \geq \loglambda$ and $\epsilon \leq \frac{1}{4}$.
    \item In the third part, we show that \cref{alg:det-thresh} has an approximation factor of $1 + (k + 14)\epsilon$ if the input and parameters satisfy $\frac{1}{k} \leq k_{v,r} \leq k$ for some small number $k$, $\epsilon \leq \frac{1}{k}$, and $\tau \geq \logn$. By combining the results of the first and third parts, we know that \cref{alg:matching} has an approximation factor of $1 + 18\epsilon$ for $\tau = O(\logn)$ and $\epsilon \leq \frac{1}{4}$.
\end{itemize}
The three parts are presented in \cref{sec:appendix-1,sec:appendix-2,sec:appendix-3}, respectively.

\subsection{Equivalence of \texorpdfstring{\cref{alg:matching,alg:det-thresh}}{Algorithms 2 and 3}} \label{sec:appendix-1}
In the following, we argue that \cref{alg:matching} is equivalent to \cref{alg:det-thresh} with a specific set of parameters. Consider an execution of \cref{alg:matching}. For ease of presentation, for a fixed round, we use $\{\hbeta_v\}_{v \in R}$ to denote the priority values maintained by \cref{alg:matching}, and use $\{\beta_v\}_{v \in R}$ to denote the priority values maintained by \cref{alg:det-thresh}. Let $\hvx_{u, v} = \frac{\hbeta_v}{\sum_{v' \in \neigh_u} \hbeta_{u'}}$ denote the corresponding fractional values in \cref{alg:matching}.

\begin{lemma} \label{lem:equivalence} Let $(G, \{\mcap_v\}_{v \in A}, \epsilon, R)$ be an input instance for \cref{alg:matching,alg:det-thresh}.
Consider an execution of \cref{alg:matching} on the instance.
With high probability, there exists a set of parameters $\{k_{v,r}\}_{v \in R, 1 \leq r \leq \tau}$ for \cref{alg:det-thresh},
all in the range $[\frac{1}{4}, 4]$,
such that the output of the execution is the same as the output of \cref{alg:det-thresh}.
\end{lemma}
\begin{proof} We prove this lemma by constructing a set of parameters $\{k_{v,r}\}_{v \in R, 1 \leq r \leq \tau}$ such that $\beta_v = \hbeta_v$ holds for all $v \in R$ across all rounds.
Initially, both algorithms set the priority values as 1.
Hence, in beginning of the the first round, $\beta_v = \hbeta_v$ holds for all $v \in R$.

Consider a fixed round $r$ and assume that $\beta_v = \hbeta_v$ holds in the beginning of round $r$.
Let $v \in R$ be a vertex.
In the following, we show how to determine the parameter $k_{v,r}$ such that the two algorithms update the priority values in the same way.
Since $\beta_v = \hbeta_v$ holds for all $v \in R$, we know that $\vx_{u,v} = \hvx_{u,v}$ holds for each edge $(u, v)$ in round $r$.
Therefore, $\alloc_v = \sum_{u \in \neigh_v} \vx_{u,v}$ is equal to $\sum_{u \in \neigh_v} \hvx_v$.
By \cref{lem:approx}, the execution of \cref{alg:matching} satisfies
\begin{equation} \label{eqn:appendix-mpc-approx}
    |\halloc_v - \sum_{u \in \neigh_v} \hvx_v| = |\halloc_v - \alloc_v| \leq \frac{\epsilon}{4} \alloc_v
\end{equation}
with high probability.
Assume that this inequality holds for the given execution.
Consider two cases:
\begin{enumerate}
    \item[] \textbf{Case 1:} In round $r$, $\alloc_v \leq 2\mcap_v$. By \cref{eqn:appendix-mpc-approx}, we have

    \begin{equation} \label{eqn:appendix-case1}
        |\alloc_v - \halloc_v| \leq \frac{\epsilon}{4} \alloc_v \leq \frac{\epsilon}{2} \epsilon \mcap_v.
    \end{equation}
    There are three subcases:

    \begin{enumerate}
        \item[] \textbf{Case 1.1:} In the execution, $\hbeta_v$ is increased in round $r$.
        That is, $\halloc_v \leq \mcap_v / (1 + \epsilon)$.
        Our goal is to choose $k_{v,r}$ such that \cref{alg:det-thresh} also increases $\beta_v$.
        By \cref{eqn:appendix-case1}, we have $\alloc_v \leq \halloc_v + \frac{\epsilon}{2} \mcap_v \leq (\frac{1}{1 + \epsilon} + \frac{\epsilon}{2}) \mcap_v$.
        Thus, we should choose $k_{v,r}$ such that $\alloc_v \leq \frac{1}{(1 + k_{v,r} \epsilon)} \mcap_v$.
        Since $(\frac{1}{1 + \epsilon} + \frac{\epsilon}{2}) \leq \frac{1}{1 + \frac{1}{4}\epsilon}$ for $\epsilon \leq \frac{1}{4}$, we may choose $k_{v,r} = \frac{1}{4}$.

        \item[] \textbf{Case 1.2:} In the execution, $\hbeta_v$ is decreased in round $r$.
        That is, $\halloc_v \geq \mcap_v (1 + \epsilon)$.
        Our goal is to choose $k_{v,r}$ such that \cref{alg:det-thresh} also decreases $\beta_v$.
        By \cref{eqn:appendix-case1}, we have $\alloc_v \geq \halloc_v - \frac{\epsilon}{2} \mcap_v \geq (1 + \epsilon - \frac{\epsilon}{2}) \mcap_v$.
        By choosing $k_{v,r} = \frac{1}{2}$, we ensure that $\alloc_v \geq (1 + k_{v,r} \epsilon) \mcap_v$ and thus \cref{alg:det-thresh} will decrease $\beta_v$.

        \item[] \textbf{Case 1.3:} In the execution, $\hbeta_v$ is unchanged in round $r$.
        That is, $\mcap_v / (1 + \epsilon) < \halloc_v < \mcap_v (1 + \epsilon)$.
        By \cref{eqn:appendix-case1}, we have $(\frac{1}{1 + \epsilon} - \frac{\epsilon}{2}) \mcap_v < \alloc_v < (1 + \frac{3\epsilon}{2}) \mcap_v$.
        Using a similar argument, we know that \cref{alg:det-thresh} will not change $\beta_v$ if $\frac{1}{1 + k_{v,r}\epsilon} \leq \frac{1}{1 + \epsilon} - \frac{\epsilon}{2}$ and $1 + k_{v,r}\epsilon \geq 1 + \frac{3\epsilon}{2}$.
        It is not hard to verify that $k_{v,r} = 3$ satisfies these conditions.
    \end{enumerate}

    \item[] \textbf{Case 2:} In round $r$, $\alloc_v > 2\mcap_v$.
    In this case, we choose $k_{v,r} = 1$ so that \cref{alg:det-thresh} will decrease $\beta_v$.
    By \cref{eqn:appendix-case1}, we have
    \begin{equation*}
        \halloc_v \geq (1 - \epsilon) \alloc_v
                  > 2(1 - \epsilon)\mcap_v > (1 + \epsilon)\mcap_v,
    \end{equation*}    
    where the last inequality holds because $\epsilon \leq \frac{1}{4}$.
    Therefore, \cref{alg:matching} must also have decreased $\hbeta_v$ in round $r$.
\end{enumerate}

By repeating the above argument for $r = 0, 1, \dots, R$, we obtain a set of parameters $\{k_{v,r}\}$ such that, in each round, the two algorithms update the priority value of each vertex in exactly the same way. Hence, the lemma holds.
\end{proof}

\subsection{Performance guarantee on low arboricity bipartite graphs} \label{sec:appendix-2}

In the following, we show that \cref{alg:det-thresh} has an approximation factor of $2 + (2k + 8)\epsilon$ if the parameters satisfy $\tau \geq \loglambda$, $\frac{1}{k} \leq k_{v,r} \leq k$ holds for all $k_{v,r}$ and for some number $k$, and $\epsilon \leq \frac{1}{k}$.
By \cref{lem:equivalence}, this result implies that \cref{alg:matching} has an approximation factor of $2 + 16 \epsilon$ if $\tau \geq \loglambda$ and $\epsilon \leq \frac{1}{4}$.
The result is proven by modifying the proof in \cref{sec:local}.

We first present the approximation factor of \cref{alg:det-thresh}. Let $k$ be a number such that $\frac{1}{k} \leq k_{v,r} \leq k$ holds for all $v \in R$ and $1 \leq r \leq \tau$.
As in \cref{sec:local}, we consider the $\beta$ variables after the end of round $\tau$ and partition $R$ into level sets $\lset_0, \lset_1, \dots, \lset_{2\tau}$, where $\lset_i = \{v \mid v \in R \mbox{ and } \beta_v = (1 + \epsilon)^{i}\}$.
We generalize \cref{lem:alloc-bound} as follows.

\begin{lemma} \label{lem:appendix-alloc-bound} Assume that we run \cref{alg:det-thresh} for $\tau \geq 1$ rounds. Then, after all rounds have completed, we have
\begin{enumerate}
    \item for any $v \in \bigcup_{j=0}^{2\tau-1} \lset_j$, $\alloc_v \geq \frac{1}{1+(k + 2)\epsilon} \mcap_v$, and
    \item for any $v \in \bigcup_{j=1}^{2\tau} \lset_j$, $\alloc_v \leq (1+(k + 2)\epsilon) \mcap_v$.
\end{enumerate}
\end{lemma}
\begin{proof} Due to the symmetry of the two claims, we only prove the former.
Since $v$ is not in level set $\lset_{2\tau}$, there was a time that we did not increase $\beta_v$.
Let $t$ be the last round where $\beta_v$ is not increased.
At the end of round $t$, $\alloc_v \geq \frac{1}{1 + k\epsilon}\mcap_v$.
For $t = \tau$, this completes the proof.
Otherwise, we consider the round $t + 1 \leq \tau$.
We first show that $\alloc_v \geq \frac{1}{1+(k+2)\epsilon} \mcap_v$ at the end of round $t + 1$.
Recall that $\alloc_v = \sum_{u \in \neigh_v} \frac{\beta_v}{\sum_{a' \in \neigh_u} \beta_{a'}}$.
If $\beta_v$ is unchanged at round $t$, the numerator of each term also remains unchanged.
The denominator terms are increased at most by a factor of $(1 + \epsilon)$.
So in total, $\alloc_v$ is not decreased by more than a factor of $(1 + \epsilon)$.
Hence, at the end of round $t + 1$, we have $\alloc_v \geq \frac{1}{(1+k\epsilon)(1+\epsilon)} \mcap_v \geq \frac{1}{(1+(k+2)\epsilon)} \mcap_v $, where the last inequality holds because $k\epsilon \leq 1$.
In the other case, $\beta_v$ is decreased at round $t$, so the numerator of each term is also reduced by a factor of $(1 + \epsilon)$.
In total, $\alloc_v$ is decreased by a factor of at most $(1+\epsilon)^2$ at round $t + 1$.
Note that the reduction of $\beta_v$ at round $t$ means $\alloc_v$ was at least $(1 + \frac{1}{k}\epsilon) \mcap_v \geq \mcap_v$, and therefore at least $\frac{1}{(1+\epsilon)^2} \leq \frac{1}{(1+(k+2)\epsilon)}$ at round $t + 1$.
So independent of whether $\beta_v$ was reduced or not, $\alloc_v \geq \frac{1}{1+(k+2)\epsilon} \mcap_v$ holds at round $t + 1$.

By definition of $t$, $\beta_v$ is increased in all rounds after $t$.
With a similar argument, we know that $\alloc_v$ does not decrease at any of these rounds.
So $\alloc_v$ remains at least $\frac{1}{1+(k+2)\epsilon} \mcap_v$ till the last round.
\end{proof}

\cref{lem:appendix-alloc-bound} implies the two lower bounds on $\mweight$. First, since each vertex in $\bigcup_{j<2\tau} \lset_j$ almost fill up their capacities, we have

\begin{equation} \label{eqn:appendix-weight-bound-1} \textstyle
    \mweight \geq \frac{1}{1+(k+2)\epsilon} \sum_{j=0}^{2\tau-1} \mcap(\lset_j).
\end{equation}
Second, since all vertices in $\bigcup_{j > 0} \lset_j$ has bounded over-allocation, when line 6 of \cref{alg:det-thresh} was executed, the ratio of $\frac{\mcap_v}{\alloc_v}$ was at least $\frac{1}{1 + (k+2)\epsilon}$.
Hence, we have

\begin{equation} \label{eqn:appendix-weight-bound-2} \textstyle
    \mweight \geq \frac{1}{1+(k+2)\epsilon} \sum_{j=1}^{2\tau} \sum_{v \in \lset_j} \alloc_v.
\end{equation}

In the proof of \cref{lem:goal}, we have mentioned the following upper bounds on $OPT$, which is proven by \cite{AZM18}.

\begin{equation} \label{eqn:appendix-opt-bound} \textstyle
    OPT \leq \sum_{j=0}^{\ell} \mcap(\lset_j) + |\neigh (\bigcup_{j=\ell+1}^{2\tau} \lset_{j})| \mbox{ for all } 0 \leq \ell \leq 2\tau.
\end{equation}

We now present a generalization of \cref{lem:goal}.

\begin{lemma} Assume that we run \cref{alg:det-thresh} for $\tau \geq 1$ rounds. Then, after all rounds have completed, we have
\begin{equation} \label{eqn:appendix-goal} \textstyle
     OPT \leq (1 + (k+2)\epsilon) \mweight + |\neigh(\lset_{2\tau})|.
\end{equation}
\end{lemma}
\begin{proof}
By setting $\ell = 2\tau - 1$ in \cref{eqn:appendix-opt-bound}, we obtain $OPT \leq \sum_{j=0}^{2\tau-1} \mcap(\lset_j) + |\neigh(\lset_{2\tau})|$.
By \cref{eqn:appendix-weight-bound-1}, the term $\sum_{j=0}^{2\tau-1} \mcap(\lset_j)$ can be replaced by $(1 + (k+2)\epsilon) \mweight$, which yields the desired inequality.
\end{proof}

We are ready to prove the approximation factor of \cref{alg:det-thresh}.

\begin{theorem} \label{thm:appendix-apx-factor-1} Assume that we run \cref{alg:det-thresh} for $\tau \geq \loglambda$ rounds. Then, $OPT \leq (2 + (2k + 8)\epsilon)\mweight$.
\end{theorem}
\begin{proof} Let $N'$ denote $\neigh(\lset_{2\tau})$. By \cref{eqn:appendix-goal}, if we can show that $|N'| \leq (1 + (k + 6)\epsilon) \mweight$, then $OPT \leq (2 + (2k+8)\epsilon)\mweight$. To prove that $|N'| \leq (1 + (k+6)\epsilon) \mweight$, we consider two cases:

\begin{itemize}
    \item[] \textbf{Case 1:} $|N'| \leq |\lset_0|$. By \cref{eqn:appendix-weight-bound-1}, we have
    \begin{equation*}
        \mweight \geq \frac{1}{1+(k+2)\epsilon} \mcap(\lset_0) \geq \frac{1}{1+(k+2)\epsilon} |\lset_0| \geq \frac{1}{1+(k+2)\epsilon}|N'|.
    \end{equation*}
    Hence, $|N'| \leq (1 + (k+6)\epsilon) \mweight$ holds for this case.

    \item[] \textbf{Case 2:} $|N'| > |\lset_0|$. We first show that $\sum_{j=1}^{2\tau} \sum_{v \in \lset_j} \alloc_v \geq (1 - \frac{\epsilon}{2}) |N'|$.
    Consider a vertex $u \in L$ and a vertex $v \in \lset_0$.
    Since $N'$ is the neighbor set of $\lset_{2\tau}$, there is a vertex $v' \in \lset_{2\tau}$ that is a neighbor of $u$.
    In the end of round $\tau$, $\beta_{v'}$ is larger than $\beta_{v}$ by a factor of $(1 + \epsilon)^{2\tau}$.
    Thus, in the beginning of round $\tau$, $\beta_{v'}$ is larger than $\beta_v$ by at least a factor of $(1 + \epsilon)^{2\tau-2}$.
    Recall that $x_{u,v}$ and $x_{u,v'}$ are calculated proportional to the priority values of $v$ and $v'$ in the beginning of round $\tau$.
    Thus, $\vx_{u,v} \leq \vx_{u,v'} / (1+\epsilon)^{2\tau - 2}$.
    Since $\tau = \loglambda$, we have $\vx_{u,v} \leq \frac{\epsilon}{4\lambda}\cdot\vx_{u,v} \leq \frac{\epsilon}{4\lambda}$.
    That is, every edge $(u, v)$ with $u \in N'$ and $v \in \lset_0$ allocates at most an amount of $\frac{\epsilon}{4\lambda}$ to $\lset_0$.
    Consider the subgraph $G'$ of $G$ induced by $N' \cup \lset_0$.
    Since the arboricity of $G$ is bounded by $\lambda$ and $|N'| > |\lset_0|$, the number of edges in $G'$ is at most $\lambda \cdot (|N'| + |\lset_0|) < 2 \lambda |N'|$.
    Therefore, the total allocation from $N'$ to $\lset_0$, $\sum_{u \in N'} \sum_{v \in \lset_0} \vx_{u,v}$, is at most $2 \lambda |N'| \cdot \frac{\epsilon}{4\lambda} = \frac{\epsilon}{2} |N'|$.
    That is, the total allocation from $N'$ to vertices not in $\lset_0$ is at least $(1 - \frac{\epsilon}{2})|N'|$.
    This implies that $\sum_{j=1}^{2\tau} \sum_{v \in \lset_j} \alloc_v \geq (1 - \frac{\epsilon}{2}) |N'|$.

    By \cref{eqn:appendix-weight-bound-2}, $\mweight$ is at least

    \begin{equation*}
        \frac{1}{1+(k+2)\epsilon} \sum_{j=1}^{2\tau} \sum_{v \in \lset_j} \alloc_v
        \geq \frac{1}{1+(k+2)\epsilon} (1 - \frac{\epsilon}{2}) |N'|
        \geq \frac{1}{(1 + (k+2)\epsilon)(1+\epsilon)} |N'|.
    \end{equation*}
    Since $k\epsilon \leq 1$, the last term is at least $\frac{1}{1+(k+6)\epsilon}$. Hence, $|N'| \leq (1 + (k+6)\epsilon) \mweight$ also holds for this case.
\end{itemize}

Since we have $|N'| \leq (1 + (k+6)\epsilon) \mweight$ in both cases, the theorem holds.
\end{proof}

\cref{lem:equivalence,thm:appendix-apx-factor-1} imply the following.

\begin{theorem} Assume that we execute \cref{alg:matching} with $\epsilon \leq \frac{1}{4}$ and $\tau \geq \loglambda$. Then, with high probability, the algorithm finds a $(2 + 16 \epsilon)$-approximate fractional allocation.
\end{theorem}

\subsection{Performance guarantee on bipartite graphs} \label{sec:appendix-3}

In the following, we show that \cref{alg:det-thresh} has an approximation factor of $1 + (k + 14)\epsilon$ if $\frac{1}{k} \leq k_{v,r} \leq k$ holds for all $k_{v,r}$ and for some number $k$, $\epsilon \leq \frac{1}{k}$, and $\tau \geq \lognExact$.
By \cref{lem:equivalence}, this result implies that \cref{alg:matching} has an approximation factor of $1 + 18 \epsilon$ if $\tau \geq \lognExact$ and $\epsilon \leq \frac{1}{4}$.
The result is proven by modifying a theorem in \cite{AZM18}, which shows that \cref{alg:local} has an approximation factor of $(1 + O(\epsilon))$.

We first present lower bounds for $\mweight$. Let $g$ denote $\gap$.

\begin{lemma} \label{lem:appendix-weight-bound} For any two indices $1 \leq \ell$ and $\ell + g \leq \ell' \leq 2\tau$, we have

\begin{equation} \label{eqn:appendix-gap-bound} \mweight \geq \left( \frac{1}{1 + (k + 6)\epsilon} \right) \left(\sum_{j=0}^\ell  \mcap(\lset_j) + \left| \neigh \left( \bigcup_{j'=\ell'+1}^{2\tau} \lset_{j'} \right) \right| \right)
\end{equation}

\end{lemma}
\begin{proof} By \cref{lem:appendix-alloc-bound}, the vertices
$\lset_0, \lset_1, \dots, \lset_\ell$ almost fill up their capacities.
Therefore, they contribute at least $\frac{1}{1 + (k + 2)\epsilon}
\sum_{j=0}^{\ell} \mcap(\lset_j)$ which is larger than the first term of the lower bound.

The second term represents all neighbors of vertices in $\lset_{\ell'+1}, \dots, \lset_{2\tau}$. We first show that for each vertex $u \in L$ having a neighbor in $\bigcup_{j=\ell'+1}^{2\tau} \lset_j$, we have:

\begin{equation} \label{eqn:appendix-gap}
    \sum_{j=\ell+1}^{2\tau} \sum_{v \in \lset_j} \vx_{u, v} \geq (1 - \frac{\epsilon}{2}),
\end{equation}

That is, a large fraction of $u$ is assigned to vertices in $\lset_{\ell+1}, \dots, \lset_{2\tau}$.
Consider vertex $u \in L$ that is a neighbor of $v' \in \lset_{j'}$ for some $j' \geq \ell' + 1$.
Because $\ell'$ is at least $\ell + \gap$, we have $\beta_{v'} \geq \frac{2|R|}{\epsilon} \beta_v$ for any $v \in \lset_j$ with $j \leq l$.
Therefore $\vx_{u, v}$ is at most $\frac{\epsilon}{2|R|}$ times $\vx_{u, v'}$. Since there are at most $|R|$ vertices like $v$, we have

\begin{equation*}
    \sum_{j=0}^{\ell} \sum_{v \in \lset_j} \vx_{u, v} \leq \sum_{j=0}^{\ell} \sum_{v \in \lset_j} \frac{\epsilon}{2|R|} \cdot \vx_{u, v'} \leq \frac{\epsilon}{2} \vx_{u, v'} \leq \frac{\epsilon}{2}.
\end{equation*}
Hence, \cref{eqn:appendix-gap} holds, which indicates that each vertex in $\neigh(\bigcup_{j'=\ell'+1}^{2\tau} \lset_{j'})$ contributes at least $1 - \frac{\epsilon}{2}$ to $\sum_{j=\ell+1}^{2\tau} \alloc_v$. Using \cref{lem:appendix-alloc-bound}, at least $\frac{1}{1+(k+2)\epsilon}$ fraction of every such vertex will be counted toward $\mweight$. So in total, we get at least $\frac{1}{1+(k + 2)\epsilon} \cdot (1 - \frac{\epsilon}{2}) \geq \frac{1}{1+6\epsilon}$ fraction for each vertex in $\neigh(\bigcup_{j'=\ell'+1}^{2\tau} \lset_{j'})$. This concludes the proof.
\end{proof}

We prove the approximation factor of \cref{alg:det-thresh} by combining the lower and upper bounds.

\begin{lemma} \label{lem:appendix-apx-factor-2} \cref{alg:det-thresh} has an approximation factor of $1 + (k + 14) \epsilon$ if the input instance and parameters satisfy all of the following:
\begin{itemize}
    \item for all $v \in R$ and $0 \leq r \leq \tau$, $\frac{1}{k} \leq k_{a,r} \leq k$ for some number $k$,
    \item $\epsilon \leq \frac{1}{k}$, and
    \item $\tau \geq \gap$.
\end{itemize}
\end{lemma}
\begin{proof} There are two main gaps between the lower bound of \cref{eqn:appendix-gap-bound} and the upper bound of \cref{eqn:appendix-opt-bound}:
the $\frac{1}{1+(k+6)\epsilon}$ factor and the sum $\sum_{j=\ell+1}^{\ell'} \sum_{v \in \lset_j} \mcap_v$.
We show that the latter gap is small for some value of $\ell$ and
$\ell' = \ell + g$.
Recall that $g = \gap$.
Summing the gap over different values of $\ell$ yields
\begin{equation} \notag \textstyle
    \sum_{\ell=0}^{2\tau - g - 1} \sum_{j=\ell+1}^{\ell + g} \mcap(\lset_j)
    \leq g \sum_{j = 1}^{2\tau - 1} \mcap(\lset_j).
\end{equation}
Therefore, there exists an $\ell$ with $0 \leq \ell \leq 2\tau - g - 1$ such that its associated gap $\sum_{j=\ell+1}^{\ell+g} \mcap(\lset_j)$ is at most $\frac{g}{2\tau - g} \sum_{j=1}^{2\tau-1} \mcap(\lset_j) \leq \epsilon \sum_{j=1}^{2\tau-1} \mcap(\lset_j)$, where the last inequality holds when $\tau$ is at least $g / \epsilon = \lognExact$ and $\epsilon \leq 1$.

By \cref{eqn:appendix-weight-bound-1}, $\mweight$ is at least $\frac{1}{1+(k+2)\epsilon} \sum_{j=1}^{2\tau} \mcap(\lset_j)$. This means the gap associated for some $\ell$ is at most $\epsilon \cdot (1 + (k + 2)\epsilon) \mweight$. Using \cref{lem:appendix-weight-bound,eqn:appendix-opt-bound}, we have
\begin{equation}
\begin{split}
    \mweight & \geq \frac{1}{1+(k+6)\epsilon}(OPT - \epsilon (1 + (k + 2)\epsilon) \mweight) \\
    & = \frac{1}{1+(k+6)\epsilon} OPT - \epsilon \cdot \frac{1 + (k + 2)\epsilon}{1 + (k + 6)\epsilon} \cdot \mweight \\
    & \geq \frac{1}{1+(k+6)\epsilon} OPT - \epsilon \mweight,
\end{split}
\end{equation}
and hence $\mweight \geq \frac{1}{(1+(k+6)\epsilon)(1 + \epsilon)} OPT$,  yielding a final approximation factor of at least $1 + (k + 14)\epsilon$.
\end{proof}

\cref{lem:equivalence,lem:appendix-apx-factor-2} imply the following.

\begin{theorem} Assume that we execute \cref{alg:matching} with $\epsilon \leq \frac{1}{4}$ and $\tau \geq \lognExact$. Then, with high probability, the algorithm finds a $(1 + 18 \epsilon)$-approximate fractional allocation.
\end{theorem}

\section{\texorpdfstring{$(1 + \epsilon)$}{1+eps} Approximation of Allocation} \label{sec:framework}
In this section, we show that the framework in \cite[Section 4]{ghaffari2022massively} can be applied to find a $(1 +\eps)$-approximate allocation on low-arboricity graphs using our MPC algorithm in \cref{sec:mpc} as a subroutine. The framework was designed for finding a $(1+\eps)$-approximate \emph{$b$-matching}.

\begin{definition}[The $b$-matching problem]
In the $b$-matching problem, the input is a graph $G$ in which each vertex $v$ is associated with an integer $b_v$. A subset of edges is called a $b$-matching if each vertex $v$ has at most $b_v$ edges in this subset. The objective is to find a $b$-matching of the maximum size.
\end{definition}

Note that the allocation problem is a special case of the $b$-matching problem, in which a bipartition $(L, R)$ is given and all vertices $v \in L$ have $b(v) = 1$.

\subsection{Review of Ghaffari et al.'s framework}
Ghaffari et al.'s framework \cite{ghaffari2022massively} assumes access to a constant approximation algorithm $A$ for the $b$-matching problem. To find a $(1+\eps)$-approximate $b$-matching, they first invoke $A$ to find a constant approximate $b$-matching $M$.
Then, the framework iteratively improve $M$ via short augmenting walks.
In a fixed iteration, they first construct a layered graph $\cL$ whose vertex set is partitioned into layers $L_0, L_1, \dots, L_{k+1}$ for some integer $k = O(\eps^{-1})$.
The graph is constructed as follows.

\begin{enumerate}
    \item[] \textbf{Step 1:} Construct a graph $W$ as follows. For each vertex $v \in G$, add $b(v)$ copies of $v$, denoted by $v^1, v^2, \dots, v^{b(v)}$, into $V(W)$. For each edge $\{u, v\} \in M$, select a copy $u^i$ and a copy $v^j$ such that no $u^i$ nor $v^j$ has any edge from $M$ incident to it. Add edge $\{u^i, v^j\}$ to $E(W)$ and mark it as being in $M$. Note that the edge set of $W$ is a matching.
    \item[] \textbf{Step 2:} Each free vertex $v^i$ of $W$ (a vertex that is not adjacent to any edge) is assigned uniformly at random to $L_0$ or $L_{k+1}$.
    \item[] \textbf{Step 3:} Each matched edge $\{v, v'\}$ is assigned to one of the layers $L_1, \dots, L_k$ uniformly at random as an arc $(v, v')$ or $(v', v)$; the arc direction is also chosen randomly.
    \item[] \textbf{Step 4:} Let $H_i$ be the heads and $T_i$ be the tails of the arcs in $L_i$. For each unmatched edge $e = \{u, v\} \in E(G)$, choose an integer $i_e$ uniformly at random from the interval $0, 1, \dots, k$ and an orientation $\vec{e} = (u, v)$ or $\vec{e} = (v, u)$; wlog, assume $\vec{e} = (u, v)$. Then, we assign $e$ to be between a copy of $u$ which is in $H_{i_e}$ (if any) and a copy of $v$ which is in $T_{i_e+1}$ (if any).
    \item[] \textbf{Step 5:} For each layer $L_i$, contract all copies of a vertex $u$ in $H_i$ to a single vertex $u'$. Set $b'(u')$ to be the number of copies contracted in this step. Contract copies of each vertex $u$ in $T_i$ in a similar way.
\end{enumerate}

The key property of this construction is that any augmenting walk is preserved in the layered graph with probability $1/\exp(O(2k))$ \cite{ghaffari2022massively}.
The framework finds an preserved augmenting walk in the layer graph by executing $O(k^k)$ iterations.
Each iteration invokes the constant approximation algorithm $A$ to find a $b'$-matching between two adjacent layers $H_i$ and $T_{i+1}$.
Note that the input to each invocation of $A$ is a subgraph of $G$.
Hence, if $G$ has arboricity $\lambda$, the input to each invocation has arboricity at most $\lambda$.
We refer the reader to \cite[Section 4]{ghaffari2022massively} for more details of the framework.

\subsection{Solving the allocation problem}
Assume that the input to the framework is an instance of the allocation problem; that is, a bipartition $(L, R)$ is given and the $b$-value of each vertex $v \in L$ is $1$.
Then, the framework can be modified as follows.
In Step 2, we assign each free vertex in $L$ to $L_0$ and each free vertex in $R$ to $L_{k+1}$.
In Steps 3 and 5, we orient each unmatched edge from $L$ to $R$ and each matched edge from $R$ to $L$.
It is not hard to verify that the above modifications do not affect the correctness of the framework, because each short augmenting walk is still preserved in $\cL$ with probability $1/ \exp(O(2k))$.
With this modification, for each layer $L_i$, all vertices in $H_i$ are from $L$ and all vertices in $T_{i+1}$ are from $R$.
Hence, to find a $b$-matching between $H_i$ and $T_{i+1}$, we can invoke a constant approximation algorithm for the allocation problem.

