\begin{align}
    \boldsymbol{\mathcal{G}}^1_{x, i} &\triangleq \mbox{col} \Big\{\widehat{\nabla_x J}_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}) \vphantom{\sum} \Big\}{}_{\vphantom{A^A} k=1}^{K_1}\label{eq:G1xi} \\
    % \boldsymbol{\mathcal{G}}^2_{x, i} &\triangleq \mbox{col} \{ - \widehat{\nabla_x} J_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1})\}_{k=K_1+1}^{K} \\
    % \boldsymbol{\mathcal{G}}^2_{y, i} &\triangleq \mbox{col} \{\widehat{\nabla_y} J_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1})\}_{k=K_1+1}^{K} \\
    \boldsymbol{\mathcal{G}}^1_{y, i} &\triangleq \mbox{col} \Big\{- \widehat{\nabla_y J}_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1})\Big\}{}_{\vphantom{A^A} k=1}^{K_1}\label{eq:G1yi}
\end{align} 
where $\widehat{\nabla_x J}_k (\cdot, \cdot)$ and $\widehat{\nabla_y J}_k (\cdot, \cdot)$ are stochastic gradients associated with $x$ and $y$ at agent $k$;
$\boldsymbol{\mathcal{G}}^2_{x, i}$ and $\boldsymbol{\mathcal{G}}^2_{y, i}$ are defined similarly. 
Finally, the augmented combination matrices are defined as follows:
\begin{align}
    \mathcal{C}^{(1)} &= C^{(1)} \otimes I_{M_2}, \quad 
    &\mathcal{C}^{(2)} &= C^{(2)} \otimes I_{M_1} \notag \\
    \mathcal{C}^{(21)} &= C^{(21)} \otimes I_{M_2}, \quad 
    &\mathcal{C}^{(12)} &= C^{(12)} \otimes I_{M_1} \notag \\    \mathcal{A}^{(1)} &= A^{(1)} \otimes I_{M_1}, \quad 
    &\mathcal{A}^{(2)} &= A^{(2)} \otimes I_{M_2}
\end{align}
With the notation so defined, we summarize the preceding procedures in \textbf{Algorithm \ref{alg:network_learning_zerosum}}.

\begin{algorithm}
\caption{
\textbf{A}dapt-then-\textbf{C}ombine and \textbf{I}nfer-then-\textbf{C}ombine (\textbf{ATC-ITC}) algorithm}  \label{alg:network_learning_zerosum}
\begin{algorithmic}[1]
\STATE \textbf{Initialize:} strategies $\boldsymbol{\mathcal{X}}^1_{-1},  \boldsymbol{\mathcal{Y}}^1_{-1},  \boldsymbol{\mathcal{X}}^2_{-1}, \boldsymbol{\mathcal{Y}}^2_{-1} \leftarrow 0$, step size $\mu$

\FOR{$i = 0,\cdots$}
\STATE \underline{\texttt{Within-team adapt-then-combine} }\\$\boldsymbol{\mathcal{X}}^1_{i} = {\mathcal{A}^{(1)}}^{\top} \left(\boldsymbol{\mathcal{X}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{x, i} \right)$\\ $\boldsymbol{\mathcal{Y}}^2_{i} = {\mathcal{A}^{(2)}}^{\top} (\boldsymbol{\mathcal{Y}}^2_{i-1} - \mu \boldsymbol{\mathcal{G}}^2_{y, i} )$

\STATE \underline{\texttt{Cross-team infer-then-combine}}

\STATE $\boldsymbol{\mathcal{\psi}}^1_{i} = \boldsymbol{\mathcal{Y}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{y, i}$
\vspace{0.2em}
\STATE $\boldsymbol{\mathcal{\psi}}^2_{i} = \boldsymbol{\mathcal{X}}^2_{i-1} - \mu \boldsymbol{\mathcal{G}}^2_{x, i}$

\STATE $\boldsymbol{\mathcal{Y}}^1_{i} = {\mathcal{C}^{(21)}}^{\top} \boldsymbol{\mathcal{Y}}^2_{i} + {\mathcal{C}^{(1)}}^{\top} \boldsymbol{\mathcal{\psi}}^1_{i}$

\STATE$\boldsymbol{\mathcal{X}}^2_{i} = {\mathcal{C}^{(12)}}^{\top} \boldsymbol{\mathcal{X}}_{i}^1 + {\mathcal{C}^{(2)}}^{\top} \boldsymbol{\mathcal{\psi}}^2_{i}$
\ENDFOR
\end{algorithmic}
\end{algorithm}

\textbf{General network-game under a strong cross-team subgraph}:
For a general game $J^{(1)} \left(x, y\right) \not = J^{(2)} \left(x, y\right)$,
the estimation  procedure in 
recursion
\eqref{eq:psi_update} may not yield accurate results since $\left\| \nabla_y J_k \left(x, y\right) + \nabla_y J^{(2)} \left(x, y\right)\right\|$
can be large.
However,  competition is still possible when a strong cross-team subgraph is present. In this scenario, agents can observe the adversary strategy by directly combining neighboring opponents' information. Since now $C^{(1)} = C^{(2)} = 0$, agent $k$ fuses Team 2's information as follows:
\begin{align}
\boldsymbol{y}_{k, i} = \sum_{\ell \in \mathcal{N}^{(2)}} c_{\ell k}  \boldsymbol{y}_{\ell, i}
\label{cross_tema_learn}
\end{align} 
The above step is the only change compared to \textbf{Algorithm 1}.
Using the notation from 
\eqref{eq:X1i}-\eqref{eq:G1xi} for Team 1 and the same notation for Team 2,
we summarize the new procedure 
in \textbf{Algorithm 2}
and we name it 
\textbf{A}dapt-then-\textbf{C}ombine and \textbf{C}ombine (\textbf{ATC-C}).
In this setup, each agent accesses the latest adversarial information and computes the stochastic gradient only once per iteration, reducing computational costs and improving efficiency.
