% \begin{remark}
%     Without the constraint of zero-sum, \eqref{eq:y_update} no longer provides a valid approximation of Team 2's strategy because $- \nabla_y J_k \left(x, y\right)$ and $\nabla_y J^{(2)} \left(x, y\right)$ may differ significantly. Thus, although it is possible to implement Algorithm \ref{alg:network_learning_zerosum} when a denser cross-team subgraph is present, convergence is not guaranteed for the nonzero-sum cases.
% \end{remark}


\begin{algorithm}
\caption{\textbf{A}dapt-then-\textbf{C}ombine and \textbf{C}ombine (\textbf{ATC-C})} \label{alg:network_learning_general_strong}
\begin{algorithmic}[1]
\STATE \textbf{Initialize:} $i$=0, actions $\boldsymbol{\mathcal{X}}_{-1}, \boldsymbol{\mathcal{Y}}_{-1} \leftarrow 0$, step size $\mu$

\WHILE{not done}
    \STATE \underline{\texttt{Within-team adapt-then-combine}} \\$\boldsymbol{\mathcal{X}}^1_{i} = {\mathcal{A}^{(1)}}^{\top} (\boldsymbol{\mathcal{X}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{x, i})$\\ $\boldsymbol{\mathcal{Y}}^2_{i} = {\mathcal{A}^{(2)}}^{\top} (\boldsymbol{\mathcal{Y}}^2_{i-1} - \mu \boldsymbol{\mathcal{G}}^2_{y, i})$

    \STATE \underline{\texttt{Cross-team combine}}\\ $\boldsymbol{\mathcal{Y}}^1_{i} = {\mathcal{C}^{(21)}}^{\top} \boldsymbol{\mathcal{Y}}^2_{i}$\\
    $\boldsymbol{\mathcal{X}}^2_{i} = {\mathcal{C}^{(12)}}^{\top} \boldsymbol{\mathcal{X}}^1_{i}$
    \STATE $i \gets i + 1$
\ENDWHILE
\end{algorithmic}
\end{algorithm}

\begin{remark*}
     Both {\bf ATC-ITC} and {\bf ATC-C} can solve zero-sum network-games under strong cross-team subgraphs since every strong cross-team subgraph is also a weak one, and general network games encompass zero-sum network games. General network-games under weak cross-team subgraphs can be addressed by {\bf ATC-ITC}, assuming partially observable stochastic gradients (see Assumption~\ref{ass:add_grad} and Corollary~\ref{corollary:ATC-ETC}). 
\end{remark*}

