\section{Convergence Analysis}
In this section, we conduct a stability performance analysis for the proposed algorithms. To support the theoretical analysis, we introduce several mild assumptions that are commonly used in the literature on distributed learning. Our objective is to provide convergence guarantees, ensuring that the algorithms converge to a Nash equilibrium at which both networks achieve an equilibrium state.
The notion of a Nash equilibrium is defined as follows.
 \begin{definition}[\textbf{Nash equilibrium}]
  A point $(x^\star, y^\star)$ is a Nash equilibrium if the following condition holds
\begin{equation}
    J^{(1)}(x^\star, y^\star) \leq J^{(1)}(x, y^\star), \; J^{(2)}(x^\star, y^\star) \leq J^{(2)}(x^\star, y)
\end{equation}  
\end{definition}
\subsection{Assumptions}

We introduce assumptions regarding the structural properties of the combination matrices $A^{(1)}$, $A^{(2)}$ and the  inference matrix $C$, and conditions related to the cost function.

\begin{assumption}[\textbf{Within-team combination matrix}] 
\label{ass:within_conn}
    For $t \in \{1,2\}$, the combination matrix $A^{(t)} \in \mathbb{R}^{K_t \times K_t}$ is primitive and left-stochastic, i.e. $\mathbbm{1}^{\top} A^{(t)} = \mathbbm{1}^{\top}$. \hfill\qed
\end{assumption}
The above assumption is standard in distributed optimization to guarantee consensus among agents\cite{sayed2022inference1}.
According to \cite{sayed2014adaptation}, 
$A^{(1)}$ and $A^{(2)}$ have Perron eigenvectors $p^{(1)}$ and $p^{(2)}$, with positive entries that satisfy $A^{(1)}p^{(1)} = p^{(1)}$,  $A^{(2)}p^{(2)} = p^{(2)}$, and $\mathbbm{1}_{K_1}^{\top} p^{(1)}= \mathbbm{1}_{K_2}^{\top} p^{(2)} = 1$. We denote 
\begin{equation}
    p \triangleq \left[\begin{array}{c}p^{(1)}  \\p^{(2)} \end{array}\right]
\end{equation}
where the $\{p_k\}_{k=1}^{K_1}$ and $\{p_k\}_{k=K_1 +1}^{K}$ correspond to the coefficients used in \eqref{eq:global_game_ya} and \eqref{eq:global_game_yb}, respectively.

% For the convenience of analysis, we define $\mathcal{V}_{L} \triangleq V_{L} \otimes I_{M_1}, \mathcal{J}_{\varepsilon} \triangleq J_{\varepsilon} \otimes I_{M_1}, \mathcal{V}_{R} \triangleq V_{R} \otimes I_{M_1}$, where $\otimes$ denotes the Kronecker product operator. Similar constructions apply to .

For the inference matrix $C$, we consider the following assumption.


\begin{assumption}[\textbf{Cross-team  inference matrix}] \label{ass:cross-conn}
The inference matrix $C$ is partitioned into blocks  $
[C^{(1)}, C^{(12)}; C^{(21)}, C^{(2)}]$
and satisfies either one of the following conditions depending on whether we are dealing with a weak (case (b)) or strong (case (a)) cross-team subgraph:  
\begin{enumerate}[label=(\alph*), ref=\theassumption\alph*]  % (2a), (2b) style
    \item \label{ass:cross-conn_strong} For every $t \in \{1,2\}$, the diagonal blocks satisfy $C^{(t)} = 0$. Moreover, for any $t, t^{\prime} \in \{1,2\}, t \neq t^{\prime}$, the off-diagonal block
    $C^{(t^{\prime} t)} \in \mathbb{R}^{K_{t^{\prime}} \times K_t}$ is left-stochastic, i.e.,  $
    \mathbbm{1}^{\top} C^{(t^{\prime} t)} = \mathbbm{1}^{\top}.$

    \item \label{ass:cross-conn_weak} $C$ is left-stochastic, and for every $t \in \{1,2\}$, the diagonal block matrices $C^{(t)}$ are irreducible. Moreover, for $t, t^{\prime} \in \{1,2\}, t \neq t^{\prime}$, there exists at least one $k \in \mathcal{N}^{(t)}$ and $\ell \in \mathcal{N}^{(t^{\prime})}$ such that $c_{\ell k} > 0$.
\end{enumerate}
\hfill\qed
\end{assumption}


