For convenience of analysis,
we define the following concatenated {\color{black} gradient} vectors:
\begin{align} 
    F(z) &\triangleq \left[\begin{array}{c}
    \nabla_x J^{(1)} \left(x, y\right) \\
    \nabla_y J^{(2)} \left(x, y\right) 
\end{array}\right],
\text{ where }     z \triangleq \left[\begin{array}{c} x \\ y \end{array}\right]\label{eq:Fz_defn}
\end{align}
This gradient mapping $F(z)$ captures the gradients of each team's global cost function with respect to its own strategy, and is commonly used in the context of game theory \cite{zimmermann2021solving, pang2023distributed}.
\begin{assumption}[\textbf{Strong monotonicity}]
\label{ass:strong mono}
    The global gradient operator \( F(z) \) is \(\nu\)-strongly monotone, i.e., for every $z_1, z_2 \in \mathbb{R}^{M}$, we have 
    \begin{equation}
        \left(F\left(z_1\right) - F\left(z_2\right)\right)^\top \left(z_1 - z_2\right) \geq \nu \|z_1 - z_2\|^2
        \label{strongmonotone}
    \end{equation}
for a positive constant $\nu$.
\hfill\qed%
\end{assumption}
Assumption \ref{ass:strong mono} is commonly used in the context of the variational inequality \cite{komlosi1999stampacchia, ryu2016primer}.  Condition \eqref{strongmonotone} generalizes the setup of
strongly-convex strongly-concave minmax problems. 


\begin{assumption}[\textbf{Lipschitz gradients}]
\label{ass:lip}
    For each $t \in \{1,2\}$ and $k \in \mathcal{N}^{(t)}$, we assume the gradients associated with each local risk function $J_k (\cdot, \cdot)$ are $L_f$-Lipschitz, i.e, for any $x_1, x_2 \in \mathbb{R}^{M_1}, y_1, y_2 \in \mathbb{R}^{M_2}$:
    \begin{equation}
    \label{eq:lip}
        \begin{aligned}
            &\| \nabla_w J_k (x_1, y_1) - \nabla_w J_k (x_2, y_2)\|\\
            & \leq L_f \left(\|x_1 - x_2\| + \|y_1 - y_2\|\right),
        \end{aligned}
    \end{equation}
    where  $w = x \text{ or } y$.\hfill\qed
\end{assumption}

\begin{assumption}[\textbf{Bounded gradient disagreement}]
\label{ass:bdis}
    For each $t \in \{1,2\}$ \textcolor{black}{and $k \in \mathcal{N}^{(t)}$,} the gradient disagreement between the local risk functions and the global risk function is bounded, i.e., for any $x_1 \in \mathbb{R}^{M_1}, y_1 \in \mathbb{R}^{M_2}$:
    \begin{equation}
    \label{eq:bdis}
        \| \nabla_w J_k (x_1, y_1) - \nabla_w J^{(t)} (x_1, y_1)\| \leq G
    \end{equation}
    where  $w = x \text{ or } y$.\hfill\qed
\end{assumption}

\begin{assumption}[\textbf{Gradient noise process}]
\label{ass:gradnoise}
    We define the filtration generated by the random processes as $\boldsymbol{\mathcal{F}}_i = \{(\boldsymbol{x}_{k, j}, \boldsymbol{y}_{k, j}) \mid k = 1, \dots, K, j = -1,\dots, i \}.$ For each $t \in \{1,2\}$ and $k \in \mathcal{N}^{(t)}$, we assume the stochastic gradients are unbiased with bounded variance conditioned on $\boldsymbol{\mathcal{F}}_i$, i.e., for any $\boldsymbol{x}, \boldsymbol{y} \in \boldsymbol{\mathcal{F}}_i$, 
    % \begin{align}
    %     &\mathbb{E} \{ \widehat{\nabla_w} J^{(t)}_k (\boldsymbol{x}, \boldsymbol{y}) \mid \boldsymbol{\mathcal{F}}_i\} = \nabla_w J^{(t)}_k (\boldsymbol{x}, \boldsymbol{y}) \\
    %     &\mathbb{E} \{ \| \widehat{\nabla_w} J^{(t)}_k (\boldsymbol{x}, \boldsymbol{y}) - \nabla_w J^{(t)}_k (\boldsymbol{x}, \boldsymbol{y}) \|^2 \mid \boldsymbol{\mathcal{F}}_i \} \leq \sigma^2
    % \end{align}
    \textcolor{black}{
    \begin{equation}
    \label{eq:unbiased}
        \mathbb{E} \{ \widehat{\nabla_w J}_k (\boldsymbol{x}, \boldsymbol{y}) \mid \boldsymbol{\mathcal{F}}_i\} = \nabla_w J_k (\boldsymbol{x}, \boldsymbol{y})
    \end{equation}
    \begin{equation}
    \label{eq:b_var}
        \mathbb{E} \{ \| \widehat{\nabla_w J}_k (\boldsymbol{x}, \boldsymbol{y}) - \nabla_w J_k (\boldsymbol{x}, \boldsymbol{y}) \|^2 \mid \boldsymbol{\mathcal{F}}_i \} \leq \sigma^2
    \end{equation}
    }
    where  $w = x \text{ or } y$.\hfill\qed
\end{assumption}
Note that similar gradient assumptions are also adopted in distributed stochastic optimization works such as \cite{vlaski2021distributed, cai2024diffusion}.

\subsection{Main Results}



