%     \end{align} Furthermore, \cite[Theorem 2.3.3]{facchinei2003finite} guarantees the existence of a unique solution $z^\star$ to \eqref{stampcchia} under the strong monotonicity condition \eqref{strongmonotone}. Thus, the proof is complete.
% \end{proof}

Before presenting the main results, we introduce the following notation: 
\begin{align}
    \boldsymbol{x}_{c,i} &\triangleq  \sum_{k \in \mathcal{N}^{(1)}} p_k \boldsymbol{x}_{k,i}, \quad &\boldsymbol{y}_{c,i} &\triangleq  \sum_{k \in \mathcal{N}^{(2)}} p_k \boldsymbol{y}_{k,i}\label{eq:centroid_x}  \\ \boldsymbol{\mathcal{X}}_{c,i} &\triangleq \mathbbm{1}_{K_1} \otimes \boldsymbol{x}_{c,i}, \quad &\boldsymbol{\mathcal{Y}}_{c,i} &\triangleq \mathbbm{1}_{K_2} \otimes \boldsymbol{y}_{c,i}\\
    \boldsymbol{\mathcal{X}}^{\prime}_{c,i} &\triangleq \mathbbm{1}_{K_2} \otimes \boldsymbol{x}_{c,i}, \quad &\boldsymbol{\mathcal{Y}}^{\prime}_{c,i} &\triangleq \mathbbm{1}_{K_1} \otimes \boldsymbol{y}_{c,i} \label{eq:centroid_network_x} 
\end{align}
By taking the weighted average of the strategies within each team, we define the variables $\boldsymbol{x}_{c,i}$ and $\boldsymbol{y}_{c,i}$ as the centroid strategies for Teams 1 and 2, respectively. The variable $\boldsymbol{\cal X}_{c,i}$ is a repeated copy of $\boldsymbol{x}_{c,i}$ and has the same dimension as Team 1’s networked strategy $\boldsymbol{\cal X}^1_{i}$, while $\boldsymbol{\cal X}^\prime_{c,i}$ matches the size  of Team 2's inferred strategy $\boldsymbol{\cal X}^2_{i}$. The quantities $\boldsymbol{\mathcal{Y}}_{c,i}$, $\boldsymbol{\cal Y}^\prime_{c,i}$ are defined in a similar way. These variables are introduced solely to support our analysis and do not appear in the proposed algorithms. For both algorithms, we can establish the following recursion for 
$\boldsymbol{\mathcal{X}}_{c,i}$:
\begin{align}
\label{eq:centroid_X_evolution}
\boldsymbol{\mathcal{X}}_{c,i} &= \mathbbm{1}_{K_1} \otimes \boldsymbol{x}_{c,i} = \left(\mathbbm{1}_{K_1} {p^{(1)}}^{\top} \otimes I_{M_1}\right) \boldsymbol{\mathcal{X}}^1_{i} \notag \\
    &= \left(\mathbbm{1}_{K_1} {p^{(1)}}^{\top} \otimes I_{M_1}\right) {\mathcal{A}^{(1)}}^{\top} \left(\boldsymbol{\mathcal{X}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{x, i} \right) \notag \\
    &= \left(\mathbbm{1}_{K_1} {p^{(1)}}^{\top} \otimes I_{M_1}\right) \left(\boldsymbol{\mathcal{X}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{x, i} \right) \notag \\
    &= \boldsymbol{\mathcal{X}}_{c,i-1} - \mu \left(\mathbbm{1}_{K_1} {p^{(1)}}^{\top} \otimes I_{M_1}\right)\boldsymbol{\mathcal{G}}^1_{x, i}
\end{align}
The above relation indicates that the network centroid $\boldsymbol{x}_{c,i}$
is updated through the following recursion
\begin{equation}
\label{eq:centroid_x_evolution}
    \boldsymbol{x}_{c,i} = \boldsymbol{x}_{c,i-1} - \mu \sum_{k \in \mathcal{N}^{(1)}} p_k \widehat{\nabla_x J}_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1})
\end{equation}
% Utilizing the clustering results and the properties of the objective functions, we will demonstrate that the network centroids act as global representatives of each team's actions. The evolution of these centroids can be viewed as equivalent to a classical two-player gradient descent process  (\ref{eq:centralized_x})-(\ref{eq:centralized_y}) but with a small perturbation of size $O(\mu^2)$ at each iteration (see Lemma \ref{lemma:learning_dynamics}). 
The recursion in \eqref{eq:centroid_x_evolution} is used for our convergence analysis of \textbf{ATC-ITC} and \textbf{ATC-C} since the local models of each team will converge to a neighborhood around their corresponding network centroid. In other words, the network centroid $\boldsymbol{x}_{c,i}$ acts as a ``proxy" for studying the network behavior. 

% Therefore, we can focus on proving the convergence of $\boldsymbol{x}_{c,i}$ and on 
% bounding the deviation of local models from this centroid.

\begin{lemma}
[{\bf Within-team and cross-team consensus}]
\label{lemma:zerosum_within_cross}
Let
Assumptions  \ref{ass:within_conn}, \ref{ass:cross-conn_weak},  \ref{ass:lip}, \ref{ass:bdis}, \ref{ass:gradnoise}
hold for \textbf{ATC-ITC} under zero-sum objectives \eqref{eq:zero-sum},
and
Assumptions \ref{ass:within_conn}, \ref{ass:cross-conn_strong}, \ref{ass:lip}, \ref{ass:bdis}, \ref{ass:gradnoise} hold for 
\textbf{ATC-C}.
The iterates 
$\boldsymbol{\mathcal{X}}^1_{i}$,$\boldsymbol{\mathcal{Y}}^2_{i}$, and the inferred adversary iterates 
$\boldsymbol{\mathcal{Y}}^1_{i}$, $\boldsymbol{\mathcal{X}}^2_{i}$ of both teams, 
cluster within $\mathcal{O}(\mu^2)$ around the corresponding
$\boldsymbol{x}_{c,i}$
and $\boldsymbol{y}_{c,i}$, namely,
 \begin{equation}
        \begin{aligned}
            &\mathbb{E} \{\|\boldsymbol{\mathcal{X}}^1_{i} - \boldsymbol{\mathcal{X}}_{c,i}\|^2 + \|\boldsymbol{\mathcal{Y}}^2_{i} - \boldsymbol{\mathcal{Y}}_{c,i}\|^2 \\
            &\quad + \|\boldsymbol{\mathcal{X}}^2_{i} - \boldsymbol{\mathcal{X}}^\prime_{c,i}\|^2 + \|\boldsymbol{\mathcal{Y}}^1_{i} - \boldsymbol{\mathcal{Y}}^\prime_{c,i}\|^2\} \leq O\left(\mu^2\right) 
        \end{aligned}
    \end{equation}
    when the step size $\mu$ is sufficiently small and after sufficient iterations (i.e., $i \geq i_\alpha$ for \textbf{ATC-ITC}, $i \geq i_\beta$ for \textbf{ATC-C}), where
    \begin{align}
        i_\alpha &=  \frac{\log \left(O\left(\mu^2\right)\right)}{\log \left(\alpha\right)} \\
        i_\beta &=  \frac{\log \left(O\left(\mu^2\right)\right)}{\log \left(\beta\right)}
    \end{align}
      and $\alpha < 1$ and $\beta < 1$ are constants depending on $A^{(1)}, A^{(2)}$, and $C$.
     \hfill\qed 
\end{lemma}

\begin{proof}
    The proof can be found in
      Appendix \ref{proof:lemma2_atcetc} for \textbf{ATC-ITC} and Appendix \ref{proof:lemma2_atcc} for \textbf{ATC-C}.
\end{proof}
 Lemma \ref{lemma:zerosum_within_cross} shows that each team’s local strategies cluster around its own network centroid, while each team’s inferred strategies cluster around the opposing team's network centroid. With a sufficiently small step size, the deviations from the centroids remain small, thereby justifying the use of the network centroids
$\boldsymbol{x}_{c,i}$ and $ \boldsymbol{y}_{c,i}$
as reliable proxies for decision-making.
Regarding the recursion of $\boldsymbol{z}_{c, i} = [\boldsymbol{x}_{c,i};\boldsymbol{y}_{c,i}]$, we present the following lemma, which characterizes the learning dynamics of the network centroid after sufficiently large iterations.
\begin{lemma}[{\bf Learning dynamics}]
\label{lemma:zerosum_learning_dynamic}
Let
Assumptions  \ref{ass:within_conn}, \ref{ass:cross-conn_weak}, \ref{ass:lip}, \ref{ass:bdis}, \ref{ass:gradnoise}
hold for \textbf{ATC-ITC} under zero-sum objectives \eqref{eq:zero-sum},
and
Assumptions \ref{ass:within_conn}, \ref{ass:cross-conn_strong}, \ref{ass:lip}, \ref{ass:bdis}, \ref{ass:gradnoise} hold for 
\textbf{ATC-C}. The 
centroid $\boldsymbol{z}_{c,i} = [\boldsymbol{x}_{c,i}; \boldsymbol{y}_{c,i}]$ 
follows the following dynamics 
\begin{equation}
        \boldsymbol{z}_{c,i} = \boldsymbol{z}_{c,i-1} - \mu F(\boldsymbol{z}_{c-1,i}) + \boldsymbol{d}_{c,i}
    \end{equation}  
    where the noisy term $\mathbb{E} \{\|\boldsymbol{d}_{c,i}\|^2\} \leq O(\mu^2)$,
for 
sufficiently small
$\mu$ 
 and sufficient iterations
i.e., $i \geq i_\alpha$ for \textbf{ATC-ITC}, $i \geq i_\beta$ for \textbf{ATC-C}.\hfill\qed
\end{lemma}

The proof of Lemma \ref{lemma:zerosum_learning_dynamic} is given in Appendix \ref{proof:lemma3}. The lemma  characterizes the long-term behavior of 
$\boldsymbol{z}_{c,i}$, showing that it approximately follows a gradient descent trajectory with an added random perturbation proportional to $\mathcal{O}(\mu^2)$. Note that Lemmas \ref{lemma:zerosum_within_cross} and \ref{lemma:zerosum_learning_dynamic} hold without requiring the assumption of strong monotonicity.

\begin{theorem}[{\bf Mean-square-error stability}]
\label{thm:zerosum_conv}
Let
Assumptions  \ref{ass:within_conn}, \ref{ass:cross-conn_weak},  \ref{ass:strong mono}, \ref{ass:lip}, \ref{ass:bdis}, \ref{ass:gradnoise}
hold for \textbf{ATC-ITC} under zero-sum objectives \eqref{eq:zero-sum},
and
Assumptions \ref{ass:within_conn}, \ref{ass:cross-conn_strong}, \ref{ass:strong mono}, \ref{ass:lip}, \ref{ass:bdis}, \ref{ass:gradnoise} hold for 
\textbf{ATC-C}.
The mean square error
decays at the following 
form for 
sufficiently small
$\mu$ 
 and sufficient iterations
(i.e., $i \geq i_\alpha$ for \textbf{ATC-ITC}, $i \geq i_\beta$ for \textbf{ATC-C}):
\begin{equation}
    \mathbb{E} \left[\|\boldsymbol{z}_{c,i} - z^\star\|^2\right] \leq 
    d \, \mathbb{E}\left[\|\boldsymbol{z}_{c,i-1} - z^\star\|^2\right] + O\left(\mu^2\right)
\end{equation}
where $d < 1$ is a constant depending on $\mu, \nu$, and $L_f$.
Furthermore,
the centroid $\boldsymbol{z}_{c,i}$ asymptotically converges to 
the Nash equilibrium $\boldsymbol{z}^\star$ 
in the mean-square-error sense
    \begin{equation}
        \limsup_{i \rightarrow \infty} \mathbb{E}\{\|\boldsymbol{z}_{c,i} - z^{\star}\|^2\} \leq O(\mu)
    \end{equation}
for sufficiently small step size $\mu$. \hfill\qed
\end{theorem}

The
proof of Theorem \ref{thm:zerosum_conv} can be found in Appendix \ref{proof:thm1}. From Lemma \ref{lemma:zerosum_within_cross}, each $\boldsymbol{z}_{k,i} = [\boldsymbol{x}_{k,i}; \boldsymbol{y}_{k,i}]$ moves towards the network centroids $\boldsymbol{z}_{c,i}$. Using the results of Theorem \ref{thm:zerosum_conv}, we conclude that $\forall k \in \mathcal{N}$,
\begin{equation}
    \limsup_{i \rightarrow \infty} \mathbb{E}\{\|\boldsymbol{z}_{k,i} - z^{\star}\|^2\} \leq O(\mu)
\end{equation}

\begin{remark*}
Although \textbf{ATC-ITC} is primarily concerned with a zero-sum network-game under weak cross-team subgraphs, we argue that it can be extended to the general game setting (i.e., nonzero sum games). 
This holds 
when 
each agent $k \in \mathcal{N}^{(1)}$ has access to a stochastic gradient, say
$\widehat{\nabla_y J}{}_k^{(2)}(\cdot,\cdot)$ which can approximate $\nabla_y J^{(2)}(\cdot,\cdot)$. For example, a natural choice could be any $\widehat{\nabla_y J}_\ell(\cdot,\cdot), \ell \in \mathcal{N}^{(2)}$ from Team 2.
This assumption is reasonable in practical scenarios where competitors have partial knowledge of how their opponents compute their costs. Such situations arise in strategic interactions where cost structures are partially transparent due to industry norms, regulatory requirements, or shared market intelligence.
\end{remark*}

\begin{assumption}[\textbf{Partially observable  stochastic gradient}]
\label{ass:add_grad}
    For $t, t^{\prime} \in \{1,2\}, t \neq t^{\prime}$, each agent $k \in \mathcal{N}^{(t)}$ has access to an additional stochastic gradient $\widehat{\nabla_{w^{(t)}} J}{}^{(t^{\prime})}_k\left(\cdot, \cdot\right)$, where $w^{(1)} = y$ and $ w^{(2)} = x$. The expectation equals to $\nabla_{w^{(t)}} J^{(t^{\prime})}_k (\boldsymbol{x}, \boldsymbol{y})$ conditioned on $\boldsymbol{\mathcal{F}}_i$ similar to \eqref{eq:unbiased}, with bounded gradient noise similar to \eqref{eq:b_var}. The $\nabla_{w^{(t)}} J^{(t^{\prime})}_k (\boldsymbol{x}, \boldsymbol{y})$ also has bounded gradient disagreement and is Lipschitz similar to \eqref{eq:bdis} and \eqref{eq:lip}.
    \hfill\qed
\end{assumption}

% This assumption implies, each agent $k \in \mathcal{N}^{(1)}$ has access to a stochastic gradient $\widehat{\nabla_y} J^{(2)}_k$ which approximates $\nabla_y J^{(2)}$ closely and has a Lipschitz expectation. A natural fit for $\widehat{\nabla_y} J^{(2)}_k$ could be any of $\widehat{\nabla_y} J_r, \forall r \in \mathcal{N}^{(2)}$, and this assumption also allows other possibilities.
% % A natural fit could be any stochastic gradients of Team 2 agents, but this assumption also allows other possibilities.
% Similarly, an additional $\widehat{\nabla_x} J^{(1)}_k$ is available for each agent $k \in \mathcal{N}^{(2)}$. 




\begin{corollary}
\label{corollary:ATC-ETC}
     Under Assumption \ref{ass:add_grad}, replacing the Inference step in \eqref{eq:psi_update} with 
    % \begin{equation}
    % \label{eq:new_cross_predict}
    %     \boldsymbol{\psi}_{k,i} = \boldsymbol{y}_{k,i-1} - \mu \widehat{\nabla_y} J^{(2)}_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}) 
    % \end{equation}
    \begin{equation}
    \label{eq:new_cross_predict}
        \boldsymbol{\psi}_{k,i} = \boldsymbol{y}_{k,i-1} - \mu \widehat{\nabla_y J}{}^{(2)}_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}) 
    \end{equation}
    ensures that Lemmas \ref{lemma:zerosum_within_cross} and \ref{lemma:zerosum_learning_dynamic}, as well as Theorem \ref{thm:zerosum_conv}, remain valid for \textbf{ATC-ITC}.
\end{corollary}
\begin{proof}
\label{proof:corollary}
The proof follows by substituting the stochastic gradient in  
$\boldsymbol{\mathcal{G}}^2_{x, i}$ with  
\[
\mbox{col} \left\{\widehat{\nabla_x J}{}^{(1)}_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1})\right\}\!{}_{\vphantom{A^{[]}}k=K_1+1}^{K}
\]
and applying the same modification to  
$\boldsymbol{\mathcal{G}}^1_{y, i}$. The steps in Lemmas \ref{lemma:zerosum_within_cross} and \ref{lemma:zerosum_learning_dynamic}, as well as Theorem \ref{thm:zerosum_conv}, then proceed identically. 
\end{proof}

