\section{Proof of Lemma \ref{lemma:zerosum_within_cross} for \textbf{ATC-ITC}} 
\label{proof:lemma2_atcetc}
In this section, we present the proof of Lemma \ref{lemma:zerosum_within_cross} when running the \textbf{ATC-ITC} algorithm. 
\vspace{-0.5em}
\subsection{Key Lemmas}
Let us define $B^{(x)} \in \mathbb{R}^{K \times K}$ and $B^{(y)} \in \mathbb{R}^{K \times K}$ as follows:
\begin{equation}
    \!\!\!\!B^{(x)} \triangleq 
    \begin{bmatrix}
    {A}^{(1)} & A^{(1)} C^{(12)}\\
    0 & {C^{(2)}} 
\end{bmatrix}, B^{(y)} \triangleq 
    \begin{bmatrix}
    {A}^{(2)} & A^{(2)} C^{(21)}\\
    0 & {C^{(1)}} 
\end{bmatrix}
\end{equation}

\begin{lemma} \label{lemma:BxBy}
Under Assumptions \ref{ass:within_conn}, \ref{ass:cross-conn_weak}, the matrices $B^{(x)}$ and $B^{(y)}$ satisfy the following properties:
\begin{enumerate}[label=(\arabic*), ref=\thelemma(\arabic*)]
    \item \label{lemma:Bx_left} $B^{(x)}$ and $B^{(y)}$ are left-stochastic.
    \item \label{lemma:Bx_simple} 
     For both matrices $B^{(x)}$ and $B^{(y)}$,
 $1$ is the associated eigenvalue which is unique, simple, and largest in magnitude.
    \item \label{lemma:Bx-vector} There exists a unique eigenvector (up to scaling factor) associated with the eigenvalue $1$
    for each matrix, i.e., 
    \begin{equation} \label{eq:eigenvectors}
        p^{(x)} \triangleq \begin{bmatrix}
            p^{(1)} \\
            0
        \end{bmatrix}, \quad 
        p^{(y)} \triangleq \begin{bmatrix}
            p^{(2)} \\
            0
        \end{bmatrix}
    \end{equation}
    where $p^{(x)}$ and $p^{(y)} \in \mathbb{R}^{K \times 1}$ are the eigenvectors of $B^{(x)}$ and $B^{(y)}$, respectively. \hfill\qed
\end{enumerate}
\end{lemma}

\begin{proof}
    \label{proof:matrix}
    We show our proof for $B^{(x)}$; the proof for $B^{(y)}$ follows a similar argument.

    \begin{enumerate}[label=(\arabic*)]
    \item  The left-stochastic property can be verified via
    \begin{equation}
    \begin{aligned}
        \mathbbm{1}_{K}^{\top} B^{(x)} & = \begin{bmatrix}
            \mathbbm{1}_{K_1}^{\top} {A}^{(1)} + \mathbbm{1}_{K_2}^{\top} 0 & \mathbbm{1}_{K_1}^{\top} A^{(1)} C^{(12)} + \mathbbm{1}_{K_2}^{\top} {C^{(2)}}
        \end{bmatrix}\\
        & \stackrel{(a)}{=}
        \begin{bmatrix}
            \mathbbm{1}_{K_1}^{\top} & \mathbbm{1}_{K_1}^{\top} C^{(12)} + \mathbbm{1}_{K_2}^{\top} {C^{(2)}}
        \end{bmatrix}\\
        & \stackrel{(b)}{=}
        \mathbbm{1}^{\top}_{K}
    \end{aligned}
    \end{equation}
    where $(a)$ follows from Assumption \ref{ass:within_conn}; $(b)$ follows from Assumption \ref{ass:cross-conn_weak}.

    \item According to \cite{ying2016information}, Assumption \ref{ass:cross-conn_weak} ensures that $\rho\left({C^{(2)}}\right) < 1$, while Assumption \ref{ass:within_conn} guarantees that  1 is the unique eigenvalue on the spectral circle of $A^{(1)}$ and is simple (i.e., multiplicity equal to one). Since $B^{(x)}$ has a block upper-triangular structure, its largest eigenvalue is also 1, and this eigenvalue is simple, with all other eigenvalues having absolute values less than 1 (i.e., $1 > |\lambda_2(B^{(x)})| \geq |\lambda_3(B^{(x)})| \cdots$).

    \item The corresponding unique eigenvector (up to scaling) for the eigenvalue 1 is
    \begin{equation}
        p^{(x)} \triangleq \begin{bmatrix}
            p^{(1)} \\
            0
        \end{bmatrix} \in \mathbb{R}^{K \times 1}
        \label{eq:px_defn}
    \end{equation}
    which satisfies
    \begin{equation}
    \begin{aligned}
        B^{(x)} p^{(x)} &= \begin{bmatrix}
            {A}^{(1)} p^{(1)} + A^{(1)} C^{(12)} 0 \\
            0 p^{(1)} + {C^{(2)}} 0
        \end{bmatrix} \\
        &\stackrel{(a)}{=} \begin{bmatrix}
            p^{(1)} \\
            0
        \end{bmatrix}
    \end{aligned}
    \end{equation}
    where $(a)$ is due to the fact that ${A}^{(1)} p^{(1)} = p^{(1)}$.
    \end{enumerate}
\end{proof}
\vspace{-1.8em}
\begin{remark}
\label{remark:jordan}
     From Lemma \ref{lemma:BxBy} and \cite{sayed2014adaptation}, we find that $B^{(x)}$ admits the following Jordan decomposition: $B^{(x)} = P M P^{-1}$, where
\begin{equation}
\label{eq:Bxjordan}
    P = \begin{bmatrix} p^{(x)} & P_{R} \end{bmatrix}, \ 
    M  = \begin{bmatrix} 1 & 0 \\ 0 & M_{\eta} \end{bmatrix}, \
    P^{-1} = \begin{bmatrix} \mathbbm{1}_K^{\top} \\ P_{L}^{\top} \end{bmatrix}.
\end{equation}
Similarly, for $B^{(y)}$, we have the decomposition $B^{(y)} = Q N Q^{-1}$, where
\begin{equation}
    Q = \begin{bmatrix} p^{(y)} & Q_{R} \end{bmatrix}, \ 
    N  = \begin{bmatrix} 1 & 0 \\ 0 & N_{\iota} \end{bmatrix}, \
    Q^{-1} = \begin{bmatrix} \mathbbm{1}_K^{\top} \\ Q_{L}^{\top} \end{bmatrix}.
\end{equation}
Here, $M_{\eta}, N_\iota$ are 
 block Jordan matrices with the eigenvalues on the diagonal and $\eta, \iota$ on the first lower subdiagonal, respectively.
We define
\begin{align}
   \mathcal{P}_L &\triangleq P_L \otimes I_{M_1}, \hspace{-8pt}
   &\mathcal{P}_R &\triangleq P_R \otimes I_{M_1}, \hspace{-8pt}
   &\mathcal{M}_\eta &\triangleq M_\eta \otimes I_{M_1}\label{eq:PPM}\\
   \mathcal{Q}_L &\triangleq Q_L \otimes I_{M_2}, \hspace{-8pt}
   &\mathcal{Q}_R &\triangleq Q_R \otimes I_{M_2}, \hspace{-8pt}
   &\mathcal{N}_\iota &\triangleq N_\iota \otimes I_{M_2} \label{eq:QQN}
\end{align}
\end{remark}

\begin{lemma}
\label{lemma:X1iX2i}
    Under Assumptions \ref{ass:within_conn}, \ref{ass:cross-conn_weak}, for \textbf{ATC-ITC}, we have:
    \begin{align}
    \!\!\!\!\| \boldsymbol{\mathcal{X}}^1_{i} - \boldsymbol{\mathcal{X}}_{c, i} \|^2 + \| \boldsymbol{\mathcal{X}}^2_{i} - \boldsymbol{\mathcal{X}}^\prime_{c, i} \|^2 &\leq \|\mathcal{P}_L\|^2 \left\| \mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i} \\
    \boldsymbol{\mathcal{X}}^2_{i}
    \end{bmatrix}\right\|^2 \label{eq:X1iX2i}\\
    \!\!\!\!\| \boldsymbol{\mathcal{Y}}^1_{i} - \boldsymbol{\mathcal{Y}}^\prime_{c, i} \|^2 + \| \boldsymbol{\mathcal{Y}}^2_{i} - \boldsymbol{\mathcal{Y}}_{c, i} \|^2 &\leq \|\mathcal{Q}_L\|^2 \left\| \mathcal{Q}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{Y}}^1_{i} \\
    \boldsymbol{\mathcal{Y}}^2_{i}
\end{bmatrix}\right\|^2 \label{eq:Y1iY2i}
    \end{align}\hfill\qed
\end{lemma}

\begin{proof}
    We establish \eqref{eq:X1iX2i}; a similar argument applies to \eqref{eq:Y1iY2i}.
    Using the property of $p^{(x)}$ in \eqref{eq:px_defn}, the following relationship holds:
\begin{equation}
\begin{aligned}
        \begin{bmatrix}
    \boldsymbol{\mathcal{X}}_{c,i} \\
    \boldsymbol{\mathcal{X}}^\prime_{c,i}
\end{bmatrix} &= \left(\mathbbm{1}_K {p^{(1)}}^{\top} \otimes I_{M_1}\right) \boldsymbol{\mathcal{X}}^1_{i} \\&= \left(\mathbbm{1}_K {p^{(x)}}^{\top} \otimes I_{M_1}\right)
    \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i} \\
    \boldsymbol{\mathcal{X}}^2_{i}
\end{bmatrix}
\end{aligned}
\end{equation}
Therefore, for $\| \boldsymbol{\mathcal{X}}^1_i - \boldsymbol{\mathcal{X}}_{c, i} \|^2 + \| \boldsymbol{\mathcal{X}}^2_i - \boldsymbol{\mathcal{X}}^\prime_{c, i} \|^2$, we have:
\begin{equation}
\label{eq:centroid_x_bound}
\begin{aligned}
    &\| \boldsymbol{\mathcal{X}}^1_i - \boldsymbol{\mathcal{X}}_{c, i} \|^2 + \| \boldsymbol{\mathcal{X}}^2_i - \boldsymbol{\mathcal{X}}^\prime_{c, i} \|^2\\
    &= \left\|\begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i} \\
    \boldsymbol{\mathcal{X}}^2_{i}
\end{bmatrix} - \begin{bmatrix}
    \boldsymbol{\mathcal{X}}_{c,i} \\
    \boldsymbol{\mathcal{X}}^\prime_{c,i}
\end{bmatrix}\right\|^2 \\
& = \left\| (I_{K} \otimes I_{M_1})\begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i} \\
    \boldsymbol{\mathcal{X}}^2_{i}
\end{bmatrix} - (\mathbbm{1}_K {p^{(x)}}^{\top} \otimes I_{M_1})\begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i} \\
    \boldsymbol{\mathcal{X}}^2_{i}
\end{bmatrix} \right\|^2 \\
& \stackrel{(a)}{=} \left\| \mathcal{P}_L \mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i} \\
    \boldsymbol{\mathcal{X}}^2_{i}
\end{bmatrix}\right\|^2 \\
& \leq 
\|\mathcal{P}_L\|^2 \left\| \mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i} \\
    \boldsymbol{\mathcal{X}}^2_{i}
\end{bmatrix}\right\|^2
\end{aligned}
\end{equation} where $(a)$ follows from the identity (see \eqref{eq:Bxjordan}):
\begin{align}
    (I_{K} \otimes I_{M_1}) &= (P^{-1} \otimes I_{M_1})^{\top} (P \otimes I_{M_1})^{\top} \notag\\
    &= \left(\mathbbm{1}_K {p^{(x)}}^{\top} + P_{L} P_{R}^{\top}\right) \otimes I_{M_1}
\end{align}
\end{proof}

\begin{lemma}
\label{lemma:PRTG}
    With zero-sum objectives \eqref{eq:zero-sum}, under Assumptions \ref{ass:within_conn}, \ref{ass:cross-conn_weak}, \ref{ass:lip}, \ref{ass:bdis}, \ref{ass:gradnoise}, for \textbf{ATC-ITC}, we have:
    \begin{align}
    &\mathbb{E} \left\{\left\|\mathcal{P}_R^{\top} \begin{bmatrix}
        \boldsymbol{\mathcal{G}}^1_{x, i} \\
        \boldsymbol{\mathcal{G}}^2_{x, i}
    \end{bmatrix}\right\|^2\right\} \notag\\
    &\leq 
    8 \|\mathcal{P}_R^{\top}\|^2 L_f^2 \left( \|\mathcal{P}_L\|^2 \mathbb{E} \left\{\left\| \mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i-1} \\
    \boldsymbol{\mathcal{X}}^2_{i-1}
\end{bmatrix}\right\|^2\right\}  \right. \notag\\
& \quad \left. + \|\mathcal{Q}_L\|^2 \mathbb{E} \left\{\left\| \mathcal{Q}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{Y}}^1_{i-1} \\
    \boldsymbol{\mathcal{Y}}^2_{i-1}
\end{bmatrix}\right\|^2\right\}\right) + 2\|\mathcal{P}_R^{\top}\|^2 K (2G^2 + \sigma^2)
\label{boundPR}
    \end{align}
    Furthermore, 
 $\mathbb{E} \left\{\left\|\mathcal{Q}_R^{\top} \begin{bmatrix}
        \boldsymbol{\mathcal{G}}^1_{y, i} \\
        \boldsymbol{\mathcal{G}}^2_{y, i}
    \end{bmatrix}\right\|^2\right\}$ admits an upper bound similar to the right-hand side of \eqref{boundPR}. \hfill\qed
\end{lemma}

\begin{proof}
    We use $\mathcal{G}^1_{x, i}$ and $\mathcal{G}^2_{x, i}$ to denote the deterministic realization for $\boldsymbol{\mathcal{G}}^1_{x, i}$ and $\boldsymbol{\mathcal{G}}^2_{x, i}$:
    \begin{align}
        \mathcal{G}^1_{x, i} &\triangleq \text{col} \{\nabla_x J_k\left(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}\right)\}_{k=1}^{K_1} \\
        \mathcal{G}^2_{x, i} &\triangleq \text{col} \{ - \nabla_x J_k\left(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}\right)\}_{k=K_1 + 1}^{K}\end{align} 
        The corresponding stochastic noise is denoted by:
        \begin{align}
        \boldsymbol{\mathcal{S}}_{x, i}^{1} &\triangleq \mathrm{col} \{\widehat{\nabla_x J}_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1})  \notag\\
        & \qquad - \nabla_x J_k\left(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}\right)\}_{k=1}^{K_1} \\
        \boldsymbol{\mathcal{S}}_{x, i}^{2} &\triangleq \mathrm{col} \{- \widehat{\nabla_x J}_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}) \notag\\
        & \qquad + \nabla_x J_k\left(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}\right)\}_{k=K_1+1}^{K}
    \end{align} 
    Next note that
    \begin{equation}
        \begin{aligned}
            \left\|\mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{G}}^1_{x, i} \\
    \boldsymbol{\mathcal{G}}^2_{x, i}
\end{bmatrix}\right\|^2 &= \left\|\mathcal{P}_R^{\top} \left( \begin{bmatrix}
    \mathcal{G}^1_{x, i} \\
    \mathcal{G}^2_{x, i}
\end{bmatrix} + \begin{bmatrix}
    \boldsymbol{\mathcal{S}}_{x, i}^{1} \\
    \boldsymbol{\mathcal{S}}_{x, i}^{2}
\end{bmatrix}
\right) \right\|^2 \\
&\leq 2\left\|\mathcal{P}_R^{\top} \begin{bmatrix}
    \mathcal{G}^1_{x, i} \\
    \mathcal{G}^2_{x, i}
\end{bmatrix}\right\|^2 + 2\left\|\mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{S}}_{x, i}^{1} \\
    \boldsymbol{\mathcal{S}}_{x, i}^{2}
\end{bmatrix} \right\|^2 \\
            &\leq 2\left\|\mathcal{P}_R^{\top} \begin{bmatrix}
    \mathcal{G}^1_{x, i} \\
    \mathcal{G}^2_{x, i}
\end{bmatrix}\right\|^2 + 2\left\|\mathcal{P}_R^{\top}\right\|^2 \left\| \begin{bmatrix}
    \boldsymbol{\mathcal{S}}_{x, i}^{1} \\
    \boldsymbol{\mathcal{S}}_{x, i}^{2}
\end{bmatrix}\right\|^2 \\
        \end{aligned}
    \end{equation}
Taking the conditional expectation and  since $\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1} \in \boldsymbol{\mathcal{F}}_{i-1}$, we obtain:

    \begin{equation}
    \label{eq:exp_PRTG}
        \mathbb{E} \left\{\left\|\mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{G}}^1_{x, i} \\
    \boldsymbol{\mathcal{G}}^2_{x, i}
\end{bmatrix}\right\|^2 \middle| \boldsymbol{\mathcal{F}}_{i-1}\right\} \leq 2\left\|\mathcal{P}_R^{\top} \begin{bmatrix}
    \mathcal{G}^1_{x, i} \\
    \mathcal{G}^2_{x, i}
\end{bmatrix}\right\|^2 + 2\left\|\mathcal{P}_R^{\top}\right\|^2 K \sigma^2
    \end{equation}
where we used Assumption \ref{ass:gradnoise}.  Now we get:
\allowdisplaybreaks
    \begin{align}
\label{eq:PRTG}
    &\left\|\mathcal{P}_R^{\top} \begin{bmatrix}\mathcal{G}^1_{x, i} \\\mathcal{G}^2_{x, i}\end{bmatrix}\right\|^2 \notag\\
    &= \left\|\mathcal{P}_R^{\top} \begin{bmatrix}
        \text{col}\{\nabla_x J_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1})\}_{k=1}^{K_1} \\
        \text{col}\{-\nabla_x J_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1})\}_{k=K_1+1}^{K}
    \end{bmatrix}\right\|^2 \notag\\
    &\stackrel{(a)}{=} \Bigg\|\mathcal{P}_R^{\top} \left(\begin{bmatrix}
        \text{col}\{\nabla_x J_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1})\}_{k=1}^{K_1} \\
        \text{col}\{-\nabla_x J_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1})\}_{k=K_1+1}^{K}
    \end{bmatrix} \right. \notag\\
    &\quad\left. - \begin{bmatrix}
        \text{col}\{\nabla_x J_k(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1})\}_{k=1}^{K_1} \\
        \text{col}\{-\nabla_x J_k(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1})\}_{k=K_1+1}^{K}
    \end{bmatrix}\right) \notag\\
    &\quad + \mathcal{P}_R^{\top} \left(\begin{bmatrix}
        \text{col}\{\nabla_x J_k(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1})\}_{k=1}^{K_1} \\
        \text{col}\{-\nabla_x J_k(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1})\}_{k=K_1+1}^{K}
    \end{bmatrix}  - (\mathbbm{1}_K \right. \notag\\
    &\quad\left. {p^{(x)}}^{\top})\otimes I_{M_1} \begin{bmatrix}
        \text{col}\{\nabla_x J_k(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1})\}_{k=1}^{K_1} \\
        \text{col}\{-\nabla_x J_k(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1})\}_{k=K_1+1}^{K}
    \end{bmatrix}\right)\Bigg\|^2 \notag\\
    &\stackrel{(b)}{\leq} 2\|\mathcal{P}_R^{\top}\|^2 \sum_{k=1}^{K} \|\nabla_x J_k(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}) - \nabla_x J_k(\boldsymbol{x}_{c, i-1},  \notag\\
    &\quad \boldsymbol{y}_{c, i-1})\|^2 + 2\|\mathcal{P}_R^{\top}\|^2 \sum_{k=1}^{K_1} \|\nabla_x J_k(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1})  \notag\\
    &\quad - \nabla_x J^{(1)}(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1})\|^2 + 2\|\mathcal{P}_R^{\top}\|^2 \sum_{k=K_1+1}^{K}  \notag\\
    & \quad \|-\nabla_x J_k(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}) + \nabla_x J^{(2)}(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1})\|^2 \notag\\
    &\stackrel{(c)}{\leq} 2\|\mathcal{P}_R^{\top}\|^2 \sum_{k=1}^{K} L_f^2 (\|\boldsymbol{x}_{k, i-1} - \boldsymbol{x}_{c, i-1}\| + \|\boldsymbol{y}_{k, i-1} - \boldsymbol{y}_{c, i-1}\|)^2 \notag\\
    &\quad + 2\|\mathcal{P}_R^{\top}\|^2 K G^2 \notag\\
    &\stackrel{(d)}{\leq} 2\|\mathcal{P}_R^{\top}\|^2 L_f^2 (2\|\boldsymbol{\mathcal{X}}^1_{i-1} - \boldsymbol{\mathcal{X}}_{c,i-1}\|^2 + 2\|\boldsymbol{\mathcal{Y}}^2_{i-1} - \boldsymbol{\mathcal{Y}}_{c,i-1}\|^2 \notag\\
    &\quad + 2\|\boldsymbol{\mathcal{X}}^2_{i-1} - \boldsymbol{\mathcal{X}}^\prime_{c,i-1}\|^2 + 2\|\boldsymbol{\mathcal{Y}}^1_{i-1} - \boldsymbol{\mathcal{Y}}^\prime_{c,i-1}\|^2) \notag\\
    &\quad + 2\|\mathcal{P}_R^{\top}\|^2 K G^2.
\end{align}
where $(a)$ follows from the fact that $P_R^{\top} \mathbbm{1}_K = 0$; and $(b)$ is due to 
    \begin{equation}
        \begin{aligned}
            &(\mathbbm{1}_K {p^{(x)}}^{\top}) \otimes I_{M_1} \begin{bmatrix}
                \text{col}\{\nabla_x J_k\left(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}\right)\}_{k=1}^{K_1} \\ \text{col}\{ - \nabla_x J_k\left(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}\right)\}_{k=K_1+1}^{K}
                \end{bmatrix} \\
                &= \mathbbm{1}_K \otimes \sum_{k=1}^{K_1} p_k \nabla_x J_k\left(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}\right)\\
                &= \mathbbm{1}_K \otimes \nabla_x \left(\sum_{k=1}^{K_1} p_k J_k\left(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}\right)\right)\\
                &= \mathbbm{1}_K \otimes \nabla_x  J^{(1)}\left(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}\right)
        \end{aligned}
    \end{equation}
    and the zero-sum setting \eqref{eq:zero-sum}, which implies $\nabla_x J^{(1)}\left(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}\right) = - \nabla_x J^{(2)}\left(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}\right)$; $(c)$ follows from Assumption \ref{ass:lip} and \ref{ass:bdis}; $(d)$ follows from the inequality $(a+b)^2 \leq 2a^2 + 2b^2$ and the fact that 
    \begin{equation}
        \begin{aligned}
            \sum_{k=1}^{K_1} \|\boldsymbol{x}_{k, i-1} - \boldsymbol{x}_{c, i-1}\|^2 &= \|\boldsymbol{\mathcal{X}}^1_{i-1} - \boldsymbol{\mathcal{X}}_{c, i-1} \|^2 \\
            \sum_{k=K_1+1}^{K_1} \|\boldsymbol{x}_{k, i-1} - \boldsymbol{x}_{c, i-1}\|^2 &= \|\boldsymbol{\mathcal{X}}^2_{i-1} - \boldsymbol{\mathcal{X}}^\prime_{c, i-1} \|^2\\
            \sum_{k=1}^{K_1}\|\boldsymbol{y}_{k, i-1} - \boldsymbol{y}_{c, i-1}\|^2 &= \|\boldsymbol{\mathcal{Y}}^1_{i-1} - \boldsymbol{\mathcal{Y}}^{\prime}_{c,i-1}\|^2\\
            \sum_{k=K_1+1}^{K}\|\boldsymbol{y}_{k, i-1} - \boldsymbol{y}_{c, i-1}\|^2 &= \|\boldsymbol{\mathcal{Y}}^2_{i-1} - \boldsymbol{\mathcal{Y}}_{c,i-1}\|^2   
        \end{aligned}
    \end{equation}
    Moreover, by Lemma \ref{lemma:X1iX2i}, we can further bound \eqref{eq:PRTG} by the following:
    \begin{equation}
    \label{eq:PRTG_2}
        \begin{aligned}
            &\left\|\mathcal{P}_R^{\top} \begin{bmatrix}\mathcal{G}^1_{x, i} \\\mathcal{G}^2_{x, i}\end{bmatrix} \right\|^2\\
            &\leq 
            2\|\mathcal{P}_R^{\top}\|^2 L_f^2 (2\|\boldsymbol{\mathcal{X}}^1_{i-1} - \boldsymbol{\mathcal{X}}_{c,i-1}\|^2 + 2\|\boldsymbol{\mathcal{Y}}^2_{i-1} - \boldsymbol{\mathcal{Y}}_{c,i-1}\|^2 \\
            & \quad + 2\|\boldsymbol{\mathcal{X}}^2_{i-1} - \boldsymbol{\mathcal{X}}^\prime_{c,i-1}\|^2 + 2\|\boldsymbol{\mathcal{Y}}^1_{i-1} - \boldsymbol{\mathcal{Y}}^\prime_{c,i-1}\|^2 )\\
            & \quad 
            + 2\|\mathcal{P}_R^{\top}\|^2 K G^2\\
            & \leq 
            4 \|\mathcal{P}_R^{\top}\|^2 L_f^2 \left( \|\mathcal{P}_L\|^2\left\| \mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i-1} \\
    \boldsymbol{\mathcal{X}}^2_{i-1}
\end{bmatrix}\right\|^2  \right.\\
& \quad \left. + \|\mathcal{Q}_L\|^2 \left\| \mathcal{Q}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{Y}}^1_{i-1} \\
    \boldsymbol{\mathcal{Y}}^2_{i-1}
\end{bmatrix}\right\|^2\right) + 2\|\mathcal{P}_R^{\top}\|^2 K G^2
        \end{aligned}
    \end{equation}
    Combining \eqref{eq:PRTG_2} with \eqref{eq:exp_PRTG}, we arrive at:
    \begin{align}
    &\mathbb{E} \left\{\left\|\mathcal{P}_R^{\top} \begin{bmatrix}
        \boldsymbol{\mathcal{G}}^1_{x, i} \\
        \boldsymbol{\mathcal{G}}^2_{x, i}
    \end{bmatrix}\right\|^2\right\} \notag\\
    &\leq 
    8 \|\mathcal{P}_R^{\top}\|^2 L_f^2 \left( \|\mathcal{P}_L\|^2 \mathbb{E} \left\{\left\| \mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i-1} \\
    \boldsymbol{\mathcal{X}}^2_{i-1}
\end{bmatrix}\right\|^2\right\}  \right. \notag\\
& \quad \left. + \|\mathcal{Q}_L\|^2 \mathbb{E} \left\{\left\| \mathcal{Q}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{Y}}^1_{i-1} \\
    \boldsymbol{\mathcal{Y}}^2_{i-1}
\end{bmatrix}\right\|^2\right\}\right) + 2\|\mathcal{P}_R^{\top}\|^2 K (2G^2 + \sigma^2)
    \end{align}
