\subsection{Main Proof}
\label{proof:lemma2}
From Algorithm \ref{alg:network_learning_zerosum}, the recursions for $\boldsymbol{\mathcal{X}}^1_{i}$  and $\boldsymbol{\mathcal{X}}^2_{i}$ are given by:
\begin{align}
    \boldsymbol{\mathcal{X}}^1_{i} &= {\mathcal{A}^{(1)}}^{\top} \left(\boldsymbol{\mathcal{X}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{x, i} \right)\\
    \boldsymbol{\mathcal{X}}^2_{i} &= {\mathcal{C}^{(12)}}^{\top} \boldsymbol{\mathcal{X}}_{i}^1 +{\mathcal{C}^{(2)}}^{\top} \left(\boldsymbol{\mathcal{X}}^2_{i-1} - \mu \boldsymbol{\mathcal{G}}^2_{x, i}\right)
\end{align}
In matrix form we write:
    \begin{equation}
        \begin{bmatrix}
            \boldsymbol{\mathcal{X}}^1_{i} \\
            \boldsymbol{\mathcal{X}}^2_{i}
        \end{bmatrix} =  
        \begin{bmatrix}
            {\mathcal{A}^{(1)}}^{\top} & 0 \\
            {\mathcal{C}^{(12)}}^{\top}{\mathcal{A}^{(1)}}^{\top} & {\mathcal{C}^{(2)}}^{\top} 
        \end{bmatrix}
        \begin{bmatrix}
            \boldsymbol{\mathcal{X}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{x, i} \\
            \boldsymbol{\mathcal{X}}^2_{i-1} - \mu \boldsymbol{\mathcal{G}}^2_{x, i}
        \end{bmatrix}
    \end{equation} 

We define the transition matrix for $x$ as:
\begin{equation}
    B^{(x)} \triangleq 
    \begin{bmatrix}
    {A}^{(1)} & A^{(1)} C^{(12)}\\
    0 & {C^{(2)}} 
\end{bmatrix} \in \mathbb{R}^{K \times K}
\end{equation}
where the superscript $(x)$ indicates that this matrix is related to the information flow of strategy $x$. From Lemma \ref{lemma:BxBy}, we know that $B^{(x)}$ and $B^{(y)}$ have Jordan decompositions: $B^{(x)} = P M P^{-1}$, $B^{(y)} = Q N Q^{-1}$. Formal definitions of $\mathcal{P}_R, \mathcal{P}_L, \mathcal{M}_\eta, \mathcal{Q}_R, \mathcal{Q}_L, \mathcal{N}_\iota$ can be found in Remark \ref{remark:jordan}.

By Lemma \ref{lemma:X1iX2i}, we can obtain:
\begin{align}
    &\mathbb{E} \left\{\| \boldsymbol{\mathcal{X}}^1_{i} - \boldsymbol{\mathcal{X}}_{c, i} \|^2 + \| \boldsymbol{\mathcal{X}}^2_{i} - \boldsymbol{\mathcal{X}}^\prime_{c, i} \|^2\right\} \notag\\
    &\quad \leq \|\mathcal{P}_L\|^2 \mathbb{E} \left\{\left\| \mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i} \\
    \boldsymbol{\mathcal{X}}^2_{i}
    \end{bmatrix}\right\|^2\right\}
\end{align}
\vspace{-1.3em}
Next,
\vspace{-1em}
\allowdisplaybreaks

\begin{align}
\label{eq:PRTX}
    &\left\| \mathcal{P}_R^{\top} \begin{bmatrix}
            \boldsymbol{\mathcal{X}}^1_{i} \\
            \boldsymbol{\mathcal{X}}^2_{i}
        \end{bmatrix}\right\|^2 \notag \\
    &= \left\| \mathcal{P}_R^{\top} {\mathcal{B}^{(x)}}^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{x, i} \\
    \boldsymbol{\mathcal{X}}^2_{i-1} - \mu \boldsymbol{\mathcal{G}}^2_{x, i}
\end{bmatrix}\right\|^2 \notag \\
    &\stackrel{(a)}{=} \left\| \mathcal{M}_\eta^{\top} \mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{x, i} \\
    \boldsymbol{\mathcal{X}}^2_{i-1} - \mu \boldsymbol{\mathcal{G}}^2_{x, i}
\end{bmatrix}\right\|^2 \notag \\
    &\stackrel{(b)}{\leq} \left\| \mathcal{M}_\eta^{\top}\right\|^2 \left(\frac{1}{\left\| \mathcal{M}_\eta^{\top}\right\|}\left\|\mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i-1}  \\
    \boldsymbol{\mathcal{X}}^2_{i-1}
\end{bmatrix}\right\|^2 \right. \notag \\
    &\quad \left. + \frac{1}{1-\left\| \mathcal{M}_\eta^{\top}\right\|} \mu^2 \left\|\mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{G}}^1_{x, i} \\
    \boldsymbol{\mathcal{G}}^2_{x, i}
\end{bmatrix}\right\|^2\right) \notag \\
    &= \left\| \mathcal{M}_\eta^{\top}\right\| \left\|\mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{X}}^1_{i-1}  \\
    \boldsymbol{\mathcal{X}}^2_{i-1}
\end{bmatrix}\right\|^2 \notag \\
    &\quad + \frac{\left\| \mathcal{M}_\eta^{\top}\right\|^2}{1-\left\| \mathcal{M}_\eta^{\top}\right\|} \mu^2 \left\|\mathcal{P}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{G}}^1_{x, i} \\
    \boldsymbol{\mathcal{G}}^2_{x, i}
\end{bmatrix}\right\|^2.
\end{align}
    where  $(a)$ follows from 
    \begin{equation}
    \label{eq:PRB}
        \begin{aligned}
            &(P_{R}^{\top} {B^{(x)}}^{\top}) \otimes I_{M_1} \\
            &= \left(P_{R}^{\top} \begin{bmatrix} \mathbbm{1}_K & P_{L} \end{bmatrix} \begin{bmatrix} 1 & 0 \\ 0 & M_{\eta}^{\top} \end{bmatrix} \begin{bmatrix} {p^{(x)}}^{\top} \\ P_{R}^{\top} \end{bmatrix}\right) \otimes I_{M_1} \\
            &= \left(\begin{bmatrix} 0 & I_{K-1} \end{bmatrix} \begin{bmatrix} 1 & 0 \\ 0 & M_{\eta}^{\top} \end{bmatrix} \begin{bmatrix} {p^{(x)}}^{\top} \\ P_{R}^{\top} \end{bmatrix}\right) \otimes I_{M_1} \\
            &= (M_{\eta}^{\top} P_{R}^{\top}) \otimes I_{M_1}.
        \end{aligned}
    \end{equation}
and $(b)$ follows from the sub-multiplicative property of $\|\cdot\|$, the convexity of $\|\cdot\|^2$, and Jensen's inequality: $\|a+b\|^2 \leq \frac{1}{\alpha} \|a\|^2 + \frac{1}{1-\alpha} \|b\|^2$. 
Combining the results from \eqref{eq:PRTX} and Lemma \ref{lemma:PRTG}, we have:
    \begin{align}
    \label{eq:PRTX_final}
            &\mathbb{E} \left\{\left\| \mathcal{P}_R^{\top} \begin{bmatrix}
            \boldsymbol{\mathcal{X}}^1_{i} \\
            \boldsymbol{\mathcal{X}}^2_{i}
        \end{bmatrix}\right\|^2\right\} \notag\\
            &\stackrel{(a)}{\leq}
            \left\| \mathcal{M}_\eta^{\top}\right\| \mathbb{E} \left\{\left\|\mathcal{P}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{X}}^1_{i-1}  \\\boldsymbol{\mathcal{X}}^2_{i-1} \end{bmatrix} \right\|^2\right\} \notag\\
            & \quad + \frac{\left\| \mathcal{M}_\eta^{\top}\right\|^2}{1-\left\| \mathcal{M}_\eta^{\top}\right\|} \mu^2 \mathbb{E} \left\{\left\|\mathcal{P}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{G}}^1_{x, i} \\\boldsymbol{\mathcal{G}}^2_{x, i}\end{bmatrix} \right\|^2\right\} \notag\\
            &\stackrel{(b)}{\leq}
            \left\| \mathcal{M}_\eta^{\top}\right\| \mathbb{E} \left\{\left\|\mathcal{P}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{X}}^1_{i-1}  \\\boldsymbol{\mathcal{X}}^2_{i-1} \end{bmatrix} \right\|^2\right\} + 8\frac{\left\| \mathcal{M}_\eta^{\top}\right\|^2 \|\mathcal{P}_R^{\top}\|^2 \|\mathcal{P}_L\|^2}{1-\left\| \mathcal{M}_\eta^{\top}\right\|} \notag\\
            & \quad L_f^2 \mu^2 \mathbb{E} \left\{\left\|\mathcal{P}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{X}}^1_{i-1}  \\\boldsymbol{\mathcal{X}}^2_{i-1} \end{bmatrix} \right\|^2\right\}
            + 8\frac{\left\| \mathcal{M}_\eta^{\top}\right\|^2 \|\mathcal{P}_R^{\top}\|^2 \|\mathcal{Q}_L\|^2}{1-\left\| \mathcal{M}_\eta^{\top}\right\|} L_f^2 \mu^2 \notag\\
            & \quad \mathbb{E} \left\{\left\| \mathcal{Q}_R^{\top} \begin{bmatrix}
    \boldsymbol{\mathcal{Y}}^1_{i-1} \\
    \boldsymbol{\mathcal{Y}}^2_{i-1}
\end{bmatrix}\right\|^2\right\} + 2\frac{\left\| \mathcal{M}_\eta^{\top}\right\|^2\left\|\mathcal{P}_R^{\top}\right\|^2}{1-\left\| \mathcal{M}_\eta^{\top}\right\|} \mu^2 K (2G ^2 + \sigma^2)
        \end{align}
    where $(a)$ follows from \eqref{eq:PRTX}; $(b)$ follows from Lemma \ref{lemma:PRTG}. Similarly, we get:
    \begin{equation}
    \label{eq:QRTY}
        \begin{aligned}
           &\mathbb{E} \left\{\left\| \mathcal{Q}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{Y}}^1_{i} \\\boldsymbol{\mathcal{Y}}^2_{i}\end{bmatrix}\right\|^2\right\} \\
            &\leq
            \left\| \mathcal{N}_\iota^{\top}\right\| \mathbb{E} \left\{\left\| \mathcal{Q}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{Y}}^1_{i-1} \\\boldsymbol{\mathcal{Y}}^2_{i-1}\end{bmatrix}\right\|^2\right\} + 8\frac{\left\| \mathcal{N}_\iota^{\top}\right\|^2 \|\mathcal{Q}_R^{\top}\|^2 \|\mathcal{Q}_L\|^2}{1-\left\| \mathcal{N}_\iota^{\top}\right\|} \\
            & \quad L_f^2 \mu^2 \mathbb{E} \left\{\left\| \mathcal{Q}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{Y}}^1_{i-1} \\\boldsymbol{\mathcal{Y}}^2_{i-1}\end{bmatrix}\right\|^2\right\}
            + 8\frac{\left\| \mathcal{N}_\iota^{\top}\right\|^2 \|\mathcal{Q}_R^{\top}\|^2 \|\mathcal{P}_L\|^2}{1-\left\| \mathcal{N}_\iota^{\top}\right\|} L_f^2 \mu^2 \\
            & \quad \mathbb{E} \left\{\left\|\mathcal{P}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{X}}^1_{i-1}  \\\boldsymbol{\mathcal{X}}^2_{i-1} \end{bmatrix} \right\|^2\right\} + 2\frac{\left\| \mathcal{N}_\iota^{\top}\right\|^2\left\|\mathcal{Q}_R^{\top}\right\|^2}{1-\left\| \mathcal{N}_\iota^{\top}\right\|} \mu^2 K (2G ^2 + \sigma^2)
        \end{aligned}
    \end{equation}
    For compactness, we introduce the following scalar coefficients:
    \begin{align}
    a_1 &= \frac{\left\| \mathcal{M}_\eta^{\top}\right\|^2 \|\mathcal{P}_R^{\top}\|^2 \|\mathcal{P}_L\|^2}{1-\left\| \mathcal{M}_\eta^{\top}\right\|}\\
    b_1 &= \frac{\left\| \mathcal{M}_\eta^{\top}\right\|^2 \|\mathcal{P}_R^{\top}\|^2 \|\mathcal{Q}_L\|^2}{1-\left\| \mathcal{M}_\eta^{\top}\right\|}\\
    c_1 &= \frac{\left\| \mathcal{M}_\eta^{\top}\right\|^2\left\|\mathcal{P}_R^{\top}\right\|^2}{1-\left\| \mathcal{M}_\eta^{\top}\right\|}\\
    a_2 &= \frac{\left\| \mathcal{N}_\iota^{\top}\right\|^2 \|\mathcal{Q}_R^{\top}\|^2 \|\mathcal{Q}_L\|^2}{1-\left\| \mathcal{N}_\iota^{\top}\right\|}\\
    b_2 &= \frac{\left\| \mathcal{N}_\iota^{\top}\right\|^2 \|\mathcal{Q}_R^{\top}\|^2 \|\mathcal{P}_L\|^2}{1-\left\| \mathcal{N}_\iota^{\top}\right\|}\\
    c_2 &= \frac{\left\| \mathcal{N}_\iota^{\top}\right\|^2\left\|\mathcal{Q}_R^{\top}\right\|^2}{1-\left\| \mathcal{N}_\iota^{\top}\right\|}
\end{align}
Adding the results from \eqref{eq:PRTX_final} and \eqref{eq:QRTY}, we obtain:
    \begin{equation}
        \begin{aligned}
            &\mathbb{E} \left\{\left\| \mathcal{P}_R^{\top} \begin{bmatrix}
            \boldsymbol{\mathcal{X}}^1_{i} \\
            \boldsymbol{\mathcal{X}}^2_{i}
        \end{bmatrix}\right\|^2\right\} + \mathbb{E} \left\{\left\| \mathcal{Q}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{Y}}^1_{i} \\\boldsymbol{\mathcal{Y}}^2_{i}\end{bmatrix}\right\|^2\right\}\\
            & \leq
            \left(\left\| \mathcal{M}_\eta^{\top}\right\| + 8 a_1 L_f^2 \mu^2 + 8 b_2 L_f^2 \mu^2\right) \mathbb{E} \left\{\left\|\mathcal{P}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{X}}^1_{i-1}  \\\boldsymbol{\mathcal{X}}^2_{i-1} \end{bmatrix} \right\|^2\right\} \\
            & \quad
            + \left( \left\|\mathcal{N}_\iota^{\top}\right\| + 8 a_2 L_f^2 \mu^2 + 8 b_1 L_f^2 \mu^2\right) \mathbb{E} \left\{\left\| \mathcal{Q}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{Y}}^1_{i-1} \\\boldsymbol{\mathcal{Y}}^2_{i-1}\end{bmatrix}\right\|^2\right\} \\
            & \quad + 2(c_1 + c_2)\mu^2 K (2G ^2 + \sigma^2)\\
            & \stackrel{(a)}{\leq}
            \alpha \left(\mathbb{E} \left\{\left\|\mathcal{P}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{X}}^1_{i-1}  \\\boldsymbol{\mathcal{X}}^2_{i-1} \end{bmatrix} \right\|^2\right\} + \mathbb{E} \left\{\left\| \mathcal{Q}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{Y}}^1_{i-1} \\\boldsymbol{\mathcal{Y}}^2_{i-1}\end{bmatrix}\right\|^2\right\}\right) \\
            & \quad + 2(c_1 + c_2)\mu^2 K (2G ^2 + \sigma^2)\\
        \end{aligned}   
    \end{equation}
    where  in $(a)$ we define:
    \begin{align}
    \label{eq:zerosum_alpha}
        \alpha &= \max \bigl\{\left\| \mathcal{M}_\eta^{\top}\right\| + 8 a_1 L_f^2 \mu^2 + 8 b_2 L_f^2 \mu^2, \notag\\
        & \qquad \left\|\mathcal{N}_\iota^{\top}\right\| + 8 a_2 L_f^2 \mu^2 + 8 b_1 L_f^2 \mu^2\bigr\} < 1
    \end{align}
    Noting that $\left\| \mathcal{M}_\eta^{\top}\right\| < 1$ is independent of $\mu$, we have $1 - \alpha = O(1)$. Thus, 
\begin{equation}
    \begin{aligned}
        &\mathbb{E} \left\{\left\| \mathcal{P}_R^{\top} \begin{bmatrix}
            \boldsymbol{\mathcal{X}}^1_{i} \\
            \boldsymbol{\mathcal{X}}^2_{i}
        \end{bmatrix}\right\|^2\right\} + \mathbb{E} \left\{\left\| \mathcal{Q}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{Y}}^1_{i} \\\boldsymbol{\mathcal{Y}}^2_{i}\end{bmatrix}\right\|^2\right\} \\
        & \stackrel{(a)}{\leq}
        O(\mu^2) + \frac{2(c_1 + c_2)\mu^2 K (2G ^2 + \sigma^2)}{1-\alpha} = O(\mu^2)
    \end{aligned}
\end{equation}
where $(a)$ holds when 
\begin{equation}
    \alpha^i \leq O(\mu^2) \Longleftrightarrow i \geq i_\alpha =\frac{\log \left(O\left(\mu^2\right)\right)}{\log \left(\alpha\right)}
\end{equation}
Therefore, by Lemma \ref{lemma:X1iX2i}, we conclude: 
\begin{equation}
\begin{aligned}
    &\mathbb{E} \{\|\boldsymbol{\mathcal{X}}^1_{i} - \boldsymbol{\mathcal{X}}_{c,i}\|^2 + \|\boldsymbol{\mathcal{Y}}^2_{i} - \boldsymbol{\mathcal{Y}}_{c,i}\|^2 + \\
    & \qquad \|\boldsymbol{\mathcal{X}}^2_{i} - \boldsymbol{\mathcal{X}}^\prime_{c,i}\|^2 + \|\boldsymbol{\mathcal{Y}}^1_{i} - \boldsymbol{\mathcal{Y}}^\prime_{c,i}\|^2\} \\
    &\leq
    \max\{\|\mathcal{P}_L\|^2, \|\mathcal{Q}_L\|^2 \}\\
    &\quad \left(\mathbb{E} \left\{\left\| \mathcal{P}_R^{\top} \begin{bmatrix}
            \boldsymbol{\mathcal{X}}^1_{i} \\
            \boldsymbol{\mathcal{X}}^2_{i}
        \end{bmatrix}\right\|^2\right\} + \mathbb{E} \left\{\left\| \mathcal{Q}_R^{\top} \begin{bmatrix}\boldsymbol{\mathcal{Y}}^1_{i} \\\boldsymbol{\mathcal{Y}}^2_{i}\end{bmatrix}\right\|^2\right\}\right) \\
        &\leq O(\mu^2) 
\end{aligned}
\end{equation}
when $i \geq i_\alpha$.

\section{Proof of Lemma \ref{lemma:zerosum_within_cross} for \textbf{ATC-C}}
\label{proof:lemma2_atcc}
In this section, we prove Lemma \ref{lemma:zerosum_within_cross} when employing \mbox{\textbf{ATC-C}.}

Note that by Assumption \ref{ass:within_conn}, 
$A^{(1)}$
and $A^{(2)}$
have Jordan decompositions 
$A^{(1)} = V J V^{-1}$ and $A^{(2)} = U K U^{-1}$ \cite{sayed2014adaptation}, where 
\begin{equation}
    V = \begin{bmatrix}
        p^{(1)} & V_{R}
    \end{bmatrix}, \
    J = \begin{bmatrix}
        1 & 0 \\
        0 & J_{\varepsilon}
    \end{bmatrix}, \
    V^{-1} = \begin{bmatrix}
        \mathbbm{1}^{\top} \\
        V_{L}^{\top}
    \end{bmatrix}
\end{equation}
\begin{equation}
    U = \begin{bmatrix}
        p^{(2)} & U_{R}
    \end{bmatrix}, \
    K = \begin{bmatrix}
        1 & 0 \\
        0 & K_{\gamma}
    \end{bmatrix}, \
    U^{-1} = \begin{bmatrix}
        \mathbbm{1}^{\top} \\
        U_{L}^{\top}
    \end{bmatrix}
\end{equation}
Here, $J_{\varepsilon}, K_\gamma$ are 
 block Jordan matrices with the eigenvalues on the diagonal and $\varepsilon, \gamma$ on the first lower subdiagonal, respectively. Using the above notation,
we can verify that 
\begin{align}
    \mathbbm{1}^{\top}_{K_1} V_{R} = 0, \mathbbm{1}^{\top}_{K_2} U_{R} = 0, V_{L}^{\top} V_{R} = I, U_{L}^{\top} U_{R} = I
\end{align}
We also define
\begin{align}
\mathcal{V}_{L} &\triangleq V_{L} \otimes I_{M_1},\!\! &
\mathcal{J}_{\varepsilon} &\triangleq J_{\varepsilon} \otimes I_{M_1},\!\! &
\mathcal{V}_{R} &\triangleq V_{R} \otimes I_{M_1} \\
\mathcal{U}_{L} &\triangleq U_{L} \otimes I_{M_2},\!\! &
\mathcal{K}_{\gamma} &\triangleq K_{\gamma} \otimes I_{M_2},\!\! &
\mathcal{U}_{R} &\triangleq U_{R} \otimes I_{M_2}
\end{align}

\subsection{Key Lemmas}
\begin{lemma}
\label{lemma:plain_within}
    Under Assumptions \ref{ass:within_conn}, for \textbf{ATC-C}, we have:
\begin{align}
    & \|\boldsymbol{\mathcal{X}}^1_{i} - \boldsymbol{\mathcal{X}}_{c,i}\|^2 \leq \|\mathcal{V}_{L} \|^2 \| \mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{X}}^1_i \|^2  \\
    & \|\boldsymbol{\mathcal{Y}}^2_{i} - \boldsymbol{\mathcal{Y}}_{c,i}\|^2 \leq
    \|\mathcal{U}_L\|^2  \left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i}\right\|^2
\end{align}
\end{lemma}

\begin{proof}
    We prove for $\|\boldsymbol{\mathcal{X}}^1_{i} - \boldsymbol{\mathcal{X}}_{c,i}\|^2$; the proof for $\|\boldsymbol{\mathcal{Y}}^2_{i} - \boldsymbol{\mathcal{Y}}_{c,i}\|^2$ follows a similar argument.
    For $\| \boldsymbol{\mathcal{X}}^1_i - \boldsymbol{\mathcal{X}}_{c, i} \|^2$, we have:
    \begin{align}
    \label{eq:lemma1_first}
        &\| \boldsymbol{\mathcal{X}}^1_i - (\mathbbm{1} {p^{(1)}}^{\top} \otimes I_{M_1})\boldsymbol{ \mathcal{X}}^1_{i} \|^2 \notag\\
        &= \| (I_{K_1} \otimes I_{M_1})\boldsymbol{\mathcal{X}}^1_i - (\mathbbm{1} {p^{(1)}}^{\top} \otimes I_{M_1})\boldsymbol{ \mathcal{X}}^1_{i} \|^2 \notag\\
        & \stackrel{(a)}{=} \|\mathcal{V}_{L} \mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{X}}^1_i\|^2 \notag\\
        & \leq \|\mathcal{V}_{L} \|^2 \| \mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{X}}^1_i \|^2
    \end{align}
    where $(a)$ follows from the fact that 
    \begin{align}
        (I_{K_1} \otimes I_{M_1}) &= (V^{-1} \otimes I_{M_1})^{\top} (V \otimes I_{M_1})^{\top} \notag\\
        &= \left(\mathbbm{1} {p^{(1)}}^{\top} + V_{L} V_{R}^{\top}\right) \otimes I_{M_1}
    \end{align}
\end{proof}

\begin{lemma}
\label{lemma:plain_cross}
    Under Assumption \ref{ass:within_conn}, \ref{ass:cross-conn_strong}, for \textbf{ATC-C}, we have:
    \begin{align}    &\|\boldsymbol{\mathcal{X}}^2_{i} - \boldsymbol{\mathcal{X}}^\prime_{c,i}\|^2 \leq K_2\|\mathcal{V}_{L} \|^2 \| \mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{X}}^1_i \|^2\\    &\|\boldsymbol{\mathcal{Y}}^1_{i} - \boldsymbol{\mathcal{Y}}^\prime_{c,i}\|^2 \leq K_1 \|\mathcal{U}_L\|^2  \left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i}\right\|^2
    \end{align} \hfill\qed
\end{lemma}

\begin{proof}
    We only prove for $\|\boldsymbol{\mathcal{Y}}^1_{i} - \boldsymbol{\mathcal{Y}}^\prime_{c,i}\|^2$ as the proof for $\|\boldsymbol{\mathcal{X}}^2_{i} - \boldsymbol{\mathcal{X}}^\prime_{c,i}\|^2$ is nearly the same. As stated in Assumption \ref{ass:cross-conn_strong}, we know that $C^{(21)}$ is left-stochastic, meaning that ${C^{(21)}}^{\top} \mathbbm{1}_{K_2} = \mathbbm{1}_{K_1}$. Consequently, we can derive the following:
    \begin{equation}
        \begin{aligned}  \boldsymbol{\mathcal{Y}}^\prime_{c,i-1} 
        &= \left(\mathbbm{1}_{K_1} {p^{(2)}}^{\top} \otimes I_{M_2}\right) \boldsymbol{\mathcal{Y}}^2_{i-1} \\
        &= 
        \left({C^{(21)}}^{\top} \mathbbm{1}_{K_2} {p^{(2)}}^{\top} \otimes I_{M_2}\right) \boldsymbol{\mathcal{Y}}^2_{i-1} \\
        &=
        \left({C^{(21)}}^{\top} \otimes I_{M_2}\right) \left(\mathbbm{1}_{K_2} {p^{(2)}}^{\top} \otimes I_{M_2}\right) \boldsymbol{\mathcal{Y}}^2_{i-1} \\
        &=
        {\mathcal{C}^{(21)}}^{\top} \boldsymbol{\mathcal{Y}}_{c,i-1}.
        \end{aligned}
    \end{equation}
    Moreover, from Algorithm \ref{alg:network_learning_general_strong}, we have $\boldsymbol{\mathcal{Y}}^1_{i-1} = {\mathcal{C}^{(21)}}^{\top} \boldsymbol{\mathcal{Y}}^2_{i-1}$. As a result, we get
    \begin{equation}
        \boldsymbol{\mathcal{Y}}^1_{i-1} -\boldsymbol{\mathcal{Y}}^\prime_{c,i-1} = {\mathcal{C}^{(21)}}^{\top} (\boldsymbol{\mathcal{Y}}^2_{i-1} - \boldsymbol{\mathcal{Y}}_{c,i-1})
    \end{equation}
    Then, by Assumption \ref{ass:cross-conn_strong}, we get:
    \begin{align}
    \label{eq:C21}
        \|{\mathcal{C}^{(21)}}^{\top}\|^2 &= \rho (C^{(21)} {C^{(21)}}^{\top}) \leq \|C^{(21)} {C^{(21)}}^{\top}\|_1 \notag\\
        &\leq \sum_{ij} (C^{(21)} {C^{(21)}}^{\top})_{i,j} = \mathbbm{1}^{\top} C^{(21)} {C^{(21)}}^{\top} \mathbbm{1} \notag\\
        & = K_1
    \end{align}
    Therefore, we conclude that:
    \begin{align}      \|\boldsymbol{\mathcal{Y}}^1_{i} - \boldsymbol{\mathcal{Y}}^\prime_{c,i}\|^2 &\leq  \|{\mathcal{C}^{(21)}}^{\top}\|^2 \|\boldsymbol{\mathcal{Y}}^2_{i-1} - \boldsymbol{\mathcal{Y}}_{c,i-1}\|^2 \notag \\
    &\stackrel{(a)}{\leq} K_1 \|\mathcal{U}_L\|^2  \left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i}\right\|^2
    \end{align}
    where $(a)$ follows from Lemma \ref{lemma:plain_within} and \eqref{eq:C21}. 
\end{proof}

\begin{lemma}
\label{lemma:VRTG}
    Under Assumptions \ref{ass:within_conn}, \ref{ass:cross-conn_strong},  \ref{ass:lip}, \ref{ass:bdis}, \ref{ass:gradnoise}, for \textbf{ATC-C}, we have:
    \begin{align}
        &\mathbb{E} \{\|\mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{G}}^1_{x, i}\|^2\} \notag\\
        &\leq 8 \|\mathcal{V}_{R}^{\top}\|^2 L_f^2 \left(\|\mathcal{V}_{L} \|^2 \mathbb{E} \{\| \mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{X}}^1_{i-1} \|^2\} \right. \notag\\
        &\quad \left. + K_1 \|\mathcal{U}_L\|^2  \mathbb{E} \{\left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i-1}\right\|^2\}\right) + 2\|\mathcal{V}_{R}^{\top}\|^2 K_1 (2G^2 +\sigma^2)
    \end{align}
    and $\mathbb{E} \{\|\mathcal{U}_{R}^{\top} \boldsymbol{\mathcal{G}}^2_{y, i}\|^2\}$ can be bounded similarly. \hfill\qed
\end{lemma}

\begin{proof}
    For $k \in \mathcal{N}^{(1)}$, we define 
    \begin{align}
        \!\!\!\!\!\boldsymbol{s}_{k, i}^x &\triangleq \widehat{\nabla_x J}_k\left(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}\right) - \nabla_x J_k\left(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}\right) \\
        \!\!\!\!\!\mathcal{G}^1_{x, i} &\triangleq \text{col} \{\nabla_x J_k\left(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}\right)\}_{k=1}^{K_1}
    \end{align}
    We can bound $\|\mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{G}}^1_{x, i}\|^2$ by:
    \begin{equation}
    \label{eq:VRTG}
        \begin{aligned}
            &\|\mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{G}}^1_{x, i}\|^2 \\
            &= \left\|\mathcal{V}_{R}^{\top} \left( \mathcal{G}^1_{x, i} + \text{col}\{\boldsymbol{s}_{k, i}^x\}_{k=1}^{K_1}\right) \right\|^2 \\
            & \leq 2\|\mathcal{V}_{R}^{\top} \mathcal{G}^1_{x, i}\|^2 + 2\|\mathcal{V}_{R}^{\top} \text{col}\{\boldsymbol{s}_{k, i}^x\}_{k=1}^{K_1} \|^2 \\
            &\leq 2\|\mathcal{V}_{R}^{\top} \mathcal{G}^1_{x, i}\|^2 + 2\|\mathcal{V}_{R}^{\top}\|^2 \|\text{col}\{\boldsymbol{s}_{k, i}^x\}_{k=1}^{K_1} \|^2 \\
            % &=  2\|\mathcal{V}_{R}^{\top}\|^2 \sum_{k=1}^{K_1} \|\nabla_x J^{(1)}\left(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i}\right)\|^2 + 2\|\mathcal{V}_{R}^{\top}\|^2 \sum_{k=1}^{K_1} \|\boldsymbol{s}_{k, i}^x\|^2\\
            &= 2\|\mathcal{V}_{R}^{\top} \mathcal{G}^1_{x, i}\|^2 + 2 \|\mathcal{V}_{R}^{\top}\|^2 \sum_{k=1}^{K_1} \|\boldsymbol{s}_{k, i}^x\|^2
        \end{aligned}
    \end{equation}
    Now we take the conditional expectation of $\|\mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{G}}^1_{x, i}\|^2$, since $\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1} \in \boldsymbol{\mathcal{F}}_{i-1}$:
    \begin{equation}
    \label{EVRG}
        \mathbb{E} \{\|\mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{G}}^1_{x, i}\|^2 \mid \boldsymbol{\mathcal{F}}_{i-1}\} \leq 2\|\mathcal{V}_{R}^{\top} \mathcal{G}^1_{x, i}\|^2 + 2\|\mathcal{V}_{R}^{\top}\|^2 K_1 \sigma^2
    \end{equation}
    which follows from Assumption \ref{ass:gradnoise}. The key lies in how to upper bound $\|\mathcal{V}_{R_1}^{\top} \mathcal{G}^1_{x, i}\|^2$. Recall that $\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}$ denote the centroids of $x, y$ for Teams 1, 2 respectively. Then,
    \begin{equation}
    \label{eq:hardlemma1}
        \begin{aligned}
            &\|\mathcal{V}_{R}^{\top} \mathcal{G}^1_{x, i}\|^2 \\
            &= \|\mathcal{V}_{R}^{\top} \text{col}\{\nabla_x J_k\left(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}\right)\}_{k=1}^{K_1}\|^2 \\
            &\stackrel{(a)}{=} \|\mathcal{V}_{R}^{\top} \left(\text{col}\{\nabla_x J_k\left(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}\right)\}_{k=1}^{K_1} - \text{col}\{\nabla_x J_k\left(\boldsymbol{x}_{c, i-1}, \right. \right.\\
            & \quad \left. \left.\boldsymbol{y}_{c, i-1}\right)\}_{k=1}^{K_1} \right) + \mathcal{V}_{R}^{\top} \left( \text{col} \{\nabla_x J_k\left(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}\right)\}_{k=1}^{K_1} \right.\\
            & \left. \quad - (\mathbbm{1} {p^{(1)}}^{\top}) \otimes I_{M_1} \text{col} \{\nabla_x J_k\left(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}\right)\}_{k=1}^{K_1} \right)\|^2 \\
            &\leq 2\|\mathcal{V}_{R}^{\top}\|^2 \sum_{k=1}^{K_1} \|\nabla_x J_k\left(\boldsymbol{x}_{k, i-1}, \boldsymbol{y}_{k, i-1}\right) - \nabla_x J_k\left(\boldsymbol{x}_{c, i-1}, \right.\\
            & \left. \quad \boldsymbol{y}_{c, i-1}\right)\|^2 + 2\|\mathcal{V}_{R}^{\top}\|^2 \sum_{k=1}^{K_1} \|\nabla_x J_k\left(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}\right) \\
            & \quad - \nabla_x J^{(1)}\left(\boldsymbol{x}_{c, i-1}, \boldsymbol{y}_{c, i-1}\right)\|^2 \\
            &\stackrel{(b)}{\leq} 2\|\mathcal{V}_{R}^{\top}\|^2 \sum_{k=1}^{K_1} L_f^2 (\|\boldsymbol{x}_{k, i-1} - \boldsymbol{x}_{c, i-1}\| + \|\boldsymbol{y}_{k, i-1} - \boldsymbol{y}_{c, i-1}\|)^2 \\
            & \quad + 2\|\mathcal{V}_{R}^{\top}\|^2 K_1 G^2\\
            &\stackrel{(c)}{\leq} 2\|\mathcal{V}_{R}^{\top}\|^2 L_f^2 (2\|\boldsymbol{\mathcal{X}}^1_{i-1} - \boldsymbol{\mathcal{X}}_{c, i-1} \|^2 + 2\|\boldsymbol{\mathcal{Y}}^1_{i-1} - \boldsymbol{\mathcal{Y}}^{\prime}_{c,i-1}\|^2) \\
            & \quad + 2\|\mathcal{V}_{R}^{\top}\|^2 K_1 G^2
        \end{aligned}
    \end{equation}
    where $(a)$ follows from the fact that $V_R^{\top} \mathbbm{1} = 0$; $(b)$ follows from Assumption \ref{ass:lip} and \ref{ass:bdis}; $(c)$ follows from the inequality $(a+b)^2 \leq 2a^2 + 2b^2$ and the facts that $\sum_{k=1}^{K_1} \|\boldsymbol{x}_{k, i-1} - \boldsymbol{x}_{c, i-1}\|^2 = \|\boldsymbol{\mathcal{X}}^1_{i-1} - \boldsymbol{\mathcal{X}}_{c, i-1} \|^2$, $\sum_{k=1}^{K_1}\|\boldsymbol{y}_{k, i-1} - \boldsymbol{y}_{c, i-1}\|^2 = \|\boldsymbol{\mathcal{Y}}^1_{i-1} - \boldsymbol{\mathcal{Y}}^{\prime}_{c,i-1}\|^2$.
    By Lemmas \ref{lemma:plain_within} and \ref{lemma:plain_cross}, we can further bound \eqref{eq:hardlemma1} by:
    \begin{align}
    \label{eq:VRTG1}
        &\|\mathcal{V}_{R}^{\top} \mathcal{G}^1_{x, i}\|^2 \notag\\
        &\leq 2\|\mathcal{V}_{R}^{\top}\|^2 L_f^2 (2\|\boldsymbol{\mathcal{X}}^1_{i-1} - \boldsymbol{\mathcal{X}}_{c, i-1} \|^2 + 2\|\boldsymbol{\mathcal{Y}}^1_{i-1} - \boldsymbol{\mathcal{Y}}^{\prime}_{c,i-1}\|^2) \notag\\
        & \quad + 2\|\mathcal{V}_{R}^{\top}\|^2 K_1 G^2 \notag\\
        & \leq 2\|\mathcal{V}_{R}^{\top}\|^2 L_f^2 (2\|\mathcal{V}_{L} \|^2 \| \mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{X}}^1_{i-1} \|^2 + 2K_1 \|\mathcal{U}_L\|^2  \left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i-1}\right\|^2) \notag\\
        & \quad + 2\|\mathcal{V}_{R}^{\top}\|^2 K_1 G^2
    \end{align}
    Combining \eqref{eq:VRTG1} and \eqref{EVRG}, we get:
    \begin{align}
        &\mathbb{E} \{\|\mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{G}}^1_{x, i}\|^2\} \notag\\
        &\leq 8 \|\mathcal{V}_{R}^{\top}\|^2 L_f^2 \left(\|\mathcal{V}_{L} \|^2 \mathbb{E} \{\| \mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{X}}^1_{i-1} \|^2\} \right. \notag\\
        &\quad \left. + K_1 \|\mathcal{U}_L\|^2  \mathbb{E} \{\left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i-1}\right\|^2\}\right) + 2\|\mathcal{V}_{R}^{\top}\|^2 K_1 (2G^2 +\sigma^2)
    \end{align}
\end{proof}
\vspace{-1.5em}
\subsection{Main Proof}
\label{proof:lemma4}
This proof below is similar to the proof of Section \ref{proof:lemma2}. 
% We will also include a discussion section at the end to highlight the key differences between the main ideas of these two proofs.

By Lemmas \ref{lemma:plain_within} and \ref{lemma:plain_cross}, we have the following bound:
\begin{align}
\label{eq:plain_first}
    & \mathbb{E} \{\|\boldsymbol{\mathcal{X}}^1_{i} - \boldsymbol{\mathcal{X}}_{c,i}\|^2 + \|\boldsymbol{\mathcal{Y}}^2_{i} - \boldsymbol{\mathcal{Y}}_{c,i}\|^2 + \notag\\
    & \qquad \|\boldsymbol{\mathcal{X}}^2_{i} - \boldsymbol{\mathcal{X}}^\prime_{c,i}\|^2 + \|\boldsymbol{\mathcal{Y}}^1_{i} - \boldsymbol{\mathcal{Y}}^\prime_{c,i}\|^2\} \notag\\
    & \leq (1+K_1) \|\mathcal{V}_{L} \|^2 \mathbb{E} \{\| \mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{X}}^1_i \|^2\} \notag \\
    & \quad +(1+K_2)\|\mathcal{U}_L\|^2 \mathbb{E} \{ \left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i}\right\|^2\}
\end{align}
To bound $\| \mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{X}}^1_i \|^2$, we have:
 \begin{equation}
    \begin{aligned}
    \label{initial}
            &\| \mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{X}}^1_i \|^2 \\
            & = \|\mathcal{V}_{R}^{\top} {\mathcal{A}^{(1)}}^{\top} (\boldsymbol{\mathcal{X}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{x, i})\|^2 \\
            &\stackrel{(a)}{=} \|\mathcal{J}_{\varepsilon}^{\top} \mathcal{V}_{R}^{\top} (\boldsymbol{\mathcal{X}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{x, i})\|^2 \\
            & \leq \|\mathcal{J}_{\varepsilon}^{\top}\|^2 \|\mathcal{V}_{R}^{\top} (\boldsymbol{\mathcal{X}}^1_{i-1} - \mu \boldsymbol{\mathcal{G}}^1_{x, i})\|^2 \\
            & \stackrel{(b)}{\leq} \|\mathcal{J}_{\varepsilon}^{\top}\|^2 \left(\frac{1}{\left\|\mathcal{J}_{\varepsilon}^{\top}\right\|}\left\|\mathcal{V}_{R}^{\top}\boldsymbol{\mathcal{X}}^1_{i-1}\right\|^2 + \frac{1}{1-\left\|\mathcal{J}_{\varepsilon}^{\top}\right\|} \mu^2 \|\mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{G}}^1_{x, i}\|^2\right) \\
            & = \|\mathcal{J}_{\varepsilon}^{\top} \|\left\|\mathcal{V}_{R}^{\top}\boldsymbol{\mathcal{X}}^1_{i-1}\right\|^2 + \frac{\|\mathcal{J}_{\varepsilon}^{\top}\|^2}{1-\left\|\mathcal{J}_{\varepsilon}^{\top}\right\|} \mu^2 \|\mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{G}}^1_{x, i}\|^2
        \end{aligned}
    \end{equation}
    where  $(a)$ follows from steps similar to \eqref{eq:PRB}
    and $(b)$ follows from the convexity of $\|\cdot\|^2$ and Jensen's inequality, i.e. $\|a+b\|^2 \leq \frac{1}{\alpha} \|a\|^2 + \frac{1}{1-\alpha} \|b\|^2$.

     Therefore, by Lemma \ref{lemma:VRTG}, we obtain:
    \begin{equation}
    \label{hardlemma1_EVRX}
        \begin{aligned}
            &\mathbb{E} \{\|\mathcal{V}_R^{\top} \boldsymbol{\mathcal{X}}^1_i\|^2 \}\\
            & \leq
            \|\mathcal{J}_{\varepsilon}^{\top} \| \mathbb{E} \{\left\|\mathcal{V}_{R}^{\top}\boldsymbol{\mathcal{X}}^1_{i-1}\right\|^2\} + \frac{\|\mathcal{J}_{\varepsilon}^{\top}\|^2}{1-\left\|\mathcal{J}_{\varepsilon}^{\top}\right\|} \mu^2 \mathbb{E} \{\|\mathcal{V}_{R}^{\top} \boldsymbol{\mathcal{G}}^1_{x, i}\|^2\} \\
            &\leq       \left(\|\mathcal{J}_{\varepsilon}^{\top} \| + 8 \frac{\|\mathcal{V}_{L}^{\top}\|^2 \|\mathcal{J}_{\varepsilon}^{\top}\|^2 \|\mathcal{V}_{R}^{\top}\|^2}{1-\left\|\mathcal{J}_{\varepsilon}^{\top}\right\|} \mu^2  L_f^2\right) \mathbb{E} \{\left\|\mathcal{V}_{R}^{\top}\boldsymbol{\mathcal{X}}^1_{i-1}\right\|^2\} \\
        & \quad
        + 8 \frac{\|\mathcal{J}_{\varepsilon}^{\top}\|^2 \|\mathcal{V}_{R}^{\top}\|^2 \|\mathcal{U}_L\|^2}{1-\left\|\mathcal{J}_{\varepsilon}^{\top}\right\|} \mu^2  L_f^2 K_1 \mathbb{E} \{\|\mathcal{U}_R^{\top} \boldsymbol{\mathcal{Y}}^2_{i-1}\|^2 \} \\
        & \quad + 2 \frac{\|\mathcal{J}_{\varepsilon}^{\top}\|^2 \|\mathcal{V}_{R}^{\top}\|^2}{1-\left\|\mathcal{J}_{\varepsilon}^{\top}\right\|} \mu^2 K_1 (\sigma^2 + 2G^2)
        \end{aligned}
    \end{equation}

    Similarly, we obtain the following:
\begin{equation}
    \begin{aligned}
        &\mathbb{E} \{\left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i}\right\|^2\}\\
        & \leq
        \left(\left\|\mathcal{K}_{\gamma}^{\top}\right\| + 8 \frac{\|\mathcal{U}_{L}^{\top}\|^2 \|\mathcal{K}_{\gamma}^{\top}\|^2 \|\mathcal{U}_{R}^{\top}\|^2}{1-\left\|\mathcal{K}_{\gamma}^{\top}\right\|} \mu^2  L_f^2\right) \mathbb{E} \{\left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i-1}\right\|^2\} \\
        & \quad
        + 8 \frac{ \|\mathcal{K}_{\gamma}^{\top}\|^2 \|\mathcal{U}_{R}^{\top}\|^2 \|\mathcal{V}_{L}^{\top}\|^2}{1-\left\|\mathcal{K}_{\gamma}^{\top}\right\|} \mu^2  L_f^2 K_2 \mathbb{E} \{\left\|\mathcal{V}_{R}^{\top}\boldsymbol{\mathcal{X}}^1_{i-1}\right\|^2\} \\
        & \quad + 2 \frac{\|\mathcal{K}_{\gamma}^{\top}\|^2 \|\mathcal{U}_{R}^{\top}\|^2}{1-\left\|\mathcal{K}_{\gamma}^{\top}\right\|} \mu^2 K_2 (\sigma^2 + 2G^2) 
    \end{aligned}
\end{equation}
For compactness, we introduce the following scalar coefficients:
\begin{align}
    d_1 &= \frac{\|\mathcal{V}_{L}^{\top}\|^2 \|\mathcal{J}_{\varepsilon}^{\top}\|^2 \|\mathcal{V}_{R}^{\top}\|^2}{1-\left\|\mathcal{J}_{\varepsilon}^{\top}\right\|}\\
    e_1 &= \frac{\|\mathcal{J}_{\varepsilon}^{\top}\|^2 \|\mathcal{V}_{R}^{\top}\|^2 \|\mathcal{U}_L\|^2}{1-\left\|\mathcal{J}_{\varepsilon}^{\top}\right\|}\\
    f_1 &= \frac{\|\mathcal{J}_{\varepsilon}^{\top}\|^2 \|\mathcal{V}_{R}^{\top}\|^2}{1-\left\|\mathcal{J}_{\varepsilon}^{\top}\right\|}\\
    d_2 &= \frac{\|\mathcal{U}_{L}^{\top}\|^2 \|\mathcal{K}_{\gamma}^{\top}\|^2 \|\mathcal{U}_{R}^{\top}\|^2}{1-\left\|\mathcal{K}_{\gamma}^{\top}\right\|}\\
    e_2 &= \frac{ \|\mathcal{K}_{\gamma}^{\top}\|^2 \|\mathcal{U}_{R}^{\top}\|^2 \|\mathcal{V}_{L}^{\top}\|^2}{1-\left\|\mathcal{K}_{\gamma}^{\top}\right\|}\\
    f_2 &= \frac{\|\mathcal{K}_{\gamma}^{\top}\|^2 \|\mathcal{U}_{R}^{\top}\|^2}{1-\left\|\mathcal{K}_{\gamma}^{\top}\right\|}
\end{align}

Therefore, we have:
\begin{equation}
\label{eq:VRXURY}
    \begin{aligned}
        & \mathbb{E} \{\left\|\mathcal{V}_{R}^{\top}\boldsymbol{\mathcal{X}}^1_{i}\right\|^2\} + \mathbb{E} \{\left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i}\right\|^2\} \\
        &\leq (\|\mathcal{J}_{\varepsilon}^{\top} \| + 8 d_1 \mu^2  L_f^2 + 8 e_2 \mu^2  L_f^2 K_2) \mathbb{E} \{\left\|\mathcal{V}_{R}^{\top}\boldsymbol{\mathcal{X}}^1_{i-1}\right\|^2\} \\
        & \quad + (\left\|\mathcal{K}_{\gamma}^{\top}\right\| + 8 d_2 \mu^2  L_f^2 + 8 e_1 \mu^2 L_f^2 K_1) \mathbb{E} \{\left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i-1}\right\|^2\}\\
        & \qquad + 2 \mu^2 (f_1  K_1 + f_2 K_2) (\sigma^2 + 2G^2)\\
        & \stackrel{(a)}{\leq}
        \beta (\mathbb{E} \{\left\|\mathcal{V}_{R}^{\top}\boldsymbol{\mathcal{X}}^1_{i-1}\right\|^2\} + \mathbb{E} \{\left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i-1}\right\|^2\}) \\
        & \quad +  2 \mu^2 (f_1  K_1 + f_2 K_2) (\sigma^2 + 2G^2)
    \end{aligned}
\end{equation}
where $(a)$ uses the fact that, for sufficiently small $\mu$ and properly selected $\epsilon, \gamma$, we have:
\begin{align}
\label{eq:beta}
    \beta &= \max \{\|\mathcal{J}_{\varepsilon}^{\top} \| + 8 \mu^2 (d_1 + e_2 K_2) L_f^2,  \notag\\
    & \quad\left\|\mathcal{K}_{\gamma}^{\top}\right\| + 8 \mu^2 (d_2 + e_1 K_1) L_f^2\} < 1
\end{align}
Noting that $\|\mathcal{J}_{\varepsilon}^{\top} \| < 1$ is independent of $\mu$, we have $1 - \beta = O(1)$. Therefore, 
\begin{equation}
    \begin{aligned}
        &\mathbb{E} \{\left\|\mathcal{V}_{R}^{\top}\boldsymbol{\mathcal{X}}^1_{i}\right\|^2\} + \mathbb{E} \{\left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}^2_{i}\right\|^2\} \\
        & \leq
        \beta^{i+1} (\mathbb{E} \{\left\|\mathcal{V}_{R}^{\top}\boldsymbol{\mathcal{X}}_{-1}\right\|^2\} + \mathbb{E} \{\left\|\mathcal{U}_{R}^{\top}\boldsymbol{\mathcal{Y}}_{-1}\right\|^2\}) \\
        & \quad +  2 \mu^2 (f_1  K_1 + f_2 K_2) (\sigma^2 + 2G^2) \sum_{j=0}^{i} \beta^j \\
        & \stackrel{(a)}{\leq}
        O(\mu^2) + \frac{2 \mu^2 (f_1  K_1 + f_2 K_2) (\sigma^2 + 2G^2)}{1-\beta} \\
        & = O(\mu^2)
    \end{aligned}
\end{equation}
where $(a)$ holds when 
\begin{equation}
    \beta^i \leq O(\mu^2) \Longleftrightarrow i \geq i_\beta = \frac{\log \left(O\left(\mu^2\right)\right)}{\log \left(\beta\right)}
\end{equation}
By \eqref{eq:plain_first}, we conclude that:
\begin{align}
    & \mathbb{E} \{\|\boldsymbol{\mathcal{X}}^1_{i} - \boldsymbol{\mathcal{X}}_{c,i}\|^2 + \|\boldsymbol{\mathcal{Y}}^2_{i} - \boldsymbol{\mathcal{Y}}_{c,i}\|^2 + \\
    & \qquad \|\boldsymbol{\mathcal{X}}^2_{i} - \boldsymbol{\mathcal{X}}^\prime_{c,i}\|^2 + \|\boldsymbol{\mathcal{Y}}^1_{i} - \boldsymbol{\mathcal{Y}}^\prime_{c,i}\|^2\} \leq O(\mu^2)
\end{align}
when $i \geq i_\beta$.
\vspace{-0.3em}
\section{Proof of Lemma \ref{lemma:zerosum_learning_dynamic}}
\label{proof:lemma3}

As can be verified and already shown in \eqref{eq:centroid_x_evolution}, we have the following recursions for the centroids:
    \begin{align}
        \boldsymbol{x}_{c,i} &= \boldsymbol{x}_{c,i-1} - \mu \sum_{k \in \mathcal{N}^{(1)}} p_k \widehat{\nabla_x J}_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1})  \label{eq:learning_centroid_x}\\
        \boldsymbol{y}_{c,i} &= \boldsymbol{y}_{c,i-1} - \mu \sum_{k\in \mathcal{N}^{(2)}} p_{k} \widehat{\nabla_y J}_{k} (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}) \label{eq:learning_centroid_y}
    \end{align}
    Note that $p = [p^{(1)};p^{(2)}]$.
   Therefore, for $\boldsymbol{x}_{c,i}$ from (\ref{eq:learning_centroid_x}), we have:
   \begin{equation}
   \label{eq:learning_1}
        \begin{aligned}
            \!\!\!\!\!&\boldsymbol{x}_{c,i} = \boldsymbol{x}_{c,i-1} - \mu \sum_{k \in \mathcal{N}^{(1)}} p_k \nabla_x J_k (\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) \\
            & 
             +  \underline{\mu \sum_{k \in \mathcal{N}^{(1)}} p_k (\nabla_x J_k (\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - \nabla_x J_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}))}\\
            & 
            \underline{+  \mu \sum_{k \in \mathcal{N}^{(1)}} p_k (\nabla_x J_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}) - \widehat{\nabla_x J}_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}))}
        \end{aligned}   
   \end{equation}
   Let $\boldsymbol{d}^{(x)}_{c,i}$ denote the underlined terms. According to the relationship between $J^{(1)}(\cdot)$ and $J_k(\cdot)$ as shown in \eqref{eq:global_game_ya}, we can rewrite (\ref{eq:learning_1}) as 
   \begin{equation}
      \boldsymbol{x}_{c,i} = \boldsymbol{x}_{c,i-1} - \mu \nabla_x J^{(1)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c, i-1}) + \boldsymbol{d}^{(x)}_{c,i} 
   \end{equation}
   Next we show that $\mathbb{E} \{\|\boldsymbol{d}^{(x)}_{c,i}\|^2\} \leq O(\mu^2)$. Indeed:
   \begin{equation}
   \label{eq:d_ki}
       \begin{aligned}
           & \mathbb{E} \{\|\boldsymbol{d}^{(x)}_{c,i}\|^2\}\\
           & \stackrel{(a)}{\leq}
           2 \mu^2 \sum_{k \in \mathcal{N}^{(1)}} p_k \mathbb{E} \{\|\nabla_x J_k (\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - \nabla_x J_k (\boldsymbol{x}_{k,i-1}, \\
           & \quad \boldsymbol{y}_{k,i-1})\|^2\} 
           + 2 \mu^2 \sum_{k \in \mathcal{N}^{(1)}} p_k \mathbb{E} \{\|\nabla_x J_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}) \\
           & \quad -  \widehat{\nabla_x J}_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1})\|^2\}\\
           & \stackrel{(b)}{\leq}
           2 \mu^2 \sum_{k \in \mathcal{N}^{(1)}} p_k L_f^2 \mathbb{E} \{2 \|\boldsymbol{x}_{c,i-1} - \boldsymbol{x}_{k,i-1}\|^2 + 2 \|\boldsymbol{y}_{c,i-1} \\
           & \quad - \boldsymbol{y}_{k,i-1}\|^2\} 
           + 2 \mu^2 \sum_{k \in \mathcal{N}^{(1)}} p_k \sigma^2 \\
           &\stackrel{(c)}{\leq}
           4 \mu^2 L_f^2 O(\mu^2) +  2 \mu^2 \sigma^2 \\
           &= 
           O(\mu^2)
       \end{aligned}
   \end{equation}
   where $(a)$ follows from Jensen's inequality $\|a+b\|^2 \leq 2\|a\|^2 + 2\|b\|^2$; $(b)$ follows from Assumption \ref{ass:lip} and Assumption \ref{ass:gradnoise}: $\mathbb{E} \{\|\nabla_x J_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}) - \widehat{\nabla_x J}_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1})\|^2 \mid \boldsymbol{\mathcal{F}}_{i-1}\} \leq \sigma^2$; $(c)$ follows from Lemmas \ref{lemma:zerosum_within_cross}.

   We will show similar results for $\boldsymbol{y}_{c,i}$ from (\ref{eq:learning_centroid_y}) in the following. After some calculation, we get:
   \begin{equation}
   \label{eq:learning_2}
        \begin{aligned}
            & \boldsymbol{y}_{c,i-1} = \boldsymbol{y}_{c,i} - \mu \sum_{k\in \mathcal{N}^{(2)}} p_k \nabla_y J_k (\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) \\
            &
            + \underline{\mu \sum_{k \in \mathcal{N}^{(2)}} p_k (\nabla_y J_k (\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - \nabla_y J_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}))}\\
            &
            \underline{+ \mu \sum_{k\in \mathcal{N}^{(2)}} p_k (\nabla_y J_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}) - \widehat{\nabla_y J}_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}))}
        \end{aligned}   
   \end{equation}
   Let $\boldsymbol{d}_{c,i}^{(y)}$ denote the underlined terms. From the relationship between $J^{(2)}$ and $J_k$ as shown in \eqref{eq:global_game_yb}, we can easily show: $\boldsymbol{y}_{c,i} = \boldsymbol{y}_{c,i-1} - \mu  \nabla_y J^{(2)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) + \boldsymbol{d}_{c,i}^{(y)}$. What remains is to
   show $\mathbb{E} \{\|\boldsymbol{d}_{c,i}^{(y)}\|^2\} \leq O(\mu^2)$:
   \begin{equation}
       \begin{aligned}
           & \mathbb{E} \{\|\boldsymbol{d}_{c,i}^{(y)}\|^2\}\\
           & \leq
           2 \mu^2 \sum_{k\in \mathcal{N}^{(2)}} p_k \mathbb{E} \{\|\nabla_y J_k (\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - \nabla_y J_k (\boldsymbol{x}_{k,i-1}, \\
           & \quad \boldsymbol{y}_{k,i-1})\|^2\}
           + 2 \mu^2 \sum_{k\in \mathcal{N}^{(2)}} p_k \mathbb{E} \{\|\nabla_y J_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}) \\
           & \quad - \widehat{\nabla_y J}_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1})\|^2\} \\
           & \leq
           2 \mu^2 \sum_{k\in \mathcal{N}^{(2)}} p_k L_f^2 \mathbb{E} \{2 \|\boldsymbol{x}_{c,i-1} - \boldsymbol{x}_{k,i-1}\|^2 + 2 \|\boldsymbol{y}_{c,i-1} \\
           & \quad - \boldsymbol{y}_{k,i-1}\|^2\} + 2 \mu^2 \sum_{k\in \mathcal{N}^{(2)}} p_k \sigma^2 \\
           &\stackrel{(a)}{\leq}
           4 \mu^2 L_f^2 O(\mu^2) +  2 \mu^2 \sigma^2 \\
           &= 
           O(\mu^2)
       \end{aligned}
   \end{equation}
    where $(a)$ follows from Lemma \ref{lemma:zerosum_within_cross}. Now we define 
    \begin{equation}
    \label{definition_Dci}
        \boldsymbol{d}_{c,i} \triangleq \left[\begin{array}{c}
             \boldsymbol{d}^{(x)}_{c,i} \\
             \boldsymbol{d}_{c,i}^{(y)} 
        \end{array}\right]
    \end{equation}
    We arrive at the conclusion that $\mathbb{E} \{\|\boldsymbol{d}_{c,i}\|^2\} \leq O(\mu^2)$, after sufficient iterations (i.e., $i \geq i_\alpha$ for \textbf{ATC-ITC}, $i \geq i_\beta$ for \textbf{ATC-C}).
\vspace{-0.4em}
\section{Proof of Theorem \ref{thm:zerosum_conv}}
\label{proof:thm1}
From Assumption \ref{ass:lip}, we have: 
    \begin{equation}
    \label{eq:operator_lip}
        \|F(z_1) - F(z_2)\| \leq 2L_f \|z_1 -z_2\|
    \end{equation}
    We set $L \triangleq 2L_f$. From Lemma \ref{lemma:zerosum_learning_dynamic}, we have after sufficient iterations:
    \begin{equation}
        \begin{aligned} 
            & \mathbb{E} \{\left\|\boldsymbol{z}_{c,i}-z^{\star}\right\|^2\} \\ 
            & =
            \mathbb{E} \{\left\|\boldsymbol{z}_{c,i-1}-\mu F\left(\boldsymbol{z}_{c,i-1}\right) + \boldsymbol{d}_{c,i} - z^{\star}\right\|^2\} \\
            & =
            \mathbb{E} \{\left\|\boldsymbol{z}_{c,i-1}-\mu F\left(\boldsymbol{z}_{c,i-1}\right)-z^{\star}\right\|^2\} \\
            & \quad + 2\mathbb{E}\{\langle \boldsymbol{z}_{c,i-1}-\mu F\left(\boldsymbol{z}_{c,i-1}\right)-z^{\star}, \boldsymbol{d}_{c,i}\rangle\} + \mathbb{E}\{\left\|\boldsymbol{d}_{c,i}\right\|^2\}
        \end{aligned}\label{eq:convg_nash}
    \end{equation}
    The key lies in upper bounding the term $2\mathbb{E}\{\langle \boldsymbol{z}_{c,i-1}-\mu F\left(\boldsymbol{z}_{c,i-1}\right)-z^{\star}, \boldsymbol{d}_{c,i}\rangle\}$.
    From Lemma \ref{lemma:zerosum_learning_dynamic}, we have:

    \begin{equation}
        \begin{aligned}
            &2\mathbb{E}\{\langle \boldsymbol{z}_{c,i-1}-\mu F\left(\boldsymbol{z}_{c,i-1}\right)-z^{\star}, \boldsymbol{d}_{c,i}\rangle\} \\
            & = 
            2\mathbb{E}\{\langle \boldsymbol{x}_{c,i-1}- \mu \nabla_x J^{(1)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - x^{\star}, \boldsymbol{d}^{(x)}_{c,i}\rangle\} \\
            & \quad+ 2\mathbb{E}\{\langle \boldsymbol{y}_{c,i-1} - \mu \nabla_y J^{(2)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - y^{\star}, \boldsymbol{d}_{c,i}^{(y)}\rangle\}
        \end{aligned}
    \end{equation}
    We will only show the derivation for the first term, as the derivation for the second is nearly the same. Recall that
    \begin{equation}
        \begin{aligned}
            \boldsymbol{d}^{(x)}_{c,i} =& \mu \sum_{k \in \mathcal{N}^{(1)}} p_k (\nabla_x J_k (\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) -\nabla_x J_k (\boldsymbol{x}_{k,i-1},\\
            &\boldsymbol{y}_{k,i-1})) + \mu \sum_{k \in \mathcal{N}^{(1)}} p_k (\nabla_x J_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}) \\
            &- \widehat{\nabla_x J}_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}))
        \end{aligned}
    \end{equation}
    Then, we have:
    \begin{equation}
        \begin{aligned}
            & 2\mathbb{E}\{\langle \boldsymbol{x}_{c,i-1}- \mu \nabla_x J^{(1)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - x^{\star}, \boldsymbol{d}^{(x)}_{c,i}\rangle \mid \boldsymbol{\mathcal{F}}_{i-1}\}\\
            & \stackrel{(a)}{=} 2 \langle \boldsymbol{x}_{c,i-1}- \mu \nabla_x J^{(1)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - x^{\star}, \\
            & \quad \mu \sum_{k \in \mathcal{N}^{(1)}} p_k (\nabla_x J_k (\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - \nabla_x J_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}))\rangle \\
            & \stackrel{(b)}{=}
            2 \mu \delta \langle \boldsymbol{x}_{c,i-1}- \mu \nabla_x J^{(1)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - x^{\star}, \\
            &\quad \frac{1}{\delta} \sum_{k \in \mathcal{N}^{(1)}} p_k (\nabla_x J_k (\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - \nabla_x J_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}))\rangle \\
            % & \leq
            % \mu \delta \|\boldsymbol{x}_{c,i-1}- \mu \nabla_x J^{(1)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - x^{\star}\|^2\\
            % & 
            % \qquad + \frac{\mu}{\delta} \sum_{k \in \mathcal{N}^{(1)}} p_k \|(\nabla J_k (\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - \nabla J_k (\boldsymbol{x}_{k,i-1}, \boldsymbol{y}_{k,i-1}))\|^2 \\
            & \stackrel{(c)}{\leq}
            \mu \delta \|\boldsymbol{x}_{c,i-1}- \mu \nabla_x J^{(1)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - x^{\star}\|^2\\
            & 
            \quad + \frac{\mu}{\delta} \sum_{k \in \mathcal{N}^{(1)}} p_k L_f^2 (\|\boldsymbol{x}_{c,i-1} - \boldsymbol{x}_{k,i-1}\| + \|\boldsymbol{y}_{c,i-1} - \boldsymbol{y}_{k,i-1}\|)^2
        \end{aligned}
    \end{equation}
    where $(a)$ follows from Assumption \ref{ass:gradnoise}; $(b)$ introduces a fixed constant $\delta > 0$ that can be chosen independently from $\mu$, for example $\delta = \nu$; $(c)$ follows from Assumption \ref{ass:lip}. Then, after sufficient iterations:
    \begin{equation}
        \begin{aligned}
            & 2\mathbb{E}\{\langle \boldsymbol{x}_{c,i-1}- \mu \nabla_x J^{(1)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - x^{\star}, \boldsymbol{d}^{(x)}_{c,i}\rangle \} \\
            & \leq
            \mu \delta \mathbb{E}\{\|\boldsymbol{x}_{c,i-1}- \mu \nabla_x J^{(1)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - x^{\star}\|^2\}\\
            & 
            \quad + \frac{\mu}{\delta} \sum_{k \in \mathcal{N}^{(1)}} p_k L_f^2 (2 \mathbb{E}\{\|\boldsymbol{x}_{c,i-1} - \boldsymbol{x}_{k,i-1}\|^2\} \\
            & \quad + 2\mathbb{E}\{\|\boldsymbol{y}_{c,i-1} - \boldsymbol{y}_{k,i-1}\|^2\}) \\
            & \stackrel{(a)}{\leq}
            \mu \delta \mathbb{E}\{\|\boldsymbol{x}_{c,i-1}- \mu \nabla_x J^{(1)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - x^{\star}\|^2\} \\
            & \quad + O\Big(\frac{\mu^3}{\delta}\Big)
        \end{aligned}
    \end{equation}
    where $(a)$ is due to Lemma \ref{lemma:zerosum_within_cross}. Also considering $2\mathbb{E}\{\langle \boldsymbol{y}_{c,i-1} - \mu \nabla_y J^{(2)}(\boldsymbol{x}_{c,i-1}, \boldsymbol{y}_{c,i-1}) - y^{\star}, \boldsymbol{d}_{c,i}^{(y)}\rangle\}$, we arrive at the following:
    \begin{equation}
        \begin{aligned}
            &2\mathbb{E}\{\langle \boldsymbol{z}_{c,i-1}-\mu F\left(\boldsymbol{z}_{c,i-1}\right)-z^{\star}, \boldsymbol{d}_{c,i}\rangle\}\\
            & \leq
            \mu \delta \mathbb{E} \{\|\boldsymbol{z}_{c,i-1}-\mu F\left(\boldsymbol{z}_{c,i-1}\right)-z^{\star}\|^2\} + O\Big(\frac{\mu^3}{\delta}\Big)
        \end{aligned}
    \end{equation}
    In addition, we have $\mathbb{E}\{\left\|\boldsymbol{d}_{c,i}\right\|^2\} \leq O(\mu^2)$. Therefore, going back to $ \mathbb{E} \{\left\|\boldsymbol{z}_{c,i}-z^{\star}\right\|^2\}$, we get:
    \begin{equation}
        \begin{aligned}
            &\mathbb{E} \{\left\|\boldsymbol{z}_{c,i}-z^{\star}\right\|^2\} \\
            & \leq 
            (1+\delta \mu)\mathbb{E} \{\left\|\boldsymbol{z}_{c,i-1}-\mu F\left(\boldsymbol{z}_{c,i-1}\right)-z^{\star}\right\|^2\} + O(\mu^2) \\
            & \leq 
            (1+\delta \mu)\left(1-2 \mu \nu+L^2 \mu^2\right) \mathbb{E}\{\left\|\boldsymbol{z}_{c,i-1}-z^{\star}\right\|^2\} + O\left(\mu^2\right)
        \end{aligned}
    \end{equation}
    where the last step is due to the following:
    \begin{equation}
        \begin{aligned}
            & \left\|\boldsymbol{z}_{c,i-1}-\mu F\left(\boldsymbol{z}_{c,i-1}\right)+\mu F\left(z^{\star}\right)-z^{\star}\right\|^2\\
            & = 
            \left\|\boldsymbol{z}_{c,i-1}-z^{\star}\right\|^2-2 \mu\left\langle F\left(\boldsymbol{z}_{c,i-1}\right)-F\left(z^{\star}\right), \boldsymbol{z}_{c,i-1} - z^{\star}\right\rangle\\
            &\quad +\mu^2\left\|F\left(\boldsymbol{z}_{c,i-1}\right)-F\left(z^{\star}\right)\right\|^2 \\ 
            & \stackrel{(a)}{\leq}
            \left\|\boldsymbol{z}_{c,i-1}-z^{\star}\right\|^2-2 \mu \nu\left\|\boldsymbol{z}_{c,i-1}-z^{\star}\right\|^2 \\
            & \quad +L^2 \mu^2\left\|\boldsymbol{z}_{c,i-1}-z^{\star}\right\|^2 \\ 
            & =
            \left(1-2 \mu \nu+L^2 \mu^2\right)\left\|\boldsymbol{z}_{c,i-1}-z^{\star}\right\|^2
        \end{aligned}
    \end{equation}
    where $(a)$ follows from Assumption 1 and (\ref{eq:operator_lip}). Now our goal is to choose a proper $\delta$ to make $(1+\delta \mu)\left(1-2 \mu \nu+L^2 \mu^2\right) <1$ when $\mu$ is sufficiently small. A reasonable choice is $\delta = \nu$, let $h(\mu) \triangleq (1+\nu \mu)\left(1-2 \mu \nu+L^2 \mu^2\right)$. We find $h(0) = 1$, $h^\prime(0) = -\nu$, which means when $\mu$ is sufficiently small, we can always ensure $(1+\delta \mu)\left(1-2 \mu \nu+L^2 \mu^2\right) <1$. Specifically, we can get: 
    \begin{equation}
        h(\mu) = 1 - \nu \mu + \left(L^2 - 2 \nu^2\right) \mu^2 + \nu L^2 \mu^3
    \end{equation}
    To let $h(\mu) < 1$, we need:
    \begin{equation}
        - \nu \mu + \left(L^2 - 2 \nu^2\right) \mu^2 + \nu L^2 \mu^3 < 0
    \end{equation}
    By simple algebra, the above inequality is satisfied when 
    \begin{equation}
    \label{eq:mu_range}
        \mu \in \left( 0, \; \dfrac{ - L^2 + 2 \nu^2 + \sqrt{ L^4 + 4 \nu^4 } }{ 2 \nu L^2 } \right)
    \end{equation}
    Therefore, just set $\delta = \nu$, we obtain that after sufficient iterations:
    \begin{equation}
        \mathbb{E} \left[\|\boldsymbol{z}_{c,i} - z^\star\|^2\right] \leq 
        d \, \mathbb{E}\left[\|\boldsymbol{z}_{c,i-1} - z^\star\|^2\right] + O\left(\mu^2\right)
    \end{equation}
    where $d \leq (1+\nu \mu)\left(1-2 \mu \nu+L^2 \mu^2\right)$, and we can ensure $d<1$ when $\mu$ is sufficiently small (e.g. \eqref{eq:mu_range}). We can conclude that:

\vspace{-2em}
        \begin{align}
            \limsup_{i \rightarrow \infty} \mathbb{E}\{\|\boldsymbol{z}_{c,i} - z^{\star}\|^2\} 
            &\leq 
            \frac{O\left(\mu^2\right)}{1 - (1+\delta \mu)\left(1-2 \mu \nu+L^2 \mu^2\right)}\notag\\
            & =
            \frac{O\left(\mu^2\right)}{\mu \nu - (L^2 - 2\nu^2) \mu^2 - L^2 \nu \mu^3} \notag\\
            & =
            O(\mu)
        \end{align}

