\section{Preliminaries}\label{sec:preliminaries}
\subsection{Ideals and varieties}\label{sect:background}
Let $\Field$ denote an arbitrary field (for the applications of this paper $\Field=\mathbb{Q}$). Let $\Field[X]$ be the ring of polynomials over a field $\Field$ and the set of indeterminates $X=\{x_1,\ldots, x_n\}$. Let $\Field[X]_d$ denote the subspace of polynomials of degree at most $d$.%The most commonly used fields will be: $\Real$, $\Complex$, $\Int$ and $\Rational$.
%%%%%%%%%%%%%%%%%%%%%%
%\paragraph{Ideals.}
%%%%%%%%%%%%%%%%%%%%%%

\begin{definition}\label{def:ideal}
The ideal (of $\Field[X]$) generated by a finite set of polynomials $\{f_1,\dots, f_m\}$ in $\Field[X]$ is defined as
\[\Ideal{ f_1,\ldots,f_m}:= \left\{\sum_{i=1}^m h_i f_i\mid h_1,\ldots,h_m\in \Field[X]\right\}.\] 

The set of polynomials that vanish on a given set $S\subset \Field^n$ is called the \textbf{\emph{vanishing ideal}} of $S$ and is defined as
$\Ideal{S}:= \{f\in \Field[X]\mid f(a_1,\ldots,a_n)=0, \forall (a_1,\ldots,a_n)\in S\}$.
\end{definition}

\begin{definition}
An ideal $I$ is \textbf{\emph{radical}} if $f^m \in I$ for some integer $m\geq 1$ implies that $f\in  I$.
\end{definition}

Other ways to denote $\Ideal{ f_1,\ldots,f_m}$ is by $\Ideal{ \{f_1,\ldots,f_m\}}$, $\langle f_1,\ldots,f_m \rangle$ and $\langle \{ f_1,\ldots,f_m\} \rangle$, and we will use notations interchangeably.
%
%
%
\begin{definition}\label{def:V(I)}
Let $\{f_1,\ldots, f_m\}$ be a finite set of polynomials in $\Field[X]$. The \textbf{\emph{affine variety}} defined by $f_1,\ldots, f_m$ is
$\Variety{ f_1,\ldots,f_m}:= \{(a_1,\ldots,a_n)\in \Field^n|\; f_i(a_1,\ldots,a_n)=0, \quad 1\leq i\leq m\}$.
%
Let $I\subseteq \Field[X]$ be an ideal. We will denote by $\mathbf{V}(I)$ the set $\Variety{I}=\{(a_1,\ldots,a_n)\in \Field^n\mid f(a_1,\ldots,a_n)=~0, \quad \forall f\in I\}$.
\end{definition}

\begin{theorem}[\cite{Cox}, Th.15, p.196]\label{th:ideal_intersection}
  If $I$ and $J$ are ideals in $\Field[X]$, then $\Variety{I\cap J}= \Variety{I}\cup \Variety{J}$.
\end{theorem}

\begin{definition}\label{def:ideal_sum}
  If $I$ and $J$ are ideals in $\Field[X]$, then the sum of $I$ and $J$, denoted by $I+J$, is the ideal $I+J=\{f+g\mid f\in I \textrm{ and } g\in J\}$.
\end{definition}

\begin{corollary}[\cite{Cox}, Cor.3, p.190] \label{cor:ideal_sum}
    If $f_1,\dots,f_r \in \Field[X]$, then $\langle f_1,\dots, f_r \rangle = \langle f_1 \rangle + \dots + \langle f_r \rangle$.

\end{corollary}

\begin{theorem}[\cite{Cox}, Th.4, p.190]\label{th:ideal_sum}
  If $I$ and $J$ are ideals in $\Field[X]$, then $\Variety{I+J}= \Variety{I}\cap \Variety{J}$.
\end{theorem}

\subsection{CSP and polymorphisms}\label{sec:CSPandpolymorphisms} 
Let $D$ denote a finite set called the  \textbf{\emph{domain}}.
By a $k$-ary \textbf{\emph{relation}} $R$ on a domain $D$ we mean a subset of the $k$-th Cartesian power $D^k$; $k$ is said to be the \textbf{\emph{arity}} of the relation. We often use relations and (affine) varieties interchangeably since both are subsets of $D^k$ (we will not refer to varieties from universal algebra in this paper). A \textbf{\emph{constraint language}} $\Gamma$ over $D$ is a finite set of relations over $D$. A constraint language is 
%\textbf{\emph{finite}} if it contains finitely many relations, and is 
\textbf{\emph{Boolean}} if it is over the two-element domain $\{0,1\}$. %In this paper, $D$ is the 3-element domain $\{0,1,2\}$.

A \emph{\textbf{constraint}} over a constraint language $\Gamma$ is an expression of the form $R(x_{i_1},\ldots, x_{i_k})$ where $R$ is a relation of arity $k$ contained in $\Gamma$, and $x_{i_1},\ldots, x_{i_k}$ are variables that belong to the variable set $X$. A constraint is satisfied by a mapping $\phi:X\rightarrow D$ if $(\phi(x_{i_1}),\ldots, \phi(x_{i_k}))\in R$.

\begin{definition}\label{def:csp}
 The \emph{(nonuniform) \textsc{Constraint Satisfaction Problem} ($\CSP$)} associated with language $\Gamma$ over $D$ is the problem $\CSP(\Gamma)$ in which: an instance is a triple $\Cc=(X,D,C)$ where $X=\{x_1,\ldots,x_n\}$ is a set of $n$ variables and $C$  is a set of constraints over $\Gamma$ with variables from $X$. The goal is to decide whether or not there exists a solution, i.e.~a mapping $\phi: X\rightarrow D$ satisfying all of the constraints. We will use $Sol(\Cc)\subseteq D^n$ to denote the set of solutions of $\Cc$.
\end{definition}
Moreover, we follow the algebraic approach to Schaefer's dichotomy result \cite{Schaefer78} formulated by Jeavons \cite{JEAVONS1998185} where each class of CSPs that are polynomial time solvable is associated with a polymorphism.
\begin{definition}\label{def:polymorph}
An operation $f:D^m \rightarrow D$ is a \textbf{polymorphism} of a relation $R\subseteq D^k$ if for any choice of $m$ tuples $(t_{11},\dots,t_{1k}),\dots,(t_{m1},\dots,t_{mk})$ from $R$ (allowing repetitions), it holds that the tuple obtained from these $m$ tuples by applying $f$ coordinate-wise, $(f(t_{11},\dots,t_{m1}),\dots,f(t_{1k},\dots,t_{mk}))$, is in $R$. We also say that $f$ \textbf{preserves} $R$, or that $R$ is \textbf{invariant} or \textbf{closed} with respect to $f$. A polymorphism of a constraint language $\Gamma$ is an operation that is a polymorphism of every $R\in \Gamma$.
\end{definition}
In this paper, we deal with two particular polymorphisms: the Boolean minority (\cref{def:minority}) and the dual discriminator (\cref{def:dual discriminator}).
\begin{example}\label{example:CSP}
Consider $D=\{0,1,2\}$ and relations $R_1=\{(0,1,1),(2,0,2),(2,2,1), (2,0,1)$, $(2,1,1)\}$ and $R_2=\{(1,1),(2,1)\}$. Let the language $\Gamma = \{R_1,R_2\}$. Consider the instance $\mathcal{C}=(X,D,C)$ of $\CSP(\Gamma)$ with $X=\{x,y,z\}$ and $C=\{C_1 = R_1 (x,y,z),C_2= R_2(x,z)\}$. The assignment $\phi$ where $\phi(x)=2, \phi(y)= 0, \phi(z)=1$ is a solution to the instance $\mathcal{C}$. 
\end{example}

