\subsection{\GB bases}\label{sect:GBbasics}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% The most commonly used fields will be: $\Real$, $\Complex$, $\Int$ and $\Rational$.
%We will use the following terminology (see \cite{Cox:2015}).
A monomial ordering $>$ on $\Field[X]$ is a total ordering on the set of all monomials in $\Field[X]$, that is invariant under multiplication (i.e.~if $a > b$ and $c$ is any other monomial then $ac>bc$, see~\cite{Cox}, Definition 1, p.55).
%
We identify the monomial $x^\alpha=x_1^{\alpha_1}\cdots x_n^{\alpha_n}$ with the $n$-tuple of exponents $\alpha =(\alpha_1,\ldots,\alpha_n)\in \Zz^n_{\geq0}$. This establishes a one-to-one correspondence between the monomials in $\Field[X]$ and $\Zz^n_{\geq0}$. Any ordering $>$ we establish on the space $\Zz^n_{\geq0}$
will give us an ordering on monomials: if $\alpha > \beta$ according to this ordering, we also say that $x^\alpha > x^\beta$. The monomial ordering that we use in this paper is the graded lexicographic ordering.% $>_\grlex$. %(mostly denoted by $>$ in this paper).

\begin{definition}\label{def:lex and grlex} Let $\alpha =(\alpha_1,\ldots,\alpha_n),\beta=(\beta_1,\ldots,\beta_n)\in \Zz^n_{\geq0}$ and $|\alpha| = \sum_{i=1}^n\alpha_i$, $|\beta| = ~\sum_{i=1}^n\beta_i$.
  \begin{enumerate}[(i)]
      \item Lexicographic order: We say $\alpha>_\lex \beta$ if, in the vector difference $\alpha -\beta \in \Zz^n$, the left most nonzero entry is positive. 
      \item Graded lexicographic order: We say $\alpha>_\grlex \beta$ if $|\alpha| >|\beta|$, or $|\alpha| =|\beta|$ and $\alpha>_\lex \beta$.

  \end{enumerate}
\end{definition}

\begin{definition}
  For any $\alpha=(\alpha_1,\ldots,\alpha_n)\in \Zz^n_{\geq0}$, let $x^\alpha:= \prod_{i=1}^{n}x_i^{\alpha_i}$. Let $f= \sum_{\alpha} a_{\alpha}x^\alpha$ be a nonzero polynomial in $\Field[X]$ and let $>$ be a monomial order (in this paper, this is always the \grlex order).
  \begin{enumerate}[(i)]

    \item The \textbf{\emph{multidegree}} of $f$ is $\multideg(f):= \max(\alpha\in \Zz^n_{\geq0}:a_\alpha\not = 0)$.
    \item The \textbf{\emph{degree}} of $f$ is deg$(f):=\sum_{i=1}^n \alpha_i$, where $(\alpha_1,\ldots,\alpha_n)=\multideg(f)$. 
    \item The \textbf{\emph{leading coefficient}} of $f$ is $\LC(f):= a_{\multideg(f)}\in \Field$.
    \item The \textbf{\emph{leading monomial}} of $f$ is $\LM(f):= x^{\multideg(f)}$ (with coefficient 1).
    \item The \textbf{\emph{leading term}} of $f$ is $\LT(f):= \LC(f)\cdot \LM(f)$.
  \end{enumerate}
\end{definition}
%In order to compute the \GB basis we will use the following known results and definitions. We refer to standard books (see e.g. \cite{becker1993grobner,Cox:2007}) for full details.
%

The concept of \emph{reduction}, also called \emph{multivariate division} or \emph{normal form computation}, is central to \GB basis theory. It is a multivariate generalization of the Euclidean division of univariate polynomials.


\begin{definition}\label{def:reduction}
Fix a monomial order and let $G=\{g_1,\ldots,g_t\}\subset \Field[X]$. Given $f\in \Field[X]$, we say that \emph{\textbf{$f$ reduces to $r$ modulo $G$}}, written
$f\rightarrow_G r$,
if $f$ can be written in the form
$f=A_1g_1+\dots+A_t g_t+r$ for some $A_1,\ldots,A_t,r\in \Field[X]$,
such that:
\begin{enumerate}[(i)]
  \item no term of $r$ is divisible by any of $\LT(g_1),\ldots,\LT(g_t)$ and 
  \item whenever $A_i g_i\not=0$, we have $\multideg(f)\geq \multideg(A_ig_i)$.
\end{enumerate}
The polynomial remainder $r$ is called a \emph{\textbf{normal form of $f$ by $G$}} and will be denoted by $f|_G$.
\end{definition}

A normal form of $f$ by $G$, i.e.~$f|_G$, can be obtained by repeatedly performing the following until it cannot be further applied: choose any $g\in G$ such that $\LT(g)$ divides some term $t$ of $f$ and replace $f$ with $f-\frac{t}{\LT(g)}g$. Note that the order we choose the polynomials $g$ in the division process is not specified.
%
In general a normal form $f|_G$ is not uniquely defined.
Even when $f$ belongs to the ideal generated by $G$, i.e.~$f\in \Ideal{G}$, it is not always true that $f|_G=0$. In particular, the order in which polynomial division is performed is important, as the following example shows.
%
\begin{example}
  Let $f=xy^2-y^3$ and $G=\{g_1,g_2\}$, where $g_1=xy-1$ and $g_2=y^2-1$. Consider the graded lexicographic order (with $x>y$). If we divide first by $g_2$ the quotient is $(x-y)$ and the remainder is $(x-y)$; the latter is not divisible by $g_1$: $f = 0\cdot g_1 + (x-y)\cdot g_2 + x-y$. Vice versa, if we divide first by $g_1$ and then by $g_2$ we obtain a zero remainder: $f = y\cdot g_1 - y\cdot g_2 + 0$.
%  \end{align*}
 % From the first equation we see that the corresponding normal form of $f$ by $G$ is zero and therefore $f\in \Ideal{G}$. The normal form of $f$ by $G$ in the second equation is not zero.
\end{example}
%
%
This non-uniqueness is the starting point of \GB basis theory.
%
\begin{definition}
Fix a monomial order on the polynomial ring $\Field[X]$. A finite subset $G = \{g_1,\ldots, g_t\}$ of an ideal $I \subseteq \Field[X]$ different from $\{0\}$ is said to be a \emph{\textbf{\GB basis}} (or \emph{\textbf{standard basis}}) if
$\langle \LT(g_1),\ldots, \LT(g_t)\rangle = \langle \LT(I)\rangle$, where we denote by $\langle \LT(I)\rangle$ the ideal generated by the elements of the set $\LT(I)$ of leading terms of nonzero elements of $I$.
\end{definition}
\begin{definition}\label{def:redGB}
The \textbf{\emph{reduced \GB basis}} of a polynomial ideal $I$ is a \GB basis $G$ of $I$ such that:
\begin{enumerate}[(i)]
  \item $\LC(g)= 1$ for all $g \in G$ and
  \item for all $g \in G$, no monomial of $g$ lies in $\GIdeal{\LT(G\setminus \{g\})}$.
\end{enumerate}
\end{definition}
%
It is known (see~\cite{Cox}, Theorem~5, p.93) that for a given monomial ordering, a polynomial ideal $I\not=\{0\}$ has a unique reduced \GB basis. %(see Definition~\ref{def:redGB}), and the reduced \GB basis is unique.
%
\begin{proposition}[\cite{Cox}, Proposition~1, p.83]\label{th:gbprop}
Let $I\subset \Field[X]$ be an ideal and let $G=\{g_1,\ldots,g_t\}$ be a \GB basis for $I$. Then given $f\in \Field[X]$, $f$ can be written in the form
$f=A_1g_1+\dots+A_t g_t+r$ for some $A_1,\ldots,A_t,r\in \Field[X]$,
such that:
\begin{enumerate}[(i)]
  \item no term of $r$ is divisible by any of $\LT(g_1),\ldots,\LT(g_t)$,
  \item whenever $A_i g_i\not=0$, we have $\multideg(f)\geq \multideg(A_ig_i)$ and
  \item $r$ is unique.
\end{enumerate}
%
In particular, $r$ is the remainder on division of $f$ by $G$ no matter how the elements of $G$ are listed when using the division algorithm.%\footnote{For the description of the division algorithm we refer to~\cite{Cox:2015}, p.61.}.
\end{proposition}
%
\begin{corollary}[\cite{Cox}, Corollary~2, p.84]\label{th:imp}
  Let $G=\{g_1,\ldots,g_t\}$ be a \GB basis for $I\subseteq \Field[X]$ and let $f\in \Field[X]$. Then $f\in I$ if and only if the remainder on division of $f$ by $G$ is zero.
\end{corollary}
%
\begin{definition}\label{def:pdiv}
We will write $\reduce f F$ for the remainder of $f$ by the ordered $s$-tuple $F=(f_1,\ldots,f_s)$. If $F$ is a $\GB$ basis for $\spn{f_1,\dots,f_s}$, then we can regard $F$ as a set (without any particular order) by Proposition~\ref{th:gbprop}.
\end{definition}
%

%\begin{definition}
%A \textbf{remainder} of a polynomial $f\in \Field[x_1,\ldots,k_n]$ on division by set $F=\{f_1,\ldots,f_s\}$ of polynomials from $\Field[x_1,\ldots,k_n]$, denoted by $f|_F$, is computed by repeatedly performing the following until it cannot be further applied: Choose any $i \in \{1, . . . ,s\}$ such that $\LT(f_i)$ divides some term $\tau$ of $f$ and set $f := f - \frac{\tau}{\LT(f_i)}f_i$.
%\end{definition}
%
The ``obstruction'' to $\{g_1,\ldots, g_t\}$ being a \GB basis is the possible occurrence of polynomial combinations of $g_i$ whose leading terms are not in the ideal generated by the $\LT( g_i)$. One way (actually the only way) this can occur is if the leading terms in a suitable combination cancel, leaving only smaller terms. The latter is fully captured by the so called $S$-polynomials that play a fundamental role in \GB basis theory.
%
\begin{definition}\label{def:spoly}
Let $f,g\in \Field[X]$ be nonzero polynomials. Let $\multideg(f)$  $=\alpha$ and $\multideg(g)=\beta$, with $\gamma=(\gamma_1,\ldots,\gamma_n)$, where $\gamma_i = \max(\alpha_i,\beta_i)$ for each $i$. We call $x^\gamma$ the \emph{\textbf{least common multiple}} of $\LM(f)$ and $\LM(g)$, written $x^\gamma = \LCM(\LM(f),\LM(g))$.
The \emph{\textbf{$S$-polynomial}} of $f$ and $g$ is the combination $S(f,g) = \frac{x^\gamma}{\LT(f)}\cdot f - \frac{x^\gamma}{\LT(g)}\cdot g$.
\end{definition}
%
The use of $S$-polynomials to eliminate leading terms of multivariate polynomials generalizes the row reduction algorithm for systems of linear equations. If we take a system of homogeneous linear equations (i.e.: the constant coefficient equals zero), then it is not hard to see that bringing the system in triangular form yields a \GB basis for the system.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}[\textbf{Buchberger's Criterion}] (See e.g. \cite{Cox}, Theorem 3, p.105)\label{th:crit}
A basis $G=\{g_1,\ldots,g_t\}$ for an ideal $I$ is a \GB basis if and only if $S(g_i,g_j)|_G= 0$ for all $i\not=j$.
\end{theorem}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
By Theorem~\ref{th:crit} it is easy to show whether a given basis is a \GB basis. Indeed, if $G$ is a \GB basis then given $f\in \Field[X]$, $f|_G$ is unique and it is the remainder on division of $f$ by $G$, no matter how the elements of $G$ are listed when using the division algorithm.
Furthermore, Theorem~\ref{th:crit} leads naturally to an algorithm for computing \GB bases for a given ideal $I=\langle f_1,\ldots,f_s \rangle$: start with a basis $G=\{f_1,\ldots,f_s\}$ and for any pair $f,g\in G$ with $S(f,g)|_G\not= 0$ add $S(f,g)|_G$ to $G$.
This is known as Buchberger's algorithm~\cite{BUCHBERGER2006475} (for more details see \cite[p. 90]{Cox} or \cite[Algorithm 1]{mastrolilli_talg21}).
%
In the remainder of the paper we will make repeated use of the following simple fact~\cite[Proposition 4 p. 106]{Cox}.
\begin{proposition}\label{th:rel_prime}
    We say the leading monomials of two polynomials $f$, $g$ are \emph{relatively prime} if $\LCM(\LM(f), \LM(g)) = \LM(f) \cdot \LM(g)$. Given a finite set $G \subseteq \Field[x_1,\ldots,x_n]$, suppose that we have $f, g \in G$ such that the leading monomials of $f$
and $g$ are relatively prime. Then $S(f, g)|_G= 0$.
\end{proposition}
%
Note that Buchberger's algorithm is non-deterministic and the resulting \GB basis in not uniquely determined by the input. This is because the normal form $S(f,g)|_G$ (see \cite[Algorithm 1, line 8]{mastrolilli_talg21}) is not unique as already remarked.
%
%
We observe that one simple way to obtain a deterministic algorithm (see \cite{Cox}, Theorem~2, p. 91) is to replace $h:=S(f,g)|_G$ in \cite[Algorithm 1, line 8]{mastrolilli_talg21} with $h:=\reduce {S(f,g)} {G''}$ (see Definition~\ref{def:pdiv}), where in the latter $G''$ is an ordered tuple. However, there are simple cases where the combinatorial growth of the set $G$ in Buchberger's algorithm is out of control very soon.



