\subsection{Complete and two-fan constraints}\label{sec:completeandtwofan}
A complete constraint is of the form $R(x_i,x_j)$ where $R=D_i\times D_j$  for some $D_i,D_j \subseteq D$. The polynomials that can represent these constraints are $\prod_{a\in D_i} (x_i-a)$ and $\prod_{b\in D_j} (x_j-b)$. We call these polynomials \textit{partial domain polynomials}. If no such input explicitly exists for a variable, the domain polynomial in that variable itself is the partial domain polynomial. A two-fan constraint is of the form $R(x_i,x_j)$ where $R=\{(\{a\}\times D_j)\cup (D_i\times \{b\})\}$ for some $D_i,D_j \subseteq D$ with $a\in D_i,b\in D_j$. This constraint can be represented by the set of polynomials  $\{(x_i-a)(x_j-b),\prod_{c\in D_i} (x_i-c), \prod_{d\in D_j} (x_j-d)\}$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{definition}\label{def:DFL}
 The set of polynomials $\ca{D}$, $\ca{F}$ and $\ca{L}$ is defined as follows: 
 \begin{align*}
    \mathcal{D} &= \{\Pi_{a\in A} (x_i-a)\mid i\in [n], A\subseteq D\},\\
    \mathcal{F} &= \{(x_i-a)(x_j-b)\mid i,j\in [n],i\neq j\},\\
    \mathcal{L} &=  \{x_i-\alpha_2 - (x_j-\beta_2)(\alpha_1-\alpha_2)/(\beta_1-\beta_2) \mid i,j\in [n],i\neq j \},
\end{align*}
for all $a,b,\alpha_1,\alpha_2,\beta_1,\beta_2\in D$ where $\alpha_1\neq \alpha_2$ and $\beta_1\neq \beta_2$.
\end{definition}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In other words $\ca{D}\cup\ca{F}$ is the set of all complete constraints and two-fan constraints and $\ca{L}$ is the set of polynomials in two variables that pass through two points $(\alpha_1,\beta_1),(\alpha_2,\beta_2)\in D^2$ where $\alpha_1\neq \alpha_2$ and $\beta_1\neq \beta_2$. Let $G\subset \ca{D}\cup\ca{F}$ be the set of polynomials that describes the input complete constraints and two-fan constraints of an instance of $\IMP_d(\Gamma)$. Let $I_{\CF}=\GIdeal{G}$ (combinatorial ideal for the Complete and two-Fan constraints). 
Recall that the constraints for $\nabla$-closed problems can be assumed to be binary \cite{Jeavons:1997:CPC} and are of three types: permutation constraints, complete constraints and two-fan constraints \cite{szendrei,Jeavons1994_Characterising_tract_constraints}. Then
%
\begin{equation*}
   \I_\Cc = \sum_{i\in J}I_{\CPC_i} + I_\CF = \sum_{i\in J}I_{\CPC_i} + \GIdeal{G}. 
\end{equation*}

\begin{lemma}\label{lem:red GB of D union F}
The reduced \GB basis of $I_\CF$ can be calculated in polynomial time and is a subset of $\ca{D}\cup\ca{F}\cup\ca{L}$.
\end{lemma}
\begin{proof}
The proof follows by a case analysis. Some cases have already been considered in \cite[Lemma 5.16]{bulatov2020complexity} and in \cite[Section 3, Case 2]{bharathi_et_al:MFCS2020}, and in the following we will refer to those references for brevity of discussion.

For any pair $f,g\in G$, we show that there are polynomials $H \subset \GIdeal{G}$ such that $H\subset \ca{D}\cup\ca{F}\cup\ca{L}$ and $\reduce{S(f,g)}{H}=0$. We then include these polynomials in $G$, i.e.~$G:=G\cup H$. We dismiss the cases where $\LM(f)$ and $\LM(g)$ are relatively prime (see \cref{th:rel_prime}). 

The cases already considered in \cite[Lemma 5.16]{bulatov2020complexity} are when:
\begin{itemize}
    \item $f,g\in\ca{F}$ where $f = (x_i-a)(x_j-b)$, $g = (x_i-c)(x_k -d)$ for $a=c$ and $a\neq c$,
    \item $f\in\ca{D},g\in\ca{F}$ where $f = \Pi_{a\in D_i} (x_i-a)$, $g = (x_i -c)(x_j - b)$ and $c\in D_i$.
\end{itemize}

We now consider the remaining cases. When a polynomial $h\in\ca{L}$ is added to $G$, we reduce all polynomials in $G$ by $h$ and therefore no other polynomial in $G$ contains $\LM(h)$.
\begin{enumerate}
    \item Suppose $f\in\ca{D},g\in\ca{F}$ where $f=\Pi_{a\in D_i}(x_i-a)$, $g=(x_i-c)(x_j-b)$ and $c\notin D_i$. 
    Every common zero of $f$ and $g$ has to satisfy $x_j = b$ (since $x_i=c$ is not feasible).
    This implies $x_j-b \in \GIdeal{G}$. Since this polynomial can divide $g$, we replace $g$ with $x_j-b$ instead and continue with the Buchberger's algorithm. With this new $g$, $\reduce{S(f,g)}{\{f,g\}}=0$ since the leading monomials are relatively prime (see \cref{th:rel_prime}). 
    \item Suppose $f,g\in\ca{F}$, where $f=(x_i-a)(x_j-b)$ and $g=(x_i-c)(x_j-d)$. If $a\neq c$ and $b\neq d$, then $R=\{(a,d),(c,b)\}$ is the set of solutions to both $f$ and $g$.
    The constraint $R(x_i,x_j)$ is a new permutation constraint and is added to $\ca{P}$. We run \cref{alg:BuildingCPC} again to update CPC's or create one.
    A \GB basis for the ideal $\GIdeal{f,g}$ is $H=\{(x_i-a)-\frac{c-a}{b-d}(x_j-d),(x_i-a)(x_i-c),(x_j-b)(x_j-d)\}$ (see \cite[Section 3, Case 2]{bharathi_et_al:MFCS2020}) and therefore $H\subset \ca{D}\cup\ca{F}\cup\ca{L}$. 
    The $S$-polynomial $S(f,g)=(d-b)x_i+(c-a)x_j+ab-cd$, hence $\reduce{S(f,g)}{H}=0$. Note that after running \cref{alg:BuildingCPC}, $x_i,x_j\in X_k$ for some $k\in J$. So, the linear polynomial in $H$ belongs to $I_{\CPC_k}$.
    If $a=c$ and $b\neq d$, then the S-polynomial is $S(f,g)=x_i(d-b)+a(b-d)=(d-b)(x_i-a)$ and $H=\{x_i-a\}$. 
    %Similarly, the other cases when $f(x_i,x_j),g(x_i,x_j)\in\ca{F}\cup\ca{L}$ are straightforward: the points of intersection can be at most two and the reduced \GB basis of $\GIdeal{f,g}$ is a subset of $\ca{D}\cup\ca{L}$. Whenever the points of intersection are two, the corresponding permutation constraint is added to $\ca{P}$ and \cref{alg:BuildingCPC} is run.
    \item Suppose $f\in \ca{D}\cup\ca{F}\cup\ca{L}$ and $g\in \ca{L}$. The polynomials $f$ and $g$ are relatively prime since if $g$ were to belong to $G$, then no other polynomial contains $\LM(g)$. This implies $\reduce{S(f,g)}{\{f,g\}}=0$.
\end{enumerate}

Hence, the $S$-polynomial for every two polynomials in $G$ is such that there are polynomials in $I_\CF$ that belong to $\ca{D}\cup\ca{F}\cup\ca{L}$ that reduce the $S$-polynomial to zero. In fact, it is not difficult to see that the reduced \GB basis is also a subset of $\ca{D}\cup\ca{F}\cup\ca{L}$. Since $|\ca{D}\cup\ca{F}\cup\ca{L}|=O(n^2)$, the reduced \GB basis of $I_\CF$ can be calculated in polynomial time.
\end{proof}
