Deg>>   20   8  39  18  49  15  30  19  16  12   6   8
\end{lstlisting}

In Python:
\begin{lstlisting}[language=python]
bd_sym_all = bd_sym_u1_a.combineBond(bd_sym_u1_c,is_grp=False)
print(bd_sym_all)
\end{lstlisting}


