         |         |    
         -----------    

RuntimeError: 
# Cytnx error occur at virtual void cytnx::BlockUniTensor::Add_(const cytnx::Scalar&)
# error: [ERROR] cannot perform elementwise arithmetic '+' btwn Scalar and BlockUniTensor.
 This operation will destroy block structure. [Suggest] using get/set_block(s) to do operation on the block(s). 
'''

\end{lstlisting}

