\end{equation}
where the second index in the subscript of $\mathbf{\mf}_{l,t}$ denotes the $t$-th transmission interval of the \gls{mf} output $\mathbf{\mf}_{l}$. 

Let us denote the transmit signal matrix of \gls{ap} $l$ by
\begin{equation}
	\bar{\mathbf{X}}_{l}^{(i)} = 
	\begin{bmatrix} \bar{\mathbf{x}}_{l,1}^{(i)}&\ldots&\bar{\mathbf{x}}_{l,M_i}^{(i)}
	\end{bmatrix}
	\in\complexm{M}{M_i},\quad i\in\{1,2\},\label{eqn:Xbarmat}
\end{equation}
 where $\bar{\mathbf{x}}_{l,m}^{(i)}\in\complexm{M}{1}$ corresponds to the $((m-1)M+1)$-th to the $mM$-th entries of $\mathbf{x}_{l}^{(i)}$ given in \eqref{eqn:Phase1Data} (on top of \bluez{this} page) and \eqref{eqn:Phase2Data}. Note that $\bar{\mathbf{x}}_{l,M_i}^{(i)}$, $i\in\{1,2\}$ are zero padded if $M$ is not an integer multiple of $\frac{K(K+1)}{2}$ and $\tauu K$ for $i=1$ and $i=2$, respectively. We present the \gls{ota} framework to coherently combine the local sufficient statistics transmitted by the \glspl{ap} at the \gls{cpu}.

The received signal at the \gls{cpu} is given by
\begin{align}
	\mathbf{Z}^{(i)} = \sqrt{\eta_{\rm c}^{(i)}}\sum_{l=1}^L  \mathbf{G}_l^H\mathbf{W}_l         \bar{\mathbf{X}}_{l}^{(i)} + \mathbf{E}^{(i)}\in\complexm{M}{M_i},\label{eqn:RxSig1_CPU}%\vspace{-2mm}
\end{align}
where $i\in\{1,2\}$ denotes the index of the two transmission phases of the \glspl{ap} to send their local sufficient statistics, $\mathbf{G}_l^H\in\complexm{M}{N}$ is the channel between the $l$-th \gls{ap} and the \gls{cpu}, $\mathbf{W}_l\in\complexm{N}{M}$ is the transmit precoder of the  $l$-th \gls{ap}, $\eta_{\rm c}^{(i)}$ is a common power assignment scaling factor of the \glspl{ap} to satisfy the average transmit power constraint
\begin{equation}\label{eq:APsPowConstraints}
    \eta_{\rm c}^{(i)} \expectL{\norm{\mathbf{W}_l\bar{\mathbf{X}}_{l}^{(i)}}^2_F} \leq P_{\rm max},
\end{equation}
where $\expectL{\cdot}$ represents the expectation of its argument with respect to all the associated random variables, $P_{\rm max}$ denotes the transmit power constraint for all the \glspl{ap}, and $\mathbf{E}^{(i)}$ is the additive noise at the \gls{cpu} with independent and identically entries distributed as $\CN{0}{\sigma^2}$~\cite{rouphael2014wireless}.

%{We consider that the \glspl{ap} obtain their respective fronthaul \gls{csi} using a pilot transmission from the \gls{cpu}. Further, we assume that the \gls{cpu} \bluez{need} not have access to any \gls{csi}.} \textcolor{red}{(Emil wanted to include motivation as to why CPU cannot obtain CSI. Maybe we can connect with the BLUE and LMMSE estimators and tell that the number of antennas at the CPU cannot scale with the number of APs?)} 

The \glspl{ap} obtain their fronthaul \gls{csi} to the \gls{cpu} using received pilot signals sent by the \gls{cpu}. \colr{Note that there is no need for pilot signals transmitted on orthogonal channels in order for the APs to obtain \gls{csi}. By exploiting reciprocity
of the AP-CPU channel, it is sufficient that the CPU broadcasts a pilot that is heard by all APs; based on this pilot, the APs estimate the CPU$\to$AP channels, which by virtue of reciprocity equal the APs$\to$CPU channels. } For ease of exposition, we assume that the fronthaul \gls{csi} available at the \glspl{ap} are perfect and have full column rank.% (assuming \glspl{ap} and the \gls{cpu} are stationary)
\footnote{In next-generation cell-free \gls{mimo} wireless systems, \glspl{ap} can be low-cost nodes strategically deployed by network planners. Consequently, the channels to the \gls{cpu} undergo rich scattering, supporting the assumption of full column rank.} 
We discuss the imperfect \gls{csi} scenario in Section~\ref{sec:impCSI}. Now to obtain the sum of the local sufficient statistics, each \gls{ap} first equalizes the effect of $\mathbf{G}_l$ using local \gls{zf} precoders ${\mathbf{W}_l = \mathbf{G}_l\left(\mathbf{G}_l^H \mathbf{G}_l\right)^{-1}\in\complexm{N}{M}}$, $l\in[L]$, where the $[\cdot]$ operator denotes the set of all integers from $1$ to its argument.

We recall that our goal is to compute $\sum_{l=1}^{L}\bar{\mathbf{X}}_{l}^{(i)}$, and although \gls{zf} precoding removes the effects of the channels between the \glspl{ap} and the \gls{cpu}, any unequal power scaling at the \glspl{ap} will result in residual scaling factors which are impossible to remove \gls{ota}. To circumvent this unequal power scaling problem, we propose an average transmit power assignment strategy at the \glspl{ap} to communicate with the \gls{cpu}.% as follows.

The total energy expended by the $l$-th \gls{ap} during the $M_1$ and $M_2$ symbol intervals is
%\vspace{-4mm}
\begin{align}
	\Omega_l^{(i)} &= \eta_{\rm c}^{(i)}\,\sum_{t=1}^{M_i} \expectL{\norm{\mathbf{W}_l\bar{\mathbf{x}}_{l,t}^{(i)}}^2},\label{eqn:ForPowerConstraint}
	%&=\rho_{\rm c}^{(i)}\,\trace{\expectL{\mathbf{W}_l^H\mathbf{W}_l}\sum_{t=1}^{M_i}\expectL{\bar{\mathbf{x}}_{l,t}^{(i)} {\bar{\mathbf{x}}_{l,t}^{(i)^H}}} }\label{eqn:ForPowerConstraint1}\\
	%&=\eta_{\rm c}^{(i)}\, \trace{\left(\mathbf{I}_{M_i}\otimes\expectL{\mathbf{W}_l^H\mathbf{W}_l}\right)\expectL{{\mathbf{x}}_{l}^{(i)} {{\mathbf{x}}_{l}^{(i)^H}}} },
\end{align}
where $i\in\{1,2\}$.\footnote{To obtain \eqref{eqn:ForPowerConstraint}, we assume that $\frac{K(K+1)}{2}$ and $\tauu K$ are multiples of $M$. However, we can handle the general case with a minor modification.} We use two separate scaling mechanisms for transmitting the Gramian and the \gls{mf} outputs from the \glspl{ap} to the \gls{cpu} to accommodate for the differences in their dynamic ranges. % \textcolor{blue}{ of symbol magnitudes}. 
Note that the \gls{mf} output has $p_{\rm ul}$ embedded inside, which changes its dynamic range compared to that of the Gramian matrix. Therefore, it is imperative to employ this two-phase power assignment strategy.

The values of $\Omega_l^{(1)}$ and $\Omega_l^{(2)}$ can be computed using the corresponding mean and covariance matrices of the sufficient statistics which we will discuss subsequently. %in { Appendix~\ref{appendxStats}}.
Therefore, the average transmit power of the $l$-th \gls{ap} to transmit the Gramian matrices and the \gls{mf} outputs of one coherence interval is
\begin{align}
	P_{l}^{(i)} = \frac{\Omega_l^{(i)}}{M_i},\qquad i\in\{1,2\}.\label{eqn:AvgTransPower}
\end{align}

We propose a low overhead feedback mechanism\footnote{\colr{The proposed feedback mechanism aligns with standardized uplink and downlink control signaling in \gls{lte} and 5G-NR~\cite{3GPP_TS_38_211}.}} to compute the common power scaling factors $\eta_{\rm c}^{(1)}$ and $\eta_{\rm c}^{(2)}$ at the \gls{cpu} (to assist in the coherent addition of the sufficient statistics at the \gls{cpu}) and broadcast it to the \glspl{ap} via a common control channel to satisfy their average transmit power constraints {\eqref{eq:APsPowConstraints}}. \colr{A small amount of control signaling between the CPU and APs is required (e.g., for power control purposes, when the large-scale fading changes) and  this signaling may advantageously take place on dedicated orthogonal channels. However, in practice, overall the amount of resources required for this will be small.}

For $i\in\{1,2\}$, each \gls{ap} sets $\eta_{\rm c}^{(i)}$ equal to $1$, computes the scalar value in \eqref{eqn:AvgTransPower} using the locally available statistics and conveys it to the \gls{cpu} using a dedicated control channel. %Since the channels between the \glspl{ap} and the \gls{cpu} are relatively invariant for a large interval, the overhead associated with sending these scalar values is very low. 
This can be done after the pilot transmissions from the \gls{cpu} to the \glspl{ap}. Upon receiving $\{P_{1}^{(i)}, \ldots, P_{L}^{(i)}\}$, $i\in\{1,2\}$, the \gls{cpu} obtains the indices of the \glspl{ap} which violate the constraint. Let us include these indices in the sets $\mathcal{V}^{(i)} = \{i_1^{(i)}, \ldots, i_{L'^{(i)}}^{(i)}\}\subseteq\{1,\ldots,L\}$, where $L'^{(i)}$, $i\in\{1,2\}$, is the number of \glspl{ap} in it. Then the scaling factors are computed as
\begin{align}
    \eta_{\rm c}^{(i)} = \frac{P_{\rm max}}{\max_{j\in\mathcal{V}^{(i)}} P_{j}^{(i)}},\qquad i\in\{1,2\}.\label{eqn:computescalefactor1}
\end{align}

This ensures that every \gls{ap} satisfies its average transmit power constraint and is necessary to add the sufficient statistics coherently at the \gls{cpu}. Otherwise, the \gls{cpu} will receive an {unequally} weighted sum of sufficient statistics.

Substituting $\mathbf{W}_l = \mathbf{G}_l\left(\mathbf{G}_l^H \mathbf{G}_l\right)^{-1}$ into the received signal \eqref{eqn:RxSig1_CPU}, the \gls{cpu} receives the signal
\begin{equation}
	\mathbf{Z}^{(i)} \triangleq \begin{bmatrix}
		\mathbf{z}_1^{(i)}&\ldots&\mathbf{z}_{M_i}^{(i)}
	\end{bmatrix}= \sqrt{\eta_{\rm c}^{(i)}}\sum_{l=1}^{L}\bar{\mathbf{X}}_{l}^{(i)} + \mathbf{E}^{(i)},%\vspace{-2mm}
\end{equation}
where $i\in\{1,2\}$, $\{\mathbf{z}_1^{(i)},\ldots,\mathbf{z}_{M_i}^{(i)}\}$ are the columns of $\mathbf{Z}^{(i)}$ and $\bar{\mathbf{X}}_{l}^{(i)}$ is given in \eqref{eqn:Xbarmat}. We define the \gls{snr} from the \glspl{ap} to the \gls{cpu} in two phases by
\begin{comment}
 \begin{align}
    \rho_{\rm c}^{(1)} &= \frac{\eta_c^{(1)} \expectL{\norm{\mathbf{H}^H\mathbf{H}}^2}}{K^2\sigma^2}\\
    \rho_{\rm c}^{(2)} &= \frac{\eta_c^{(2)} \expectL{\norm{\mathbf{H}^H\mathbf{y}}^2}}{K\sigma^2}
\end{align}   
\end{comment}
 \begin{align}
    \rho_{\rm c}^{(1)} &= \frac{\eta_c^{(1)} \expectL{\norm{\mathbf{\gram}}^2}}{K^2\sigma^2},\\
    \rho_{\rm c}^{(2)} &= \frac{\eta_c^{(2)} \expectL{\norm{\mathbf{\mf}}^2}}{K\sigma^2}.
\end{align}  
%\newline

