% 	\end{bmatrix}^T,\\ %;\quad \bar{\boldsymbol{\mu}}_{t}^{(i)} = \expectL{\sum_{l=1}^{\numAPs}\bar{\mathbf{x}}_{l,t}^{(i)}}\\
% 	%\mathbf{C}^{(i)} &= {\rm blkdiag}(\bar{\mathbf{C}}_{1}^{(i)},\ldots,\bar{\mathbf{C}}_{M_i}^{(i)});
% 	&\expectL{\left(\sum_{l=1}^{\numAPs}\bar{\mathbf{x}}_{l,t}^{(i)}-\bar{\boldsymbol{\mu}}_{t}^{(i)}\right)\left(\sum_{l=1}^{\numAPs}\bar{\mathbf{x}}_{l,t}^{(i)}-\bar{\boldsymbol{\mu}}_{t}^{(i)}\right)^H}\triangleq\bar{\mathbf{C}}_{t}^{(i)}.
% \end{align}
Then, the \gls{lmmse} estimate of $\sum_{l=1}^L \bar{\mathbf{x}}_{l,m}^{(i)}$, $i\in\{1,2\}$ (denoted by $\widehat{\bar{\mathbf{x}}}_m^{(i)}$), for $m\in[M_i],\ i\in\{1,2\}$ is% given by
\begin{align}\label{eqn:LMMSEestimatSuffStats}
	\widehat{\bar{\mathbf{x}}}_m^{(i)} =\bar{\boldsymbol{\mu}}_m^{(i)} + \sqrt{\eta_{\rm c}^{(i)}}\bar{\mathbf{C}}_m^{(i)}&\left({\eta_{\rm c}^{(i)}}\bar{\mathbf{C}}_m^{(i)} + \sigma^2\mathbf{I}_{M}\right)^{-1}\nonumber\\
    &\times\left(\mathbf{z}_m^{(i)} - \sqrt{\eta_{\rm c}^{(i)}}\bar{\boldsymbol{\mu}}_m^{(i)}\right).
\end{align}
