\subsection{Mathematical Formulation}\label{sec:math_formulation}\vspace{-0.1cm}
Let the overall training be divided into discrete rounds \(t = 1, 2, \dots\). We aim to learn a policy that adaptively assigns the split index \(\varphi(i)\) with constraints $R_i$ and $T_i$ (ref. Eq.~\eqref{eq:main_obj}).

\subsubsection{State Space}
At round $t$, the state of the device \(d_i\) is:
\vspace{-0.2cm}
\begin{equation}
\vspace{-0.2cm}
s_i^t \;=\;\bigl(R_i^t,\,T_i^t,\,\mathcal{P}_i^t\bigr),
\label{eq:state_space}
\end{equation}
\noindent where $R_i^t$ and $T_i^t$ represent the available computational resources and time window, respectively, for device \(d_i\), dedicated to local training in round \(t\), and $\mathcal{P}_i^t$ encapsulates partial model performance metric % or relevant performance metrics 
for the client-side model.

After each round, the environment (\textit{ReinDSplit} plus the device’s local conditions) transitions \(s_i^t \to s_i^{t+1}\) based on the chosen action \(a_i^t\) and the resource--time consumption of training, as highlighted in Fig.~\ref{overview}.

\subsubsection{Action Space}
At each round \(t\), device \(d_i\) selects an action \(a_i^t\) from the finite set $\mathcal{A}_i = \bigl\{\,1,\,2,\,\dots,\,K\bigr\},$ where each integer \(k \in \{1,\dots,K\}\) indicates choosing the split pair \(\bigl(\mathcal{M}_C^k,\,\mathcal{M}_S^k\bigr)\) for local processing. Here, \(a_i^t\!=\!k\) determines how many layers are executed on the client versus the server, thus dictating the local resource--time burden. 

\subsubsection{Reward Function}\label{subsubsec:reward}
Upon taking action \(a_i^t\) in state \(s_i^t\), the agent receives an immediate reward \(r_i^t\). We design \(r_i^t\) to balance classification performance and resource--time feasibility, aligning with the objective formulated in \eqref{eq:main_obj}:

\begin{equation}
% \vspace{-0.15cm}
\small
\label{eq:reward_function}
r_i^t =
\begin{cases}
\displaystyle
\alpha\,\text{Acc}\bigl(\varphi(i)\bigr)
-\beta\,
\Bigl(
\max\{0,\;R_{\text{required}}(\mathcal{M}_C^{\varphi(i)})-R_i^t\} \\
\hspace{20pt}+\max\{0,\;T_{\text{required}}(\mathcal{M}_C^{\varphi(i)})-T_i^t\}
\Bigr), 
& \hspace{-0.75cm} \text{if feasible}, \\[2pt]
\displaystyle
-\gamma\,(\text{penalty}), & \hspace{-0.75cm} \text{otherwise}
\end{cases}
% \vspace{-0.15cm}
\end{equation}

where \(\alpha\), \(\beta\), and \(\gamma\) are nonnegative weighting parameters. The term \(\text{Acc}(\varphi(i))\) captures the classification accuracy for the chosen split, while the penalty terms reflect deficits in resources or time. Infeasible actions incur a direct penalty to discourage unworkable split assignments.

\subsubsection{RL Objective}
Each device \(d_i\) seeks a policy \(\pi_i\colon s_i^t \mapsto a_i^t\) that maximizes its discounted cumulative reward:
% \vspace{-0.15cm}
\begin{equation}
% \vspace{-0.15cm}
\max_{\pi_i} \quad \mathbb{E}_{\pi_i}\Bigl[\sum_{t=0}^{\infty}\,\delta^t\,r_i^t\Bigr],
\label{eq:rl_objective}
\end{equation}
where \(\delta \in [0,1]\) is discount factor. The Q-function \(Q_i^\pi(s, a)\) is approximated via a DQN, updated iteratively to converge to an optimal policy \(\pi_i^{*}\). This occurs for all devices in \(\mathcal{H}\).%, potentially with coordination by the server.

By penalizing or rewarding local splitting decisions, \textit{ReinDSplit} allocates deeper model segments to nodes with ample computational resources, while resource-constrained devices offload heavier workloads to a centralized server, eliminating conventional SL strategies' ``same-split-fits-all" limitation for heterogeneous scenarios with various applications such as the pest recognition system. Additionally, \textit{ReinDSplit} maintains raw image data onsite, preserving privacy and enabling large-scale deployment across geographically dispersed farms. 
We provide the pseudocode of \textit{ReinDSplit} in Algorithm~\ref{alg:ReinDSplit_insect_monitoring} as Appendix.

\section{Theoretical Analysis}\label{theoretical_ana}
This section develops a theoretical foundation for \emph{straggler mitigation} and \emph{convergence} of our \textit{ReinDSplit} framework.

\begin{definition}[\textbf{Straggler Effect in \textit{ReinDSplit}}]
\label{def:rl_straggler}
Let $\mathcal{H} = \{d_1, d_2, \dots, d_N\}$ be $N$ devices, and each $d_i$ selects a \textit{split index} $k \in \{1,\dots,K\}$ using its RL policy $\pi_i$. We define the \textit{straggler effect} as the probability that, in a training round $t$,
% \vspace{-0.2cm}
\begin{equation}
% \vspace{-0.25cm}
\exists\, d_i \;\text{such that}\; \Delta_i^k < 0
  \quad \text{and} \quad a_i^t = k,  
\end{equation}

where $\Delta_i^k$ is a local resource surplus for a device $d_i$ under split $k$. Equivalently, a \textit{straggler} arises if a device selects a split that exceeds its resource/time availability, delaying the global update or even incomplete local training.
\end{definition}

\begin{lemma}[Bound on Straggler Probability]
\label{lemma:straggler_probability}
Suppose each device $d_i$ executes a Q-learning over a finite state-action space $\mathcal{S}_i \times \{1,\dots, K\}$. Then the probability that $d_i$ selects an infeasible action $k \notin \mathcal{F}_i$ (i.e., $\Delta_i^k < 0$) $t\to 0$ as $t\to\infty$:
% \vspace{-0.15cm}
\begin{equation}
% \vspace{-0.15cm}
\lim_{t\to\infty}\; \Pr\bigl[a_i^t \notin \mathcal{F}_i\bigr] = 0  
\end{equation}

\end{lemma}
% \vspace{0.2cm}

\begin{theorem}[Diminishing Straggler Effect]
\label{theorem:straggler_diminish}
Let $\pi_i^{*}$ be the optimal policy for the device $d_i$ in our proposed \textit{ReinDSplit} framework. Suppose $\Pr[\text{Straggler at round }t]$ is the probability that, at time step $t$, at least one device $d_i \in \{d_1, \dots, d_N\}$ selects an action/split $k$ outside its feasibility set $\mathcal{F}_i$. Mathematically, 
\vspace{-0.35cm}
\begin{equation*}
    \vspace{-0.25cm}
  \Pr\bigl[\text{Straggler at round } t\bigr] 
  \;=\;
  \Pr\Bigl[\,
    \bigcup_{i=1}^{N}
    \{\,a_i^t \notin \mathcal{F}_i\}
  \Bigr].
\end{equation*}
Then, under Q-learning convergence: \vspace{-0.2cm}
\[
  \lim_{t\to\infty}\; \Pr\bigl[\text{Straggler at round } t\bigr] 
  \;=\; 0.
\]
\end{theorem}

\begin{definition}[\textbf{ReinDSplit Convergence}]
\label{def:global_rl_ReinDSplit_convergence}
\textit{Global convergence} is achieved when, across repeated training rounds, each device $d_i$ takes action $k \in \{1,\dots, K\}$ following its learned policy $\pi_i$, executes local forward/backward passes on $\mathcal{M}_C^k$, and transmits the resulting smashed gradients to the server for updates of $\mathcal{M}_S^k$. Convergence occurs if the local (client-side) and global (server-side) model parameters stabilize in expectation, ensuring no unbounded variance in performance metrics (accuracy) over time.
\end{definition}

\begin{lemma}[Stability of Local Updates]
\label{lemma:local_update_stability}
If each device $d_i$ consistently selects actions $k \in \mathcal{F}_i$ (its feasibility set), then local updates remain bounded. Formally, for any feasible split $k\in\mathcal{F}_i$, the gradients of the partial model $\mathcal{M}_C^k$ satisfy%\vspace{-0.1cm}
\[
  \|\nabla \mathcal{M}_C^k\| \;\le\; M_{\mathrm{grad}},
\]
where $M_{\mathrm{grad}}$ is a device-independent constant determined by batch size and network architecture factors.
\end{lemma}

\begin{theorem}[Global Convergence of \textit{ReinDSplit}]
\label{theorem:global_convergence_rl_ReinDSplit}
Suppose a finite MDP models each device $d_i$ with a corresponding Q-learning routine that converges to the optimal policy $\pi_i^{*}$; local gradients remain bounded as per Lemma~\ref{lemma:local_update_stability}; and a central server periodically aggregates partial updates from all devices. Then, our proposed \textit{ReinDSplit} algorithm converges in expectation to a stable partition of model parameters $\{\mathcal{M}_C^{k^*}, \mathcal{M}_S^{k^*}\}$ across devices, thereby maximizing total accuracy subject to the given resource/time constraints.
\end{theorem}

