\section*{Our Proposed Framework}
\begin{algorithm}[!h]
\setlength{\floatsep}{2pt}      
\setlength{\textfloatsep}{2pt}  
\setlength{\intextsep}{2pt}     
\caption{\textit{ReinDSplit} Algorithm}
\label{alg:ReinDSplit_insect_monitoring}
\begin{algorithmic}[1]
\REQUIRE $\mathcal{H}=\{d_1,\dots,d_N\}$, total rounds $T$, Q-net params $\{\theta_i\}$, $\epsilon$, $\gamma$, $\mathcal{A}_i=\{1,\dots,K\}$.
\ENSURE $\{\theta_i^*\}$ for split decisions.
\vspace{2pt}
\FOR{$t=1 \rightarrow T$}
    \FOR{each $d_i \in \{1,\dots,N\}$ \textbf{in parallel}}
        \STATE Observe $s_i^t \!=\!(R_i^t,\,T_i^t,\,\mathcal{P}_i^t)$
        \STATE Select $a_i^t$:\vspace{-0.4cm}
        \[
          a_i^t = \begin{cases}
          \text{random in } \mathcal{A}_i, & \text{w.p.\ } \epsilon,\\
          \arg\max\limits_{a} Q_i(s_i^t,a;\theta_i), & \text{otherwise}
          \end{cases}
        \]%\vspace{-0.3cm}
        \IF{$R_i^t \!\ge\! R_{\mathrm{req}}(\mathcal{M}_C^{a_i^t}) \!\land\! T_i^t \!\ge\! T_{\mathrm{req}}(\mathcal{M}_C^{a_i^t})$}
            \STATE \textit{Local training} on $\mathcal{M}_C^{a_i^t}$; send smashed data
            \STATE \textit{Server update} on $\mathcal{M}_S^{a_i^t}$; return gradients
            \STATE \textit{Local backprop}; compute $r_i^t$
        \ELSE
            \STATE $r_i^t \!\leftarrow\! -\gamma\,(\text{penalty})$
        \ENDIF
        \STATE Update $Q_i$ with $(s_i^t,\,a_i^t,\,r_i^t,\,s_i^{t+1})$: %\vspace{-0.2cm}
        \[
          L(\theta_i)\!=\!\bigl(r_i^t + \gamma\,\max_{a'}Q_i(s_i^{t+1},a';\theta_i^{-}) - Q_i(s_i^t,a_i^t;\theta_i)\bigr)^2
        \]\vspace{-0.25cm}
        \STATE Periodically set $\theta_i^{-} \leftarrow \theta_i$
    \ENDFOR
    \STATE $\epsilon \leftarrow \text{decay}(\epsilon)$
\ENDFOR
\RETURN $\{\theta_i\}$
\end{algorithmic}
% \vspace{-0.15cm}
\end{algorithm}

\section*{Theoretical Analysis}\label{theoretical_ana}

\begin{proof}[Proof of Lemma 1] Given $d_i$ interacts with a finite state-action space \(\mathcal{S}_i \times \{1,\dots,K\}\) and each action \(k \in \{1,\dots,K\}\) corresponds to a specific client-side split \(\mathcal{M}_C^k\) and server-side \(\mathcal{M}_S^k\). With the reward function in Eq.~\eqref{eq:reward_function}, selecting an infeasible action \(k \notin \mathcal{F}_i\) results in a substantial negative reward due to resource or time constraints being violated (\(\Delta_i^k < 0\)). Conversely, feasible action \(k \in \mathcal{F}_I \) yields higher or non-negative rewards, reflecting successful model training without resource violations.

Given that the state and action spaces are finite, Q-learning convergence results (ref. \ Section~\ref{prelim:rl}) ensure that the Q-values \(Q_i(s, a)\) will converge to the optimal Q-function \(Q_i^{*}(s, a)\) provided that each state-action pair is visited sufficiently often and the learning rate satisfies the usual diminishing conditions. Constantly associated with negative rewards, infeasible actions will have their Q-values suppressed over time relative to feasible actions.

As a result, the optimal policy \(\pi_i^{*}\), derived from the converged Q-function, will preferentially select actions from the feasibility set \(\mathcal{F}_i\). Formally, for any state \(s \in \mathcal{S}_i\),
% \vspace{-0.2cm}
\begin{equation}
% \vspace{-0.2cm}
\pi_i^{*}(s) = \arg\max_{k \in \mathcal{F}_i} Q_i^{*}(s, k),    
\end{equation}
ensuring that infeasible actions are never chosen in the limit. Consequently, the probability that \(d_i\) selects an infeasible action \(k \notin \mathcal{F}_i\) approaches zero as the number of training rounds \(t\) increases: $\lim_{t \to \infty} \Pr\bigl[a_i^t \notin \mathcal{F}_i\bigr] = 0.$
\end{proof}

\begin{proof}[Proof of Theorem 1]
For each device $d_i$, Lemma~\ref{lemma:straggler_probability} establishes that %\vspace{-0.1cm}
\[
  \lim_{t\to\infty}\,\Pr\bigl[a_i^t \notin \mathcal{F}_i\bigr] 
  \;=\;
  0.
\]
In other words, the probability of selecting an infeasible action for any individual device $d_i$ vanishes as $t$ grows. By a standard union bound, we have %\vspace{-0.2cm}
\[
  \Pr\Bigl[
    \bigcup_{i=1}^N \{a_i^t \notin \mathcal{F}_i\}
  \Bigr]
  \;\le\;
  \sum_{i=1}^{N}
    \Pr\bigl[a_i^t \notin \mathcal{F}_i\bigr].
\]
Since each term $\Pr[a_i^t \notin \mathcal{F}_i]$ converges to zero by Lemma~\ref{lemma:straggler_probability}, the sum on the right also converges to zero. Consequently,\vspace{-0.2cm}
\[
  \lim_{t\to\infty}\,\Pr\Bigl[
    \bigcup_{i=1}^N \{a_i^t \notin \mathcal{F}_i\}
  \Bigr]
  \;=\;
  0.
\]
Hence, the probability of encountering \textit{any} straggler in a given round diminishes to zero in the limit. 
\end{proof}

\begin{proof}[Proof of Lemma 2]
Since $d_i$ selects only $k\in \mathcal{F}_i$ and by definition of feasibility, $d_i$ can complete the local forward and backward passes without interruptions or resource/time deficits. In this setting, the assumptions on stochastic gradient descent (see Section~\ref{prelim:rl}) imply that the norm of each gradient update is bounded when the input batch size and network layers are finite and \textit{Lipschitz} continuous.  

Mathematically, let $\mathcal{L}\bigl(\mathcal{M}_C^k; \mathbf{x}_i, \mathbf{y}_i\bigr)$ be the local loss function for device $d_i$, based on training batch-size $\{(\mathbf{x}_i, \mathbf{y}_i)\}$. Under mild smoothness conditions on $\mathcal{L}$, it follows that%\vspace{-0.1cm}
\[
  \bigl\|\nabla \mathcal{M}_C^k\bigr\|
  \;=\;
  \Bigl\|
    \frac{\partial \mathcal{L}}{\partial \mathcal{M}_C^k}
    \Bigl(\mathbf{x}_i, \mathbf{y}_i\Bigr)
  \Bigr\|
  \;\le\;
  M_{\mathrm{grad}},
\]
where $M_{\mathrm{grad}}$ is constant depending on the maximum batch size, the network’s layer structure, and \textit{Lipschitz} coefficients of the activation functions. Because the device remains within its feasible resource/time range ($k \in \mathcal{F}_i$), it completes backpropagation successfully, preserving this bound each round.

Thus, when each $d_i$ executes feasibility constraints, the partial model updates $\nabla \mathcal{M}_C^k$ cannot grow unbounded. This proves stable local learning and supports global RL-\textit{ReinDSplit} convergence, as no erratic or divergent local updates pollute the server’s aggregated model.
\end{proof}

\begin{proof}[Proof of Theorem 2]
Given each device $d_i$ learns via Q-learning over a finite state-action space, selecting a split $k\in\{1,\dots, K\}$ to execute locally. By convergence analysis for Q-learning in finite MDPs, each device’s action-value function $Q_i$ converges to an optimal $Q_i^{*}$. Lemma~\ref{lemma:straggler_probability} proved that it yields an optimal policy $\pi_i^{*}$ that avoids infeasible splits over continuous learning.

Next, by Lemma~\ref{lemma:local_update_stability}, whenever a device chooses a feasible split $k \in \mathcal{F}_i$, its local gradient norm remains bounded by $M_{\mathrm{grad}}$. Consequently, in each training round, the server receives non-explosive partial gradients, aggregates them for the server-side model $\mathcal{M}_S^k$, and periodically synchronizes its updated parameters with all participating devices.

Over training episodes, no device selects an infeasible split with high probability, as proved in Theorem~\ref{theorem:straggler_diminish}, thereby preventing any ``straggling" and ensuring stable local parameter updates. Since each device’s local Q-learning policy converges to maximizing classification accuracy (with resource/time limits), the aggregated global model $\{\mathcal{M}_C^{k}, \mathcal{M}_S^{k}\}$ converges to a partition that yields consistently high performance across all devices. In expectation, no unbounded fluctuations remain in either local or server-side parameters, ensuring convergence in expectation to a stable global partition $\{\mathcal{M}_C^{k^*}, \mathcal{M}_S^{k^*}\}$. Therefore, with the reward structure and Q-value maximization, this partition balances accuracy with resource/time constraints for each device.
\end{proof}

