\subsection{Results Comparison with Advanced Baselines}
\begin{figure}[htb]   
\center{\includegraphics[width=8.3cm]  {spatial_spectrum.png}}   
\caption{\label{1} Spatial spectrum calculated by MUSIC algorithm.}   
\vspace{-0.5cm}
