\vspace{1em}
\begin{minipage}{.4\textwidth}
Program \textsc{Escalating}:
\begin{center}
\begin{tabular}{l}
  $\mathit{x} \gets 0$\\
  $\mathit{y} \gets 0$\\
  \textbf{loop} \\
  \quad\textbf{if} $x \equiv 0 \pmod 2$ \textbf{then}\\
  \quad\quad $y \gets y + 1$\\
  \quad \textbf{else}\\
  \quad\quad $y \gets y + x$\\
  \quad \textbf{havoc} $s \in \{\, 1, 2 \,\}$\\
  \quad $x \gets x + s$
\end{tabular}
