\section{AG-based Interleaved RS codes}\label{sec:IRS}	
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Li et al. \cite{encAG24} generalized the G-FFT \cite{LX24} framework over rational function fields to algebraic function fields, which enables some \rAG codes to be encoded in time $O(N\log N)$ (here $N$ denotes the length of $\AG$ codes). In this section, we use the G-FFT technique in \cite{encAG24} to convert \rAG codes to interleaved Reed-Solomon codes, which will be used to decode AG and RS  codes with burst errors in subsequent sections.

\subsection{$O(N\log N)$ time encodable {$\AG$} codes}\label{sec:fastEncAG}
Let us first briefly recap the G-FFT framework using algebraic function fields in \cite{encAG24}. Let $F=\F_q(x)$ be a rational function field and $P_{\infty}$ be the unique pole place of $x$. Assume $E/F$ is a Galois extension with field extension degree $m=[E: F]$. Suppose that $m=\prod_{i=1}^rp_i$ is a factorization of $m$, where the factors $p_1,\dots,p_r$ are not required to be distinct. To establish G-FFT over $E$, the field extension $E/F$ is expected to satisfy the following assumptions:\bigskip
\\
\fbox{\begin{minipage}{39.5em}
\begin{center}
   {\bf  G-FFT assumptions}
\end{center}
\begin{enumerate}
\item[(P1)] The pole place $P_{\infty}$ of $x$ is totally ramified in $E/F$.
\item[(P2)] There exists a tower of subfields of $E$: $E=E_0\supsetneq E_1\supsetneq\dots \supsetneq E_r=F$ such that $E_{i}/E_{i+1}$ is a Galois extension and the extension degree $[E_{i}: E_{i+1}]=p_{i+1}$ for $0\leq i\leq r-1$.
\item[(P3)] Let $E_{i}=E_{i+1}(y_{i})$ and $P^{(i)}_{\infty}\in\PP_{E_i}$ be the unique place in $E_i$ lying over $P_{\infty}$. Each $y_i$ has a unique pole place $P^{(i)}_{\infty}$ and $\gcd(\nu_{P^{(i)}_{\infty}}(y_i), p_{i+1})=1$. Moreover, $\{1,y_i,\dots,y_i^{p_i-1}\}$ is an integral basis of $E_i/E_{i+1}$ at all places $Q\in\PP_{E_i}$ with $Q\neq P_{\infty}^{(i)}$.
\item[(P4)] There are $n\in\Z_+$ rational places $\{P_1,\ldots,P_n\}\in\PP_F$ that are splitting completely in $E/F$.
\end{enumerate}
\end{minipage}}

\begin{remark}
   The above assumptions (P2) and (P3) differ slightly with the assumptions in \cite{encAG24} for explicit construction of generators $y_1,y_2,\dots,y_r$ via automorphisms in $\Aut(E/\F_q(x))$. Since the generators $y_1,y_2,\dots,y_r$ will be used in our construction of a basis of the Riemann-Roch space $\cL(\lambda P^{(0)}_{\infty})$ of $E$ in the following Lemma~\ref{lem:basis}, we will give a proof of Lemma~\ref{lem:basis} in the Appendix.
\end{remark}

Let $k<n$ be a positive integer and $\lambda:=(k-1)m$. From assumptions (P1)-(P3), there is an explicit basis of the Riemann-Roch space $\cL(\lambda P^{(0)}_{\infty})$ of $E$. Before introducing the basis we need some notations. For a fixed factorization $m=\prod_{i=1}^rp_i$ of $m$, any $u\in[0,m-1]$ can be uniquely written as 
\begin{equation}\label{eq:expu}
u=u_0+u_1p_1+\ldots+u_{r-1}p_1p_2\cdots p_{r-1},\ \text{where}\ u_i\in[0,p_{i+1}-1],\ i=0,\dots,r-1.
\end{equation}
Let $\bu=(u_0,u_1,\ldots,u_{r-1})\in\prod_{i=1}^{r}\Z_{p_j}$ be the expansion coefficients of $u$ and define a function $\by^{\bu}$ as follows:
\begin{equation}\label{eq:expans}
\by^{\bu}:=y_0^{u_0}y_1^{u_1}\cdots y_{r-1}^{u_{r-1}}.
\end{equation}


%$\cB_{\infty}=\{\by^{\be}x^j\mid 0\leq e\leq m-1,\ j\geq 0\}\subset \cL(\infty P^{(0)}_{\infty})$ is $\F_q$-linearly independently.
\begin{lemma}{\cite{encAG24}}\label{lem:basis}
Suppose $E/F$ is a field extension satisfying (P1)-(P3). The set $\cB=\left\{\by^{\bu}x^j\mid \nu_{P^{(0)}_{\infty}}(\by^{\bu}x^j)\geq -\lambda,\ 0\leq u\leq m-1,\ 0\leq j\leq k-1\right\}$ is a basis of $\cL(\lambda P^{(0)}_{\infty})$. Therefore, every function $f\in\cL(\lambda P^{(0)}_{\infty})$ has a unique representation as
\[f=f_0(x)+f_1(x)\by^{\mathbf 1}+\dots+f_{m-1}(x)\by^{\mathbf{m-1}},\ \text{where}\ f_u(x)\in\F_q[x]_{<k}\ \text{for}\ u=0,\dots,m-1.\]
 \end{lemma}
\begin{proof}
See Appendix~\ref{app:basis}.
\end{proof}
\begin{remark}
    The above assumptions (P1)-(P3) are used to construct a polynomial basis of the Riemann-Roch space $\cL(\lambda{P}^{(0)}_{\infty})$. For some function field $E/\F_q$ that does not satisfy all assumptions (P1)-(P3), if its Riemann-Roch space has a good polynomial basis, then the AG codes based on $E$ can still be burst decoded in quasi-linear time by using same techniques. We give an example in Subection 5.5 to illustrate this point.
\end{remark}

From assumption (P4), assume $P\in\{P_1,\dots, P_n\}$ is a rational place that splits completely in $E/F$. Let $\fP_1,\dots,\fP_m$ be $m$ rational places in $E$ lying over $P$. Assume $f=\sum_{u=0}^{m-1}f_u(x)\by^{\mathbf u}\in\cL(\lambda P_{\infty}^{(0)})$. Note that each $f_u(x)\in\F_q[x]_{<k}$ is a constant function restricted on $\{\fP_1,\dots,\fP_m\}$, i.e., $f_u(\fP_1)=\dots=f_{u}(\fP_m)=f_u(P)\in\F_q$. Thus
\[\ev_{\{\fP_1,\dots,\fP_m\}}(f)=\ev_{\{\fP_1,\dots,\fP_m\}}\left(f_0(P)+f_1(P)\by^{\mathbf 1}+\dots+f_{m-1}(P)\by^{\mathbf{m-1}}\right),\]
For any $ f\in\cL(\lambda P^{(0)}_{\infty})$. let $f_P=\sum_{u=0}^{m-1}f_{u}(P)\by^{\mathbf{u}}$. We define the G-FFT and inverse G-FFT (G-IFFT for short) of $ f\in\cL(\lambda P^{(0)}_{\infty})$ at place $P$ as follows:
\begin{equation}\label{eq:fft}
\begin{split}&\GFFT_P:\ \left(f_0(P), f_1(P),\dots,f_{m-1}(P)\right) \rightarrow\left(f(\fP_1),\ldots,f(\fP_m)\right);\\
&\GIFFT_P:\ \left(f(\fP_1),\ldots,f(\fP_m)\right)\rightarrow \left(f_0(P), f_1(P),\dots,f_{m-1}(P)\right). \end{split}
\end{equation}
The local G-FFT and G-IFFT of length $m$ correspond to the column G-FFT and G-IFFT in the map from $\AG$ code to the interleaved $\RS$ code in the next subsection. The following lemma shows that local G-FFT and G-IFFT can be performed in time $O(m\log m)$. Its proof is similar to \cite[Theorem 3.3]{encAG24} which considers the whole G-FFT and G-IFFT of length $N=nm$. For the sake of completeness, we provide a proof in the Appendix.

\begin{lemma}{\cite{encAG24}}\label{lem:gfft}
Suppose $E/F$ is a field extension satisfying (P1)-(P4). Assume $m=\prod_{i=1}^r p_i$ and $B=\max\{p_1,\ldots,p_r\}$. Let $P$ and $\fP_1,\dots,\fP_m$ be defined as above. For any $f=\sum_{u=0}^{m-1} {\Ga_{u}}\by^{\bu}\in\F_q[y_0,y_1,\dots,y_{r-1}]$, the multipoint evaluation $\left(f(\fP_1),\ldots,f(\fP_m)\right)$ can be computed in time $O(B m\log m)$; conversely, given $\left\{f(\fP_1),\ldots,f(\fP_m)\right\}$, the coefficients  $\{\Ga_{0},\Ga_{1},\ldots,\Ga_{m-1}\}\subset\F_q^m$ of $f$ can be computed in time $O(Bm\log m)$.
\end{lemma}
\begin{proof}
See the Appendix~\ref{app:gfft}.
\end{proof}

Next, we present the \rAG codes from $E$. Assume $\{P_1,\dots,P_n\}$ as in (P4), let $\calP[j]$ be the set of all places in $E$ lying over $P_j$ and $\calP$ be the set of all places lying over $P_1,\dots,P_n$, i.e.,
\begin{equation}\label{eq:points}
\calP=\bigcup_{j=1}^n\calP[j]\ \text{and}\ \calP[j]=\{\fP_{1,j},\dots,\fP_{m,j}:\ \fP_{i,j}\mid P_j\}.
\end{equation}
Then $|\calP|:=N=nm$. From now on, we always assume the parameter $\lambda$ satisfying $2\fg(E)-1\leq \lambda <N$, where $\fg(E)$ is the genus of $E$. The one-point \rAG code is defined as
\begin{equation}\label{eq:agc}
\mathfrak{C}(\lambda P^{(0)}_{\infty},\calP)=\{\ev_{\calP}(f)=(\ev_{\calP[1]}(f),\ldots,\ev_{\calP[n]}(f))\mid f\in\cL(\lambda P^{(0)}_{\infty})\}.
\end{equation}

From the above Lemma~\ref{lem:gfft}, then $\mathfrak{C}(\lambda P^{(0)}_{\infty},\calP)$ can be encoded in time $O(N\log N)$ under the capability to perform FFT for any polynomial in $\F_q[x]_{<n}$ at $\{P_1,P_2,\dots,P_n\}$: For any $f=\sum_{u=0}^{m-1}f_u(x)\by^{\bu}\in\cL(\lambda P^{(0)}_{\infty})$ that is represented under the basis $\cB$, one can 
\begin{itemize}
\item[-]\textbf{Step 1}: compute $\{f_u(P_1),\ldots f_u(P_n)\}_{u=0}^{m-1}$ in time $mO(n\log n)$ via FFT;
\item[-]\textbf{Step 2}: compute $\left\{\ev_{\calP[j]}\left(\sum_{u=0}^{m-1}f_u(P_j)\by^{\bu}\right)\right\}_{j=1}^n$ in time $nO(m\log m)$ by Lemma~\ref{lem:gfft}. 
\end{itemize}
Hence, the total complexity to compute $\ev_{\calP}(f)$ is $O(N\log N)$.

