\subsection{Burst list decoding $\RS[n,k]_q$ in time $O_{\ep}(n\log n)$}
\begin{lemma}\label{lem:ldIRS}
The interleaved \rRS code $\IRS_{m}(n,k)$ is $(1-\cR,O(n))$-burst list-decodable, where $\cR=k/n$. %Moreover, it can be list decoded in time $O(Lmn\log^2 n)=O(mn^2\log ^2n)$.
\end{lemma}
\begin{proof}
Let $\fl=n-k$. For any $\sR\in\F_q^{m\times n}$, we consider the number of codewords $\sC\in\IRS_m(n,k)$ such that $\sC=\sR-\sE$ for some $\fl$-burst $\sE$ in $\F_q^{m\times n}$. % which is corrupted by a consecutive error $\sE$, i.e., $$.  
As a burst $\sE$ corrupts all $m$ constituent $\RS$ codewords with the same locations, the bursts in all rows $\sR(1),\dots,\sR(m)$ of $\sR$ are in the same burst interval. Note that the erasure decoding radius of $\RS[n,k]$ is $n-k$. Since for any codeword $\br\in\F_q^n$ with erased positions $\leq n-k$, then reminder $k$ entries of $\br$ uniquely determine a codeword in $\RS[n,k]$ by interpolation. Thus, for a burst interval $I\subset[1,n]$ of length $n-k$, by erasing the columns of $\sR$ with indices in $I$ and then decoding each row of $\sR$ with the left entries, we can obtain at most one codeword in $\IRS_m(n,k)$. There are $k+1$ burst intervals of length $n-k$ in total. Thus, at most $k+1=O(n)$ codewords can be decoded from $\sR$.  Consequently, we have that $\IRS_m(n,k)$ is $(1-\cR, O(n))$-list decodable.
\end{proof}


 \begin{algorithm}[!h]\label{alg: ListDec}
  \caption{Burst list decoding($\br$).}
  \label{alg:ListDec}
  \begin{algorithmic}[1]
    \Require
     $\br\in\F_q^n$.
    \Ensure
      $\mathfrak L=\left\{f\in\F_q[x]_{<k}\mid \ev_{\calP}(f)-\br\ \text{is\ an}\ \fl\text{-burst}\right\}$ for $\fl=n-k-2\prod_{j=1}^{s}p_j$.
    \State $\mathfrak L=\emptyset$.
    \State Fold $\br$ with length $m_s=\prod_{j=1}^{s}p_j$ into $\br=(\br^T_1,\br^T_2,\ldots,\br^T_{n_s})\in\F_q^{{m_s}\times{n_s}}$.
    \State For $j=1,\dots,n_s$, use G-IFFT to recover $g_j(x)=g_{0,j}+g_{1,j}\bx^{\mathbf 1}+\ldots+g_{m_s-1,j}\bx^{\mathbf{m_s-1}}$.
    \For {every burst interval $I\subset[n_s]$ of length $n_s-k(s)$}
           \For {$i=0$ to $m_s-1$}
                  \State Recover $f_i(x_s)\in\F_q[x_s]_{<k(s)}$ from $\{g_{i,j} \mid j\in [n_s]\setminus I \}$ via erasure decoding.
               %   \State $i=i+1$.
            \EndFor
            \State Compute $f(x)=f_0(x_s)+f_1(x_s)\bx^{\mathbf 1}+\ldots f_{m_s-1}(x_s)\bx^{\mathbf{m_s-1}}$.
            \State If $\deg(f)<k$ and $\br-\ev_{\calP}(f)$ is an $\fl$-burst, $\mathfrak L=\mathfrak L\cup\{f(x)\}$.
     \EndFor

  \State  \Return  $\mathfrak L$.
   %\State Output $\big(\ev_{\calP}(f)[P_{1}], \dots, \ev_{\calP}(f)[P_{N}]\big)$.
  \end{algorithmic}
\end{algorithm}

\begin{theorem}\label{thm:listDecRS}
Let $\RS[n,k]$ be defined as in Equation~\eqref{eq:RS}. For any real number $\epsilon >0$, the $\RS$ code $\RS[n,k]$ is $(1-\cR-\epsilon,O(1/\epsilon))$-burst list-decodable, where $\cR=k/n$ is the code rate. Furthermore, if $n$ is an $O(1)$-smooth integer, then $\RS[n,k]$ can be list decoded in time $O(\frac 1{\epsilon} n\log n)=O_{\ep}(n\log n)$ by Algorithm 1.
\end{theorem}
\begin{proof}
Given an erroneous codeword $\br$ corrupted by a burst error of length at most $\fl:=n-k-n\epsilon$, we will show that 
\[|B_{\fb}(\br, \fl)\cap \RS[n,k]|=O(1/\ep).\]

Let $m_s=\prod_{j=1}^sp_j\mid n$ and $n_s=n/m_s$, $k(s)=\lceil k/m_s\rceil$. Assume $\bc\in B_{\fb}(\br, \fl)\cap \RS[n,k]$ and $\br=\bc+\be$ for some burst $\be$ of length $\fl$. %where $\bc=\ev_{\calP}(f(x))$ and $f(x)=\sum_{i=0}^{m_s-1}f_i(x_s)\bx^{\bi}$. 
