\subsection{Unique decoding RS codes in time $O_{\ep}(n\log n)$}
%In this subsection, we will discuss the unique decoding algorithm for \rRS codes when the burst error length is smaller than the minimum distance. 
Let $\RS[n,k]$ be defined as in Equation~\eqref {eq:RS} with certain multipoint set $\calP$. When $n=t\mid q-1$, by Lemma~\ref{lem:MPset}, $\calP$ is a cyclic subgroup of order $n$ or a coset of a cyclic group. In this case, $\RS[n,k]$ can correct burst errors of length less than $n-k-e$ with miscorrection probability at most $1/q^e$ by Lemma~\ref{lem:UniDec}. When $n=\ell^wt\nmid q-1$ and $t>1$, one can not use Wu's algorithm directly for $\RS[n,k]$. In this case, we choose $n_s\mid t$ hence $n_s\mid\ell-1$. By Remark~\ref{rmk:cyc}, the multipoint set $\sP_s$ in $\IRS_{m_s}((k-1)P^{(0)}_{\infty},\calP)$ forms a cyclic subgroup of order $n_s$ or a coset of it. Then we convert the decoding problem in $\RS[n,k]$ to the decoding problem in $\IRS_{m_s}(n_s,k(s))$ which is solvable by Wu's algorithm. Finally, we can get the correct codeword in $\RS[n,k]$ by the inverse map.

%The following Lemma is a generalized version of Wu's algorithm 

\begin{lemma}\label{lem:UniIRS}
Assume $\alpha\in  \F_q^*$ is an element of order $n$. Let $\sP=\langle \alpha\rangle$ or a coset in $\F_q^*/\langle \alpha\rangle$. Let $\IRS_m(n,k_1,\ldots,k_m)$ be a heterogeneous $\IRS$ code defined on $\sP$ and $k=\max\{k_i:\ i\in[m]\}$. Let $e\geq 1$ be an integer.
%satisfying $k(1)\leq k(2)\leq \dots \leq k(m)\leq n$ and $k(m)-k(1)\leq 1$. 
Then $\IRS_m(n,k_1,\ldots,k_m)$ can correct burst error of length less than $n-k-e$ with miscorrection probability at most $m/q^e$.
\end{lemma}
\begin{proof}
Assume $\sR=\sC+\sE$ is a received erroneous $\IRS$ codeword, where $\sE$ is an $\fl$-burst in $\F_q^{m\times n}$ with length $\fl< n-k-e$. For each row $\sR(i)$ of $\sR$, since $\fl<n-k-e\leq n-k_i-e$, by Lemma~\ref{lem:UniDec},  we can find the correct $\sC(i)$ with miscorrection probability at most $1/q^e$. Thus, after running Wu's algorithm for all rows $\sR(1),\dots,\sR(m)$, $\sC$ can be correctly computed with miscorrection probability at most $m/q^e$.
\end{proof}

 \begin{algorithm}[!h]\label{alg: UniqDec}
  \caption{Probabilistic unique decoding($\br$).}
  \label{alg:UniqDec}
  \begin{algorithmic}[1]
    \Require
     $\br\in\F_q^n$ with burst error of length $\fl< n-k-n\epsilon(e+2)$.
    \Ensure
      $\bc\in  \RS[n,k]\cap B_{\fb}(\br,\fl)$.
%    \State Let $\{1=\beta^0,\beta, \dots,\beta^{n_s-1}\}=\{x_s(\fp)\mid \fp\in\sP_s\}$. Precompute $\Lambda(x)=\prod_{i=0}^{n_s-k(s)-1}(1-\beta^ix)=\sum_{i=0}^{n_s-k(s)}\Lambda_i x^i$.
    \State Fold $\br$ with length $m_s=\prod_{j=1}^{s}p_j$ into $\br=(\br^T_1,\br^T_2,\ldots,\br^T_{n_s})\in\F_q^{m_s\times n_s}$.
     \For {$j=1$ to $n_s$}
            \State Run G-IFFT on $\br_j$, obtaining a polynomial $g_j(x)=g_{0,j}+g_{1,j}\bx^{\mathbf 1}+\ldots+g_{m_s-1,j}\bx^{\mathbf{m_s-1}}$.
     \EndFor
     \For {$i=0$ to $m_s-1$}
           \State Run probabilistic unique decoding Algorithm 3 in Appendix A with input $\mathbf g_i=(g_{i,1},\dots,g_{i,n_s})$, obtaining $\sC(i)=(\sC_{i,1},\dots,\sC_{i,n_s})$.
           \State Compute a polynomial $f_i(x_s)\in\F_q[x_s]_{<k_i}$ from $\sC(i)$ by G-IFFT.
      \EndFor
     \State Compute $f(x)=f_0(x_s)+f_1(x_s)\bx^{\mathbf 1}+\ldots f_{m_s-1}(x_s)\bx^{\mathbf{m_s-1}}$.
     \State Compute $\bc=\ev_{\calP}(f(x))$.
     \State  \Return $\bc$.
   %\State Output $\big(\ev_{\calP}(f)[P_{1}], \dots, \ev_{\calP}(f)[P_{N}]\big)$.
  \end{algorithmic}
\end{algorithm}

\begin{theorem}\label{thm:uniqDecRS}
For any real number $\ep>0$ and an integer $e\geq 1$, $\RS[n,k]$ can probabilistic uniquely correct burst errors of length less than $n-k-n\ep(e+2)$ with miscorrection probability at most $\ep/q^{e-1}$.
%For any real number $\ep>0$, let $n_s=\prod_{j=s+1}^rp_j$ be a divisor of $n$ such that $n_s=O(4/\ep)$. Given a received word $\br=\bc+\be$ with $\be$ an $e$-burst error such that $e<n-k-\ep n$, Algorithm 2 will output $\bc$ with probability at least $1-1/q$. 
Moreover, if $n$ is an $O(1)$-smooth integer, then probabilistic unique decoding can be performed by Algorithm 2 in time $O(\frac{1}{\ep}n\log n)$.
\end{theorem}
\begin{proof}
%The proof is very similar to the proof of Theorem~\ref{thm:listRS}. 
Assume $n=\ell^wt=\prod_{j=1}^rp_j$, where $t\mid \ell-1$. Choose $n_s=\prod_{j=s+1}^rp_j\mid t$ and $n_s=1/\ep$. Hence $n$ is $\ell$-smooth if $w\neq 0$, and $O(1/\ep)$-smooth for sufficiently small $\ep$ if $w=0$. Overall, $n$ is $O(1/\ep)$-smooth. Let $m_s=n/n_s=\prod_{j=1}^sp_j$. By Theorem~\ref{thm:convert}, we can map $\RS[n,k]$ to the AG-based $\IRS$ code $\IRS_{m_s}((k-1)P_{\infty},\calP)=\IRS_{m_s}(n,k_1,\dots,k_{m_s})$. In this case, by Lemma~\ref{lem:MPset}, the multipoint set $\sP_s$ used to define $\IRS_{m_s}((k-1)P^{(0)}_{\infty},\calP)$ is $\langle\xi\mid \xi^{n_s}=1\rangle \cdot L(\gamma)^{t/n_s}$, which is a coset in $\F_q^*/\langle \xi\rangle$ of order $n_s$. 

For any erroneous word $\br=\bc+\be\in\F_q^n$ corrupted by an $\fl$-burst $\be$, after folding and running G-IFFT, we get an erroneous word $\sR=\sC+\sE$ corrupted by an $\lfloor\fl/m_s\rfloor+2$-burst $\sE$ in $\F_{q}^{m_s\times n_s}$. 
By Lemma~\ref{lem:UniIRS}, $\IRS_{m_s}(n,k_1,\dots,k_{m_s})$ can correct  burst errors with length less than $n_s-k_0-e$ with miscorrection probability at most $m_s/q^e\leq \ep/q^{e-1}$ and any $\IRS$ codeword $\sC$ uniquely corresponds to an $\RS$ codeword $\bc=\tau^{-1}(\sC)$. Thus, $\RS[n,k]$ can correct bursts of length $\fl< n-k-n\ep(e+2)$ (which is derived from $\fl/m_s+2< n_s-k_0-e$), and the miscorrection probability of unique decoding is less than $\ep/q^{e-1}$.

From the above proof, the unique decoding problem in $\RS[n,k]$ is determined by the unique decoding problem in $\IRS_{m_s}(n,k_1,\dots,k_{m_s})$. According to the proof of Lemma~\ref{lem:UniIRS}, we give the probabilistic unique decoding algorithm as in Algorithm~2. The decoding cost includes the complexity of probabilistic unique decoding Algorithm~3 for $\RS$ code and the G-IFFT. Steps 2-4 cost $n_sO(\frac{1}{\ep}m_s\log m_s)$ operations;  Steps 5-8 cost $m_sO(n_s\log n_s)$ operations; Step 9 costs $O(n)$ operations and Step 10 costs $O(\frac{1}{\ep}n\log n)$ operations by G-FFT. Therefore, the total complexity is $O(\frac 1{\ep}n\log n)$.
\end{proof}


