\subsection{Examples of {$\AG$} codes from Hermitian curve}
%In Section 5, we show that the {$\AG$} codes $\fC(\lambda P^{(0)}_{\infty},\calP)$ constructed from algebraic function fields $E$ satisfying (P1)-(P4) can be fast list and unique decoded with burst errors under the assumption that the constituent $\RS[n,k]$ of  $\IRS(\lambda P^{(0)}_{\infty},\calP)$ satisfying the conditions in Theorem~\ref{thm:listRS} and ~\ref{thm:uniqDecRS}, respectively. 
In this subsection, we give examples of  \rAG codes that satisfy all the assumptions in Theorem~\ref{thm:LDAG} and ~\ref{thm:uniqDecAG}.

\begin{example}{(Hermitian curve~ \cite{sti09})}\label{ex:hc}
Let $\kappa$ be a power of a prime $p$. Let $\F_q=\F_{\kappa^2}$ be a finite field. Consider the Hermitian curve $\H$ over $\F_q$ defined by
\[\H(x,y):=y^{\kappa}+y-x^{\kappa+1}.\]
Then $\H(x,y)$ is absolutely irreducible. Let $E=\F_q(x, y)=\mathrm{Frac}(\F_q[x,y]/\H(x,y))$ be the function field of $\H$. On the one hand, $E$ can be viewed as a Kummer extension over $\F_q(y)$ by extending $\F_q(y)$ with a variable $x$ satisfying the relation $\H(x,y)=0$. On the other hand, $E$ can also be viewed as an Artin-Schreier extension over $\F_q(x)$ by extending $\F_q(x)$ with a variable $y$ satisfying the relation $\H(x,y)=0$. The following Lemma ensures that $E$ satisfies the assumption (P1)-(P4) in Section 3. 

\begin{lemma}{\cite{sti09}}\label{lem:preH}
Let $E$ be the Hermitian function field.
\begin{enumerate}
\item The pole place ${P}_{\infty}$ of $x$ in ${\F_q(x)}$ (resp. $Q_{\infty}$ of $y$ in ${\F_q(y)}$) is totally ramified in $E$. Let ${\fP}_{\infty}$ be the unique place in $E$ lying above ${P}_{\infty}$ and $Q_{\infty}$. Then the discrete valuations of $x, y$ at ${\fP}_{\infty}$ are
\[\nu_{{P}_{\infty}}(x)=-\kappa,\ \nu_{{P}_{\infty}}(y)=-(\kappa+1).\]
Moreover, for positive integer $\lambda$, the Riemann-Roch space $\cL(\lambda \fP_{\infty})$ has the following two bases 
\[\begin{split}
&\cB_1=\{x^jy^u\mid j\kappa+u(\kappa+1)\leq \lambda,\ 0\leq u\leq \kappa-1,\ j\geq 0\},\ \text{and}\\ 
&\cB_2=\{y^jx^v\mid j(\kappa+1)+v\kappa\leq \lambda,\ 0\leq v\leq \kappa,\ j\geq 0\}.\end{split}\] 
\item The filed extension $E/\F_q(x)$ is Galois of degree $\kappa=[E: \F_q(x)]$, and its Galois group $\Gal(E/\F_q(x))=\{\sigma \mid \sigma(y)= y+\alpha,\ \alpha\in \F_{\kappa}\}$ is isomorphic to $\F_{\kappa}$. Moreover, all rational places in $\PP_{\F_q(x)}$ except $P_{\infty}$ are splitting completely in $E/\F_q(x)$.
\item The extension $E/\F_q(y)$ is Galois of degree $\kappa+1=[E: \F_q(y)]$ and its Galois group $\Gal(E/\F_q(y))=\{\sigma \mid \sigma(x)=\omega x,\ \omega^{\kappa+1}=1\}$ is isomorphic to the $\kappa+1$-cyclic subgroup of $\F_q^*$. Moreover, the set of rational places $\{P_{\beta}\in\PP_{\F_q(y)}\mid \beta^{\kappa}+\beta\neq 0\}$ are splitting completely in $E/\F_q(y)$.
\end{enumerate}
\end{lemma}

Thus, by constructing a basis of the Riemann-Roch space $\cL(\lambda \fP_{\infty})$ and selecting a certain multipoint set as in Section~3, we can define \rAG codes from $E$ that care fast encodable and burst decodable.


\subsubsection{ \textbf{$\F_q$ has constant characteristic $p$}}\label{sec:hcca}
Assume $\kappa=p^r$. Let $\{1=w_1,w_2,\dots,w_{r}\}$ be an $\F_p$-basis of $\F_{\kappa}$. For $1\leq i\leq r$, let $W_{i}=\oplus_{j=1}^i\F_pw_j$ be an $\F_p$-subspace of dimension $i$. By Lemma~\ref{lem:preH}(2), there exists a subgroup
\[G_i\leq\Gal(E/\F_{q}(x))\ \text{such\ that}\ G_i\cong W_i.\] 
Then the fixed subfield $E_i=E^{G_i}=\F_q(y_i,x)$ and
$y_i=\prod_{\alpha\in W_i}(y+\alpha)$~\cite{encAG24}. Thus $E$ has a chain of subfields: $E_i\supset E_{i+1}$ with extension degree $[E_i: E_{i+1}]=p$, for $i=1,\dots,r-1$.

Next we construct the basis of $\cL(\lambda{\fP}_{\infty})$ as in Lemma~\ref{lem:basis}. For any $0\leq u\leq p^r-1$, let $\bu=(u_0,u_1,\dots,u_{r-1})$ be the coefficients of $p$-adic expansions of $u=\sum_{i=0}^{r-1}u_ip^i$. Define
\begin{equation}\label{eq:hexp}
    \by^{\bu}=y_0^{u_0}y_1^{u_1}\cdots y_{r-1}^{u_{r-1}}.
\end{equation}
Since $\nu_{\fP_{\infty}}(\by^{\bu})=\sum_{i=0}^{r-1}u_i\nu_{\fP_{\infty}}(y_i)=-\sum_{i=0}^{r-1}u_ip^i(\kappa+1)=\nu_{\fP_{\infty}}(y^{u})$, by substituting $x^jy^u$ with $x^j\by^{\bu}$ in $\cB_1$ in Lemma~\ref{lem:preH}(1), the set $\tcB_1=\{x^{j}\by^{\bu}\mid j\kappa+u(\kappa+1)\leq \lambda, 0\leq u\leq \kappa-1\}$ is also a basis of $\cL(\lambda{\fP}_{\infty})$.

By Lemma~\ref{lem:preH}(2), any rational place $P\neq P_{\infty}$ in $\F_q(x)$ splits into $\kappa$ rational places in $E$. For different purposes of decoding, we first choose $\{P_1,P_2,\dots, P_n\}\subset \PP_{\F_q(x)}$ as follows and take $\calP$ be the the set of rational places in $E$ lying over these $n$ rational places. 
\begin{itemize}
\item[(i)] For list decoding, we take $n=q=\kappa^2$ and $\{P_1,P_2,\dots, P_n\}=\F_q$. Let $\calP$ be the set of rational places in $E$ lying over $\{P_1,P_2,\dots, P_n\}$. Then $N=|\calP|=\kappa^3$.
\item[(ii)] For probabilistic unique decoding, we take $n=\ell^{\frac{2r}{s}-1}(\ell-1)<q$ for $\ell=p^s$ is a small constant power of $p$. Let $\{P_1,P_2,\dots, P_n\}=\{u(\gamma+w)\mid u\in\F_{\ell}^*,\ L(w)=0\}$, where $L(x)$ is a linearized polynomial of degree $\ell^r$ and $\gamma\in\F_q$ satisfying $L(\gamma)\neq 0$ as in Lemma~\ref{lem:MPset}. Thus $N=|\calP|=\kappa^3(1-\frac{1}{\ell})$.
\end{itemize}
From above, all assumptions (P1)-(P4) hold for the Hermitian function field. Assume $k$ is a positive integer such that $\kappa\leq k\leq n$. Let $\lambda=\kappa(k-1)$ and $\fC(\lambda \fP_{\infty},\calP)$ be the Hermitian code defined on $\calP$. Since $\lambda\geq 2\fg(E)-1=\kappa(\kappa-1)-1$, by the Riemann-Roch theorem \cite{sti09}, $\fC(\lambda \fP_{\infty},\calP)$ has code rate 
$$\cR=\frac{k-1}{n}+\frac{1}{n\kappa}-\frac{\kappa-1}{2n}.$$ Moreover, from the above construction, the constituent $\RS$ code in the $\AG$-based $\IRS_{m}(\fC(\lambda \fP_{\infty},\calP))$ satisfies assumptions in Section~\ref{sec:RS}. By Theorem~\ref{thm:LDAG} and \ref{thm:uniqDecAG}, we have the following results


\begin{corollary}\label{coro:ha}
    Assume $\F_q$ has constant characteristic. Let $\fC(\lambda \fP_{\infty},\calP)$ be defined as above and $\cR$ be the code rate.  
\begin{itemize}
\item[(1)] For any real number $\ep>0$, $\fC(\lambda \fP_{\infty},\calP)$ is $(1-\cR-\ep,O(1/\ep))$-burst list decodable. Moreover, it can be list decoded in time $O_{\ep}(N\log N)$.
\item[(2)] For any real number $\ep>0$ and positive integer $e\geq 2$, $\fC(\lambda \fP_{\infty},\calP)$ can correct bursts of length less than $N\left(1-\cR-\ep\right)$ with miscorrection probability at most $\ep\kappa/q^{e-1}=\ep/\kappa^{2e-3}$. Moreover, it can be probabilistic uniquely decoded in time $O(\frac{e}{\ep}N\log N)$.
\end{itemize}
\end{corollary}
\begin{proof}
By Theorem~\ref{thm:LDAG}, for any $\ep>0$, we have that $\fC(\lambda \fP_{\infty},\calP)$ is $(1-\cR-\fg/N-\ep/2,O(1/\ep))$-burst list decodable. Since $N=\kappa^3$, $\fg/N=\frac{\kappa(\kappa-1)}{2\kappa^3}<1/2\kappa<1/2n_s$, where $n_s=2/\ep$. Thus $1-\cR-\ep\leq 1-\cR-\fg/N-\ep/2$ and the results in (1) follow immediately.

By Theorem~\ref{thm:uniqDecAG}, for any $\ep>0$ and constant integer $e\geq 2$, we have that $\fC(\lambda \fP_{\infty},\calP)$ can correct burst errors of length less than $N(1-\cR-\fg/N-\ep/2)$ with miscorrection probability at most $\ep/\kappa^{2e-3}$. Put $\ell=2/\ep$ and $\kappa=\ell^{r/s}>\ell^2$. By settings in (ii), $\fg/N<1/2\kappa(1-1/\ell)<\ep/2$. Then the results in (2) follow.
\end{proof}

\subsubsection{\textbf{$q-1$ is $O(1)$-smooth.}} \label{sec:hccm}
Assume $\kappa+1=\prod_{i=1}^r p_j\mid q-1$. By Lemma~\ref{lem:preH}(3), let 
\[G_i\leq \Gal(E/\F_q(y))\ \text{of\ order}\ |G_i|=\prod_{j=1}^ip_j\ text{for}\ 1\leq i\leq r.\]
Then the fixed subfield $E_i=E^{G_i}=\F_q(x_i,y)$, where $x_i=\prod_{\alpha\in G_i}\alpha (-x)=x^{|G_i|}$. Thus $E$ has a chain of subfields: $E_i\subset E_{i+1},$ and $[E_i: E_{i+1}]=p_i$. 

For any $0\leq v\leq \kappa$, let $\bv=(v_0,v_1,\dots,v_{r-1})$ be the coefficients of expansions of $v=\sum_{i=0}^{r-1}v_{i-1}p_0p_1\cdots p_i$ (where $p_0:=1$) as in Equation~\eqref{eq:expu}. Then 
$$\bx^{\bv}=x_0^{v_0}x_1^{v_1}\cdots x_{r-1}^{v_{r-1}}=x^v.$$ Hence, the basis $\{\bx^{\bv}y^{j}\mid j(\kappa+1)+v\kappa\leq \lambda, 0\leq v\leq \kappa\}$ in Lemma~\ref{lem:basis} is just $\cB_2$.

Let $\Ker(\Tr_{q/\kappa})=\{\alpha\in \F_q \mid \alpha^{\kappa}+\alpha=0\}$. By Lemma~\ref{lem:preH}(3), for any $\beta\notin \Ker(\Tr_{q/\kappa})$, the equation $x^{\kappa+1}=\beta^{\kappa}+\beta$ has $\kappa+1$ solutions in $\F_q$, i.e., $y-\beta$ splits completely in $E/\F_q(y)$. We take a multiplicative group or a coset of a multiplicative group $\sP$ in $\F_q\setminus\Ker(\Tr_{q/\kappa})$ of order $n$. Let $\calP$ be the set of all rational places lying above $\sP$. Then $N=|\calP|=n(\kappa+1)$ and $N$ is $O(1)$-smooth.

Assume $\kappa\leq k\leq n$ is a positive integer. Let $\lambda=(k-1)(\kappa+1)$ and $\fC( \lambda{\fP}_{\infty},\calP)$ be the Hermitian code defined on $\calP$. Then the code rate is 
$$\cR=\frac{k-1}{n}+\frac{1}{n(\kappa+1)}-\frac{\kappa(\kappa-1)}{2n(\kappa+1)}.$$  Since $n\mid q-1$ is $O(1)$-smooth, the RS code $\RS[n,k]$ defined on the multipoint set $\sP$ satisfies conditions in Theorem~\ref{thm:listDecRS} and \ref{thm:uniqDecRS}. 
\begin{corollary}
   Assume $q-1$ is $O(1)$-smooth. Let $\fC( \lambda{\fP}_{\infty},\calP)$ be defined as above and $\fg=\frac{\kappa(\kappa-1)}{2}$ be the genus of $E$. For any $\ep>0$,
\begin{itemize}
\item[(1)] $\fC(\lambda \fP_{\infty},\calP)$ is $(1-\cR-\fg/N-\ep,O(1/\ep))$-burst list decodable; 
\item[(2)] $\fC(\lambda \fP_{\infty},\calP)$ can correct bursts of length less than $N\left(1-\cR-\fg/N-\ep(2+e)\right)$ for $e\geq 2$ with miscorrection probability at most $\ep(\kappa+1)/q^{e-1}$. 
\end{itemize}
Moreover, there exist $O_{\ep}(N\log N)$ list and probabilistic unique decoding algorithms for $\fC( \lambda{\fP}_{\infty},\calP)$.
\end{corollary}

\end{example}


\subsection{Examples of {$\AG$} codes from Hermitian tower}
Let $\kappa$ be a prime power and let $q=\kappa^2$. In this example, we only consider the case that $\F_q$ has constant characteristic. The case that $q-1$ is $O(1)$-smooth can be similarly discussed.

Let $F_1=\F_q(x_1)$. The Hermitian tower \cite{Shen93} is defined by the following recursive equations
\begin{equation}\label{eq:x2}
x_{i+1}^{\kappa}+x_{i+1}=x_i^{{\kappa}+1},\quad i=1,2,\dots,t-1.
\end{equation}
Put  $F_i=\F_q(x_1,x_2,\dots,x_{i})$ for $i\ge 2$. We fix an integer $t$ satisfying $2\le t\le \kappa/2$. 

Since each field extension $F_i/F_{i-1}$ has the same properties as Hermitian function field $F_2/F_1$ in Lemma~\ref{lem:preH}, we have the following facts:
\begin{itemize}
\item[(i)] The pole $P_{\infty}\in\PP_{\F_q(x_1)}$ of $x_1$ is totally ramified in the extension $F_t/F_1$. Let $\fP_{\infty}^{(t)}$ be the unique place of $F_t$ lying over $P_{\infty}$. For an integer $\Gl>0$, the Riemann-Roch space $\cL(\Gl \fP_\infty^{(t)})$ of $F_t$ has a basis as follows \cite[Proposition 5]{Shen93}
\begin{equation}\label{eq:x3}
\small
\cB_1^{(t)}=\left\{x_1^{j_1}\cdots x_t^{j_t}\mid (j_1,\dots,j_t)\in\mathbb{N}^t,\ \sum_{i=1}^tj_i\kappa^{t-i}({\kappa}+1)^{i-1}\le \Gl, 0\le j_2,\cdots,j_t\le \kappa-1\right\}
\end{equation}
\item[(ii)] For every $\Ga\in\F_q$, the rational place $P_\Ga\in\PP_{\F_q(x_1)}$ splits completely in $F_t$, i.e., there are $\kappa^{t-1}$ rational places in $F_t$ lying over $P_\Ga$.
\end{itemize}

Replace each $x_i^{j_i}$ with $\bx_i^{\bj_i}$ as in Equation~\eqref{eq:hexp} for $i=2,\dots,t$, then $\cB_1^{(t)}=\{x_1^{j_1}\bx_2^{\bj_2}\cdots \bx_t^{\bj_t}$ is a basis of $\cL(\Gl \fP_\infty^{(t)})$ ensuring that the G-FFT and G-IFFT work well for functions in $\cL(\lambda_t{\fP}^{(t)}_{\infty})$. Next, let $\{P_1,P_2,\dots, P_n\}\subsetneq {\F_q}$ be the same multipoint set chosen as in \S~\ref{sec:hcca} (i) and (ii), i.e., $n=\kappa^2$ for list decoding, and $n=\kappa^2(1-\ep)$ for unique decoding, respectively, and $\calP^{(t)}$ be the set of rational places in $F_t$ lying over them. Then $|\calP^{(t)}|:=N_t=\kappa^{t-1} n$. Let $\kappa\leq k\leq n$, $\lambda_t=\kappa^{t-1}(k-1)$ and $\fC(\lambda_t \fP^{(t)}_{\infty},\calP)$ be the Hermitian code defined on $\calP^{(t)}$. Then the code rate
\[\cR_t=\frac{(k-1)\kappa^{t-1}+1-\fg_t}{n\kappa^{t-1}}\geq \frac{k-1}{n}-\frac{t\kappa}{n}.\]
The above inequality follows from the genus $\fg_t$ of $\F_t$ satisfying $\fg\leq t\kappa^t$ \cite[Section 6]{encAG24}. Hence, for $t<\kappa \ep$, we have $\fg_t/N_t<\ep$. By similar analysis as in Corollary~\ref{coro:ha}, we have the following results for Hermitian tower codes. 
\begin{corollary}\label{coro:ha}
    Assume $\F_q$ has constant characteristic. Let $\fC(\lambda_t \fP_{\infty}^{(t)},\calP^{(t)})$ be defined as above and $\cR_t$ be the code rate. For any real number $\ep>0$, let $t<\kappa\ep$. 
\begin{itemize}
\item[(1)] $\fC(\lambda_t \fP_{\infty}^{(t)},\calP^{(t)})$ is $(1-\cR_t-\ep,O(1/\ep))$-burst list decodable. Moreover, it can be list decoded in time $O_{\ep}(N\log N)$.
\item[(2)] For any positive integer $e>(t+1)/2$, $\fC(\lambda_t \fP^{(t)}_{\infty},\calP^{(t)})$ can correct bursts of length less than $N_t(1-\cR_t-\ep)$ with miscorrection probability at most $\ep/\kappa^{2e-t-1}$. Moreover, it can be probabilistic uniquely decoded in time $O(\frac{e}{\ep}N\log N)$.
\end{itemize}
\end{corollary}




