\subsection{Examples of {$\AG$} codes from the Garcia-Stichtenoth tower}
As we have mentioned (P1)-(P3) in the G-FFT assumptions are used to construct a basis for the one-point Riemann-Roch space, from which we can reduce the decoding problem of AG codes to the decoding problem of interleaved RS codes. There are some function fields $E/\F_q$ that do not satisfy all three assumptions (P1)-(P3) of the G-FFT, but have  good polynomial base. By using the same technique as in previous sections, we will show that the algenraic geometry codes based on $E$ can still be burst decoded in quasi-linear time.
%Let us recap some known result about Garcia-Stichtenoth tower($\GS$ tower for short), one can refer to~\cite{gs95tower} for details. 

In the following, we always $\F_q$ has constant characteristic $\Char \F_q=O(1)$.
\begin{example}{(Garcia-Stichtenoth tower)}\label{ex:gs}
Let $\F_q=\F_{\kappa^2}$ be a finite field and $\F_q(x)$ be the rational function field. The Garcia-Stichtenoth tower over $\F_q$ is the sequence of function fields defined by $F_1=\F_q(x),\ F_{i+1}=F_i(z_{i+1})$ where $z_{n+1}$ satisfies
\begin{equation}\label{eq:defGS}
    z^{\kappa}_{n+1}+z_{n+1}=x_n^{\kappa+1},\ x_1=x\ \text{and}\ x_n=\frac{z_n}{x_{n-1}}\ \text{for}\ n\geq 2.
\end{equation}
Particularly, $F_2$ is just the Hermitian function field. \textbf{Note that the field extension $F_n/\F_1$ does not satisfy  (P3) in the G-FFT assumptions in section 3}. In \cite{gs95tower}, the authors pointed out the extension of places in $F_n/F_1$. We will only consider the third function field $F_3$ in the following.
%Let $\Ker \Tr_{q/\kappa}=\{\gamma\in\F_q\mid \gamma^\kappa+\gamma=0\}$. Then
\begin{itemize}
    \item[(i)] All places in $\{P_{\alpha}\in\PP_{F_1}\mid \alpha\in\F_q^*\}$ are splitting completely in $F_3/F_1$: first, the equation $z_2^{\kappa}+z_2=\alpha^{\kappa+1}$ has $\kappa$ solutions in $\F_q$; next, for each solution $z_2=\beta$, the equation $z_3^{\kappa}+z_3=(\frac{\beta}{\alpha})^{\kappa+1}$ also has $\kappa$ solutions. We denote $P_{\alpha,\beta,\gamma}$ by the zero place of $x_1=\alpha,z_2=\beta,z_3=\gamma$. There are $(\kappa^2-1)\kappa^2$ such places $\{P_{\alpha,\beta,\gamma}\in\PP_{F_3}\mid \alpha\in\F_q^*\}$ in total.
%    \item[(ii)] There exists a unique place $Q_{1}$ which is the common zero of $x_0=z_1=0$. Since the equation $z_2^{\kappa}+z_2=0$ has $\kappa$ solution in $\Ker \Tr_{q/\kappa}$. Then $Q_{1}$ splits into $\kappa$ places, denoted by $S_0^{(2)}=\{P_{0,0,\gamma}\mid \gamma\in \Ker \Tr_{q/\kappa}\}$.
    \item[(ii)] Let $P^{(1)}_{\infty}\in\PP_{F_1}$ be the unique pole place of $x_1$ in $F_1$. Then $P^{(1)}_{\infty}$ is totally ramified in $F_3/F_1$, denoted by $P_{\infty}^{(3)}$ the unique place in $F_3$ lying over $P^{(1)}_{\infty}$.
\end{itemize}
Moreover, the genus of $F_3$ is $\fg(F_3)=\kappa^3-2\kappa+1$. Consider the Riemann-Roch space $\cL(\lambda P^{(3)}_{\infty})$ with $\lambda=(k-1)q$ and the positive integer $k$ satisfying $2\kappa<k<\kappa^2$. Then 
\[\dim_{\F_q}\left(\cL(\lambda P^{(3)}_{\infty})\right)=(k-1-\kappa)\kappa^2+2\kappa.\]
For the third function field $F_3$, by~\cite{vos97GS3}, we can get an explicit basis of the Riemann-Roch space $\cL(\lambda P^{(3)}_{\infty})$. By computation, we note that there is a subspace of $\cL(\lambda P^{(3)}_{\infty})$ which has dimension close to $\dim_{\F_q}\cL(\lambda P^{(3)}_{\infty})$ but a simpler basis. Under this basis, we can use the same technique to burst decode the \rAG codes based on the third function $F_3$. 



\begin{lemma}\label{lem:subsp}
   Define the following set
    \[\begin{split}
        \mathcal{I}_1(\lambda)=\{(i_1,i_2,i_3)\mid\  &i_1\kappa^2+i_2\kappa+i_3(\kappa+1)\leq \lambda,\ i_2\kappa+i_3(\kappa+1)\leq i_1\kappa,\\
   &0\leq i_1,\ 0\leq i_2,i_3\leq \kappa-1\}.
    \end{split}  \]
   The set $\cB(\lambda)=\{x_1^{i_1}x_2^{i_2}z_3^{i_3}\mid (i_1,i_2,i_3)\in\mathcal{I}_1(\lambda)\}$ is an $\F_q$-linearly subset of $\cL(\lambda P^{(3)}_{\infty})$. Moreover, 
   \[\dim_{\F_q}(\cL(\lambda P^{(3)}_{\infty}))-|\cB(\lambda)|\leq (\kappa^2+\kappa-2)/2.\]
\end{lemma}
\begin{proof}
    Define 
    \[\begin{split}\mathcal{I}_2(\lambda)&=\{(i_1,-i_2,i_3)\mid\  i_1\kappa^2+i_2\kappa+i_3(\kappa+1)\leq \lambda,\ i_3(\kappa+1)\leq i_2\kappa+i_1\kappa, \\
   &1\leq i_2\leq \kappa,\ i_1\geq \kappa i_2,\ 0\leq i_3\leq \kappa-1,\ (i_1-1,\kappa-i_2,i_3)\notin \mathcal{I}_1(\lambda)\}.
\end{split}\]
    The Lemma~4.2 in \cite{vos97GS3} shows that $\cB'(\lambda)=\{x_1^{i_1}x_2^{i_2}z_3^{i_3}\mid (i_1,i_2,i_3)\in\mathcal{I}_1(\lambda)\cup\mathcal{I}_2(\lambda)\}$ is a basis of $\cL(\lambda P^{(3)}_{\infty})$. It suffice to show $|\mathcal{I}_2(\lambda)|\leq (\kappa^2+\kappa-2)/2=O(q)$. Since
    \[\nu_{P_{\infty}^{(3)}}(x_1^{i_1}x_2^{-i_2}z_3^{i_3})=\nu_{P_{\infty}^{(3)}}(x_1^{i_1-1}x_2^{\kappa-i_2}z_3^{i_3}),\]
    by the definition of $\mathcal{I}_1(\lambda)$, the condition $(i_1-1,\kappa-i_2,i_3)\notin \mathcal{I}_1(\lambda)$ implies that
    \begin{equation}\label{eq:I2}
    (\kappa-i_2)\kappa+i_3(\kappa+1)>(i_1-1)\kappa\Rightarrow \kappa^2+\kappa+i_3(\kappa+1)>i_1\kappa+i_2\kappa.
    \end{equation}
    As $i_1\geq i_2\kappa$, $i_2\geq 1$ and $0\leq i_3\leq \kappa-1$ in $\mathcal{I}_2(\lambda)$, there must be 
    \[1\leq i_2<1+i_3/\kappa \Rightarrow i_2=1,\ 1\leq i_3\leq\kappa-1,\ \text{and}\ \kappa\leq i_1.\]
    %But another conditions in $\mathcal{I}_2(\lambda)$ restricting 
    In this case, the inequality in Equation~\eqref{eq:I2} implies
    \[\kappa \leq i_1\leq i_3+\kappa,\text{and}\ 1\leq i_3\leq \kappa-1.\]
    There are at most $\sum_{i_3=1}^{\kappa-1}(i_3+1)=(\kappa^2+\kappa-2)/2$ such tuples $(i_1,i_2=-1,i_3)\in \mathcal{I}_2(\lambda)$.
\end{proof}

Let $K=|\cB(\lambda)|$ and denote the elements in $\cB(\lambda)$ simply by $\cB(\lambda)=\{\mathbf{b}_i:\ i=1,\dots,K\}$. We define the \rAG code from $F_3$ as follows:
\begin{itemize}
    \item\textbf{Message space}: $\mathcal{V}=\left\{\sum_{i=1}^K\alpha_i\mathbf{b}_i\mid \alpha_i\in\F_q\right\}\cong\F_q^K$ and $K\approx (k-1-\kappa)\kappa^2$ by Lemma~\ref{lem:subsp};
    \item\textbf{The set of evaluation places}: Assume $\F_q=\F_{\ell^{u}}$ and $W\subset\F_q$ is a subspace of dimension $u-1$, where $\ell\mid q$ is a constant prime power. Let $L(x)=\prod_{\alpha\in W}(x-\alpha)$ and $\gamma\in\F_q$ such that $L(\gamma)\neq 0$. We take a subset $\sP=\{\alpha_1,\dots,\alpha_n\}\subset \F_q^*$ of order $n=(\ell-1)\ell^{u-1}=q(1-1/\ell)$ which are the roots of $L(x)^{\ell-1}=L(\gamma)^{\ell-1}$ as in Lemma~\ref{lem:MPset}. Let $\calP=\cup_{i=1}^n\calP_{\alpha_i}$, where $\calP_{\alpha_i}=\{P_{\alpha_i,\beta,\gamma}:\ x(P_{\alpha_i,\beta,\gamma})=\alpha_i\}$ is the set of all places lying over $P_{\alpha_i}$ defined as in (i). Then $|\calP|=n\kappa^2=\kappa^4(1-1/\ell)$. 
    %\cup \{P_{0,0,\gamma}:\ \gamma\in \Ker \Tr_{q/\kappa}\}$. Then $|\calP|=\kappa^4-\kappa^2+\kappa$.
\end{itemize}
The \rAG code from $\GS$-tower is defined as
\[\fC(\mathcal{V},\calP)=\left\{\ev_{\calP}(f)=\left(\ev_{\calP_{\alpha_1}}(f),\dots,\ev_{\calP_{\alpha_{n}}}(f)\right)\mid f\in\mathcal{V}\right\}.\]
Thus $\fC(\mathcal{V},\calP)$ is an $\F_q$-linear code with length $N=n\kappa^2$ and dimension $K=(k-1-\kappa)\kappa^2$, where $n<\kappa^2$ and $2\kappa+1\leq k\leq n$. 

Every function $f\in\mathcal{V}$ under the basis $\cB(\lambda)$ can be decomposed as follows:
\[f(x_1,x_2,z_3)=\sum_{i_2,i_3=1}^{\kappa-1}f_{i_2,i_3}(x)x_2^{i_2}z_3^{i_3},\ f_{i_2,i_3}(x)\in\F_q[x]_{<k}
\]
Since $\F_q$ has constant characteristic, by the G-FFT technique in Section~\ref{sec:RS}, put $m_s=\ell^{u-1}$, $n_s=\ell-1$ and $x_s=L(x)$, then $f(x_1,x_2,z_3)$ can be further decomposed as 
\[ f(x_1,x_2,z_3)=\sum_{j_s=0}^{m_s-1}\sum_{i_2,i_3=1}^{\kappa-1}f_{j_s,i_2,i_3}(x_s)x_1^{j_s}x_2^{i_2}z_3^{i_3},\ f_{j_s,i_2,i_3}(x_s)\in\F_q[x_s]_{<\lceil k/m_s\rceil}.
\]
Let $\sP_s=\{t_1,\dots,t_{\ell-1}\}=\{x_s(\alpha)\mid \alpha\in\sP\}$ be the set of rational places in $\F_q(x_s)$ lying below $\calP$. For each $t_j$, there are $m_s\kappa^2$ places in $\calP$ lying over $x_s-t_j$, i.e., 
$$\calP[j]:=\{(\alpha, \beta,\gamma)\ \text{satisfying\ Equation}\ \eqref{eq:defGS}\mid \alpha=t_jw,\ w\in W\}.$$
Then 
\[\ev_{\calP[j]}(f)=\ev_{\calP[j]}\left(\sum_{j_s=0}^{m_s-1}\sum_{i_2,i_3=1}^{\kappa-1}f_{j_s,i_2,i_3}(t_j)x_1^{j_s}x_2^{i_2}z_3^{i_3}\right).\]
%Note that $\calP[j]$ has semi-grid structure, 
For each polynomial $f_j:=\sum_{j_s=0}^{m_s-1}\sum_{i_2,i_3=1}^{\kappa-1}f_{j_s,i_2,i_3}(t_j)x_1^{j_s}x_2^{i_2}z_3^{i_3}\in\F_q[x_1,x_2,z_3]$ with three variables, we make use of the fast multivariate MPE and interpolation \cite{BRS20,von13} to do the DFT and IDFT, respectively. Then the multipoint evaluation of $f_j$ at $\calP[j]$ can be computed in time $\tO(m_s\kappa^2)$; conversely, given the MPE of $f_j$ at $\calP[j]$, the coefficients $\{f_{j_s,i_2,i_3}(t_j) \mid 0\leq j_s\leq m_s-1,\ 0\leq i_2,i_3,\leq \kappa-1\}$ can be computed in time $\tO(m_s\kappa^2)$. Thus by folding $\ev_{\calP}(f)$ with length $m_s\kappa^2$ and running multivariate IDFT on each column, we get an interleaved $\RS[n_s,k/m_s]$
\[
(\ev_{\calP_{\alpha_1}}(f),\ldots,\ev_{\calP_{\alpha_{n}}}(f))
\xrightleftharpoons[]{}
\left(\begin{matrix}
f_{0,0,0}(t_1)                   &   \cdots   & f_{0,0,0}(t_{n_s})\\ 
f_{1,0,0}(t_1)                   &   \cdots   & f_{1,0,0}(t_{n_s})\\ 
\vdots                           &   \cdots   & \vdots            \\
f_{m_s-1,\kappa-1,\kappa-1}(t_1)  &   \cdots   & f_{m_s-1,\kappa-1,\kappa-1}(t_{n_s})\\  \end{matrix}\right).
\]
Thus decoding $\fC(\mathcal{V},\calP)$ with burst errors can be reduced decoding $\IRS[n_s,k/m_s]$ with burst errors. By a similar proof of Corollary~\ref{coro:ha}, we have the following results
\begin{itemize}
\item[(1)] For any $\ep>0$, $\fC(\mathcal{V},\calP)$ is $(1-\cR-\ep,O(1/\ep))$-burst list decodable; 
\item[(2)] For any  $\ep>0$ and constant integer $e\geq 2$, $\fC(\mathcal{V},\calP)$ can correct bursts of length less than $N(1-\cR-\ep)$ with miscorrection probability at most $\ep/q^{e-2}$,
\end{itemize}
where $\cR=K/N$ is the code rate. Moreover, there exist quasi-linear time $\tO_{\ep}(N)$ list and probabilistic unique decoding algorithms for $\fC( \lambda{\fP}_{\infty},\calP)$.
\end{example}




