\section{The proof of Lemma~\ref{lem:UniDec}}\label{app:uniq}
In this section, we will give a generalized version of Wu's algorithm that can be applied to $\RS$ codes defined on a non-cyclic multipoint set. Let us first recap some notations in syndrome decoding. 

Assume $\calP=\{\xi,\xi\alpha,\dots,\xi\alpha^{n-1}\}\in\F_q^*/\langle \alpha\rangle$ is a coset of cyclic group, where $\alpha\in\F_q^*$ has order $n$. The $\RS[n,k]$ that we concerned is defined as 
\[\RS[n,k]=\{\left(f(\xi),f(\xi\alpha^{}),\dots,f(\xi\alpha^{n-1})\right)\mid f(x)\in\F_q[x]_{<k}\}.\]
Let $r=n-k$. For a burst interval $[i,i+r-2]$, we always view it as a subset of $[1,n]$ in the following sense
$$[i,i+r-2](\bmod\ {n+1})=\begin{cases}
    [i,i+r-2],\ &\text{if}\ i+r-2\leq n;\\
    [i,n]\cup [1,(i+r-2\bmod n+1)+1],\ &\text{if}\ i+r-2> n.
\end{cases}$$
The corresponding reciprocal error locator of $[i,i+r-2]$ is defined as
\begin{equation}\label{eq:errorlocator}
    \Lambda^{(i)}(x)=\prod_{j=i}^{i+r-2}(1-\xi\alpha^{j-1}x)=\Lambda^{(i)}_0+\Lambda^{(i)}_1x+\dots,\Lambda^{(i)}_{r-1}x^{r-1}.
\end{equation}
Given a received word $\br=\bc+\be$, where $\be$ is a burst with length $\fl\leq r-1$. The syndrome polynomial of $\br$ is defined as 
\begin{equation}\label{eq:syndpoly}
    \begin{split}S(x)&=\sum_{j=1}^{n} \frac{r_j\Gd_j}{1-\xi\Ga^{j-1}x}\bmod x^{n-k},\ \text{where}\ \Gd_j=\prod_{k\neq j}(\xi\alpha^{j-1}-\xi\alpha^{k-1})^{-1}\\
&=S_0+S_1x+\dots+S_{r-1}x^{r-1}.\end{split}
\end{equation}

Assume the burst interval of $\be$ is $[i,i+\fl-1]$. Then $[i,i+\fl-1]\subset [i,i+r-2]$. By syndrome decoding \cite{10synd}, we have
\begin{equation}\label{eq:synd}
S_{r-1}\Lambda_{0}^{(i)}+S_{r-2}\Lambda_{1}^{(i)}+\dots+S_1\Lambda_{r-2}^{(i)}+S_0\Lambda_{r-1}^{(i)}=0.
\end{equation}
Particularly, let $\Lambda^{(1)}(x)=\prod_{j=1}^{r-1}(1-\xi\alpha^{j-1}x)$ be the reciprocal error locator of burst $[1,r-1]$. Define a polynomial as follows
\begin{equation}\label{eq:gamax}
\Gamma(x)=S_{r-1}\Lambda_{0}^{(1)}+S_{r-2}\Lambda_{1}^{(1)}x+\dots+S_0\Lambda_{r-1}^{(1)}x^{r-1}.
\end{equation}

\begin{lemma}\label{lem:app1}
Assume $\br$ is a corrupted codeword in $\RS[n,k]$ by an $\fl$-burst with interval $[i,i+\fl-1]\subset[1,n]$. Let $S(x)$ be the syndrome polynomial of $\br$ and $\Gamma(x)$ be defined as in Equation~\eqref{eq:gamax}. If $\fl\leq n-k-1$, then $\Gamma(x)$ has $n-k-1-\fl$ consecutive roots $\alpha^{i-1},\alpha^{i-2},\dots,\alpha^{i-(n-k)+\fl}$.
\end{lemma}
\begin{proof}
Let $r=n-k$. By definition, $\Lambda^{(i)}(x)=\Lambda^{(1)}(\alpha^{i-1}x)=\Lambda_{0}^{(1)}+\Lambda_{1}^{(1)}\alpha^{i-1}x+\dots+\Lambda_{r-1}^{(1)}(\alpha^{i-1}x)^{r-1}$. Thus the coefficients satisfy
\[\Lambda_{j}^{(i)}=\Lambda_{j}^{(1)}\alpha^{j(i-1)}\ \text{for}\ j=0,\dots,r-1.\]
By substituting the above relation into Equation~\eqref{eq:synd}, we have
\[0=S_{r-1}\Lambda_{0}^{(1)}+S_{r-2}\Lambda_{1}^{(1)}\alpha^{i-1}+\dots+S_0\Lambda_{r-1}^{(1)}\alpha^{(r-1)(i-1)}=\Gamma(\alpha^{i-1}).\]
For $u=i,i-1,\dots,i-(r-\fl)+1$, let $\Lambda^{(u)}(x)$ be the reciprocal error locator of $[u,u+r-2]$ defined as in Equation~\eqref{eq:errorlocator}. Since the burst interval $[i,i+\fl-1]$ is also contained in the interval $[u,u+r-2]$,
the coefficients of $\Lambda^{(u)}(x)$ and $S(x)$ also satisfy Equation~\eqref{eq:synd}, i.e.,
\[\sum_{j=0}^{r-1}S_{r-1-j}\Lambda_{j}^{(u)}(\alpha^{j(u-1)})=\Gamma(\alpha^{u-1})=0.\]
Thus, $\alpha^{i-1},\alpha^{i-2},\dots,\alpha^{i-(n-k)+\fl}$ are $\fl$ consecutive roots of $\Gamma(x)$.
\end{proof}

