 \section{The proof of Lemma~\ref{lem:basis}}\label{app:basis}
\begin{proof}
First, it easy to see that $\cB\subset \cL(\lambda P^{(0)}_{\infty})$ by the definition of Riemann-Roch space. Next, we will show that $\cB$ is $\F_q$-linearly independent. Actually, all $\by^{\bu}x^j\in\cB$ have distinct discrete valuations at $P^{(0)}_{\infty}$, thus they must be linearly independent over $\F_q$. We claim that \[\nu_{P^{(0)}_{\infty}}(\by^{\bu}x^j)= \nu_{P^{(0)}_{\infty}}(\by^{\bu'}x^{j'})\ \text{if\ and\ only\ if}\ u=u' \ \text{and}\ j=j'.\]
This can be proved by induction. Note that if $j\neq j'$, then $\nu_{P^{(0)}_{\infty}}(x^j)\neq \nu_{P^{(0)}_{\infty}}(x^{j'})$. Assume $\nu_{P^{(0)}_{\infty}}(\by^{\bu}x^j)= \nu_{P^{(0)}_{\infty}}(\by^{\bu'}x^{j'})$ and $u_j=u'_j$ for all $j\leq i-1$ in the expansion of $u$ as in Equation~\eqref{eq:expu}. Then
\[\begin{split} &0= \nu_{P^{(0)}_{\infty}}\left(\by^{\bu}x^j\right)-\nu_{P^{(0)}_{\infty}}\left(\by^{\bu'}x^{j'}\right)\equiv \left(\prod_{j=1}^ip_j\right) (u_i-u_i')\nu_{P^{(i)}_{\infty}}(y_i)\bmod \prod_{j=1}^{i+1}p_j. \end{split}\]
Since $\gcd(\nu_{P^{(i)}_{\infty}}(y_i),p_{i+1})=1$, there must be $u_i=u'_i$. By induction, we have $u=u'$. Thus $j=j'$ and the claim is true. 

Finally, by the second part in assumption $(P3)$, the set $\cB$ spans the whole Riemann-Roch space $\cL(\lambda P^{(0)}_{\infty})$. We show it by induction. For any $f\in\cL(\lambda P_{\infty})$, since $E=E_1(y_0)$, then $f=\sum_{i=0}^{p_1-1}\alpha_iy_0^i$ where $\alpha_i\in E_{1}$ for all $0\le i\le p_1-1$. Since $\{1, y_0, \dots, y_0^{p_1-1}\}$ is an integral basis of $E/E_1$ at $Q$ for $Q\neq P^{(1)}_{\infty}$, by \cite[Corollary 3.3.5]{sti09}, one has
\[\bigcap_{P\mid Q}\calO_{P}=\bigoplus\limits_{i=0}^{p_1-1} \calO_{Q}y_0^i,\ \forall\  Q\neq P^{(1)}_{\infty}.\]
As $f\in\bigcap_{P\mid Q}\calO_{{P}}$ for $Q\neq P^{(1)}_{\infty}$, by the above equation, the coefficients $\alpha_0,\dots,\alpha_{p_1-1}$ of $f$ are all in $\calO_{Q}$, namely, they have poles only at $P^{(1)}_{\infty}$. For $0\le i\le p_1-1$, assume $\nu_{P^{(1)}_{\infty}}(\alpha_i)=-a_i$. Then $a_i\leq \frac{m(k-1)}{p_1}$ by $\nu_{P^{(0)}_{\infty}}(f)\geq -m(k-1)$. Thus $\alpha_i\in \cL(\frac{m(k-1)}{p_1}P^{(1)}_{\infty})$. By induction on $\alpha_0,\dots,\alpha_{p_1-1}$, we can obtain that
\[f= f_0(x)+f_1(x)\by^{\mathbf 1}+\dots+f_{m-1}(x)\by^{\mathbf{m-1}},\ \text{and}\ f_u(x)\in\cL((k-1)P^{(r)}_{\infty})=\F_q[x]_{\leq k-1}.\] 
Hence $\cB$ is a basis of the Riemann-Roch space $\cL(\lambda P^{(0)}_{\infty})$.

%Finally, assume $f=f_0(x)+f_1(x)\by^{\mathbf 1}+\dots+f_{m-1}(x)\by^{\mathbf{m-1}}\in \cL(\lambda P^{(0)}_{\infty})$ is represented under basis $\cB$. Since 
%\[\nu_{P^{(0)}_{\infty}}(f)=\min\{\nu_{P^{(0)}_{\infty}}(f_u(x)\by^{\bu})\}\geq -\lambda\Rightarrow \nu_{P^{(r)}_{\infty}}(f_u(x)\geq-\lambda/m=k-1,\]
%then $f_u(x)\in\cL((k-1)P^{(r)}_{\infty})=\F_q[x]_{\leq k-1}$.
\end{proof}

 \section{The proof of Lemma~\ref{lem:gfft}}\label{app:gfft}

\begin{proof}
   Denote the complexity (i.e., the total number of operations in $\F_q$) of evaluating an $f$ at the set $\cP$ by $C(m)$. Let $\calP_i=\{\fP_1,\dots,\fP_m\}\cap E_i$ for $1\leq i\leq r$. Since $P$ is splitting completely in $E/F$ and $[E:E_i]=p_1\cdots p_i$, then $|\calP_i|=m/p_1\cdots p_i$. For any $\fp_i\in\calP_1$, let $\fP_{i,1},\dots,fP_{i,p_1}$ be all $p_1$ places lying over $\fp$. Assume 
   \[f=f_0(y_1,\dots,y_{r-1})+f_0(y_1,\dots,y_{r-1})y+\dots+f_0(y_1,\dots,y_{r-1})y^{p_1-1}.\]
   Then 
   \begin{equation}\label{eq:rec}
\left(\begin{matrix} f(\fP_{i,1})\\
f(\fP_{i,2})\\
\vdots\\
f(\fP_{i,p_1-1})\end{matrix}\right)=\left(\begin{matrix}
1            &            y(\fP_{i,1})    & \cdots  & y^{p_1-1}(\fP_{i,1})\\ 
1 & y(\fP_{i,2}) & \cdots  & y^{p_1-1}(\fP_{i,2}) \\
\vdots       & \vdots       & \cdots   & \vdots \\
1 &   y(\fP_{i,p_{1}}) & \cdots &  y^{p_1-1}(\fP_{i,p_{1}})\end{matrix}\right)\cdot \left(\begin{matrix} f_0(\fp_i)\\
f_1(\fp_i)\\
\vdots\\
f_{p_1-1}(\fp_i)\end{matrix}\right)\end{equation}
   Thus, the computation of $f$ at $m$ points $\fP_1,\dots,\fP_m$ can be reduced to the computation of $f_0,f_1,\dots,f_{p_1-1}$ at $\calP_1$ through the above Equation~\eqref{eq:rec}. Hence $C(m)$ satisfies the following recursive formula
   \[C(m)=p_1C(m/p_1)+p_1^2m/p_1=p_1C(m/p_1)+p_1m.\]
By recursive reduction, we can finally reduce the computation of $(f(\fP_1),\dots,f(\fP_m))$ to MPEs of $m$ functions in $E_r$ at $P$. In this case, by recursive formula of $C(m)$, we have
\[C(m)=p_1\cdots p_rC(1)+(p_1+\dots+p_r)m=O(Bm\log m).\]

Conversely, let $I(m)$ denote the G-IFFT of length, i.e., given the $m$ evaluation of $(f(\fP_1),\dots,f(\fP_m))$, find its $m$ coefficients under basis $\{\by^{\bu}:\ u\in[m]\}$. By the Equation~\eqref{eq:rec}, we have
   \begin{equation}\label{eq:irec}
\left(\begin{matrix} f_0(\fp_i)\\
f_1(\fp_i)\\
\vdots\\
f_{p_1-1}(\fp_i)\end{matrix}\right)=\left(\begin{matrix}
1            &            y(\fP_{i,1})    & \cdots  & y^{p_1-1}(\fP_{i,1})\\ 
1 & y(\fP_{i,2}) & \cdots  & y^{p_1-1}(\fP_{i,2}) \\
\vdots       & \vdots       & \cdots   & \vdots \\
1 &   y(\fP_{i,p_{1}}) & \cdots &  y^{p_1-1}(\fP_{i,p_{1}})\end{matrix}\right)^{-1}\cdot \left(\begin{matrix} f(\fP_{i,1})\\
f(\fP_{i,2})\\
\vdots\\
f(\fP_{i,p_1-1})\end{matrix}\right),\end{equation}
Thus, the computation of $f$ from $m$ evaluations can be reduced to the computation of $f_0,f_1,\dots,f_{p_1-1}$ from $m/p_1$ evaluation through the above Equation~\eqref{eq:irec}. Hence $I(m)$ also satisfies the following recursive formula
   \[I(m)=p_1I(m/p_1)+p_1^2m/p_1=p_1I(m/p_1)+p_1m=O(Bm\log m).\]
\end{proof}


