	\includegraphics[width=0.8\linewidth]{bvtt.pdf}
    \caption{{\bf BVTT expansion:} We traverse all BVTT nodes in the input front $\rm buffer_1$ and, based on the input adaptive depth step, obtain the expanded BVTT front $\rm buffer_2$.}
